BEGIN;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"0d02f031-f0b1-423e-9997-09aa4b73eee9": {"definition": "The setup discipline of halting a line check or system check the moment a fault is found and resolving it immediately, rather than noting it and continuing, so problems are not forgotten or allowed to compound.", "plain_english": "It means fixing each problem the moment you find it. You do not keep going and hope to remember it later.", "purpose_function": "It stops faults from being overlooked or interacting with later problems, keeping the check reliable and the finished system trustworthy.", "practical_application": "If a channel shows no signal present, the engineer stops and fixes it — checking cable, patch and gain — before moving to the next channel.", "category": "Soundcheck Workflow", "related_terms": ["Line check", "Source check", "Signal present", "System check", "Start at channel one", "Show-ready state"], "common_mistakes": ["Noting several faults to fix 'later', then running out of time before the show.", "Continuing past a fault so its cause gets confused with the next channel's problem.", "UNSAFE: Pressing on past a suspected grounding or mains fault instead of stopping to fix it, risking equipment damage or electric shock."], "scenario_contexts": ["During line check a dead channel appears, so the crew stops and fixes the broken cable before continuing.", "A hum on one input triggers a stop-and-fix to trace a grounding problem before soundcheck.", "A failed amplifier channel is swapped on the spot rather than deferred, keeping the system check honest."]}, "b2dd9639-fb5a-4df3-9e7e-4064b5cab32b": {"definition": "A structured verification that the complete audio system works correctly end to end — sources, processing, distribution, amplifiers and loudspeakers — confirming every output produces the intended signal at the correct level and polarity before use.", "plain_english": "It is a full test of the whole sound system before use. You confirm every speaker and path works and sounds right.", "purpose_function": "It confirms the entire signal path and loudspeaker system are working and correctly configured, catching faults in coverage, polarity or routing before the audience arrives.", "practical_application": "Before doors, the engineer runs a system check with pink noise or music, walking the room to confirm every zone and subwoofer is live and correct.", "category": "System Verification", "related_terms": ["Source check", "Line check", "Show-ready state", "Signal present", "Polarity", "Pink noise"], "common_mistakes": ["Checking only the main hangs and forgetting the fills, delays or subwoofers.", "Assuming a system check passes because audio is heard, without verifying polarity and level per zone.", "Running the system check at low level, missing faults that only appear at show volume.", "UNSAFE: Running full-level pink noise through the system with people close to the loudspeakers, risking hearing damage."], "scenario_contexts": ["A system tech runs a daily system check on an installed PA before the venue opens.", "After rigging line arrays, the crew performs a system check to confirm every box and sub is driven correctly.", "Following a power outage, a quick system check verifies all amplifiers and zones returned correctly."]}, "7f78427f-d274-4bf5-b4f7-3da3253776b5": {"definition": "A tuning track is a piece of well-known, high-quality recorded program material an engineer uses as a familiar reference when tuning a sound system, judging tonal balance and translation by comparing how it reproduces in the room against its remembered sound on trusted systems. It provides an experienced subjective check that complements instrument-based measurement such as pink noise and a real-time or transfer-function analyzer.", "plain_english": "A tuning track is a song you know very well. You play it through the PA to hear how the system sounds. Because you know the song, odd bumps or dips stand out fast. Engineers use it along with measurement tools.", "purpose_function": "It gives the engineer a trusted, consistent sonic reference so tonal problems stand out against known material, catching subjective issues that instrument measurements alone can miss.", "practical_application": "An engineer plays a familiar reference track through the mains during setup, then adjusts system EQ and levels until it sounds as balanced in the room as it does on their trusted monitors or headphones.", "category": "System Tuning", "related_terms": ["Pink Noise", "Real-Time Analyzer (RTA)", "Transfer Function", "Reference Monitor", "Frequency Response", "System Equalization"], "common_mistakes": ["Using an unfamiliar or poorly produced track, so you cannot tell whether a flaw comes from the recording or from the system.", "Tuning only by ear with the track while skipping measurement, or the reverse; the two methods work best together.", "Judging the system from a single listening spot instead of walking the coverage area while the track plays."], "scenario_contexts": ["Playing a familiar reference song through the mains to fine-tune system EQ after taking measurements.", "Comparing how a known track translates in a new venue versus in the studio.", "Walking the audience area with a trusted track to check tonal consistency across seats."]}, "ae537842-8991-4384-bcb1-b29f6574d737": {"definition": "Vocal at show level is the practice of setting and auditioning the lead vocal channel at the actual sound-pressure level it will run at during the performance, rather than at a quiet check level, so that gain structure, feedback margin, monitor levels, and overall mix balance are all established under realistic conditions.", "plain_english": "This means checking the singer's voice at the same loudness as the real show. Quiet checks can hide problems. At full show level you hear the true balance. You also learn how close the mics are to feedback.", "purpose_function": "It verifies the vocal's gain structure, feedback margin, and place in the mix at realistic levels, because balances and feedback behavior change as loudness rises.", "practical_application": "During soundcheck the engineer brings the lead vocal up to its expected show level, then builds the rest of the mix and sets monitor sends and EQ around that reference.", "category": "Soundcheck Workflow", "related_terms": ["Gain Before Feedback", "Gain Structure", "Soundcheck", "Ringing Out", "Monitor Mix", "Sound Pressure Level (SPL)"], "common_mistakes": ["Setting the vocal level during a quiet check, then finding the balance and feedback margin change once the band plays at full volume.", "UNSAFE: Bringing the system up to show level without hearing protection or warning people nearby, exposing them to sudden high sound levels that can damage hearing.", "Forgetting that raising the whole system to show level also raises feedback risk, so gain before feedback must be rechecked."], "scenario_contexts": ["Establishing the lead vocal at show level during soundcheck before building the band mix around it.", "Rechecking feedback margin on vocal mics once the PA is at performance loudness.", "Setting a singer's monitor wedge level for the volume they will actually sing over."]}, "fb3a87da-9803-4bf5-b42b-de17938f199d": {"definition": "To work the input list is to proceed methodically through the channel input list, the document mapping each source to a console input, during setup and soundcheck, verifying, line-checking, gain-setting, labeling, and patching every input in order so that no channel is missed before the show.", "plain_english": "The input list shows which source feeds each channel on the desk. To work the list, you go down it one line at a time. You check that each mic or DI is plugged in and working. This makes sure no channel is missed.", "purpose_function": "It provides a systematic checklist so every source is confirmed present, patched, gained, and labeled, preventing dead or wrongly assigned channels once the performance starts.", "practical_application": "Before doors, the engineer and stage crew go line by line down the input list, tapping or line-checking each mic and DI while setting gain and confirming the patch on the console.", "category": "Soundcheck Workflow", "related_terms": ["Input List", "Line Check", "Patch", "Stage Plot", "Gain Structure", "Soundcheck"], "common_mistakes": ["Skipping around instead of working the list in order, which makes it easy to miss a channel or check one twice.", "Line-checking a signal without confirming the channel label and patch, so a working input lands on the wrong fader.", "Setting gain during the quiet line check but not rechecking it once the performer plays at full level."], "scenario_contexts": ["Line-checking every input against the input list before a festival changeover deadline.", "Confirming patch and gain on each channel during a studio session setup.", "Tracing a dead channel by returning to the input list to check its source and patch."]}, "6a768864-75b7-40a8-9b5c-4243a7479647": {"definition": "To zero the desk is to reset a mixing console to a known neutral starting state, typically with faders down, input gains at minimum, EQ flat, dynamics and routing cleared, and sends and effects reset, so that setup for the next event begins from a clean, predictable baseline instead of inheriting another engineer's settings.", "plain_english": "To zero the desk means resetting the mixing board to a blank start. Faders go down, EQ goes flat, and old routing is cleared. It is like wiping a whiteboard clean before you write. Then you build your setup from scratch.", "purpose_function": "It removes leftover settings that could cause surprises in level, routing, or processing, giving each engineer a consistent, safe baseline to build a new setup from.", "practical_application": "Before setting up for a new act or session, the engineer recalls a default or initialized scene, or manually resets faders, gains, EQ, and routing, so nothing carries over from the previous show.", "category": "Console Setup", "related_terms": ["Mixing Console", "Scene Recall", "Default Preset", "Signal Routing", "Gain Structure", "Soundcheck"], "common_mistakes": ["UNSAFE: Zeroing or recalling a default scene with the system unmuted and amplifiers live, causing a sudden loud output that can harm hearing or damage drivers.", "Assuming a stored 'default' scene is truly neutral without checking, when it may still hold old routing or processing.", "Zeroing the desk without first saving the previous show file, losing settings that may be needed again."], "scenario_contexts": ["Resetting a shared festival console to neutral during a changeover between bands.", "Recalling an initialized scene on a digital console before programming a new show.", "Clearing a house desk to a known state at the start of a rental or install commissioning."]}, "c0bdea3d-6133-4791-b7e3-71647ae24a08": {"definition": "A bad cable is an audio or signal cable that fails to pass its signal correctly because of an internal or connector fault - such as a broken (open) conductor, a short between conductors or to the shield, a cold or fractured solder joint at the connector, or a worn or dirty contact. The fault may be constant or intermittent and produces symptoms such as no signal, dropouts, crackling, hum, or added noise; because cables flex and are handled far more than fixed gear, they are among the most common causes of signal problems.", "plain_english": "A bad cable is a lead that no longer carries its signal properly. A wire inside may be broken, or a joint at the plug may have failed. This can cause silence, crackles, hum, or sound that cuts in and out. Cables fail often because they get bent, pulled, and stepped on.", "purpose_function": "The term focuses troubleshooting on the cable as a likely fault point, since cables flex, pull, and wear far more than fixed equipment. Identifying a bad cable lets a technician restore signal by swapping or repairing it instead of chasing the wrong component.", "practical_application": "A technician confirms a bad cable by substituting a known-good cable or checking it on a cable tester for continuity and shorts, then repairs or replaces it.", "category": "Cable fault", "related_terms": ["No signal", "Reseat the connector", "Cable tester", "Intermittent connection", "Cold solder joint", "Continuity test"], "common_mistakes": ["Assuming the cable is bad before checking simpler causes such as a mute, wrong routing, or a gain control turned down.", "Trusting a cable that only fails when flexed, because an intermittent fault can pass a quick static continuity test.", "Repeatedly repairing a badly worn cable instead of replacing it once it becomes unreliable."], "scenario_contexts": ["A microphone goes silent mid-show and swapping the cable restores the sound.", "A guitar lead crackles whenever the player moves, pointing to a broken connection at a plug.", "Testing a batch of stage cables on a cable tester before a gig to pull out the faulty ones."]}, "b5823b29-072e-4a49-95b6-18b37522da14": {"definition": "No signal is a troubleshooting condition in which an expected audio (or other) signal fails to reach its destination, so a channel, device, or output produces nothing. It arises from a break somewhere in the signal chain - for example a disconnected, bad, or wrongly patched cable; a muted, unrouted, or wrongly selected channel; missing phantom power or device power; or a failed component - and is diagnosed by working systematically along the signal path from source to output.", "plain_english": "No signal means the sound is not getting through to where you expect it. Something in the chain is broken, muted, or plugged in wrong. You may also have picked the wrong input or left the power off. You fix it by checking each step from source to output in order.", "purpose_function": "The term labels a total loss of signal so a technician can begin structured fault-finding along the signal path. Framing the problem this way points to checking the whole chain rather than guessing at a single part.", "practical_application": "Facing no signal, a technician traces the path from source to output - checking cables, mutes, routing, gain, input selection, and power - to find where the signal stops.", "category": "Fault symptom", "related_terms": ["Bad cable", "Reseat the connector", "Signal chain", "Signal flow", "Phantom power", "Mute"], "common_mistakes": ["Jumping into the middle of the chain instead of checking it in order from source to output.", "Overlooking simple causes first, such as a mute, a pulled-down fader, or the wrong input selected.", "Missing that a condenser microphone needs phantom power switched on, and blaming the mic instead."], "scenario_contexts": ["A newly patched channel shows no meter movement, so the engineer checks routing and gain.", "A condenser microphone gives no signal until phantom power is switched on.", "An amplifier stays silent because its input cable is unplugged at the far end."]}, "9823a91b-0da9-4319-beff-5e20ec424f60": {"definition": "To reseat a connector is the troubleshooting action of unplugging a connector and firmly re-inserting it to restore a reliable electrical contact. It clears faults caused by a partially inserted plug, contact oxidation or contamination, or contacts loosened by vibration or handling, and is a standard low-cost first step when a connection is intermittent or absent.", "plain_english": "Reseating a connector means pulling the plug out and pushing it back in firmly. This can fix a link that was loose, dirty, or only half plugged in. It is a quick, cheap first thing to try. It often brings back a connection that had cut out.", "purpose_function": "Reseating exists as a fast, low-risk check that restores contact without tools or parts. It rules out a loose or dirty connection before a technician suspects the cable or device itself.", "practical_application": "When a signal is intermittent or missing, a technician unplugs and re-inserts the connector at both ends - powering down or muting first where needed - then tests again before swapping the cable.", "category": "Troubleshooting step", "related_terms": ["No signal", "Bad cable", "Intermittent connection", "Contact oxidation", "Signal chain", "Connector"], "common_mistakes": ["Reseating once and moving on, when a badly oxidised contact may need cleaning rather than just re-insertion.", "UNSAFE: Unplugging and re-inserting mains power connectors while live, risking shock or arcing; disconnect power first.", "UNSAFE: Reseating audio connectors with amplifiers turned up and phantom power on, causing loud pops that can damage loudspeakers or hearing; mute or turn down first."], "scenario_contexts": ["A patchbay connection drops out, and reseating the plug fully restores it.", "An XLR link is intermittent, so the technician reseats both ends before swapping the cable.", "A loose jack or speakON connector is pushed back in until it clicks and locks."]}, "917ee85f-daf7-4670-abfe-19dc97099e9b": {"definition": "Antenna shadowing (RF shadowing) is the attenuation and dropout of a wireless microphone or in-ear signal that occurs when a person's body, a metal object, or a structure obstructs the line-of-sight path between the transmitter and the receiving antenna. Because UHF radio waves are readily absorbed by the human body and blocked by conductive surfaces, the obstruction creates an RF 'shadow' of reduced field strength in which the receiver can lose signal.", "plain_english": "Antenna shadowing happens when something blocks the path between a wireless mic and its antenna. A body or metal object soaks up or blocks the radio signal. This leaves a weak spot, much like a shadow. The receiver can drop out there.", "purpose_function": "The concept explains why wireless signals fade or drop when performers move or when objects block the antenna. It guides antenna placement so the receiver keeps a clear line of sight to the transmitter.", "practical_application": "A technician who sees dropouts when a presenter turns away raises the receiving antennas and moves them for a clear line of sight to reduce shadowing.", "category": "Wireless fault", "related_terms": ["Dropout", "Line of sight", "Diversity reception", "Multipath", "Antenna distribution", "Body absorption"], "common_mistakes": ["Placing the receiving antenna behind the stage or scenery, where the performer's body blocks it.", "Blaming interference for dropouts that are really caused by body or object shadowing.", "Hiding antennas inside a metal rack or behind metal, which blocks the signal."], "scenario_contexts": ["A lavalier drops out whenever the presenter turns their back to the antenna.", "A guitarist's bodypack fades when they walk behind a metal riser.", "Repositioning antennas for a clear line of sight in a theater full of scenery."]}, "e54fe717-3433-4bde-9320-5d7f5d31ffb5": {"definition": "'Audio but no control' is a troubleshooting symptom in which a device passes its audio signal normally while its separate control or management path is unresponsive - for example, a networked audio device whose channels are heard but which cannot be seen or configured from its control software, or a stagebox that outputs audio yet no longer responds to remote commands. It indicates the audio path is intact while the control layer (control network traffic, control connection, or data link) has failed.", "plain_english": "This means the sound still plays, but you cannot change any settings. The audio path works fine. The control link that carries commands is down. So faders, apps, or remote screens stop responding.", "purpose_function": "Naming this symptom separates a working audio path from a failed control path, which narrows the fault fast. It points the technician to the control network or data link rather than the audio wiring.", "practical_application": "When a stagebox still passes audio but the console cannot control its preamps, a technician checks the control network cabling, addresses, and settings rather than the audio path.", "category": "Diagnostic symptom", "related_terms": ["Control network", "Dante", "Signal path", "Stagebox", "Remote control", "Network audio"], "common_mistakes": ["Assuming a dead control link also means the audio is lost, and rebooting good gear needlessly.", "Confusing the audio flow with the separate control path when they take different routes.", "Overlooking a wrong IP address or subnet that blocks control but not audio."], "scenario_contexts": ["A Dante device is heard fine but does not appear in the control software.", "A digital stagebox passes audio but the console cannot adjust its gain.", "Remote control of an amplifier fails while it keeps playing sound."]}, "9ffaec9d-7ee3-474a-af1e-1f1e71c6eedd": {"definition": "A 'bad leg' is a faulty line (hot) conductor of the AC mains supply feeding a sound system - one phase/leg of a split-phase or three-phase service that is dead, at incorrect voltage, or improperly wired, while the other legs remain live. Because loads are distributed across the legs of a power distribution system, a bad leg causes only the equipment fed from that leg to lose power or receive abnormal voltage.", "plain_english": "A bad leg means one of the hot power lines feeding the rig is dead or wrong. Big power feeds are split into several legs. If one leg fails, only the gear on that leg loses power. The rest keeps working.", "purpose_function": "The idea helps a technician explain why only part of a rig lost power while the rest runs. It points troubleshooting toward the power distribution and its individual legs, not the audio gear.", "practical_application": "When one side of the stage goes dark but the other stays on, a qualified electrician meters each leg at the distro to find the dead or low leg.", "category": "Power fault", "related_terms": ["Power distribution", "Phase", "Mains voltage", "Ground fault", "Distro", "Neutral"], "common_mistakes": ["UNSAFE: Opening or testing a live power distribution panel without lockout/tagout, correct PPE, and the qualification required by NFPA 70E.", "UNSAFE: Lifting or defeating the equipment grounding conductor to chase a power or hum problem.", "Assuming the whole system has failed when only the gear on one leg has lost power."], "scenario_contexts": ["Half the stage loses power at load-in while the rest stays live.", "Amplifiers on one leg of the distro shut off but the console keeps running.", "A qualified electrician metering each leg of a three-phase feed to find a dead phase."]}, "762bdde8-9b3c-42f2-ac66-2836daa6816a": {"definition": "A 'bad line' is a signal cable run or channel that is faulty - open, shorted, intermittent, or noisy - so the audio it should carry is lost, degraded, or accompanied by hum, crackle, or dropouts. The fault may lie in the cable, a connector, a solder joint, or a patch point anywhere along that particular signal path.", "plain_english": "A bad line is a single audio cable or channel that is broken or noisy. The sound may cut out, crackle, or hum on that path only. The fault is in the cable, a plug, or a connection. Other lines still work fine.", "purpose_function": "Calling one path a 'bad line' isolates the fault to a single run instead of the whole system. This tells the technician to test or swap that cable and its connectors.", "practical_application": "When one channel is dead or noisy, a technician swaps the suspect cable for a known-good one to confirm the line is bad before rewiring.", "category": "Signal fault", "related_terms": ["Continuity", "Cable tester", "Intermittent", "Cold solder joint", "Patch point", "Signal path"], "common_mistakes": ["Blaming the console channel before testing the cable and connectors on that line.", "Missing an intermittent fault because it only appears when the cable is flexed.", "Not confirming the fault with a known-good cable, so the real problem is missed."], "scenario_contexts": ["One microphone channel is dead while every other channel works.", "A cable that crackles only when a performer moves and flexes it.", "Tracing hum on a single line back to a damaged connector."]}, "ce425f94-e447-4daf-bd98-34227b12ce27": {"definition": "A 'bad pack' is a wireless bodypack transmitter that is failing or non-functional - commonly from a depleted or faulty battery, a damaged input connector or antenna, an intermittent internal fault, or being set to the wrong frequency/group - producing dropouts, noise, or loss of RF from that unit. The term distinguishes a defective transmitter from problems in the receiver or the RF environment.", "plain_english": "A bad pack is a faulty wireless bodypack transmitter. This is the small box a performer wears. A dead battery, a broken plug, or an inside fault can cause dropouts or silence. Swapping in a good pack shows if the pack was the problem.", "purpose_function": "The label points the fault at the worn or faulty transmitter rather than the receiver or antennas. This lets a technician swap the pack quickly to restore the channel.", "practical_application": "When one wireless channel keeps dropping, a technician fits a fresh battery or a spare bodypack to confirm the original pack is bad.", "category": "Wireless fault", "related_terms": ["Bodypack transmitter", "Dropout", "Receiver", "Battery", "Squelch", "Frequency coordination"], "common_mistakes": ["Blaming the receiver or RF when a weak battery in the pack is the real cause.", "Not checking that the pack is on the correct frequency or group for its receiver.", "Ignoring a damaged antenna or input connector on the bodypack."], "scenario_contexts": ["A performer's bodypack drops out while other wireless channels stay solid.", "Battery level on one pack falls fast and its audio starts to gate.", "Swapping a spare bodypack mid-show to restore a failing channel."]}, "6ba224b6-6403-4a7a-bd58-b641ad448efa": {"definition": "A barrel is a small in-line coupler that joins two cables of the same connector type end to end - most often an XLR female-to-female or male-to-male adapter used to extend a mic line or reverse gender, or a coaxial (BNC) barrel that joins two RF or video cables. It carries the signal straight through with no processing, acting only as a passive junction.", "plain_english": "A barrel is a short adapter that joins two cables end to end. It links two of the same kind of plug, like two XLR mic cables. It just passes the signal through. Techs use it to make a cable longer or to swap plug gender.", "purpose_function": "A barrel lets a technician extend a cable run or match connector genders without building a new cable. It provides a quick passive junction in the signal or RF path.", "practical_application": "When a mic cable is a little short, a technician joins two cables with an XLR barrel instead of running a whole new line.", "category": "Connector/adapter", "related_terms": ["XLR connector", "Adapter", "Coupler", "BNC connector", "Gender changer", "Cable run"], "common_mistakes": ["Using several barrels in one run, adding failure points and intermittent contacts.", "Grabbing the wrong gender barrel, so the two cables will not mate.", "Forgetting that a loose barrel joint can cause noise or dropouts on that line."], "scenario_contexts": ["Joining two XLR cables to reach a distant microphone position.", "Reversing connector gender to mate two cables that both end in the same plug.", "Coupling two BNC leads to extend a word-clock or antenna run."]}, "20cafcb5-1ae6-4001-88d4-35e8682bf91a": {"definition": "A blown driver is a loudspeaker transducer that has failed and no longer reproduces sound correctly, typically from an open or shorted voice coil, a voice coil rubbing or seized in the magnetic gap, or mechanical damage to the cone, surround, or diaphragm. Common causes are thermal overload from excessive continuous power and mechanical over-excursion from clipping or over-driving, producing symptoms such as no output, distortion, rattling, or reduced level.", "plain_english": "A blown driver is a speaker part that has failed and no longer plays right. Too much power can overheat its wire coil. Clipping can push it too far. The result is silence, distortion, or a rattle. Only that driver is affected.", "purpose_function": "Recognizing a blown driver tells the technician the fault is in the loudspeaker itself, not upstream gear. It signals the need to repair, recone, or replace that transducer.", "practical_application": "When a cabinet distorts or goes quiet, a technician swaps in a known-good box to confirm the driver is blown before reconing or replacing it.", "category": "Loudspeaker fault", "related_terms": ["Voice coil", "Overexcursion", "Clipping", "Reconing", "Thermal overload", "Crossover"], "common_mistakes": ["Assuming distortion is a blown driver when a clipping amplifier upstream is the real cause.", "Driving speakers from a clipping, overdriven amplifier, which overheats and destroys drivers.", "Confusing a blown driver with a bad cable or a muted channel before testing."], "scenario_contexts": ["A top box plays with harsh distortion after being pushed hard all night.", "A subwoofer makes a rattling or flapping sound instead of clean bass.", "One driver in a multi-way cabinet goes silent while the others still play."]}, "7667d11e-4128-48c0-a7d9-1312b6e1860c": {"definition": "'Bricked' describes a piece of electronic equipment rendered completely non-functional and unrecoverable by normal means - typically after a firmware or software update that was interrupted, corrupted, or incorrect - so it will not boot or respond, being 'as useful as a brick.' A bricked device usually requires a factory recovery procedure, reflashing, or service to restore, if it can be recovered at all.", "plain_english": "Bricked means a device is dead and will not turn on or respond. It often happens when a firmware update fails or gets cut off. The gear becomes as useful as a brick. It usually needs special recovery or a trip to service.", "purpose_function": "The term flags that the failure is in the device's firmware or software state, not a cable or a setting. It warns technicians to protect updates and to seek recovery or service.", "practical_application": "A technician avoids bricking gear by keeping stable power and following the maker's steps during a firmware update, never interrupting it.", "category": "Device fault", "related_terms": ["Firmware", "Firmware update", "Recovery mode", "Reflash", "Bootloader", "Factory reset"], "common_mistakes": ["Cutting power or unplugging a device in the middle of a firmware update, which can brick it.", "Loading the wrong firmware file or version for the model.", "Assuming a frozen device is bricked before trying the maker's recovery procedure."], "scenario_contexts": ["A mixer will not boot after a firmware update lost power partway through.", "A wireless receiver becomes unresponsive after a failed update and needs recovery.", "Loading incorrect firmware leaves a device stuck and needing factory service."]}, "381deeea-698a-47a7-aff1-bcc1e47af1d2": {"definition": "A broadcast split is an isolated feed of the stage microphone and DI signals, distributed by a microphone splitter to a broadcast, outside-broadcast, or recording destination and kept electrically separate from the front-of-house and monitor consoles. The isolation, usually provided by a splitter transformer, prevents one system's gain, phantom power, or grounding from affecting the others and breaks ground loops between them.", "plain_english": "A broadcast split sends a copy of the stage microphones to a TV, radio, or recording team. A special box, called a splitter, makes the copies. It keeps the teams separate. So one team's settings cannot spoil another team's mix. It also helps stop hum between systems.", "purpose_function": "It exists so a broadcast or recording crew can take the same stage sources as the live crews without sharing control of phantom power, gain, or grounding. Transformer isolation prevents ground loops and stops a fault in one system from disrupting the others.", "practical_application": "At a televised concert, a technician patches the stage box into a mic splitter and hands the isolated broadcast split to the outside-broadcast truck, so its engineer mixes independently of front of house.", "category": "Signal distribution", "related_terms": ["Microphone splitter", "Ground loop", "Phantom power", "Front of house (FOH)", "Direct box (DI)", "Isolation transformer"], "common_mistakes": ["Assuming every output of a splitter is transformer-isolated, when the direct output shares ground and phantom power with the source.", "Enabling phantom power from more than one console on a shared direct split, which can conflict and cause faults.", "Forgetting that only one console on a direct split should supply phantom power to a condenser microphone."], "scenario_contexts": ["Feeding an outside-broadcast truck at a televised concert from the same stage microphones used by front of house.", "Providing an isolated recording feed for a live album while monitors and front of house mix separately.", "Splitting a festival's shared stage microphones between rotating consoles plus a broadcast feed."]}, "01913235-5946-49f5-8d0e-240faf92e6f4": {"definition": "A buzzing fret, or fret buzz, is an unwanted rattling tone produced when a vibrating guitar or bass string contacts one or more frets other than the one being fretted. Common causes include string action set too low, insufficient neck relief, uneven or worn fret height, and heavy playing, and it originates at the instrument rather than in the sound system.", "plain_english": "Fret buzz is a rattle you hear when a guitar string touches metal frets it should clear. It often means the strings sit too low or the neck is too straight. Some frets may be worn. The buzz comes from the guitar itself. It is not a fault in the speakers or mixer.", "purpose_function": "Naming it as an instrument fault helps a technician place the noise at its true source. This stops wasted time chasing a rattle through the sound system when the fix belongs on the guitar.", "practical_application": "When a guitar buzzes through the PA, a technician first checks whether the sound is fret buzz at the instrument, by listening unplugged or on headphones, before adjusting EQ or suspecting the rig.", "category": "Instrument fault", "related_terms": ["String action", "Neck relief", "Direct box (DI)", "Signal chain", "Backline", "Distortion"], "common_mistakes": ["Blaming the PA, amplifier, or EQ for a rattle that is actually fret buzz coming from the instrument.", "Confusing fret buzz with a loose connector, a cold solder joint, or a speaker rattle in the signal chain.", "Assuming all string buzz is a fault, when a small amount can be normal depending on setup and playing style."], "scenario_contexts": ["Diagnosing a rattling guitar tone at soundcheck and tracing it to the instrument, not the rig.", "Deciding whether a player's guitar needs a setup by a tech before a show.", "Ruling out fret buzz by monitoring the DI signal on headphones before adjusting channel EQ."]}, "c93c2290-fb62-43a3-ad19-fe5ac015f45d": {"definition": "To bypass the processor is a troubleshooting method in which a signal processor, such as an equalizer, compressor, effects unit, or system DSP, is temporarily removed from the signal path by its bypass control or by re-patching around it, so the signal passes unprocessed. Comparing the sound with and without the device isolates whether that processor is causing a problem such as distortion, noise, level loss, or an unexpected tonal change.", "plain_english": "To bypass a processor means to send the audio around a device so its effect is removed. You use its bypass switch or patch past it. Then you listen. If the problem goes away, that box caused it. If the problem stays, the fault is elsewhere.", "purpose_function": "It exists to test one device at a time by comparing the signal with and without it. This narrows a fault down to a single processor quickly, without rewiring the whole system.", "practical_application": "When a channel sounds distorted, a technician hits bypass on its compressor or EQ, or patches around an outboard unit, to hear whether the processor is adding the distortion.", "category": "Troubleshooting method", "related_terms": ["Signal chain", "Insert point", "Equalizer", "Compressor", "Signal flow", "Patch bay"], "common_mistakes": ["Confusing a hardware bypass that removes the device from the path with a soft bypass that still routes through its converters or gain stage.", "Bypassing a processor but forgetting it was set to make up gain, so the level jumps and masks the real result.", "Changing more than one thing at once, so the test no longer isolates a single device."], "scenario_contexts": ["Checking whether a graphic EQ on a monitor send is the source of unexpected noise.", "Testing if a system DSP preset, rather than the amplifier, is causing a tonal problem.", "Isolating an outboard effects unit suspected of adding distortion to a vocal."]}, "d595f67e-71c9-42c6-a636-71c402e47464": {"definition": "A channel chase is a troubleshooting method of tracing a single channel's signal step by step along its path, from source through cable, stage box, splitter, console input, processing, bus, and output, to locate the exact point where the signal is lost, distorted, or degraded. The technician follows signal flow in order, testing at each stage, rather than guessing at the fault.", "plain_english": "A channel chase means following one channel's signal from start to finish. You check each step in order. Is the sound at the mic? At the cable? At the mixer input? You keep moving along until you find the spot where it fails.", "purpose_function": "It exists to find a fault by method instead of guesswork, by checking signal flow one stage at a time. Working in order makes sure no part of the path is skipped.", "practical_application": "When a channel is silent, a technician chases it from the microphone outward, swapping the cable, checking the stage box, and metering the console input, until the dead point is found.", "category": "Troubleshooting method", "related_terms": ["Signal flow", "Signal chain", "Stage box", "Continuity test", "Console input", "Bypass the processor"], "common_mistakes": ["Skipping stages and guessing at the fault instead of checking the path in order.", "Forgetting the simple checks first, such as a mute, a pad, a routing assignment, or an unplugged cable.", "Not using a meter or headphones to confirm where signal is actually present along the path."], "scenario_contexts": ["Finding why one input channel is dead while the rest of the console works.", "Tracing intermittent dropouts on a single microphone during a performance.", "Locating where a channel's signal is lost between the stage and the front-of-house console."]}, "f493b257-fdc4-400d-9858-3b545aa02953": {"definition": "Channel normalization is the process of adjusting an individual channel's gain so its signal reaches a defined reference level, such as a target peak or unity, giving each channel a consistent and known baseline. This repeatable starting point makes level mismatches, gain-structure errors, and faults easier to judge than leaving channel levels arbitrary.", "plain_english": "Channel normalization means setting a channel's gain so its level matches a chosen reference. Every channel then starts from the same known point. This makes levels easy to compare. It also makes odd readings easier to spot when something goes wrong.", "purpose_function": "It exists to give channels a consistent reference level, so gain-structure and level faults stand out clearly. A known baseline makes measurements repeatable and comparisons fair.", "practical_application": "During setup, a technician normalizes each input's gain to a reference level, so that a channel reading far from that baseline immediately flags a wiring, source, or gain problem.", "category": "Gain structure", "related_terms": ["Gain structure", "Unity gain", "Input gain (trim)", "Signal-to-noise ratio", "Headroom", "Reference level"], "common_mistakes": ["Confusing channel normalization, a gain adjustment to a reference level, with patchbay normalling, which is a fixed connection convention.", "Normalizing to peaks on sources with very different crest factors, so channels end up mismatched in loudness.", "Setting the reference level so high that no headroom remains for peaks."], "scenario_contexts": ["Setting consistent input gains across a console so every channel starts from the same reference.", "Establishing a known baseline before troubleshooting a level mismatch between channels.", "Preparing a repeatable gain structure so a fault shows up as a departure from the reference."]}, "3c1bc298-de16-43a2-a41a-a0766a9a9d21": {"definition": "To chase feedback is a troubleshooting method of locating and removing acoustic feedback in a sound system by identifying which microphone, loudspeaker, or frequency is sustaining the loop and then reducing it. Typically the technician raises gain carefully until the system rings, finds the ringing frequency and cuts it with an equalizer, or repositions or mutes the offending microphone or loudspeaker, aiming to raise usable gain-before-feedback without the system howling.", "plain_english": "Chasing feedback means hunting down the squeal or howl in a sound system. That noise comes from sound looping between a speaker and a mic. You raise the level until it just starts to ring. You find the pitch that rings. Then you cut that pitch with an EQ, or move the mic.", "purpose_function": "It exists to stop feedback while keeping as much level as possible, by targeting the exact cause instead of just turning everything down. Finding the ringing frequency lets you cut only what is needed.", "practical_application": "Before doors open, a technician rings out the monitors, slowly raising each send until it just feeds back and then notching the ringing frequency on a graphic EQ, to chase feedback out of the system.", "category": "Troubleshooting method", "related_terms": ["Acoustic feedback", "Gain before feedback", "Graphic equalizer", "Ringing out", "Monitor wedge", "Notch filter"], "common_mistakes": ["Lowering overall level instead of finding and notching the specific feedback frequency, which wastes usable gain.", "Cutting far too wide a band on the EQ, which removes wanted tone along with the feedback.", "UNSAFE: Ringing out at high level near people, where a sudden loud feedback squeal can harm hearing or damage drivers."], "scenario_contexts": ["Ringing out stage monitors during soundcheck to raise gain before feedback.", "Finding which open microphone is causing a howl during a live event.", "Notching a room's problem frequency on the main system before an event."]}, "ffd1242d-bcde-4ec4-a09f-092fae42d9a8": {"definition": "Choking is the unwanted abrupt truncation of a wanted audio signal caused by an overly aggressive dynamics process, most often a noise gate or downward expander whose threshold is set too high or whose hold or release is too short, so the sustain or natural decay of the sound is cut off. It is heard as notes or words being clipped short, stuttering, or dropping out.", "plain_english": "Choking is when a sound gets cut off too soon and sounds unnatural. It usually happens when a noise gate is set too strict. The gate is meant to shut out quiet noise. But if set wrong, it also chops the wanted sound. Notes get cut short or drop out.", "purpose_function": "Naming this symptom helps a technician trace choppy, cut-off sound back to a mis-set gate or expander. It points to the fix, easing the threshold or timing, rather than blaming the source or the mix.", "practical_application": "When a singer's words keep dropping out, a technician suspects choking and lowers the gate threshold or lengthens its hold and release until the natural sustain returns.", "category": "Dynamics processing", "related_terms": ["Noise gate", "Downward expander", "Threshold", "Release time", "Hold time", "Dynamics processor"], "common_mistakes": ["Setting the gate threshold above the quietest wanted passages, so soft notes are choked off with the noise.", "Using a very fast release or short hold, which chops the natural decay and causes stuttering.", "Blaming the source or the performer for dropouts that are actually a mis-set gate choking the signal."], "scenario_contexts": ["A tom gate closing too fast and choking the drum's natural ring.", "A vocal gate cutting off soft word endings during a quiet passage.", "Diagnosing stuttering on a channel and tracing it to overly aggressive gating."]}, "a3e943ff-5979-400d-8d3e-0d6b91196a12": {"definition": "Clip, or clipping, is the distortion that occurs when a signal's amplitude tries to exceed the maximum level a device or stage can pass, so the waveform peaks are flattened, or clipped, to that ceiling. This flattening adds harmonic and intermodulation distortion, and a clip indicator lights to warn that a stage, such as a preamp, converter, or amplifier, has run out of headroom.", "plain_english": "Clipping happens when a signal is too loud for a device to handle. The device cannot go any higher, so it flattens the tops of the wave. This adds a harsh, distorted sound. A clip light warns you it is happening. The fix is to turn the level down.", "purpose_function": "The clip point marks the ceiling of a stage's usable range, and the clip indicator warns when a signal has hit it. This lets a technician manage gain structure and avoid distortion.", "practical_application": "A technician watches the clip LEDs while setting input gain, backing off the level whenever a stage flashes clip so the signal stays below the distortion point.", "category": "Signal integrity", "related_terms": ["Headroom", "Gain structure", "Distortion", "Clipping the amplifier", "Peak level", "Input gain (trim)"], "common_mistakes": ["Confusing clip distortion with a bad cable or a faulty source, when the real cause is too much gain.", "Assuming a brief clip LED flash is harmless in every stage, when a clipping power amplifier can damage drivers.", "Chasing clipping at the wrong stage instead of finding where in the gain structure headroom runs out."], "scenario_contexts": ["Setting a microphone preamp's gain so peaks stay just below the clip point.", "Spotting a clip LED on an analog-to-digital converter and reducing level to stop digital clipping.", "Tracing harsh distortion on a channel to a stage that is running out of headroom."]}, "a8577e35-9d60-4af7-867e-f9c108eba1cc": {"definition": "Clipping the amplifier is the condition in which a power amplifier is driven beyond its rated output voltage swing, so its output waveform peaks are flattened toward a square shape because the amplifier cannot deliver more voltage from its power supply. Sustained clipping produces heavy distortion and increases the average power and high-frequency energy sent to loudspeakers, which can overheat and damage drivers, especially high-frequency compression drivers and tweeters.", "plain_english": "Clipping the amplifier means pushing a power amp harder than it can go. The amp cannot make the wave any bigger, so it flattens the peaks. This sounds harsh and distorted. It also sends extra energy to the speakers. That extra energy can overheat and burn out the tweeters.", "purpose_function": "Recognizing amplifier clipping matters because it both ruins the sound and can destroy loudspeaker drivers. Spotting it early lets a technician reduce level or manage gain before damage occurs.", "practical_application": "A technician watches an amplifier's clip indicators and pulls the drive level down when they light, rather than pushing the amp into clipping to gain more volume.", "category": "Amplifier fault", "related_terms": ["Clip", "Power amplifier", "Headroom", "Compression driver", "Gain structure", "Loudspeaker protection"], "common_mistakes": ["UNSAFE: Pushing a power amplifier into hard clipping for more volume, which can overheat and destroy compression drivers and tweeters.", "Believing only oversized amplifiers damage speakers, when an underpowered amp driven into clipping is a common cause of tweeter failure.", "Relying only on hearing to catch clipping, when brief clipping peaks can pass unnoticed while still stressing drivers.", "Confusing amplifier clipping with a speaker or crossover fault, and replacing the wrong component."], "scenario_contexts": ["A too-small amplifier run flat out during a loud show, clipping and burning out high-frequency drivers.", "Watching amplifier clip lights at front of house to keep the system out of clipping.", "Diagnosing repeated tweeter failures and finding the amplifier was being driven into clipping."]}, "6ebcbdde-88f8-4bdf-82a5-da4476280448": {"definition": "Clipping the desk is driving a mixing console's signal beyond the maximum level its circuitry can pass, so the waveform peaks are flattened and the output becomes audibly distorted. 'Desk' is common British and live-sound usage for the mixing console, and clipping usually happens when input gain, channel, or master levels exceed the available headroom.", "plain_english": "The desk is the mixing console. Clipping means pushing the signal louder than the desk can handle. The tops of the sound wave get chopped off flat. This adds a harsh, crunchy distortion. You fix it by turning the level down.", "purpose_function": "The term names a common gain-staging fault so technicians can spot and correct it quickly. Recognizing clipping at the console points to too much gain or level rather than a broken component.", "practical_application": "A technician sees the channel or output meters hitting the red clip indicators and hears crackly distortion, then lowers the input gain or fader to restore clean headroom.", "category": "Level/gain fault", "related_terms": ["Headroom", "Gain staging", "Clip LED", "Distortion", "Overload", "Mixing console"], "common_mistakes": ["Pulling the master fader down to cure clipping that is actually happening at the input gain stage, so the distortion remains.", "Confusing clipping distortion with a faulty channel or cable, and swapping gear instead of lowering the level.", "Assuming meters that never reach clip mean there is no problem, when clipping can occur at an earlier gain stage."], "scenario_contexts": ["A vocal mic input is set with too much gain, and the channel clips on loud passages.", "The mix bus output clips into a distorted signal feeding the amplifiers.", "A hot line-level source overloads a channel input, causing crackling on peaks."]}, "6958d91a-d1c9-43f5-8d21-5fcb32175fb8": {"definition": "Clocking noise is unwanted audio - typically clicks, pops, ticks, or dropouts - caused by faults in the digital audio sample clock, such as devices not locked to a common word clock, a sample-rate mismatch, or excessive clock jitter. In a digital audio system every device must be synchronized to a single clock reference, or samples are read at the wrong instants and produce these artifacts.", "plain_english": "Digital audio gear keeps time with a shared clock. If two devices do not share the same clock, samples slip. This creates clicks, pops, or dropouts in the sound. Locking everything to one clock source usually fixes it.", "purpose_function": "The term identifies audio faults that come from clock errors, not from the audio path itself, so technicians check synchronization first. It reminds engineers that digital devices must share one clock reference to stay in sync.", "practical_application": "When a technician hears regular ticks or dropouts across a digital console or audio network, they check that all devices lock to a single master clock at the same sample rate.", "category": "Digital fault", "related_terms": ["Word clock", "Sample rate", "Jitter", "Digital audio", "Dropout", "AES3"], "common_mistakes": ["Setting more than one device as clock master, so the system has competing clocks and produces clicks.", "Mixing devices running at different sample rates and expecting clean audio.", "Blaming the audio cabling for clicks that actually come from a clock synchronization fault."], "scenario_contexts": ["Two digital devices linked by an AES3 connection are not clocked together, and the audio ticks.", "A networked audio device is set to the wrong sample rate and drops out.", "A recording clicks because the interface and converter are not locked to one clock."]}, "caf60834-cf04-4cc7-94eb-e44e703abb10": {"definition": "A continuity check is a test that confirms an unbroken electrical path exists between two points, usually made with a multimeter's continuity or resistance function, which indicates a near-zero-resistance connection, often with an audible beep. In audio work it verifies that cables, connectors, and solder joints carry signal or ground without a break or short.", "plain_english": "A continuity check tests whether electricity can flow through a path. You touch a meter's two probes to the two ends of a wire. If the wire is whole, the meter beeps. No beep means the wire is broken. It is a fast way to find a bad cable.", "purpose_function": "It exists to prove quickly whether a conductor is intact or broken, without needing a live signal. This lets a technician isolate a wiring fault to a specific cable, pin, or joint.", "practical_application": "A technician unplugs a suspect mic cable and uses a multimeter set to continuity to check each pin end to end, finding an open or shorted conductor.", "category": "Test procedure", "related_terms": ["Multimeter", "Cable tester", "Short circuit", "Open circuit", "Pinout", "Dead line"], "common_mistakes": ["UNSAFE: Running a continuity test on a circuit that is still powered, which can damage the meter or give a false reading; test only unpowered, disconnected cables.", "Forgetting that a cable can pass continuity yet still have an intermittent fault that only appears when it is flexed.", "Testing the wrong pins because the connector pinout was not checked first."], "scenario_contexts": ["Checking a mic cable end to end to find a broken conductor.", "Verifying that a solder joint on a repaired XLR connector actually connects.", "Confirming a patch bay point is wired to the intended destination."]}, "16f4cf61-7339-41d8-b82e-f2d6f91d279c": {"definition": "Control but no audio is a troubleshooting symptom in which a device's control or data functions work normally - remote commands respond, indicators light, settings change - yet no audio passes through the signal path. It steers the diagnosis toward the audio chain itself, such as routing, patching, mutes, converters, or the audio network, rather than power or control connectivity.", "plain_english": "Sometimes the gear seems alive but makes no sound. Buttons work, lights come on, and the remote responds. But no audio comes through. This tells you the control side is fine. The problem is in the audio path, like routing or a mute.", "purpose_function": "Naming this pattern helps a technician split the system into a control path and an audio path, and focus on the one that has failed. It rules out dead power and points them to routing, mutes, and audio links instead.", "practical_application": "On a digital console or networked stage box, the surface and metering respond but a channel stays silent, so the technician checks routing, mute state, and the audio network subscription rather than the power.", "category": "Fault symptom", "related_terms": ["Signal flow", "Dead channel", "Mute", "Routing", "Audio network", "Control surface"], "common_mistakes": ["Assuming the whole device is dead because there is no sound, when the control side is clearly working.", "Overlooking a mute, a wrong routing assignment, or an unsubscribed network channel.", "Replacing a unit that responds to control when the fault is only in the audio path."], "scenario_contexts": ["A digital console channel meters and its fader moves, but no audio reaches the mix.", "A networked audio device shows online and controllable but has no audio subscription, so it is silent.", "A processor's front panel and remote respond, yet its output carries no signal."]}, "b6925019-b353-4bbf-832f-aabd629eac88": {"definition": "A cooked driver is a loudspeaker drive unit that has failed from thermal overload, in which sustained excess power overheats the voice coil until its wire insulation, adhesive, or former is damaged - the coil may open-circuit, short, deform, or rub in the magnetic gap. It is a power-related failure caused by driving the loudspeaker beyond its thermal power-handling limit for too long, often made worse by amplifier clipping.", "plain_english": "A speaker's voice coil is a coil of wire that gets hot as it works. Too much power for too long overheats it. The wire can burn, melt its glue, or warp. Then the driver rubs, buzzes, or goes silent. This is called a cooked driver.", "purpose_function": "The term names a heat-based speaker failure so technicians link it to excess power and heat, not to a signal fault. Knowing the cause guides prevention, such as respecting power ratings and avoiding sustained amplifier clipping.", "practical_application": "A technician finds a silent or distorted driver, smells burnt varnish, and measures an open or wrong voice-coil resistance, confirming thermal failure that needs a recone or replacement.", "category": "Loudspeaker fault", "related_terms": ["Voice coil", "Power handling", "Power compression", "Amplifier clipping", "Recone", "Thermal overload"], "common_mistakes": ["Believing only over-powered amplifiers cook drivers, when an underpowered amp driven into hard clipping is a very common cause.", "Confusing a thermally cooked coil with a mechanically damaged over-excursion driver, which needs a different diagnosis.", "Assuming a higher-wattage amplifier is always safer, when excess continuous power can overheat the coil."], "scenario_contexts": ["A subwoofer run at full output for a long set overheats and its voice coil opens.", "A small amp pushed into clipping cooks a high-frequency compression driver.", "A monitor wedge driven past its rated power goes silent mid-show from a burnt coil."]}, "813a3aa1-13dd-4b69-93a5-6745abc00945": {"definition": "A dead channel is a mixing console or signal-path channel that passes no audio, producing no output or metering from a source known to be working. Causes include a muted or unrouted channel, a failed input stage, a faulty cable or connector, or missing phantom power for a condenser source.", "plain_english": "A dead channel is a mixer channel that makes no sound. The source works, but nothing comes through that strip. It might be muted, unrouted, or wrongly patched. It could also be a bad cable or a broken input. You check each of these in turn.", "purpose_function": "The term flags a fault located in one channel rather than the whole system, so a technician can compare it against working channels. It focuses troubleshooting on that channel's routing, mute, gain, and input.", "practical_application": "A technician moves a known-good source to the suspect channel; if it stays silent, they check mute, routing, gain, and phantom power, then the input hardware.", "category": "Fault symptom", "related_terms": ["Dead microphone", "Mute", "Phantom power", "Signal flow", "Gain", "Channel strip"], "common_mistakes": ["Overlooking an engaged mute or a channel that is not routed to the output.", "Forgetting that a condenser mic on that channel needs phantom power to work.", "Assuming the channel hardware failed before swapping in a known-good cable and source."], "scenario_contexts": ["One input on a console produces no signal while the others work.", "A channel is silent because it was left muted or unassigned to the mix.", "A condenser mic gives no output because phantom power is off on that channel."]}, "14558703-973a-40b5-bf3e-5fbe99e142ab": {"definition": "A dead line is a signal cable or line-level connection that carries no signal, usually because of an open (broken) conductor, a bad connector or solder joint, a short, or a disconnected patch. The term describes the cable run or line itself rather than the device at either end.", "plain_english": "A dead line is a cable that carries no signal. The wire may be broken inside, or a plug may be faulty. It could also be unplugged at a patch point. Swapping in a known-good cable, or a continuity test, shows if the line is the problem.", "purpose_function": "The term isolates the fault to the cabling or patch path, separating it from the source and destination gear. This tells a technician to test or replace the line before suspecting the equipment.", "practical_application": "When a signal disappears, a technician substitutes a known-good cable or runs a continuity check on the suspect line to confirm the conductor is broken.", "category": "Fault symptom", "related_terms": ["Continuity check", "Open circuit", "Cable tester", "Patch bay", "Dead channel", "Signal flow"], "common_mistakes": ["Blaming the source or destination device before testing the cable itself.", "Missing an intermittent break that only opens when the cable is moved or flexed.", "Assuming a patched line is connected when the patch point is wrong or unplugged."], "scenario_contexts": ["A stage box channel is silent because a multicore conductor is broken.", "A patch bay line passes nothing because the cable has a cold solder joint.", "A snake line goes dead when its connector is flexed during the show."]}, "761d33d1-e699-495d-bf29-08c9e1f57b94": {"definition": "A dead microphone is a microphone that produces no output signal, even though the input channel and system are otherwise working. Common causes include a faulty or disconnected cable, a muted or unrouted channel, missing phantom power for a condenser or active mic, a flat battery in a wireless or electret unit, or an internal capsule or electronics failure.", "plain_english": "A dead microphone is a mic that gets no sound to the mixer. The cause is often a bad cable or a muted channel. A condenser mic also needs phantom power to work. A wireless mic may have a flat battery. If all that is fine, the mic itself may be broken.", "purpose_function": "The term guides a technician through a quick chain of checks from cable to power to the mic itself. It separates a microphone fault from a channel or system fault.", "practical_application": "A technician swaps in a known-good cable, checks the mute and phantom power, tries the mic on another channel, and replaces the mic only if it is still silent.", "category": "Fault symptom", "related_terms": ["Dead channel", "Phantom power", "Continuity check", "Wireless microphone", "Condenser microphone", "Mute"], "common_mistakes": ["Declaring the mic dead before checking the cable, mute, routing, and phantom power.", "Forgetting that a condenser mic needs phantom power and stays silent without it.", "UNSAFE: Plugging or unplugging a mic cable with the channel unmuted at high gain, which can send a loud transient to the speakers and to hearing; mute the channel first."], "scenario_contexts": ["A condenser vocal mic is silent because phantom power was never switched on.", "A wireless handheld cuts out because its battery is flat.", "A mic produces nothing because of a broken cable, confirmed by swapping a known-good one."]}, "bbb4993c-643f-4b8b-82cb-a7276d0db80b": {"definition": "Live-sound slang for a wireless bodypack transmitter (a \"pack\") that has stopped delivering usable RF or audio to its receiver, so its channel goes silent or drops out. Common causes are a depleted battery, a powered-off or muted transmitter, a failed or disconnected lavalier/headset element, or a lost RF link.", "plain_english": "A dead pack is a body-worn wireless transmitter that has stopped working. Its channel goes quiet. The most common cause is a flat battery. A muted switch or a broken mic connector can also do it.", "purpose_function": "The term flags a specific failure point so a technician checks the transmitter itself, not the console or receiver. Naming the fault speeds up the fix during a live show.", "practical_application": "When a presenter's mic drops out, a technician checks the bodypack first: battery meter, power and mute switches, then the mic element connection.", "category": "Wireless fault", "related_terms": ["Bodypack transmitter", "Dropout", "RF link", "Squelch", "Battery", "Lavalier microphone"], "common_mistakes": ["Blaming the receiver or console when the fault is simply a dead battery in the bodypack.", "Forgetting to check the transmitter's mute or power switch before declaring the pack dead.", "Not carrying charged spare batteries, so a dead pack can stop the show."], "scenario_contexts": ["A lapel mic on a keynote speaker goes silent mid-sentence and the tech suspects a dead pack.", "A guitarist's wireless cuts out during a set because the bodypack battery died.", "During line check a channel shows no RF, pointing to a powered-off or dead pack."]}, "446afdde-7678-43ff-921a-208f21d1543a": {"definition": "Live-sound slang for a floor monitor (wedge) that is producing no sound for the performer it feeds. The cause lies in the monitor path: a muted or unassigned aux/monitor send, a failed amplifier channel or cable, or a blown driver.", "plain_english": "A wedge is the angled speaker on the floor that lets performers hear themselves. A dead wedge is one that has gone silent. Either the signal to it was cut, or the speaker or amp has failed.", "purpose_function": "Naming it points the technician to the monitor signal path, separate from the main PA. This narrows the search to the send, amp, cable, or driver feeding that wedge.", "practical_application": "When a singer signals they cannot hear themselves, the monitor engineer checks the wedge's send level, mute, amplifier, and cabling in turn.", "category": "Monitor fault", "related_terms": ["Stage monitor", "Foldback", "Aux send", "Monitor mix", "Powered speaker", "Mute"], "common_mistakes": ["Assuming the wedge driver blew when the monitor send is simply muted or turned down.", "Confusing a dead wedge with a wedge that is ringing with feedback; the symptoms are opposite.", "Not checking the amplifier channel or speaker cable feeding a passive wedge."], "scenario_contexts": ["A vocalist gestures that they cannot hear during soundcheck, pointing to a dead wedge.", "One wedge in a line of monitors is silent while the others work normally.", "After a patch change a performer's monitor send was left unassigned, leaving a dead wedge."]}, "646815e1-6466-4cab-ac44-ed489b658598": {"definition": "Desense (receiver desensitization) is the reduction of a radio receiver's effective sensitivity caused by a strong nearby RF signal or an elevated RF noise floor overloading or blocking the receiver front end. The wanted signal must then be stronger to be received, cutting operating range and causing dropouts.", "plain_english": "Desense is short for desensitization. A strong nearby radio signal, or high radio noise, makes a wireless receiver go partly deaf. The signal you want then has to be much stronger to get through. Range drops and audio can cut out.", "purpose_function": "The term explains why a wireless system loses range even with a healthy transmitter, steering the technician toward interference rather than a hardware fault.", "practical_application": "Seeing short wireless range near an LED wall or a high-power transmitter, a technician suspects desense and relocates antennas or the interfering source.", "category": "RF interference", "related_terms": ["Intermodulation", "RF noise floor", "Squelch", "Antenna distribution", "Dropout", "Front end"], "common_mistakes": ["Blaming a weak transmitter battery when a strong local signal is desensitizing the receiver.", "Placing receive antennas next to LED walls or Wi-Fi gear, which raises the noise floor.", "Confusing desense (front-end blocking) with intermodulation products, though both hurt reception."], "scenario_contexts": ["Wireless range collapses when an LED video wall is switched on, a classic desense case.", "A nearby high-power transmitter blocks a microphone receiver's front end.", "Co-located antennas overload each other, desensitizing the receivers."]}, "f6d00006-62e9-4d68-997a-12030001045f": {"definition": "A digital tick is a brief, often periodic click in a digital audio signal caused by dropped or corrupted samples. It typically results from clock or synchronization loss, a sample-rate mismatch, or buffer under/overruns between digital devices, such as a word-clock or PTP unlock on an AES3, MADI, or Dante link.", "plain_english": "A digital tick is a small click in digital audio. It happens when the system loses a sample or two. The usual cause is two devices not sharing the same clock. A wrong sample-rate setting can cause it too.", "purpose_function": "It names a clocking or sync symptom, so the technician checks the clock master and sample rate rather than analog cabling.", "practical_application": "Hearing regular ticks over a Dante or AES feed, a technician verifies one clock master and matching sample rates across every device.", "category": "Digital fault", "related_terms": ["Word clock", "Sample rate", "Clock master", "Dante", "AES3", "Jitter"], "common_mistakes": ["Setting two devices as clock master, so they drift and produce ticks.", "Running linked devices at different sample rates over a digital connection.", "Blaming a cable when the real cause is a clocking or sync fault."], "scenario_contexts": ["Regular ticking on a Dante network is traced to a lost PTP clock leader.", "Ticks appear when a recorder is set to 44.1 kHz but the console runs at 48 kHz.", "An AES3 link ticks because the receiving device is not slaved to the source clock."]}, "b25a1d4b-bab2-4a85-bbba-a8a594d5afbc": {"definition": "A direct split (direct output) is the straight-through, hard-wired leg of a microphone splitter that connects the source directly in parallel, with no transformer in the path. It passes the full signal and phantom power, in contrast to a transformer-isolated split, which blocks DC (and thus phantom) and galvanically isolates the grounds.", "plain_english": "A direct split is one output of a mic splitter wired straight through. It shares the mic signal with no transformer in the way. Because it is a direct path, it passes phantom power. It has no isolation, so it cannot break a ground loop.", "purpose_function": "The direct leg feeds the console that supplies phantom power and keeps a full-level, unaltered signal. Splitters use it alongside isolated legs to feed several consoles from one source.", "practical_application": "A technician patches the phantom-supplying console (often FOH) to the direct split, then feeds monitors and broadcast from the transformer-isolated legs.", "category": "Signal distribution", "related_terms": ["Microphone splitter", "Transformer isolation", "Phantom power", "Ground loop", "Ground lift", "Snake"], "common_mistakes": ["Expecting phantom power on a transformer-isolated leg; only the direct split passes it.", "UNSAFE: lifting the mains safety ground to cure hum instead of using the splitter's audio ground-lift switch.", "Feeding two phantom-powered consoles from direct legs and causing phantom conflicts or hum."], "scenario_contexts": ["Splitting stage mics to FOH, monitors, and broadcast, with FOH on the direct split for phantom power.", "A ground-loop hum appears because two consoles share the direct split's grounds.", "A condenser mic on an isolated leg has no phantom, so it is moved to the direct split."]}, "43cb6fee-f481-4660-9fff-2bc9e7e87eea": {"definition": "Informal term for AC mains supply that deviates from a clean, stable sinusoid, containing disturbances such as voltage sags/swells, transients and surges, harmonic distortion, electrical noise/EMI, or frequency variation. These disturbances, formally described under power quality, can induce hum, buzz, or malfunction in audio equipment.", "plain_english": "Dirty power is mains electricity that is not clean and steady. It carries spikes, dips, or electrical noise on top of the normal supply. That noise can add hum or buzz to the audio. It can also make gear behave oddly.", "purpose_function": "The term flags the AC supply itself as a noise or fault source, prompting checks of power quality and proper grounding rather than the audio signal chain.", "practical_application": "Facing persistent hum across several devices, a technician checks for dirty power and uses a power conditioner or a dedicated, correctly grounded circuit, never by lifting the safety ground.", "category": "Power & grounding", "related_terms": ["Ground loop", "Power conditioner", "Mains hum", "Grounding", "Surge", "Harmonic distortion"], "common_mistakes": ["UNSAFE: lifting the equipment safety ground (e.g. a 3-to-2 adapter) to stop hum, which creates a shock and electrocution hazard.", "UNSAFE: running audio gear from ungrounded or miswired outlets without first verifying the receptacle.", "Assuming a power conditioner regulates voltage; most only filter noise and clamp surges.", "Blaming dirty power for hum that is actually an audio ground loop."], "scenario_contexts": ["A buzz on the whole PA at an old venue points to dirty power on the house circuits.", "Lighting dimmers on a shared circuit inject noise into audio, a dirty-power symptom.", "Voltage sags when large HVAC motors start cause amplifiers to misbehave."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"1289eaee-8e7b-4d77-8942-fc92824f896b": {"definition": "A routing error in which one signal reaches a mix output by two paths at once, for example a channel assigned both directly to the main bus and to a subgroup that also feeds the main. The signal then sums twice, raising its level (up to about 6 dB) and risking comb filtering if the two paths differ in time.", "plain_english": "Double assignment means one sound is sent to the same output twice. It can go straight to the main mix and also through a group that feeds the main. The signal then adds to itself and gets louder than expected. Timing differences between the paths can also hurt the sound.", "purpose_function": "Recognising it explains a sudden level jump or hollow tone as a routing mistake, so the technician removes the duplicate path.", "practical_application": "When a channel is oddly loud, a technician checks whether it is assigned to both the main bus and a subgroup that also routes to the main.", "category": "Routing fault", "related_terms": ["Bus", "Subgroup", "Routing", "Main mix", "Comb filtering", "Matrix"], "common_mistakes": ["Assigning a channel to a subgroup and to the main bus when the subgroup already feeds the main.", "Blaming a fader or gain for a level that is really doubled by two routing paths.", "Overlooking comb filtering when the two paths reach the output with different delays."], "scenario_contexts": ["A vocal is about 6 dB too hot because it feeds both a group and the main mix.", "A patch mistake sends one input to two channels that both hit the main bus.", "A drum submix sounds hollow because the kick is assigned direct and through the group."]}, "3fd0f518-f5a8-4f59-beaa-3a4d04e2a8d9": {"definition": "Routing a single channel to two mix buses at the same time (double-bussing). It is sometimes intentional, such as feeding two subgroups or parallel-processing chains, but becomes a fault when those buses recombine at a common output, doubling level and risking comb filtering.", "plain_english": "Double bus means sending one channel to two mix buses at once. Sometimes engineers do this on purpose for parallel effects. It causes trouble when both buses meet again at one output. The signal then adds to itself and can get louder or sound hollow.", "purpose_function": "Understanding it lets a technician tell a deliberate parallel routing from an accidental duplicate that inflates level.", "practical_application": "Setting up parallel compression, a technician buses one channel to a dry group and a compressed group, checking they combine as intended.", "category": "Routing fault", "related_terms": ["Bus", "Subgroup", "Parallel processing", "Routing", "Double assignment", "Main mix"], "common_mistakes": ["Bussing a channel to two groups that both feed the main, which doubles its level.", "Forgetting that two recombined buses can comb-filter if their timing differs.", "Confusing intentional parallel bussing with an accidental double bus."], "scenario_contexts": ["Parallel drum compression: the kit is bussed to a dry group and a squashed group.", "An accidental double bus makes a channel about 6 dB loud when both groups hit the main.", "A stem is double-bussed to the FOH mix and a separate record feed."]}, "c943af8b-fa70-4e8f-99c0-2d9a90e69889": {"definition": "The loud, sustained howl or high-pitched squeal produced when a sound system's output re-enters its own input, for example a microphone picking up its loudspeaker, and the loop gain reaches or exceeds unity at one or more frequencies. The loop then oscillates uncontrollably at those resonant frequencies.", "plain_english": "Feedback squeal is the loud howl or screech from a PA system. It happens when a microphone hears its own speaker and the sound loops back. The loop feeds itself and grows until it screams at one pitch. Lowering the mic level or moving it usually stops it.", "purpose_function": "Naming the runaway loop guides the technician to cut gain, move the mic or speaker, or notch the ringing frequency, protecting both drivers and hearing.", "practical_application": "When a mic starts to ring, a technician pulls that channel's gain and uses an EQ to notch the offending frequency.", "category": "Acoustic fault", "related_terms": ["Gain before feedback", "Ringing out", "Graphic EQ", "Notch filter", "Monitor wedge", "Microphone"], "common_mistakes": ["UNSAFE: pushing gain up to chase level, risking a sudden squeal that can damage hearing and drivers.", "Boosting EQ to brighten a dull mic and triggering feedback instead of cutting the ringing band.", "Aiming a wedge into a cardioid mic's most sensitive angle.", "Confusing feedback with a buzzing cable or ground-loop hum."], "scenario_contexts": ["A handheld mic squeals when a performer walks in front of the main PA.", "A vocalist's wedge rings at one frequency during soundcheck.", "Cupping a mic grille raises effective gain and sets off feedback."]}, "d7250d21-acdb-4efa-89cb-b06568a3e194": {"definition": "A festival split is a microphone/line signal splitter that takes each stage input and distributes it simultaneously to multiple mixing consoles, typically front-of-house, monitors, and a broadcast or recording rig, usually through transformer-isolated or actively buffered outputs. It lets several audio teams share the same stage sources during multi-act events without one console electrically loading or affecting another.", "plain_english": "A festival split copies each stage signal and sends it to several mixing desks at once. This lets the main mixer, the monitor mixer, and a recording team all use the same microphones. Each desk gets its own clean feed.", "purpose_function": "It exists so several consoles can share one set of stage inputs without interfering, and so different acts can swap consoles quickly at festivals. Isolation prevents ground loops and stops one console's phantom power or faults from reaching the others.", "practical_application": "A technician patches stage mics into the split's inputs, runs separate multicore feeds to FOH, monitors, and the broadcast position, and confirms phantom power comes from only the one designated console.", "category": "Signal distribution", "related_terms": ["Microphone splitter", "Transformer isolation", "Ground loop", "Phantom power", "Stage box", "Multicore (snake)"], "common_mistakes": ["Enabling phantom power from more than one console on a transformerless (direct) split tap, which can conflict and damage inputs.", "Assuming every split output is isolated, when hardwired direct taps share ground and can create ground loops.", "Expecting the split alone to cure hum without checking which console supplies phantom power and how grounds are handled."], "scenario_contexts": ["A multi-band festival where FOH, monitors, and a recording rig all need the same stage mics.", "A broadcast truck taking an isolated feed of every stage channel from the split.", "Guest engineers bringing their own consoles that must tap the house stage inputs."]}, "bcec1ed1-cb0d-49d1-927f-036e13111e42": {"definition": "'Fix it upstream' is a troubleshooting principle stating that a problem should be corrected as close as possible to its source in the signal chain, rather than compensated for at a later stage. Correcting the earliest point, such as mic choice, placement, gain, or cabling, stops the fault propagating and avoids stacking corrective processing downstream.", "plain_english": "Fix it upstream means solve a problem where it starts, not later in the chain. If a mic sounds bad, move the mic instead of piling on EQ at the desk. Fixing the source keeps the whole signal clean.", "purpose_function": "It exists to stop technicians masking a root cause with downstream processing, which usually adds noise and complexity. Solving problems at the source gives cleaner audio and fewer knock-on faults.", "practical_application": "When a vocal is harsh, a technician first tries a different mic, position, and correct gain, only reaching for EQ or de-essing once the source is as good as it can be.", "category": "Troubleshooting principle", "related_terms": ["Gain staging", "Garbage in garbage out", "Signal chain", "Root cause analysis", "Microphone placement", "Equalization (EQ)"], "common_mistakes": ["Reaching for channel EQ or plugins before checking mic choice, placement, and gain at the source.", "Assuming downstream processing can fully repair a poorly captured or distorted source.", "Confusing 'upstream' with the console output; upstream means toward the source, not toward the speakers."], "scenario_contexts": ["A muddy drum sound solved by repositioning the mic instead of cutting EQ.", "Hum traced back to a cable or DI at the source rather than gated out at the console.", "Feedback reduced by fixing monitor placement before adding filters."]}, "46c1a82d-605f-4151-ac35-8c5e81db9ec4": {"definition": "To 'flat the channel' is to return all of a channel strip's adjustable processing, including EQ, filters, dynamics, and often the gain trim, to a neutral (unity/zero) state so the channel passes signal without coloration. It is used as a diagnostic baseline to isolate whether a problem originates in the channel processing or somewhere else.", "plain_english": "Flatting a channel means setting all its tone and dynamics controls back to neutral. The channel then passes sound without changing it. Engineers do this to see if the channel settings are causing a problem.", "purpose_function": "It exists to remove processing as a variable during troubleshooting and to give a clean starting point before building a mix. A neutral channel makes it easy to hear the raw source.", "practical_application": "When a channel sounds wrong, a technician flats the EQ and dynamics to check whether the fault lies in the settings or in the source, cable, or preamp.", "category": "Troubleshooting technique", "related_terms": ["Channel strip", "Equalization (EQ)", "Unity gain", "Signal chain", "Bypass", "Gain staging"], "common_mistakes": ["Confusing 'flat' (neutral EQ) with muted or turned down; a flat channel still passes full signal.", "Forgetting to also reset filters, dynamics, and routing, so the channel is not truly neutral.", "Flatting a working channel during a show without noting the original settings to restore them."], "scenario_contexts": ["Isolating whether harshness comes from the EQ or from the mic itself.", "Resetting a channel inherited from a previous act before line check.", "Establishing a neutral baseline before dialing in a new mix."]}, "076b6a82-a4bb-42d4-b45c-5ec7ddb98942": {"definition": "A frequency conflict occurs when two or more signals compete for the same portion of the spectrum: in audio, overlapping instrument or voice energy causes masking and a cluttered mix; in RF/wireless, two systems on the same or adjacent frequencies interfere, causing dropouts or noise. Resolving it means separating the competing sources in frequency, level, or channel assignment.", "plain_english": "A frequency conflict is when two sounds fight for the same pitch range and blur together. It also means two wireless mics on the same channel interfering. The fix is to move one of them to a different range or channel.", "purpose_function": "Naming the problem helps a technician diagnose muddiness and masking in a mix, or interference between wireless systems. It points to the fix: separate the competing sources in frequency or channel.", "practical_application": "A technician carves out overlapping EQ ranges so bass and kick stop masking each other, or re-coordinates two wireless mics onto clear, non-conflicting frequencies.", "category": "Signal problem", "related_terms": ["Masking", "Equalization (EQ)", "Frequency coordination", "Intermodulation distortion", "Feedback", "RF interference"], "common_mistakes": ["Boosting a masked instrument louder instead of carving space with EQ, which worsens the clutter.", "Assuming a wireless dropout is a dead battery when two systems actually share a conflicting frequency.", "Ignoring local TV broadcast and other RF activity when choosing wireless frequencies."], "scenario_contexts": ["A mix where kick and bass occupy the same low range and lose definition.", "Two wireless mics dropping out because they were set to the same frequency.", "Vocals lost behind guitars that share the same midrange."]}, "1552efb1-0c17-4e1e-bdc6-6513500350e4": {"definition": "'Fried' is informal shop language for an electronic component or device that has been permanently damaged, usually by excess voltage, current, or heat, so it no longer functions. Common causes include phantom-power mishaps, incorrect mains voltage, short circuits, and overheating.", "plain_english": "Fried means a part or piece of gear is burned out and dead. Too much voltage, current, or heat has wrecked it. It usually cannot be fixed by changing settings and needs repair or replacement.", "purpose_function": "The term quickly flags that a fault is hardware damage, not a setting or patch error, so the technician stops chasing signal flow and moves to repair or replacement.", "practical_application": "When a channel is dead and swapping cables and settings changes nothing, a technician suspects a fried preamp or output stage and pulls the unit for service.", "category": "Fault condition", "related_terms": ["Phantom power", "Overvoltage", "Short circuit", "Fuse", "Thermal protection", "Signal chain"], "common_mistakes": ["Hot-patching or connecting cables with phantom power engaged, which can damage inputs and passive ribbon microphones.", "Assuming a dead channel is fried when the real fault is a bad cable, an engaged mute, or a wrong patch.", "Repeatedly powering up a suspected fried unit, which can worsen the damage."], "scenario_contexts": ["A DI box that stops working after being plugged into an incorrect supply voltage.", "An amplifier channel that goes silent and smells burnt after a sustained short.", "A console input killed by an accidental power or wiring fault."]}, "30521226-0611-4d69-abb6-9e18da7d8624": {"definition": "A gain-sharing system is an automatic microphone mixer that continuously distributes a fixed total gain among all open microphones in proportion to each mic's relative level, rather than gating channels fully on or off. As one talker gets louder, that channel's gain rises while the others are attenuated, so the summed system gain stays roughly constant, controlling feedback and noise buildup while keeping natural, seamless transitions.", "plain_english": "A gain-sharing automatic mixer shares one total volume across all the open mics. The loudest talker gets more of it, and the quieter mics turn down. This keeps the overall level steady and cuts feedback and noise. Mics fade rather than snap on, so it sounds smooth.", "purpose_function": "It exists to keep many live microphones open without runaway feedback, comb filtering, or noise buildup, while still sounding natural. Sharing gain smoothly avoids the audible chopping of gate-style automatic mixers.", "practical_application": "In panel discussions, houses of worship, and conferences, a technician uses a gain-sharing automixer so every mic stays available but only active talkers dominate the mix.", "category": "Automatic mixing", "related_terms": ["Automatic microphone mixer", "Number of open microphones (NOM)", "Gating automixer", "Feedback", "Comb filtering", "Unity gain"], "common_mistakes": ["Confusing gain-sharing with gating; gating switches channels on and off, while gain-sharing continuously blends them.", "Setting per-channel input gains unevenly, which biases the shared gain toward the loudest input.", "Expecting the automixer to replace good mic technique and placement for feedback control."], "scenario_contexts": ["A conference room with many table mics that must all stay open.", "A house of worship with multiple lectern and lavalier mics.", "A broadcast panel show keeping every guest mic live without feedback."]}, "4842ce57-47ca-4689-a81b-b8e5f877136b": {"definition": "'Gain-staged into a corner' describes a signal chain with such poor gain distribution that no remaining control can fix the result without adding noise or distortion, for example a source set so hot that a downstream stage clips, or so low that later make-up gain also lifts the noise floor. The technician is left with no clean adjustment and must reset gains earlier in the chain.", "plain_english": "Being gain-staged into a corner means the levels were set so badly there is no good fix left. One stage is too loud and distorts, or too quiet and noisy. The only real cure is to reset the levels from the start.", "purpose_function": "The phrase warns that fixing levels only at the end of a chain fails when earlier stages are already wrong. It pushes the technician to correct gain at the source instead of chasing symptoms.", "practical_application": "When a channel is noisy no matter how the faders are set, a technician re-checks the preamp trim and each stage's level to escape the corner they gain-staged into.", "category": "Gain staging", "related_terms": ["Gain staging", "Headroom", "Noise floor", "Signal-to-noise ratio", "Clipping", "Unity gain"], "common_mistakes": ["Trying to fix a bad level with a downstream fader when the real problem is the input trim.", "Turning up make-up gain to recover a weak signal, which also raises the noise.", "Setting preamp gain by fader position instead of by meters and headroom."], "scenario_contexts": ["A quiet source boosted late in the chain that becomes hissy.", "A preamp set too hot so every later stage clips.", "A DI level so low that the console gain adds audible noise."]}, "b40615f2-a821-4cfb-91e1-ce94ba634195": {"definition": "'Garbage in, garbage out' (GIGO) is the principle that an output can never exceed the quality of its input: a poorly captured, noisy, or distorted source cannot be fully repaired by later processing. In audio it stresses that good results depend first on the source, meaning instrument, room, mic, placement, and gain, before any mixing or effects.", "plain_english": "Garbage in, garbage out means a bad recording stays bad no matter what you do later. Processing cannot rescue a noisy or distorted source. Good sound starts with a good source, mic, and setup.", "purpose_function": "The principle reminds technicians to invest effort at the capture stage, because no plugin or EQ can restore information that was never recorded cleanly. It underpins the 'fix it upstream' approach.", "practical_application": "Before recording, a technician spends time on instrument tuning, mic choice, and placement, knowing a clean source saves hours of futile fixing in the mix.", "category": "Troubleshooting principle", "related_terms": ["Fix it upstream", "Signal chain", "Microphone placement", "Gain staging", "Signal-to-noise ratio", "Noise floor"], "common_mistakes": ["Believing EQ, plugins, or restoration tools can fully fix a badly recorded or distorted source.", "Rushing the capture stage while planning to 'fix it in the mix'.", "Blaming the console or effects for problems that actually started at the source."], "scenario_contexts": ["A distorted guitar DI that cannot be cleaned up later in the mix.", "A vocal recorded in a noisy room that stays noisy through processing.", "A poorly placed drum mic that no EQ can make sound natural."]}, "ea6f9681-33c0-486c-bf31-057a78ec367f": {"definition": "A ground lift switch is a control, commonly on direct boxes (DIs), some interfaces, and rack gear, that disconnects the audio signal ground/shield path (XLR pin 1 or the input-to-output ground link) between two devices to break a ground loop that causes hum and buzz. It lifts only the audio/chassis signal ground; it does not, and must not, disconnect the AC mains safety (protective earth) ground, which must always stay connected.", "plain_english": "A ground lift switch breaks a hum-causing loop between two devices. It disconnects only the audio ground or cable shield, not the power safety ground. Flip it to stop hum and buzz. Never use a power adapter that lifts the wall safety ground, because that can cause a deadly shock.", "purpose_function": "It exists to break ground loops safely by opening the audio signal-ground path between two units, removing hum and buzz without defeating the equipment's mains safety earth.", "practical_application": "When a DI or line feed hums, a technician flips the ground lift to disconnect the audio ground and quiet the buzz, while leaving every power-cord safety ground intact.", "category": "Grounding control", "related_terms": ["Ground loop", "Direct box (DI)", "Pin 1 problem", "Hum and buzz", "Shielding", "Protective earth ground"], "common_mistakes": ["UNSAFE: Using an AC 'cheater' adapter to defeat the power-cord safety ground; this creates a shock and electrocution hazard and violates electrical code.", "UNSAFE: Assuming the audio ground lift also removes the mains safety earth; it does not, and the power ground must never be disconnected.", "Trying the ground lift for problems it cannot fix, such as buzz from a bad cable, dimmer noise, or a real pin 1 wiring fault.", "Leaving the lift engaged without confirming that shielding and safety grounds remain correct."], "scenario_contexts": ["A DI box between a keyboard and the console producing hum until the ground lift is engaged.", "A laptop feed buzzing because its charger and the console sit on different grounds.", "Diagnosing whether hum is a ground loop (helped by the lift) or a cable fault (not helped)."]}, "fbe1bdde-6eb3-4895-bc11-39e040a3ccc8": {"definition": "Half-split troubleshooting is a systematic fault-location method that tests the signal path at its midpoint to determine which half contains the fault, then repeatedly halves the suspect section until the failure is isolated to a single stage, cable, or component. Because each test eliminates roughly half of the remaining chain, it locates a fault in far fewer steps than checking every point in sequence.", "plain_english": "Half-split troubleshooting finds a fault by testing the middle of the signal path first. If the sound is good there, the problem is later on. If not, it is earlier. You keep splitting the bad part in half until you find it.", "purpose_function": "It exists to find a fault quickly in a long signal chain by discarding half the possibilities with each test, instead of checking every connection one by one. This saves time under show pressure and reduces guesswork.", "practical_application": "When a channel is dead, a technician injects or monitors signal at a midpoint such as the stage box or console input, decides which half is faulty, and repeats until the bad cable, connector, or unit is found.", "category": "Troubleshooting technique", "related_terms": ["Signal chain", "Signal flow", "Intermittent", "Line check", "Test tone", "Root cause analysis"], "common_mistakes": ["Starting at one end and checking every point in order, which is far slower than splitting the chain in half.", "Changing more than one thing at a time, so it is unclear which action fixed or moved the fault.", "Forgetting to test at a true midpoint, which wastes the halving advantage."], "scenario_contexts": ["A dead vocal channel traced by testing signal at the stage box, then narrowing to a specific cable.", "No audio at the main speakers, split-tested between console output, processor, and amplifier.", "An intermittent dropout isolated by checking successive midpoints of a long multicore run."]}, "d83d6509-b369-44ea-a5d4-503f929f5377": {"definition": "The head amp (head amplifier, HA) is the microphone/line input preamplifier that raises a low-level source to the console's operating level; the head-amp control is the gain/trim adjustment (and associated pad and phantom-power settings) that sets how much amplification the input stage applies. On digital systems the head amp usually sits in a remote stage box, and the control is operated remotely from the console surface or software.", "plain_english": "The head amp is the mic preamp that boosts a weak microphone signal up to a usable level. The head-amp control sets how much boost, or gain, it adds. On digital desks you can often adjust it from far away at the mixing position.", "purpose_function": "It exists to set the input gain correctly so the signal is strong enough to use but not so hot that it clips, which is the foundation of good gain staging. Remote head-amp control lets one engineer set gains for stage inputs from the console.", "practical_application": "During line check a technician turns up the head-amp control until the source peaks healthily with headroom, then leaves it, adjusting the fader (not the head amp) for balance during the show.", "category": "Input control", "related_terms": ["Gain staging", "Microphone preamplifier", "Input rack", "Pad", "Phantom power", "Headroom"], "common_mistakes": ["Riding the head-amp gain like a fader during a show, which changes gain structure and, on shared splits, affects other consoles.", "Setting head-amp gain by fader position instead of by the input meter and available headroom.", "Forgetting that on a shared digital snake, head-amp changes may follow the source to other desks unless gain tracking is configured."], "scenario_contexts": ["Setting input gain for each stage mic during line check on a digital console.", "Adjusting a distant stage-box preamp remotely from the front-of-house position.", "Coordinating head-amp gain between FOH and monitors when they share one stage rack."]}, "74b7a88e-dfa2-43ad-adec-b11d2db78188": {"definition": "A hollow sound is a subjective tonal defect in which audio seems thin, distant, and lacking body, as though heard through a tube, typically caused by comb filtering from phase cancellation when a signal combines with a delayed copy of itself (from a second microphone, a reflection, or a summed direct-plus-mic path), or by a broad midrange dip. It signals cancellations that scoop energy out of parts of the spectrum rather than a level problem.", "plain_english": "A hollow sound is thin and empty, like talking into a pipe or a barrel. It often happens when two copies of the same sound mix together and partly cancel. That cancelling removes chunks of the tone and leaves it sounding scooped out.", "purpose_function": "Naming the symptom points a technician toward its usual cause, phase cancellation and comb filtering, rather than toward simple EQ. It directs the fix to mic placement, polarity, and timing instead of just boosting levels.", "practical_application": "When a miked source sounds hollow, a technician checks for a second open mic, a reflective surface, or a direct-plus-mic sum, then fixes spacing, polarity, or delay before reaching for EQ.", "category": "Signal problem", "related_terms": ["Comb filtering", "Phase cancellation", "Polarity", "3:1 rule", "Equalization (EQ)", "Reflection"], "common_mistakes": ["Trying to cure hollowness with EQ boosts alone when the real cause is phase cancellation between two paths.", "Placing two mics too close together and ignoring the 3:1 spacing guideline.", "Overlooking a flipped polarity or a summed direct-and-mic signal as the source of the cancellation."], "scenario_contexts": ["A vocal that goes thin when a second nearby mic is opened.", "A guitar that sounds hollow when its DI and mic are summed out of time.", "A lectern mic thinned by strong reflections off a hard desk surface."]}, "6d1f06c6-92f4-4754-8abf-b04bbb3c55f6": {"definition": "A hot line is a conductor that is energized, that is, carrying voltage relative to ground; in AC mains distribution it is the ungrounded 'line' (live) conductor at supply potential relative to the neutral and equipment-grounding conductors. Any hot line must be treated as a shock and arc hazard until verified de-energized and locked out, because contact can cause severe injury or death.", "plain_english": "A hot line is a wire that is live, meaning it is carrying electrical voltage. In wall power it is the line, or live, conductor. Always treat any hot line as dangerous. It can give a serious shock and can kill you.", "purpose_function": "The term flags that a conductor is energized so workers know to isolate, verify dead, and lock out power before touching it. Correctly identifying the hot conductor is essential for safe wiring, testing, and fault finding.", "practical_application": "Before servicing powered gear or mains wiring, a technician uses a tester to confirm whether a line is hot, then de-energizes and locks/tags it out before working, never relying on a switch alone.", "category": "Electrical safety", "related_terms": ["Neutral", "Equipment grounding conductor", "Lockout/tagout", "Mains voltage", "Protective earth ground", "Ground fault"], "common_mistakes": ["UNSAFE: Assuming a line is dead because a switch is off; it must be tested and locked out, since switches and wiring can be miswired or backfed.", "UNSAFE: Working on or probing an energized (hot) line without proper insulated tools, PPE, and training as required by NFPA 70E and OSHA.", "Confusing the mains 'hot' (line) conductor with the audio-signal 'hot' (non-inverting, pin 2) leg; they are unrelated and carry very different hazards."], "scenario_contexts": ["Verifying which mains conductor is live before wiring or repairing a power connector.", "Locking out an energized circuit before servicing a powered amplifier rack.", "Diagnosing why a chassis is 'buzzing' or shows voltage, indicating a possible hot-to-chassis fault."]}, "87e41c75-e1cf-4258-90a4-d4b2a85d22e1": {"definition": "An input rack (stage rack, I/O rack, or stage box) is the on-stage enclosure where microphones and instruments plug in and whose head-amp preamps convert those sources to line or digital level, transmitting them to one or more consoles over a digital snake (e.g., Dante, MADI, or a proprietary link). It concentrates many stage inputs at the source so a single cable replaces a heavy analog multicore.", "plain_english": "An input rack is a box on stage where the mics and instruments plug in. It changes those signals so they can travel to the mixing desk over one thin cable. It often holds the mic preamps as well.", "purpose_function": "It exists to gather all stage sources at one point, boost and digitize them, and send them to the console over a single lightweight cable instead of a bulky analog snake. This simplifies cabling and lets consoles share the same inputs.", "practical_application": "A technician patches each stage mic and DI into the input rack, then runs one network or MADI cable to the console, checking that head-amp gain and phantom power are set per channel at the rack.", "category": "System hardware", "related_terms": ["Stage box", "Digital snake", "Head-amp control", "Multicore (snake)", "Dante", "Festival split"], "common_mistakes": ["Assuming inputs are patched one-to-one to console channels when the rack's routing or sample-rate/clock must be configured first.", "Overlooking that on a shared rack, head-amp and phantom settings can affect every console taking those inputs.", "Neglecting a stable word-clock or network configuration, causing dropouts mistaken for cable faults."], "scenario_contexts": ["Setting up a digital console so one CAT5/fiber cable carries all stage inputs from the rack.", "FOH and monitors both taking inputs from a single shared stage rack.", "Troubleshooting a dead channel by checking the patch and gain at the input rack itself."]}, "cd28f010-9d45-4d8b-87ae-d3204ca254d6": {"definition": "An intermittent fault is one that appears and disappears irregularly rather than remaining constant, so the equipment works normally at some times and fails at others, often triggered by movement, vibration, temperature, or connector wear. Because the fault is frequently absent during testing, it is among the hardest failures to reproduce and diagnose.", "plain_english": "An intermittent fault comes and goes instead of staying. The gear may work fine, then cut out, then work again. These faults are hard to find because they often hide the moment you try to test them.", "purpose_function": "The term tells a technician the fault is not constant, so diagnosis must provoke the failure, for example by flexing cables or tapping connectors, rather than assuming the last test result is the whole picture. Recognising intermittency guides the search toward loose, worn, or thermal causes.", "practical_application": "To catch an intermittent dropout, a technician wiggles connectors, flexes suspect cables, and monitors while moving gear, then replaces the marginal cable, jack, or connection once the fault is provoked.", "category": "Fault condition", "related_terms": ["Half-split troubleshooting", "Cold solder joint", "Connector", "Cable tester", "Signal chain", "Dropout"], "common_mistakes": ["Declaring a unit fixed because it works during testing, when the intermittent fault simply did not appear.", "Replacing whole units instead of finding the loose connector, worn jack, or cracked solder joint actually at fault.", "Not stressing the system (flexing cables, tapping, warming/cooling) to reproduce the fault before diagnosing."], "scenario_contexts": ["A mic that cuts out only when the cable is moved at the connector.", "A console channel that drops out when the rack warms up during a show.", "A crackle that appears only when a plug is nudged, pointing to a worn jack."]}, "d1803b3d-aa80-41e4-b06b-6b08162ece67": {"definition": "An isolated output is an output that is galvanically separated from the source, typically by an audio transformer (or opto-isolator), so signal passes across while there is no direct electrical (ground) connection between the two devices. This broken ground path prevents ground loops and the resulting hum and buzz, and can also block DC and provide safety separation between systems.", "plain_english": "An isolated output lets sound pass but keeps the two devices apart. Cutting the direct ground link stops the loop that makes hum and buzz. A small transformer inside usually does the job.", "purpose_function": "It exists to pass audio between devices while blocking the ground continuity that creates hum-inducing ground loops, and to keep one system's electrical faults or noise from crossing into another. Isolation is common on splits, DIs, and interconnects between separate power systems.", "practical_application": "When feeding a broadcast truck, a recording rig, or a device on another power source, a technician uses an isolated (transformer) output to prevent hum and keep the systems electrically separate.", "category": "Signal distribution", "related_terms": ["Transformer isolation", "Ground loop", "Direct box (DI)", "Festival split", "Ground lift switch", "Balanced line"], "common_mistakes": ["Assuming any output is isolated; only transformer or opto-isolated outputs break the ground path, not standard direct outputs.", "UNSAFE: Treating audio (signal) isolation as a substitute for mains safety earthing; the equipment grounding conductor must always remain connected.", "Expecting isolation to fix hum caused by a bad cable, pin 1 wiring fault, or dimmer noise, which it will not."], "scenario_contexts": ["Sending an isolated feed to a broadcast or recording truck to avoid a ground loop.", "Splitting stage inputs to a second console through transformer-isolated outputs.", "Connecting two systems on different mains circuits without hum by using an isolated output."]}, "77c70e0d-bc28-4486-8087-bf41f4fd43f7": {"definition": "'Kill the channel' is informal live-sound instruction to immediately silence a single console channel, normally by engaging its mute (or pulling the fader fully down), so that input stops contributing to any mix. It is used to stop feedback, noise, an open mic, or a fault quickly without altering other channels or the rest of the system.", "plain_english": "Kill the channel means mute or turn off one input on the mixing desk. It instantly stops that channel's sound. Engineers do this to cut feedback, a noisy input, or an open mic in a hurry.", "purpose_function": "It exists as a fast, reversible way to remove one problem source from the mix without touching anything else, buying time to diagnose the fault. Muting rather than unplugging keeps settings intact for restoring the channel later.", "practical_application": "When one mic starts ringing into feedback or picks up a loud clatter, the engineer kills (mutes) that channel at once, fixes the cause, then unmutes it.", "category": "Troubleshooting technique", "related_terms": ["Mute", "Fader", "Feedback", "Channel strip", "Kill the wedge", "Gain staging"], "common_mistakes": ["Pulling the fader down instead of using mute, so any post-fader sends or effects may still pass signal.", "Killing the wrong channel under pressure because channels were not clearly labeled.", "Forgetting to unmute the channel after the problem is solved, leaving a source silent."], "scenario_contexts": ["Muting a vocal mic that suddenly rings into feedback.", "Killing a channel whose mic was knocked and is making loud noise.", "Silencing an unused open mic that is adding stage noise to the mix."]}, "5fe35163-1f7a-4df3-83f4-26c533c217ae": {"definition": "'Kill the wedge' is informal live-sound instruction to immediately silence a floor monitor (wedge) by muting its output or pulling down its send/level, usually to stop feedback originating at that monitor or to remove a hazard or distraction on stage. It targets the specific monitor rather than the whole monitor system or the main mix.", "plain_english": "A wedge is the angled speaker on the floor that lets performers hear themselves. Kill the wedge means mute it or turn it off. Engineers do this fast to stop feedback howling from that monitor.", "purpose_function": "It exists to quickly remove a feeding-back or unwanted monitor from the stage without changing the front-of-house mix or other monitors. Silencing the specific wedge stops the feedback loop at its source.", "practical_application": "When a wedge starts to ring, the monitor engineer kills that wedge (mutes its output), identifies the offending frequency or mic, then brings it back once controlled.", "category": "Troubleshooting technique", "related_terms": ["Stage monitor (wedge)", "Feedback", "Monitor mix", "Kill the channel", "Ring out", "Graphic equalizer"], "common_mistakes": ["Muting the whole monitor mix or the wrong wedge instead of the one feeding back.", "Killing the wedge but not addressing the cause, so feedback returns when it is turned back up.", "Confusing a wedge (floor monitor) send with the performer's channel, silencing the wrong path."], "scenario_contexts": ["A floor wedge howling into feedback during a vocal.", "Silencing a performer's wedge who has moved to in-ear monitors.", "Killing a wedge whose feedback is bleeding into the front-of-house mix."]}, "30d6193a-f14c-45c4-88cd-f0a40ad0dad4": {"definition": "A known-good replacement is a component, cable, or device already confirmed to be working that is temporarily substituted for a suspect one to determine whether the original is at fault. If swapping in the known-good item clears the problem, the original was defective; if the fault remains, it lies elsewhere in the chain.", "plain_english": "A known-good replacement is a part you already know works. You swap it in for a part you think is broken. If the problem goes away, the old part was the cause. If not, the fault is somewhere else.", "purpose_function": "It gives a fast, reliable way to confirm or rule out a suspect part without test gear, by comparing behaviour against a proven-working equivalent. This narrows a fault down one part at a time.", "practical_application": "When a channel is dead, a technician swaps the mic cable for a known-good one, then the mic, then the input, isolating the fault step by step.", "category": "Troubleshooting technique", "related_terms": ["Half-split troubleshooting", "Signal chain", "Fault isolation", "Cable tester", "Intermittent", "Substitution method"], "common_mistakes": ["Using a replacement that has not actually been verified as working, which gives a false result.", "Swapping several parts at once, so you cannot tell which one fixed the problem.", "Blaming hardware before ruling out settings, patching, phantom power, or an engaged mute."], "scenario_contexts": ["Swapping a suspect XLR cable for a tested one to find a dead line.", "Replacing a wireless receiver with a spare to confirm a faulty unit.", "Trying a known-good DI box to isolate a buzzing input."]}, "610a71ad-c432-40be-8855-96b65a68a0ac": {"definition": "'Let the smoke out' is informal shop slang for permanently destroying an electronic component or device through overvoltage, overcurrent, or overheating, often visibly emitting smoke as it fails. It jokingly references the notion that parts run on 'magic smoke' and stop working once that smoke escapes.", "plain_english": "Let the smoke out is a joking way to say gear got burned out. Too much power or heat wrecks a part, and it may actually smoke. Once that happens, the part is dead. It needs repair or replacement, not new settings.", "purpose_function": "The phrase flags that a failure is permanent physical damage, not a setting or patch error, so the technician stops chasing signal flow and investigates the cause before any repower.", "practical_application": "When a unit puffs smoke and goes silent, a technician cuts power at once, notes what caused it, and pulls the device for service rather than switching it back on.", "category": "Fault condition", "related_terms": ["Fried", "Overvoltage", "Short circuit", "Fuse", "Thermal protection", "Component failure"], "common_mistakes": ["UNSAFE: Powering a smoking unit back on to 'see what happens', risking fire, worse damage, and electric shock.", "Ignoring the smell of burnt electronics instead of shutting the system down immediately.", "Assuming the visibly burnt part is the whole fault when it may be a symptom of another problem."], "scenario_contexts": ["A power supply that smokes after being fed the wrong mains voltage.", "A resistor that burns out from a short during a repair.", "An amplifier channel that fails with a puff of smoke under a shorted load."]}, "b234adf0-3c7f-4579-8e58-3fbee38e7ec2": {"definition": "To 'lift the ground' is to disconnect the audio signal ground or cable-shield path between two devices, typically via a DI or interface ground-lift switch or by opening pin 1 at one end, in order to break a ground loop that causes hum and buzz. It refers only to the audio/chassis signal ground and must never mean defeating the AC mains safety (protective earth) ground, which must always remain connected.", "plain_english": "Lifting the ground means breaking a hum-causing loop between two devices. You disconnect only the audio ground or cable shield, not the power safety ground. This can stop hum and buzz. Never remove the wall power safety ground, because that can cause a deadly shock.", "purpose_function": "It exists to cure ground-loop hum by opening one audio ground path so unwanted current stops flowing through the signal shield, all without disturbing the equipment's mains safety earth.", "practical_application": "When a DI or line feed hums, a technician engages the ground-lift switch to disconnect the audio ground, while leaving every power-cord safety ground fully intact.", "category": "Grounding control", "related_terms": ["Ground loop", "Ground lift switch", "Direct box (DI)", "Pin 1 problem", "Hum and buzz", "Protective earth ground"], "common_mistakes": ["UNSAFE: Using an AC 'cheater' plug or adapter to defeat the power-cord safety ground; this creates a shock and electrocution hazard and violates electrical code.", "UNSAFE: Believing an audio ground lift also removes the mains safety earth; it does not, and the power ground must never be disconnected.", "Lifting the ground for hum that is really a bad cable, dimmer noise, or a pin 1 wiring fault, which the lift cannot fix.", "Lifting grounds at random instead of tracing which connection actually forms the loop."], "scenario_contexts": ["A hum that clears when the DI ground-lift switch is engaged between a keyboard and console.", "A laptop feed buzzing because its charger and the console sit on different grounds.", "Deciding whether hum is a ground loop, helped by lifting, or a cable fault, which it will not fix."]}, "b233f303-7a96-45c8-9fd4-4d11f835525b": {"definition": "'Limiter light show' is informal slang for the limiter or clip indicators on amplifiers, loudspeaker processors, or console channels flashing frequently or continuously, showing the signal is repeatedly reaching the limiter threshold. It signals the system is being driven at or beyond its clean/safe level, and that drive or gain should be reduced.", "plain_english": "A limiter light show is when the limiter or clip lights keep flashing. It means the signal is being pushed too hard, so the limiter keeps catching it. It is a warning to turn things down before the sound suffers or the gear is stressed.", "purpose_function": "The phrase draws attention to constant limiting as a warning sign, prompting the technician to lower the drive level so the system stays clean and protected instead of being clamped all the time.", "practical_application": "When an amp's limit LEDs flash on every beat, a technician pulls back the console output or drive gain until the lights only flicker on the loudest peaks.", "category": "Level indication", "related_terms": ["Limiter", "Clipping", "Gain staging", "Headroom", "Amplifier protection", "Metering"], "common_mistakes": ["Treating constant limiting as normal instead of a sign the system is overdriven.", "Turning down the amp output while leaving the drive clipping upstream, so limiting continues.", "Assuming flashing limit lights always mean damage, when brief peak limiting can be normal."], "scenario_contexts": ["Powered speakers whose limit LEDs stay lit through a loud set.", "A DSP loudspeaker processor limiting hard because its input drive is set too high.", "Console output meters pinned while the amp limiters flash on every beat."]}, "b212dbd1-ca81-4de0-b2a9-bc3775564836": {"definition": "'Link but no audio' describes a networked-audio fault (e.g. Dante or AES67) in which the Ethernet link is established, the port link light is on, and devices appear on the network, yet no audio passes. Typical causes are missing or failed subscriptions, clock/sync errors, incorrect routing or patching, muted channels, or a switch blocking the required multicast or QoS traffic.", "plain_english": "Link but no audio means the network connection is fine but no sound gets through. The devices can see each other, yet audio does not flow. Common causes are missing routing, a clock problem, a mute, or a switch blocking the traffic.", "purpose_function": "The phrase separates a physical/network-connection problem from an audio-routing problem, telling the technician the cabling and link are good and to look instead at subscriptions, clocking, patching, or switch settings.", "practical_application": "When a Dante device shows a green link but silence, a technician checks subscriptions, clock-master status, and channel patching in Dante Controller before touching any cables.", "category": "Network fault", "related_terms": ["Link light", "Dante", "Clock (PTP/word clock)", "Subscription", "Multicast", "Signal chain"], "common_mistakes": ["Reseating and swapping cables when the link light already proves the physical connection is good.", "Overlooking a clock or sync error, which stops audio even when routing looks correct.", "Forgetting to make or confirm the subscription/patch that actually routes the audio.", "Ignoring switch settings such as blocked multicast or missing QoS."], "scenario_contexts": ["A Dante stagebox shown online in Controller but passing no channels to the console.", "A network mic system linked to the switch yet silent because the clock master dropped.", "Audio lost after a switch swap that no longer passes the required multicast traffic."]}, "b487b392-1897-4ff9-9483-5cd89a44faa0": {"definition": "A link light is an LED on a network port, device, or switch that indicates a valid Ethernet physical-layer connection to another active device; it lights when a link is successfully negotiated and may blink or change colour to show activity or link speed. In networked audio and AV it is the first check that a cable run and port are electrically connected.", "plain_english": "A link light is a small LED that shows a network cable is properly connected. When it is on, the port has found a working connection at the other end. It is the first thing to check when a network device seems offline.", "purpose_function": "It gives an at-a-glance confirmation that the physical Ethernet connection and cabling are good, so a technician can quickly rule the cable and port in or out during troubleshooting.", "practical_application": "When a networked device seems offline, a technician checks the link light at both ends of the cable to confirm the physical connection before looking at addressing or routing.", "category": "Status indicator", "related_terms": ["Link but no audio", "Ethernet", "Dante", "Network switch", "Activity light", "Auto-negotiation"], "common_mistakes": ["Assuming a lit link light means audio or data is actually flowing, when it only confirms a physical link.", "Confusing the link LED with the activity LED, which blinks with traffic.", "Ignoring link-speed colour codes that reveal a connection negotiated at the wrong speed."], "scenario_contexts": ["Confirming a stagebox is cabled to the switch by its port link light.", "A dark link light revealing a bad patch cable or dead port.", "Checking both ends of a long Cat cable run for link before chasing configuration."]}, "c7990c45-253e-4d62-9a60-a5507c49bb7e": {"definition": "'Loop problem' is general troubleshooting slang for any fault caused by an unintended closed loop in a system. In audio the most common is a ground loop, which injects hum and buzz; related cases include an acoustic feedback loop (howl or ringing) and, on networked-audio systems, an Ethernet switching loop that floods the network. Diagnosis centres on finding and breaking the offending loop.", "plain_english": "A loop problem is trouble caused by a path that circles back on itself. The most common is a ground loop that adds hum. It can also mean feedback that howls, or a network cable loop that jams the system. The fix is to find the loop and break it.", "purpose_function": "The phrase groups faults by their shared cause, an unwanted loop, pointing the technician toward finding and opening that loop rather than just treating the symptom.", "practical_application": "When hum, howl, or a flooded network appears, a technician looks for the loop, such as two ground paths, a mic feeding its own speaker, or a doubled network link, and breaks it.", "category": "Signal problem", "related_terms": ["Ground loop", "Feedback", "Lift the ground", "Hum and buzz", "Network loop", "Signal chain"], "common_mistakes": ["Masking ground-loop hum with EQ or a noise gate instead of finding and breaking the loop.", "UNSAFE: Breaking a ground loop by removing the mains safety earth instead of lifting only the audio ground.", "Assuming every hum is a ground loop when it may be a bad cable or a pin 1 fault.", "Creating an Ethernet switching loop by patching two switch ports together without loop protection."], "scenario_contexts": ["Hum traced to a ground loop between two grounded devices.", "Acoustic feedback ringing from a mic looping through its own monitor.", "A networked-audio system flooded by an accidental switch-to-switch loop."]}, "e7f8f686-2453-4b6d-a93d-0ab4fb13f6fa": {"definition": "Loose hardware vibration is a mechanical buzz or rattle produced when a loose screw, panel, grille, connector, or rack fitting vibrates sympathetically at certain frequencies and levels, usually driven by loudspeaker energy. It is a physical (acoustic/mechanical) noise rather than an electrical signal fault, and is cured by locating and tightening the offending hardware.", "plain_english": "Loose hardware vibration is a buzz or rattle from something physically shaking. Loud sound makes a loose screw, grille, or panel vibrate at certain notes. It is not an electrical problem. You fix it by finding and tightening the loose part.", "purpose_function": "Naming this cause reminds the technician that some buzzes are mechanical, not electronic, so the fix is to find and secure vibrating hardware rather than chase the signal chain.", "practical_application": "When a buzz appears only at certain frequencies or volumes, a technician touches or tightens grilles, screws, panels, and rack ears to find the vibrating part.", "category": "Fault condition", "related_terms": ["Loose lug buzz", "Rattle", "Sympathetic resonance", "Buzz", "Loudspeaker enclosure", "Intermittent"], "common_mistakes": ["Blaming the console, EQ, or a cable for a buzz that is really vibrating hardware.", "Chasing the noise electronically when it only appears at specific loud frequencies.", "Tightening one screw and stopping, when several loose fittings may rattle at different notes."], "scenario_contexts": ["A loudspeaker grille buzzing on low bass notes.", "A rack panel or blank rattling near a subwoofer.", "A loose connector shell vibrating against a chassis during loud passages."]}, "f76d5b92-0181-4e27-a019-619419b54391": {"definition": "Loose lug buzz is a rattling or buzzing noise caused by a loose drum lug or tension rod (or a similar loose threaded fitting) vibrating sympathetically when the instrument, or nearby loud sound, excites it. On a miked drum kit it is a common source of a mystery buzz that appears only at certain pitches, and it is cured by tightening or seating the loose lug.", "plain_english": "Loose lug buzz is a rattle from a loose drum lug or tension rod. When the drum is hit, the loose part vibrates and buzzes into the mic. It shows up only at certain notes. You fix it by tightening the loose lug.", "purpose_function": "The term points to a mechanical rattle at the instrument as the source of a buzz, so the technician checks and tightens drum hardware instead of blaming the mic, cable, or console.", "practical_application": "When a drum mic picks up a buzz on certain hits, a technician taps around the kit and tightens loose lugs, tension rods, and snare parts until the rattle stops.", "category": "Fault condition", "related_terms": ["Loose hardware vibration", "Sympathetic resonance", "Rattle", "Buzz", "Microphone placement", "Snare buzz"], "common_mistakes": ["Blaming the microphone, cable, or channel for a buzz that is really loose drum hardware.", "Adding EQ or a gate to hide the buzz instead of tightening the loose lug.", "Checking only the drum being played, when a loose lug on another drum can rattle sympathetically."], "scenario_contexts": ["A tom miked for recording that buzzes on certain notes from a loose lug.", "A snare drum rattling because a tension rod has worked loose.", "A mystery kit buzz traced to a loose lug excited by the kick drum."]}, "7a56db1a-e634-4b96-8966-358ce3582328": {"definition": "A low-frequency howl is acoustic feedback that oscillates in the bass or low-mid region, heard as a deep rumbling or booming tone rather than a high squeal. It occurs when a microphone or pickup re-captures the system's own low-frequency output, often reinforced by room modes, stage resonance, or proximity effect, and the loop gain at that frequency reaches or exceeds unity.", "plain_english": "A low-frequency howl is deep feedback. It is a low, rumbling tone that builds when a mic hears its own sound from the speakers. It sits in the bass range, not the high squeal range. You stop it by lowering gain or notching out that frequency.", "purpose_function": "Naming the problem tells a technician the feedback is low, not high, which points to different causes and fixes. Low howl is usually tied to room modes, mic proximity effect, or subwoofer energy, so it guides where to cut gain or EQ.", "practical_application": "When a stage rumbles or booms near the edge of feedback, a technician high-pass filters unused low end, checks mic placement and proximity effect, and notches the offending low frequency instead of just pulling the whole channel down.", "category": "Feedback condition", "related_terms": ["Feedback", "Room mode", "Proximity effect", "Notch it", "High-pass filter", "Gain before feedback"], "common_mistakes": ["Assuming all feedback is a high squeal and missing a slow low-frequency build until it dominates.", "Boosting low EQ for warmth without a high-pass filter, which invites low howl on open mics.", "Cutting the master fader for everything instead of notching the single low frequency that is ringing."], "scenario_contexts": ["A vocal mic booming when the singer cups it or works in close, raising the proximity bass.", "A room mode reinforcing a low tone until the system rings at that pitch.", "Stage wedges adding low energy that couples back into open microphones."]}, "cbb32401-50a0-45ed-9ed7-135ce9032baa": {"definition": "'Magic smoke' is humorous shop language for the visible smoke or vapor released when an electronic component is destroyed by excess current, voltage, or heat. It references the joke that components run on trapped smoke, so once the smoke escapes the part is permanently dead; in practice it signals overload or catastrophic failure of a component such as a resistor, capacitor, semiconductor, or transformer.", "plain_english": "Magic smoke is a joke name for the smoke that puffs out when a part burns up. Once you let the smoke out, the part is dead for good. It means real damage, not a setting you can fix. The smoke can be toxic, so do not breathe it.", "purpose_function": "The phrase instantly flags that a fault is destructive hardware failure, not a patch or setting error, so the technician stops the source of overload and moves to repair or replacement. It also warns that power must be removed before more damage or hazard occurs.", "practical_application": "When a unit emits smoke or a burnt smell, a technician immediately removes power, does not re-energize it, ventilates the area, and pulls the device for service rather than trying to run it again.", "category": "Fault condition", "related_terms": ["Fried", "Overvoltage", "Short circuit", "Fuse", "Thermal protection", "Overcurrent"], "common_mistakes": ["UNSAFE: Re-powering a device that has smoked, which can worsen damage or start a fire.", "UNSAFE: Leaning in to sniff or inhaling the fumes, which can contain toxic combustion products.", "Assuming the fault is a setting when burnt smell or smoke means a component has physically failed.", "Replacing only a blown fuse without finding what caused the overload, so it fails again."], "scenario_contexts": ["A power amplifier that smokes and goes silent after a sustained short across its output.", "A DI box or pedal that releases smoke when fed the wrong supply voltage.", "A power supply that puffs and dies, taking the device offline until it is serviced."]}, "b65aeeb9-e050-4c86-8f32-1931be659aa2": {"definition": "A mix problem is a sound-quality issue that arises from mixing decisions, such as level balance, equalization, dynamics, panning, or effects, rather than from a hardware fault or signal-path failure. Diagnosing it means recognizing that the signal chain works correctly and the fault lies in how the sources are balanced and processed.", "plain_english": "A mix problem is a bad-sound issue caused by mix choices, not broken gear. Levels, EQ, or balance are set wrong. The fix is to adjust the mix. You do not need to swap cables or hunt for a fault.", "purpose_function": "Labeling something a mix problem separates artistic and balance issues from technical faults, so the technician stops testing hardware and starts adjusting levels, EQ, and processing. It focuses effort on the right kind of fix.", "practical_application": "When vocals get lost or the low end is muddy but every channel passes signal cleanly, a technician treats it as a mix problem and rebalances faders, carves EQ, and manages dynamics rather than chasing a fault.", "category": "Mix fault", "related_terms": ["Masking", "Equalization (EQ)", "Gain staging", "Frequency conflict", "Not an audio problem", "Balance"], "common_mistakes": ["Chasing a hardware fault, swapping cables and channels, when the real issue is balance or EQ.", "Turning a masked instrument louder instead of carving EQ space, which just makes the mix cluttered.", "Blaming the console or speakers for a muddy result that comes from mix decisions."], "scenario_contexts": ["Vocals buried under guitars even though every channel is working normally.", "A boomy, muddy mix caused by overlapping low-end levels rather than a faulty subwoofer.", "A harsh mix traced to aggressive EQ boosts instead of a broken input."]}, "740763ba-d04e-497d-b4e1-cef9b31dbfbb": {"definition": "'Mute first, diagnose second' is a live-sound troubleshooting principle stating that when a sudden loud noise, feedback, or unexpected signal appears, the first action is to mute or pull down the affected channel or output to protect hearing and loudspeakers, and only then investigate the cause. Silencing the fault immediately limits the risk before any diagnosis begins.", "plain_english": "Mute first, diagnose second means silence the sound before you look for the cause. A sudden loud noise or feedback can hurt ears and blow speakers. So you cut it fast. Then you figure out what went wrong.", "purpose_function": "The rule exists to prevent hearing damage, speaker damage, and audience shock during a live fault, where a loud problem can cause harm in seconds. It puts safety and protection ahead of curiosity so damage is contained first.", "practical_application": "When a channel erupts into feedback or a loud pop, a technician mutes that channel or the main output at once, then checks the source, gain, and routing to find the cause with the sound safely stopped.", "category": "Troubleshooting principle", "related_terms": ["Feedback", "Mute", "Master fader", "Hearing protection", "Notch it", "Signal chain"], "common_mistakes": ["UNSAFE: Leaving a loud feedback or noise running while investigating, risking hearing damage and blown drivers.", "Muting the wrong channel because the source of the noise was not confirmed first.", "Forgetting to note or restore the muted state, leaving a needed channel silent later in the show."], "scenario_contexts": ["A channel bursting into feedback mid-show, muted at once before the cause is found.", "A loud pop or crackle from a failing cable, cut immediately to protect the PA.", "An open mic picking up a sudden bang that is muted first, then investigated."]}, "52308b0a-e2f6-4fd1-9bb1-4bb9b1912948": {"definition": "'Never lift safety earth' is a mandatory electrical-safety rule stating that the mains protective earth (equipment grounding conductor) of any powered device must never be disconnected, including as a means of curing hum or ground-loop noise. The safety earth carries fault current to ground and keeps exposed metalwork at earth potential; defeating it, for example with a 'cheater' adapter or a lifted ground pin, creates a shock and electrocution hazard and violates electrical code.", "plain_english": "Never lift the safety earth means keep the power ground connected at all times. Some people pull it to stop hum, but that is very dangerous. Without it, a fault can put deadly voltage on the metal case. Touching that case could kill you. Fix hum a safe way instead.", "purpose_function": "The rule exists because the protective earth is the last line of defense against electric shock: it gives fault current a safe path and trips the breaker. Lifting it to chase quiet audio trades a nuisance hum for a lethal hazard, so it is never acceptable.", "practical_application": "When a system hums, a technician keeps every power-cord safety ground intact and instead breaks the loop with an audio ground-lift switch, a transformer isolator (DI or line isolator), or correct pin 1 wiring.", "category": "Safety practice", "related_terms": ["Protective earth ground", "Ground loop", "Ground lift switch", "Transformer isolation", "Direct box (DI)", "Pin 1 problem"], "common_mistakes": ["UNSAFE: Using an AC 'cheater' plug or clipping the ground pin to remove hum, which creates a shock and electrocution hazard and breaks electrical code.", "UNSAFE: Confusing the audio signal ground lift with the mains safety earth; only the audio ground may be lifted, never the power ground.", "Assuming a system that works fine without its earth is safe, when it is only one internal fault away from a live chassis."], "scenario_contexts": ["A humming backline where the earth stays connected and an isolation transformer breaks the loop instead.", "A rig on a cheater plug found during a safety check and corrected before use.", "Diagnosing hum on stage while keeping every power-cord safety ground intact."]}, "28cceecd-92c3-4727-ac8f-7dcab2df8517": {"definition": "'Not an audio problem' is a troubleshooting conclusion that the fault does not originate in the audio signal path or equipment, but in an adjacent system such as mains power, a data or control network, an instrument or its cabling, playback software, or the acoustic environment. Reaching it redirects the technician to investigate outside the audio chain.", "plain_english": "Not an audio problem means the fault is not in the sound gear at all. The real cause might be power, a network, a bad instrument, or software. It reminds you to stop testing the audio path. Look outside it instead.", "purpose_function": "The label saves time by stopping a fruitless search inside the mixer and cables when the true cause lies elsewhere. It widens the technician's view to power, network, source instruments, and software as possible culprits.", "practical_application": "When a laptop's audio stutters, a technician who has ruled out cables and the console recognizes it as not an audio problem and checks the computer's CPU load, buffer settings, or network instead.", "category": "Troubleshooting principle", "related_terms": ["Root cause analysis", "Signal chain", "Mix problem", "Fix it upstream", "Ground loop", "Buffer size"], "common_mistakes": ["Endlessly swapping audio cables and channels when the fault is in power, a laptop, or a network.", "Blaming the sound system for a dead or badly tuned instrument at the source.", "Missing that a dropout is a data or clocking issue rather than an analog audio fault."], "scenario_contexts": ["A digital dropout caused by a lost network clock rather than a bad audio cable.", "A buzz that turns out to be a lighting dimmer or bad mains circuit, not the console.", "A soft or dead sound traced to a flat instrument battery, not the input channel."]}, "7684424a-858a-48e6-b6f7-692dd8a083d2": {"definition": "To 'notch it' is to apply a narrow, deep equalization cut (a notch filter) at a single problem frequency to remove it while leaving the surrounding spectrum largely unaffected. It is most often used to suppress a specific feedback tone or a discrete resonance or hum, using a high-Q parametric band or a dedicated feedback suppressor.", "plain_english": "To notch it means to cut one narrow band of sound with an EQ. You use it to kill a single ringing feedback tone or a buzz. It removes just that pitch. The rest of the sound is left alone.", "purpose_function": "Notching exists to fix a single offending frequency without dulling the whole signal, which a broad cut or a lower fader would do. It buys extra gain before feedback while keeping the source sounding natural.", "practical_application": "When a mic rings at one pitch near feedback, a technician sweeps a narrow parametric band to find that frequency and cuts it, or lets a feedback suppressor place the notch automatically.", "category": "Troubleshooting technique", "related_terms": ["Notch filter", "Parametric EQ", "Q (bandwidth)", "Feedback", "Gain before feedback", "Low-frequency howl"], "common_mistakes": ["Using a wide, deep cut instead of a narrow notch, which removes tone the source needs.", "Notching many frequencies to mask poor mic placement or monitor aim instead of fixing the cause.", "Cutting the wrong frequency because the ringing pitch was not correctly identified first."], "scenario_contexts": ["A monitor wedge ringing at one frequency that is notched to raise gain before feedback.", "Removing a discrete mains hum or whistle without dulling the full signal.", "Ringing out a room by finding and notching the frequencies that feed back first."]}, "efdc10e6-3042-4884-af87-a50f1149f755": {"definition": "'On the edge' describes a sound system operating just below the threshold of instability, most commonly right at the point where the gain is close to triggering acoustic feedback (loop gain near unity). A system on the edge may ring faintly, sound tense, or break into feedback at the slightest increase in level or change in mic position.", "plain_english": "On the edge means the system is running right where feedback is about to start. One small push and it will ring or howl. The sound may already feel tense or ringy. Engineers back off the gain a little to stay safe.", "purpose_function": "The phrase warns that there is no headroom left before feedback, so any extra gain or movement will cause a howl. It tells the technician to reduce gain, notch resonances, or improve mic and monitor placement before pushing further.", "practical_application": "When channels start to ring faintly as faders come up, a technician recognizes the system is on the edge, pulls back a few dB of gain before feedback, and notches problem frequencies to regain margin.", "category": "Feedback condition", "related_terms": ["Feedback", "Gain before feedback", "Notch it", "Low-frequency howl", "Ringing out", "Headroom"], "common_mistakes": ["Pushing gain higher when the system already rings, tipping it straight into feedback.", "Ignoring faint ringing as harmless when it signals almost no margin is left.", "Blaming a single mic when the whole system is at its feedback limit and needs less overall gain."], "scenario_contexts": ["Monitors ringing faintly at soundcheck, warning of little gain before feedback.", "A vocal channel that howls the instant the singer turns toward a wedge.", "A room pushed for maximum level where any small change triggers feedback."]}, "86b08af2-334b-4d54-9efa-8d8d0680dcba": {"definition": "An open line is a signal path with a break in electrical continuity, an open circuit, so no signal passes through it. The break may be a severed conductor, a cold or broken solder joint, a disconnected connector pin, or a failed switch contact, and it typically measures as very high or infinite resistance across the line.", "plain_english": "An open line is a broken signal path. Somewhere a wire or joint is not connected, so no sound gets through. It is like a gap in a garden hose that stops the water. A meter reads the break as no connection.", "purpose_function": "Naming a fault as an open line tells the technician the problem is a break in the wiring, not a setting or level. It points straight to testing the continuity of cables, connectors, and joints.", "practical_application": "When a channel is dead, a technician uses a cable tester or multimeter to find the open line, then repairs the joint, connector, or cable.", "category": "Fault condition", "related_terms": ["Continuity test", "Short circuit", "Cold solder joint", "Cable tester", "Signal chain", "Multimeter"], "common_mistakes": ["Assuming a dead channel is an open line before checking mutes, patching, and gain settings.", "Testing continuity on a cable still connected to powered gear instead of isolating it first.", "Overlooking an intermittent open line that only breaks when the cable is flexed."], "scenario_contexts": ["A mic cable that passes no signal because a pin has broken free of its solder cup.", "A patch bay point that reads open due to worn or dirty contacts.", "An intermittent dropout traced to an open line inside a connector."]}, "99ab3d7a-9e61-4025-9d53-c02dc04be462": {"definition": "An open voice coil is a loudspeaker-driver failure in which the voice-coil winding, or its lead-in wires, has broken and lost electrical continuity, so the driver receives no current and produces no sound. It usually measures as infinite DC resistance across the driver terminals, and is commonly caused by overheating from sustained overpowering.", "plain_english": "The voice coil is the wire coil that makes a speaker cone move. An open voice coil means that wire has broken. No current can flow, so the speaker stays silent. Too much power for too long often burns it open.", "purpose_function": "The term pinpoints the fault inside the driver itself, not the amplifier, cable, or signal. It tells the technician the driver must be reconed or replaced.", "practical_application": "When one driver is silent, a technician disconnects it and measures its DC resistance; an infinite reading confirms an open voice coil.", "category": "Loudspeaker fault", "related_terms": ["Voice coil", "Reconing", "Continuity test", "Impedance", "Thermal failure", "Loudspeaker driver"], "common_mistakes": ["Assuming an open voice coil when the fault is really a broken cable or a lost amplifier channel.", "Measuring impedance with the driver still connected through the crossover, which can hide the open reading.", "Overpowering drivers over time, which overheats and eventually burns the coil open."], "scenario_contexts": ["One box in an array goes silent while the others play, pointing to an open voice coil.", "A driver reads infinite resistance on a meter after a night of overpowering.", "A blown high-frequency compression driver traced to an open voice coil."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"05dbc33b-c1ba-487f-a079-dde1d48307bc": {"definition": "'Out of gas' is informal shop language for a power amplifier, or a powered system, that has reached the limit of its available output power and can deliver no more level without clipping. The system has exhausted its headroom, so pushing it harder only drives it into distortion rather than increasing clean output.", "plain_english": "Out of gas means an amplifier has no more power to give. It is already working as hard as it can. Turning it up just makes it distort, not get louder. It is like flooring a car that has nothing left.", "purpose_function": "The phrase tells the technician the shortfall is a power or headroom limit, not a gain or routing fault. It signals the need for more amplifier power or more efficient loudspeakers, not more level.", "practical_application": "When a system will not get louder and distorts at the top, a technician recognises it is out of gas and adds amplifier power or higher-sensitivity speakers.", "category": "Amplifier condition", "related_terms": ["Headroom", "Clipping", "Amplifier power", "Loudspeaker sensitivity", "Overload", "Gain staging"], "common_mistakes": ["Driving a clipping amplifier harder to chase level, which can overheat and damage high-frequency drivers.", "Confusing 'out of gas' (a power limit) with a gain or routing problem.", "Adding more input gain instead of more amplifier power to a system already at its limit."], "scenario_contexts": ["A small PA that cannot fill a larger room and distorts at full level.", "Amplifier clip lights flashing constantly because the system is out of gas.", "A subwoofer rig that runs out of headroom during loud passages."]}, "9c060dd7-ce73-418a-944f-1a2ac3309572": {"definition": "Out of polarity means two related signals have opposite absolute polarity, so one is an inverted (mirror-image) copy of the other. When such signals are summed, or when two loudspeakers are wired in reverse, they cancel rather than reinforce, causing level loss and a thin, hollow sound, most noticeably in the low frequencies. It is distinct from being out of phase, which is a time (delay) difference rather than an instantaneous sign inversion.", "plain_english": "Out of polarity means one signal is flipped compared to another. As one pushes, the other pulls by the same amount. Added together, they cancel and the sound gets thin and quiet. A common cause is speaker wires or a cable connected backwards.", "purpose_function": "The term flags a sign-inversion problem, so the technician looks for reversed wiring or a polarity switch, not a level fault. Fixing it restores full level and solid low end.", "practical_application": "When the low end disappears with two mics or two speakers combined, a technician checks polarity and flips the polarity switch or corrects the reversed connection.", "category": "Signal problem", "related_terms": ["Polarity", "Phase", "Comb filtering", "Cancellation", "Polarity switch", "Loudspeaker wiring"], "common_mistakes": ["Confusing polarity (an instant sign flip) with phase (a time delay); the fixes differ.", "Wiring one loudspeaker's terminals in reverse, putting it out of polarity with the others.", "Swapping XLR pins 2 and 3 on a cable, which inverts polarity through that line."], "scenario_contexts": ["A stereo pair that sounds thin and hollow because one channel is out of polarity.", "A kick drum losing punch when top and bottom snare mics are out of polarity.", "A speaker that pulls while its neighbour pushes, cancelling the bass."]}, "d35ee84c-073e-4898-ab81-5df99ab2da16": {"definition": "An output rack is the equipment rack, sited near the loudspeakers in a distributed sound system, that holds the output-side devices: power amplifiers or amplified stage boxes, system processors and DSP, and the output stage of a digital snake that converts the console's feed into the signals driving the PA. It is the counterpart to the input (stage) rack that gathers microphone and line sources.", "plain_english": "An output rack is a case of gear placed near the speakers. It holds the amplifiers and processors that drive the PA. In a digital system it turns the console's signal back into the feeds the speakers need. It is the opposite end from the input rack that collects the mics.", "purpose_function": "It concentrates output amplification and processing at the speaker end, cutting long analog runs and keeping amplifier-to-speaker cables short. This improves signal quality and simplifies system wiring.", "practical_application": "A technician sites the output rack near the PA, sends the console feed to it over a digital link, and patches its amplifier outputs to the loudspeakers.", "category": "System infrastructure", "related_terms": ["Stage rack", "Digital snake", "Power amplifier", "Loudspeaker processor", "Stage box", "Amplifier"], "common_mistakes": ["Confusing the output rack (amplifier and processor end) with the input or stage rack that collects sources.", "Running long speaker cables from a distant rack instead of siting the output rack near the PA.", "Overlooking the cooling and power needs of amplifiers packed into the output rack."], "scenario_contexts": ["A touring rig where amplifiers live in an output rack at the base of the PA.", "A digital system splitting inputs at a stage rack and amplification at an output rack.", "An installed venue with the output rack in an amplifier room feeding the house speakers."]}, "8f1fc5ee-a4d8-4b92-8b86-14df1f561338": {"definition": "Overload is the condition in which a signal, circuit, or device is driven beyond its rated capacity. In an audio stage it means the input or output level exceeds the maximum the stage can handle, forcing it into clipping and audible distortion; in electrical terms it is current or power drawn beyond a device's safe rating, which can trip protection or cause damage.", "plain_english": "Overload means something is pushed past its limit. A signal too strong for a circuit gets clipped and distorts. Too much current for a device can trip its protection or harm it. An overload light warns you before the sound turns ugly.", "purpose_function": "Overload indicators and limits warn the technician that a stage is being driven too hard, so level can be reduced before distortion or damage occurs. The concept protects both audio quality and equipment.", "practical_application": "Seeing an input overload LED flicker, a technician lowers the preamp gain or pads the input until the signal sits safely below clipping.", "category": "Fault condition", "related_terms": ["Clipping", "Headroom", "Pad", "Gain staging", "Clip indicator", "Distortion"], "common_mistakes": ["Ignoring an overload light and leaving the input to clip and distort.", "Confusing overload (too hot a level) with a wiring fault or a noise problem.", "Adding a pad but forgetting to reset gain, so the stage still overloads downstream."], "scenario_contexts": ["A loud vocalist making the preamp overload LED flash on peaks.", "A hot line source overloading a mic-level input until a pad is inserted.", "An amplifier protection circuit engaging under an output overload."]}, "1ddae38c-c106-461b-98e5-20e2ab230384": {"definition": "A phantom master is a master control on a mixing console or preamp that switches the 48-volt phantom power supply on or off for a whole group of inputs, or for the entire console, rather than channel by channel. It provides one global point to enable the DC powering that condenser and active microphones require.", "plain_english": "Phantom power is the 48 volts a mixer sends up the mic cable to run condenser microphones. A phantom master is one switch that turns that power on or off for many channels at once. It saves flipping each channel by hand. Turn it off before plugging in ribbon mics.", "purpose_function": "It exists to enable or disable phantom power globally, which is handy on consoles powering many condenser mics. A single master avoids setting each channel separately.", "practical_application": "Before line check, a technician confirms the phantom master is on so condenser mics power up, and off when patching ribbon or sensitive dynamic mics.", "category": "Console control", "related_terms": ["Phantom power", "Condenser microphone", "Ribbon microphone", "Preamp", "48V", "Direct box (DI)"], "common_mistakes": ["Patching or unpatching microphones with the phantom master on, which can damage ribbon mics and stress inputs.", "Assuming a channel is powered when only the master switch, not the per-channel switch, is engaged.", "Leaving the phantom master off, then wondering why every condenser mic is silent."], "scenario_contexts": ["A console with one master switch enabling 48V across a bank of condenser mics.", "A silent condenser mic traced to the phantom master being switched off.", "Powering down phantom at the master before connecting a vintage ribbon mic."]}, "ada8c876-bf3a-4091-b309-f064264380a7": {"definition": "A phantom problem is a fault that appears to exist but has no identifiable cause when investigated, or an intermittent fault that comes and goes and cannot be reliably reproduced. The symptom may be genuine but elusive, or it may stem from a misreading, an unrelated change, or an intermittent connection that behaves normally during testing.", "plain_english": "A phantom problem is a fault that hides when you look for it. Here \"phantom\" means the fault hides, not phantom power. It comes and goes, so you cannot make it happen on cue. Sometimes it is a loose connection that behaves during testing. Sometimes the real cause is somewhere you did not expect.", "purpose_function": "The term names the frustrating class of faults that vanish under testing, reminding the technician to hunt for intermittent connections and to change one variable at a time. It guards against 'fixing' something that was never the cause.", "practical_application": "Facing a dropout that will not repeat, a technician flexes cables and connectors and swaps suspect items methodically to expose the phantom problem.", "category": "Fault condition", "related_terms": ["Intermittent fault", "Open line", "Cold solder joint", "Signal chain", "Cable tester", "Root cause analysis"], "common_mistakes": ["Declaring a phantom problem fixed after a change that did not actually address the cause.", "Not testing methodically, so an intermittent fault keeps escaping diagnosis.", "Overlooking loose or intermittent connections that behave normally while being tested."], "scenario_contexts": ["A crackle that disappears whenever the technician touches the suspect cable.", "An intermittent dropout during a show that will not repeat at soundcheck.", "A 'fault' that turns out to be a mis-set control rather than broken gear."]}, "c579e897-1d9f-4272-9cff-6e2aba45c060": {"definition": "'Phasey' is informal descriptive language for audio that has a hollow, thin, swirling, or comb-filtered character caused by phase or polarity interaction between combined signals. It typically results from summing two mics on one source, mixing a signal with a delayed copy of itself, or combining out-of-polarity feeds, producing frequency-dependent cancellation.", "plain_english": "Phasey describes sound that seems hollow, thin, or swirly. It happens when two versions of the same sound mix and partly cancel. Using two mics on one instrument is a common cause. The result loses body and can seem to move.", "purpose_function": "The word alerts a technician that combining signals is causing cancellation, pointing to mic placement, timing, or polarity as the fix. It describes a symptom that guides diagnosis.", "practical_application": "When a multi-mic source sounds phasey, a technician adjusts mic spacing, checks polarity, and aligns timing to reduce the cancellation.", "category": "Signal problem", "related_terms": ["Comb filtering", "Phase", "Polarity", "Out of polarity", "Microphone placement", "3:1 rule"], "common_mistakes": ["Fixing a phasey sound with EQ alone instead of correcting mic placement or timing.", "Ignoring the 3:1 mic spacing guideline when using several mics on one source.", "Confusing a phasey (comb-filtered) sound with simple dullness or a bad EQ setting."], "scenario_contexts": ["Two overhead drum mics that sound thin and phasey when summed to mono.", "A guitar mic and a DI combined out of alignment, giving a phasey tone.", "A stereo mix that goes hollow and phasey when checked in mono."]}, "c0c61b0c-988b-4299-81a0-1ba72a0e2b21": {"definition": "A pin test is a continuity check of an audio connector's individual pins, typically the three pins of an XLR (pin 1 ground/shield, pin 2 hot, pin 3 cold), using a dedicated cable tester or a multimeter. It confirms each conductor is continuous end-to-end and not open, shorted to another pin, or shorted to the shell, isolating opens, shorts, and mis-wires in cables and connectors.", "plain_english": "A pin test checks each wire inside an audio plug. A tester or meter shows if a pin is broken, shorted, or wired wrong. It quickly finds a bad cable so you can swap it.", "purpose_function": "It exists to prove or rule out a cable or connector as the fault, so a technician can find bad wiring fast rather than chasing the problem elsewhere in the system.", "practical_application": "When a channel is dead or noisy, a technician runs a pin test on the suspect cable to see if a pin is open, shorted, or swapped before replacing gear.", "category": "Troubleshooting technique", "related_terms": ["XLR connector", "Cable tester", "Continuity", "Pin 1 problem", "Multimeter", "Signal chain"], "common_mistakes": ["Assuming a cable is good because it worked before; intermittent breaks often only show under flex during a pin test.", "Testing only static continuity and missing an intermittent short that appears when the cable is moved.", "Blaming the console or microphone before pin-testing the cable that connects them."], "scenario_contexts": ["A dead mic line traced to an open pin 2 in the XLR cable.", "An intermittent channel that drops out when a cable is wiggled during a pin test.", "Sorting a box of mixed cables into working and faulty before a show."]}, "646ffdc8-e91c-4366-bb68-df93eafc2e55": {"definition": "'Pin-two problem' is informal shorthand for polarity inconsistencies arising from the XLR pin-2-hot wiring convention. Standards (AES14, IEC 60268-12) define pin 2 as the hot, in-phase (positive) audio conductor and pin 3 as the return; equipment or cables that instead place the hot signal on pin 3 invert polarity when combined with pin-2-hot gear, causing partial or total cancellation.", "plain_english": "Pro audio agrees that pin 2 of an XLR plug carries the plus signal. Some old or mis-wired gear puts it on pin 3 instead. Mixing the two flips the signal and sounds thin or hollow. Checking pin 2 keeps everything lined up.", "purpose_function": "Naming this points the technician at a wiring or convention mismatch, not a broken part, when combined signals thin out or cancel.", "practical_application": "When two combined sources sound thin or cancel, a technician confirms every cable and device follows pin-2-hot wiring rather than legacy pin-3-hot.", "category": "Wiring fault", "related_terms": ["Polarity flip", "Pin 1 problem", "XLR connector", "Balanced line", "Phase cancellation", "Pin test"], "common_mistakes": ["Confusing a polarity (pin 2 versus 3) issue with a level or EQ problem when summed signals sound thin.", "Assuming all gear is pin-2-hot; some legacy equipment was wired pin 3 hot.", "Mixing home-made and commercial cables that follow different hot-pin conventions."], "scenario_contexts": ["A vocal that cancels when two mics are summed because one cable is wired pin 3 hot.", "Interfacing legacy pin-3-hot equipment with modern pin-2-hot consoles.", "Thin, phasey sound cured by correcting a mis-wired XLR."]}, "c8454359-153c-48f3-860a-64a023904298": {"definition": "A polarity flip (commonly mislabeled 'phase reverse') inverts a signal's polarity by 180 degrees, swapping its positive and negative excursions so the waveform is mirrored about zero. On a balanced line it is done by exchanging pins 2 and 3 or with a console/preamp polarity (Ø) switch, and is used to correct cancellation when two sources of the same signal are combined.", "plain_english": "A polarity flip turns a signal upside down and swaps its plus and minus. It is a button marked with a circle and slash. Engineers use it when two mics fight and sound thin. Flipping one can make them add up instead of cancel.", "purpose_function": "It exists to realign two signals that are working against each other, so combining them adds level and low end instead of cancelling it.", "practical_application": "When top and bottom snare mics sound thin together, a technician flips the polarity on one so the two reinforce rather than cancel.", "category": "Signal correction", "related_terms": ["Phase cancellation", "Pin-two problem", "Balanced line", "Comb filtering", "Microphone placement", "Summing"], "common_mistakes": ["Confusing polarity inversion (an instant 180-degree swap) with time-based phase differences, which a polarity flip does not fix.", "Flipping polarity at random instead of listening for which setting gives the fuller sound.", "Forgetting a flipped channel is still inverted when it is later soloed or recombined."], "scenario_contexts": ["Top and bottom snare mics that sum thin until one is polarity-flipped.", "A DI and a mic on the same bass combined for maximum low end.", "Fixing cancellation between a kick-in and a kick-out mic."]}, "3369dab6-ec73-4093-bd72-009a8e896aa6": {"definition": "Port assignment is the mapping of logical audio channels to specific physical or network input/output ports, such as console sockets, stagebox connectors, DSP I/O, or Dante/AVB network endpoints. Correct assignment routes each source and destination to the intended connector or network address; a wrong assignment sends signal to the wrong place or nowhere.", "plain_english": "Port assignment tells the system which socket or network address each channel uses. It links a stage input to the right console channel. If the ports are set wrong, sound goes to the wrong place or vanishes.", "purpose_function": "It exists so signals reach the correct physical or network destination in flexible digital systems, where almost any channel can be routed to almost any port.", "practical_application": "When a stage input shows up on the wrong console channel, a technician checks the port assignment in the stagebox and network routing before suspecting a cable.", "category": "Signal routing", "related_terms": ["Patch", "Stage box", "Dante", "Signal routing", "Re-enumerate", "Input list"], "common_mistakes": ["Assuming a silent channel is a hardware fault when the port is simply assigned to the wrong input or output.", "Changing port assignments without saving or documenting them, so routing is lost on reload.", "Confusing physical socket numbers with the logical channel numbers they are mapped to."], "scenario_contexts": ["A digital stagebox input appearing on the wrong console channel.", "Setting up Dante so each network device sends to the intended receiver.", "Recalling a show file and finding I/O ports mapped for a different venue."]}, "4754ea9e-0f56-45d5-99e3-c9507f5d5c04": {"definition": "'Pull the master' means to rapidly bring the main output fader (the master or grand master) down to minimum, muting or drastically reducing the system's overall level. It is used as an immediate response to a serious problem such as runaway feedback, a loud fault, or any need to silence the PA quickly and safely.", "plain_english": "Pull the master means pull the main volume fader all the way down. It instantly quiets the whole PA. Engineers do this fast when there is bad feedback or a loud fault. It protects ears and speakers.", "purpose_function": "It exists as a quick, single-move way to kill overall output in an emergency, protecting hearing and loudspeakers while the real fault is found.", "practical_application": "When feedback erupts or a loud bang starts, a technician pulls the master to silence the system before diagnosing the cause.", "category": "Emergency response", "related_terms": ["Master fader", "Feedback", "Mute", "Gain staging", "Loudspeaker protection", "Signal chain"], "common_mistakes": ["UNSAFE: Leaving the system loud while hunting for a feedback source instead of pulling the master to protect hearing and loudspeaker drivers.", "Pulling a subgroup or the wrong fader instead of the true master, so output continues.", "Bringing the master back up abruptly, causing a sudden jump in level."], "scenario_contexts": ["Sudden feedback during a speech that must be silenced instantly.", "A loud electrical bang or fault requiring the PA to be killed fast.", "A wrong playback track launched at full level that must be stopped at once."]}, "acacba7c-78b4-4ccb-b6ac-9a1349387a3f": {"definition": "To re-enumerate is to force a host or controller to re-detect and re-list the devices on a bus or network, such as USB devices or Dante/AVB network nodes, so a device that failed to appear or dropped off is rediscovered and re-registered. It is typically triggered by reconnecting the device, refreshing the controller, or power-cycling the host or device.", "plain_english": "Re-enumerate means make the computer or controller scan again for connected gear. A device that did not show up can then be found. It is like refreshing a list so a missing item comes back.", "purpose_function": "It exists to recover devices that were connected but not recognized, without a full system rebuild, by making the host repeat its discovery process.", "practical_application": "When a USB interface or Dante device is missing from the software, a technician re-enumerates by reconnecting or refreshing so it reappears in the device list.", "category": "Troubleshooting technique", "related_terms": ["Dante", "USB", "Device discovery", "Port assignment", "Reboot it", "Network switch"], "common_mistakes": ["Assuming a missing device is broken before trying to re-enumerate the bus or network.", "Re-enumerating repeatedly without fixing the real cause, such as a bad cable or wrong network settings.", "Confusing re-enumeration with a full reboot; often only a refresh or reconnect is needed."], "scenario_contexts": ["A USB audio interface that vanishes from the DAW until the bus re-enumerates.", "A Dante device missing in the controller until the network is refreshed.", "A control surface reconnected mid-session so the software rediscovers it."]}, "e67f1b41-42aa-41de-8035-58a745388441": {"definition": "'Reboot it' means to restart or power-cycle a device, clearing its volatile memory and re-running its startup sequence to recover from a transient software or firmware fault such as a freeze, a lost clock, or corrupted running state. It is a common first-line troubleshooting step when a device misbehaves but its hardware appears intact.", "plain_english": "Reboot it means turn a device off and on, or restart it. This clears its short-term memory and starts it fresh. It often fixes a freeze or glitch. It is the classic first thing to try when gear acts up.", "purpose_function": "It exists to clear temporary faults in a device's running state quickly, restoring normal operation without deeper repair when the hardware itself is fine.", "practical_application": "When a digital console or interface freezes or drops sync, a technician reboots it during a break to clear the fault before investigating further.", "category": "Troubleshooting technique", "related_terms": ["Power cycle", "Firmware", "Re-enumerate", "Digital console", "Word clock", "Signal chain"], "common_mistakes": ["UNSAFE: Rebooting critical gear during a live performance without warning, which can cut audio at the worst possible moment.", "Rebooting repeatedly to mask a recurring fault instead of finding its root cause.", "Assuming a reboot can fix hardware damage, which it cannot."], "scenario_contexts": ["A frozen digital mixer restarted during a set change.", "An audio interface that lost clock sync recovered by a power cycle.", "A control app reconnected to hardware after a restart."]}, "9fecc4c0-a236-47f9-aecd-b9bd9ee8ea50": {"definition": "A recording split is an isolated tap of the stage microphone and line signals fed to a recording or broadcast console, taken from a microphone splitter so the recording rig shares the same sources as front-of-house and monitors without electrically affecting them. The split is usually transformer-isolated to prevent ground loops and to keep phantom power and faults from crossing between consoles.", "plain_english": "A recording split copies each stage signal and sends a clean feed to the recording desk. The recording team then uses the same mics as the main mixer. Isolation stops the two systems from humming or interfering.", "purpose_function": "It exists so a show can be recorded or broadcast from the same stage sources without the recording setup loading, humming into, or otherwise disturbing the live mix.", "practical_application": "A technician patches stage inputs through a splitter and runs the isolated recording split to the capture rig, confirming only one console supplies phantom power.", "category": "Signal distribution", "related_terms": ["Microphone splitter", "Festival split", "Transformer isolation", "Ground loop", "Phantom power", "Stage box"], "common_mistakes": ["Enabling phantom power from the recording console on a shared direct tap, which can conflict with the front-of-house feed.", "Assuming the recording split is isolated when it is actually a hardwired direct tap sharing ground.", "Overlooking which console owns phantom power, leading to lost signal on the recording feed."], "scenario_contexts": ["A live album captured from an isolated split of the stage mics.", "A broadcast truck taking a recording split of every channel.", "A house engineer providing an isolated feed to a visiting recording team."]}, "c9014bfc-4f64-4d9a-87ed-3a8315ca577e": {"definition": "Redlining is running a signal so hot that its level meter reads in the red 'over' zone, at or beyond the nominal maximum and into or near clipping with little remaining headroom. On analog gear brief redlining may still fall within available headroom, but on digital systems it risks hard clipping and audible distortion once 0 dBFS is reached.", "plain_english": "Redlining means pushing the level so the meter lights up in the red. It warns you are near or past the safe maximum. On digital gear this can cause harsh distortion. Engineers back off the level to stay out of the red.", "purpose_function": "The term flags that levels are too hot and headroom is gone, prompting the technician to reduce gain before distortion or clipping spoils the sound.", "practical_application": "When channel or output meters sit in the red, a technician lowers the gain or fader to restore headroom and avoid clipping.", "category": "Level metering", "related_terms": ["Clipping", "Headroom", "Gain staging", "0 dBFS", "Peak meter", "Signal-to-noise ratio"], "common_mistakes": ["Confusing analog red-zone headroom with digital clipping; digital red at 0 dBFS distorts hard.", "Chasing the loudest possible meter reading instead of leaving headroom for peaks.", "Assuming redlining a channel is fine because the master bus is not yet clipping."], "scenario_contexts": ["Input meters pinned in the red producing distorted, crunchy sound.", "A digital recording clipping because tracks were captured while redlining.", "Reducing preamp gain when line-check meters redline on loud sources."]}, "1c428818-5cac-4f65-9bc5-5da5280d5d30": {"definition": "A remote input/output rack (also stage rack, I/O rack, or stage box) is a networked enclosure of microphone/line preamplifiers, analog inputs, and analog outputs placed near the stage and linked to a mixing console over a digital audio transport such as Dante, MADI, or a proprietary protocol carrying many channels on one cable. It converts stage analog signals to and from digital and has its preamps remote-controlled from the console, replacing a bulky analog multicore.", "plain_english": "A remote I/O rack is a box of inputs and outputs placed near the stage. It turns microphone signals into digital audio. One network cable then carries all the channels to the mixing desk. It replaces the thick analog snake.", "purpose_function": "It exists to move preamps and connectors close to the stage sources, so many channels reach the console on one lightweight digital cable instead of a heavy analog multicore. The console sets its preamp gains remotely over the same link.", "practical_application": "A technician places the rack at the stage, plugs mics and DIs into it, runs one network cable to the console, and sets each preamp's gain from the console surface.", "category": "Signal distribution", "related_terms": ["Stage box", "Multicore (snake)", "Dante", "MADI", "Digital mixing console", "Preamplifier"], "common_mistakes": ["Confusing the rack's audio-network cable with ordinary computer data and using unsuitable cabling or switches.", "Chasing a level fault at the rack when the preamp gain is actually set from the console.", "Assuming any console can control any rack, when the digital protocol and clock must match.", "Not confirming word-clock and sample-rate agreement between rack and console, causing dropouts."], "scenario_contexts": ["A festival stage feeding many channels to front-of-house over one Dante cable.", "A theatre with the console far from the stage connected by a single network run.", "Sharing stage inputs to separate front-of-house and monitor consoles from one networked rack."]}, "2fad51b4-1a65-427c-9c23-576ea6f0c878": {"definition": "To 'reseat the card' is to remove a plug-in module or circuit card from its connector or slot, following the maker's power-down and anti-static procedure, and firmly re-insert it to restore a clean electrical contact. It is a first-line fix for intermittent faults caused by a partially unseated card, oxidized or contaminated contacts, or connector movement from vibration or thermal cycling.", "plain_english": "Reseating a card means pulling a plug-in board out and pushing it back in firmly. This remakes the electrical contact. It often fixes odd faults that come and go from a loose or dirty connector.", "purpose_function": "It exists as a quick, low-risk check that rules out a bad connection before deeper repair. Remaking the contact can cure faults that come and go without replacing any parts.", "practical_application": "When an input card or DSP module behaves intermittently, a technician powers down as required, removes the card, and re-inserts it fully before suspecting a deeper hardware fault.", "category": "Troubleshooting technique", "related_terms": ["Intermittent fault", "Edge connector", "Modular console", "Contact cleaner", "Signal chain", "DSP card"], "common_mistakes": ["UNSAFE: Opening or reseating a card in mains-powered equipment without following the maker's power-down, lockout, and anti-static procedure, risking shock and equipment damage.", "Reseating repeatedly instead of cleaning corroded contacts or finding the real fault.", "Forcing a card into the wrong slot or orientation and bending pins.", "Touching card contacts with bare fingers, leaving oils that worsen the connection."], "scenario_contexts": ["An input channel on a modular console that cuts in and out.", "A DSP or network card in a rack unit that intermittently drops offline.", "A stage-rack module that returns to normal after being removed and re-inserted."]}, "edc55145-272b-4e69-b6ee-f8153929131b": {"definition": "Resync (re-synchronize) is the act of restoring digital clock lock between devices so their sample clocks run at the same rate and phase, typically after a lost or changed word clock, a sample-rate mismatch, or a digital link that was broken and reconnected. Until devices are re-synced, digital audio can mute, drop out, or produce clicks and pops.", "plain_english": "Digital gear must share one master timing clock. Resync means getting the devices back in step after they lose that lock. Losing sync causes clicks, dropouts, or silence. Re-syncing clears the noise and restores clean audio.", "purpose_function": "It exists because every digital audio device must lock to a single clock reference; re-syncing re-establishes that shared timing so samples line up and transfer without errors.", "practical_application": "After a device shows a clock error or a digital cable is reconnected, a technician re-selects the correct clock source and confirms every unit reads 'locked' before passing audio.", "category": "Digital clocking", "related_terms": ["Word clock", "Sample rate", "Digital audio", "MADI", "Dante", "Dropout"], "common_mistakes": ["Setting more than one device as clock master, so nothing locks.", "Assuming a mismatched sample rate will still pass audio cleanly.", "Ignoring an 'unlocked' clock warning and blaming clicks on cables or converters.", "Forgetting to re-sync after hot-swapping or reconnecting a digital link."], "scenario_contexts": ["A recording rig clicking because a converter lost word clock.", "A console and stage rack muting until their sample rates match and lock.", "Reconnecting a MADI or Dante link and waiting for devices to relock."]}, "d4e273a7-13c7-46d4-842f-585ffffed2ec": {"definition": "An 'RF hit' is a brief burst of radio-frequency interference that momentarily disrupts a wireless microphone or in-ear monitor system, heard as a click, crackle, or short dropout as the receiver briefly loses a clean signal. Common causes include another transmitter, intermodulation products, digital or switching noise, multipath fades, or a weak signal at the edge of range.", "plain_english": "An RF hit is a quick blast of radio interference on a wireless mic. You hear a click, crackle, or a split-second dropout. It happens when another signal or noise briefly overpowers the mic's own signal.", "purpose_function": "Naming a fault an RF hit tells the technician the problem is over the air, not in the cabling or console, so the fix lies in frequency coordination, antennas, or gain, not the wired path.", "practical_application": "When a wireless channel clicks or drops for an instant, a technician checks for co-channel and intermodulation conflicts, antenna placement, and battery or signal strength before swapping audio cables.", "category": "Signal problem", "related_terms": ["Frequency coordination", "Intermodulation distortion", "Dropout", "Squelch", "Diversity reception", "Wireless microphone"], "common_mistakes": ["Blaming a wired fault or the console for what is actually over-the-air interference.", "Assuming a dropout is a dead battery when the real cause is an RF conflict.", "Skipping frequency coordination and a channel scan before the show.", "Placing receiver antennas behind metal, bodies, or too far from the stage."], "scenario_contexts": ["A wireless vocal mic that clicks whenever a phone or transmitter is nearby.", "Short dropouts on an in-ear system in a crowded RF environment.", "Intermittent crackles traced to two systems producing intermodulation."]}, "37c2ffc0-cdc7-484d-a166-a2929fbd88c1": {"definition": "To 'ring out' a system is to deliberately raise gain until the mains or monitors just begin to feed back, identify each ringing frequency, and cut it with an equalizer, repeating the process until the system reaches usable level without feedback. The goal is maximum gain before feedback with minimal change to overall tone.", "plain_english": "Ringing out means slowly turning a mic up until it starts to squeal. You find each squealing pitch and cut it with an EQ. You repeat this so the system can go louder before it feeds back.", "purpose_function": "It exists to raise how loud microphones can get before feedback, by pulling down only the frequencies that ring. This gives more usable level for the mains and stage monitors.", "practical_application": "Before doors, a technician rings out each monitor mix and the mains, notching problem frequencies on a graphic or parametric equalizer to gain headroom before feedback.", "category": "Troubleshooting technique", "related_terms": ["Feedback", "Graphic equalizer", "Gain before feedback", "Monitor mix", "Parametric equalizer", "Notch filter"], "common_mistakes": ["Cutting too many bands too deeply, which thins the sound instead of just removing the ring.", "Ringing out at low level, then meeting new feedback once the show gets loud.", "UNSAFE: Ringing out at high sound levels close to your ears without hearing protection, risking permanent hearing damage.", "Relying only on EQ instead of also fixing microphone and monitor placement."], "scenario_contexts": ["Setting up stage monitors so singers can be loud without howling.", "Ringing out the mains in a reflective room before a show.", "Adding gain to a lectern mic in a house of worship without feedback."]}, "19609f9f-5339-47bb-98a4-41df95eaa3f2": {"definition": "A 'room problem' is a fault whose true cause is the acoustics of the space, such as reflections, standing-wave resonances (room modes), reverberation, or comb filtering, rather than the electronics, microphones, or mix. It is diagnosed when the same signal chain sounds correct on headphones or in another space but wrong in that particular room.", "plain_english": "A room problem means the space itself is causing the bad sound, not the gear. Echoes, reflections, and boomy spots color what you hear. The fix is treating or working with the room, not just changing settings.", "purpose_function": "Labeling a fault a room problem stops the technician endlessly re-tuning gear that is actually fine, and points instead to acoustic causes and fixes like placement, treatment, or speaker aiming.", "practical_application": "When boominess or harshness persists across different mics and settings, a technician checks speaker and listener positions, room modes, and reflections instead of chasing more EQ.", "category": "Acoustics", "related_terms": ["Room modes", "Reverberation", "Comb filtering", "Standing wave", "Acoustic treatment", "Reflection"], "common_mistakes": ["Trying to EQ away a room resonance that only acoustic treatment or repositioning can truly fix.", "Blaming the microphone or console for boominess caused by room modes.", "Ignoring speaker and listener placement, which strongly changes what the room does.", "Assuming a room that sounds good empty will sound the same full of people."], "scenario_contexts": ["A boomy conference room where every mic sounds muddy.", "A gym or church with long reverberation smearing speech.", "A control room with a bass buildup at one listening position."]}, "f0fd1328-0f80-404f-aa91-4c3ae27f9955": {"definition": "'Rub and buzz' is a loudspeaker fault in which the moving parts produce a rasping, buzzing, or scraping noise, usually from a voice coil rubbing in the magnetic gap, a deformed or partly delaminated cone or surround, loose particles in the gap, or a loose part. It shows up as high-order, non-linear distortion and is a key defect screened for in loudspeaker production and field testing.", "plain_english": "Rub and buzz is a raspy, buzzing noise from a faulty speaker driver. It usually means the voice coil is scraping, or a part is loose or torn. It is a sign the driver is damaged and needs testing or replacement.", "purpose_function": "The term names a specific mechanical driver defect so it is not confused with electronic distortion; spotting it flags a physically damaged speaker for repair or rejection.", "practical_application": "A technician hears rub and buzz on a sustained low tone or sees it on distortion analysis, then isolates the faulty driver and recones or replaces it.", "category": "Fault condition", "related_terms": ["Voice coil", "Cone (diaphragm)", "Total harmonic distortion", "Driver (transducer)", "Reconing", "Loudspeaker"], "common_mistakes": ["Confusing mechanical rub and buzz with electronic clipping or a rattling cabinet part.", "Pushing a rubbing driver harder, which worsens the voice-coil damage.", "Assuming any buzz is the driver when it may be a loose grille, screw, or panel.", "Testing only at high level and missing rub that shows on low, sustained tones."], "scenario_contexts": ["Quality testing new drivers on a production line.", "Field-checking a PA cabinet that buzzes on bass notes.", "Diagnosing a partly damaged woofer after an overload."]}, "9d4efb2d-fe08-415c-8646-fb65fb74b022": {"definition": "'Running out of rig' is informal live-sound language for reaching the limits of the deployed sound system, so it can no longer cleanly deliver more of what is asked, whether that is loudness (SPL) and headroom, low-frequency output, coverage area, or available input/output channels. Beyond this point, pushing harder produces distortion, limiting, or gaps in coverage rather than more clean output.", "plain_english": "Running out of rig means the PA system has hit its limit. It cannot go louder or cover more area cleanly. Turning it up further just adds distortion, not more sound. The real fix is a bigger or better-placed system.", "purpose_function": "The phrase tells the team that a shortfall is a capacity limit of the chosen system, not a settings mistake, so the answer is more or better-placed equipment rather than more gain.", "practical_application": "When a room needs more level or coverage than the boxes and amplifiers can give cleanly, a technician recognizes they are running out of rig and adds or repositions elements instead of driving the system into limiting.", "category": "System capacity", "related_terms": ["Headroom", "Sound pressure level (SPL)", "Amplifier clipping", "System design", "Coverage", "Limiter"], "common_mistakes": ["Driving amplifiers into clipping to get level the system cannot cleanly produce.", "Blaming the mix or EQ for a shortfall that is really a capacity limit.", "Undersizing the PA for the room or audience during system design.", "Ignoring coverage, so some seats stay quiet even when the system is loud elsewhere."], "scenario_contexts": ["A small PA asked to cover a large outdoor crowd.", "A subwoofer count too low for the low-end level a show needs.", "A channel count exhausted before every stage source is patched."]}, "66cc3c52-e0c2-4998-93f6-9d0767493fc1": {"definition": "To 'safe the channel' is to place a console channel into recall safe (and, where offered, automation safe), so scene or snapshot recalls do not overwrite its current settings. The safed channel keeps its live parameters while the rest of the show file recalls as normal.", "plain_english": "On a digital desk, scenes recall saved settings at the push of a button. To safe a channel is to protect it from those recalls. Its settings then stay put while other channels change. Engineers safe channels they must control by hand.", "purpose_function": "It exists so a channel that must stay under manual control, such as a lead vocal or a show-critical feed, is not changed by scene recalls during a show, protecting chosen settings from automation.", "practical_application": "Before running scenes, a technician safes the channels they want to ride manually, so snapshot changes never jump their gain, EQ, or fader mid-show.", "category": "Console automation", "related_terms": ["Recall safe", "Scene recall", "Snapshot", "Recall scope", "Digital mixing console", "Show file"], "common_mistakes": ["Confusing 'safe' with mute or with a locked channel; a safed channel still passes audio and can be adjusted.", "Forgetting which channels are safed, then wondering why a scene did not change them.", "Leaving a channel safed after it should follow scenes again.", "Assuming safe protects every parameter when the recall scope may cover only some."], "scenario_contexts": ["Keeping a lead vocal channel under manual control across many scenes in a musical.", "Protecting a walk-in music or announcement channel from show snapshots.", "A guest engineer safing key channels before running the house show file."]}, "496c3c9c-1676-42c3-a4f9-bec30bc86a90": {"definition": "A short (short circuit) is an unintended low-resistance connection between two points in a circuit that lets current bypass its intended path, such as a signal conductor touching ground or the two conductors of a cable touching each other. It typically collapses the signal or supply voltage at that point and can draw excessive current, tripping protection or damaging components.", "plain_english": "A short is when two parts of a circuit touch that should not. Electricity then takes a shortcut instead of its proper path. This can kill the signal, blow a fuse, or damage gear.", "purpose_function": "Naming a short pinpoints one specific fault: a wrong low-resistance path. It tells the technician to look for touching conductors, crushed cables, or solder bridges rather than a settings problem.", "practical_application": "When an output goes dead or an amplifier keeps shutting down, a technician checks cables and connectors for a short, using a multimeter's continuity or resistance test with the circuit de-energized.", "category": "Fault condition", "related_terms": ["Open circuit", "Short circuit protection", "Continuity test", "Ground", "Fuse", "Solder bridge"], "common_mistakes": ["UNSAFE: Probing for a short on live mains or an amplifier output; test with the circuit de-energized and follow lockout/tagout to avoid shock.", "Confusing a short (resistance too low) with an open (broken path); they give opposite continuity readings.", "Assuming a dead channel is a short when the real cause is an engaged mute, a wrong patch, or an open cable."], "scenario_contexts": ["A speaker cable pinched under road cases shorting and forcing an amplifier into protection.", "A solder bridge shorting two adjacent pads on a repaired circuit board.", "An XLR connector with a pin touching the shell, shorting the signal to ground."]}, "813692d4-f0a0-41b8-a045-154406a20d77": {"definition": "A shorted turn is an inter-turn short circuit within a coil or winding, where the insulation between adjacent turns fails and two or more turns connect directly. The shorted loop behaves like a shorted secondary, drawing a large induced current that causes localized heating, loss of inductance, and often failure of the transformer, inductor, or loudspeaker voice coil.", "plain_english": "A coil is made of many wire loops wound side by side. A shorted turn is when the insulation fails and two loops touch. That small loop then overheats and stops the part working right.", "purpose_function": "Identifying a shorted turn explains symptoms like a transformer that overheats, hums, or loses output with no external fault. It tells the technician the part itself is damaged and must be replaced.", "practical_application": "When a power or audio transformer runs hot and hums with nothing connected to it, a technician suspects a shorted turn and replaces the transformer rather than chasing external wiring.", "category": "Fault condition", "related_terms": ["Transformer", "Inductor", "Voice coil", "Short", "Winding insulation", "Impedance"], "common_mistakes": ["Blaming an external overload for a transformer that overheats, when the real fault is a shorted turn inside it.", "Believing a shorted turn can be fixed at the bench; it usually means replacing the whole component.", "UNSAFE: Leaving a transformer with a suspected shorted turn energized on full mains; it can overheat and become a fire or shock hazard."], "scenario_contexts": ["A guitar amplifier power transformer that buzzes and overheats from a shorted turn.", "A loudspeaker voice coil with shorted turns that lowers impedance and distorts.", "An audio output transformer losing level because some turns have shorted together."]}, "98972352-1941-449a-9607-1a7e08f378ac": {"definition": "'Signal but no sound' is a troubleshooting symptom where metering or a listen/PFL bus confirms signal is present in the system, yet no audio reaches the intended output. It localizes the fault to a point downstream of the metering tap, such as an engaged mute, wrong routing, a faulty amplifier, a disconnected loudspeaker, or a broken monitoring path.", "plain_english": "Signal but no sound means the meters show audio is there, but you hear nothing. So the problem is after the meter, not before it. The tech checks mutes, routing, amps, and speakers.", "purpose_function": "The phrase narrows a fault quickly: signal exists but the audible path is broken. It tells the technician to search downstream of the meter instead of at the source or input.", "practical_application": "Seeing a channel meter normally but hearing nothing, a technician checks mutes, bus and matrix routing, the amplifier, and the loudspeaker connection in turn.", "category": "Fault symptom", "related_terms": ["Signal flow", "Mute", "Routing", "PFL (pre-fade listen)", "Metering", "Sound but no meter"], "common_mistakes": ["Re-checking the source and input gain when the meter already proves signal is present.", "Forgetting that many meters tap pre-fader or pre-mute, so the meter can move while the output is silenced.", "Overlooking a wrong bus or matrix assignment as the reason nothing is heard."], "scenario_contexts": ["A channel metering fine but muted at the output group.", "Audio present on the console but no sound because the amplifier is powered off.", "A monitor mix showing signal but silent from a disconnected wedge."]}, "de1669f7-61f8-46c5-a8ef-c98391562207": {"definition": "'Sniff the line' is informal troubleshooting slang for probing or monitoring a signal line to detect whether signal is present and where it stops, typically with an audio probe, a signal tracer, or a console solo/PFL listen. It is a signal-tracing method used to follow audio through a chain and find the point at which it disappears.", "plain_english": "Sniff the line means listen in on a cable or signal path to see if audio is there. You move along the chain and check point by point. Where the sound stops is near the fault.", "purpose_function": "It lets a technician follow a signal step by step and find exactly where it is lost. Checking for signal at each point turns a vague 'no audio' into a located fault.", "practical_application": "Using an audio probe or a PFL listen, a technician sniffs the line at the DI, the stage box, and the console input in turn to find where the signal vanishes.", "category": "Troubleshooting method", "related_terms": ["Signal tracing", "Signal injector", "PFL (pre-fade listen)", "Audio probe", "Signal flow", "Continuity test"], "common_mistakes": ["Sniffing at random points instead of working in order along the signal chain.", "UNSAFE: Touching a bare probe to amplifier outputs or mains-level points; use line-level test points and de-energize where needed.", "Confusing signal presence with correct level; a weak but present signal can still be the fault."], "scenario_contexts": ["Tracing a dead vocal channel from mic to console to find the break.", "Checking each patch point on a snake to locate a bad cable.", "Following signal through outboard gear to find a unit that kills it."]}, "baea9a5f-2b5b-4ba5-8ad1-318b224d12d5": {"definition": "A socket number is the numbered label identifying a specific physical connector on a stage box, patch panel, wall panel, or multicore, used to route and communicate which input or output a source is patched to. It gives every tie line and connection a unique reference so patching can be documented and repeated reliably.", "plain_english": "A socket number is the number printed on each connector on a stage box or wall panel. It tells everyone exactly which input a mic is plugged into. This makes patching quick to set up and repeat.", "purpose_function": "It gives each connection a unique name so engineers, stagehands, and paperwork all refer to the same point. This prevents patching mistakes and speeds up setup and fault-finding.", "practical_application": "A technician labels the patch sheet by socket number, so the engineer can say 'the kick is on socket 3' and everyone patches and troubleshoots the same input.", "category": "Signal routing", "related_terms": ["Stage box", "Multicore (snake)", "Patch panel", "Stage input", "Patch sheet", "Tie line"], "common_mistakes": ["Assuming the socket number always equals the console channel number, when the patch can remap them.", "Not matching stage-end and console-end socket numbers, causing miswired inputs.", "Relying on memory instead of a patch sheet, so socket numbers get confused under pressure."], "scenario_contexts": ["Calling out a faulty input by its socket number during a line check.", "Documenting a stage plot and patch list by socket number.", "Repatching a stage box quickly between acts using socket numbers."]}, "37f3e8b6-331a-448b-8a00-d17813105d47": {"definition": "'Sound but no meter' is a troubleshooting symptom where audio is clearly audible yet the channel or bus meter shows little or no deflection. It points to a metering fault or to the meter tapping a different point than the audible path, for example a broken meter, a meter fed from a pre-source point, or signal reaching the output by a route that bypasses that meter.", "plain_english": "Sound but no meter means you can hear audio but the meter barely moves. So the meter, not the sound, is the problem. The audio may also reach the output by a path the meter does not watch.", "purpose_function": "The symptom tells a technician to trust their ears and suspect the metering or routing, not the audio itself. It stops them from adding gain to chase a meter that is simply not reading.", "practical_application": "Hearing normal audio while the meter sits dead, a technician checks the meter's source point, the routing, and whether the signal reaches that bus by another path.", "category": "Fault symptom", "related_terms": ["Metering", "Signal but no sound", "Routing", "PFL (pre-fade listen)", "Signal flow", "Direct out"], "common_mistakes": ["Raising gain to make the meter move when the audio is already at correct level.", "Assuming a dead meter means dead audio, ignoring what the ears report.", "Forgetting the meter may read a different tap point than the audible signal."], "scenario_contexts": ["A channel heard clearly while its meter stays flat due to a metering fault.", "Audio reaching the mix by a direct out while the selected meter reads nothing.", "A digital console page showing no meter because the wrong tap point is selected."]}, "aed9c333-6c8f-4794-a007-6cad1d37c3f6": {"definition": "A source problem is a fault that originates at the signal source, such as the instrument, microphone, direct box, or playback device, rather than in the console, processing, or reinforcement system downstream. Diagnosing a fault as a source problem means the fix belongs at the input end, not in the mix or the PA.", "plain_english": "A source problem is when the fault starts at the source itself. That could be the instrument, the mic, the DI, or a playback device. Fixing the desk or speakers will not help until the source is fixed.", "purpose_function": "Labeling a fault a source problem separates input-end causes from system-end causes. It stops a technician from adjusting the console when the real fault is upstream at the source.", "practical_application": "When only one input sounds wrong and swapping to a known-good source fixes it, a technician treats it as a source problem and checks the instrument, mic, cable, or DI.", "category": "Fault symptom", "related_terms": ["Signal chain", "Fix it upstream", "Direct box (DI)", "Microphone", "Garbage in garbage out", "Stage input"], "common_mistakes": ["EQing or processing at the console to mask a fault that is really at the source.", "Not swapping the source to confirm whether the fault follows it.", "Assuming a system-wide fault when only one input is affected."], "scenario_contexts": ["A crackling guitar traced to a bad instrument cable, not the console.", "A dull vocal caused by a faulty mic rather than the channel EQ.", "A hum that follows one playback device wherever it is patched."]}, "216dea20-eb79-4c8b-875b-14a2b303ff17": {"definition": "In troubleshooting, a squeak is a brief, high-pitched unwanted sound produced by a system or component, often the onset of acoustic feedback, a parasitic oscillation in an amplifier or circuit, or an intermittent-contact or RF artifact. It is treated as a symptom whose source must be traced, because the underlying cause determines the fix.", "plain_english": "A squeak is a short, high-pitched noise you did not want. It is often the start of feedback or a circuit oscillating. The tech has to find what is causing it before fixing it.", "purpose_function": "Naming the squeak as a symptom prompts the technician to find its cause rather than just turning things down. Different causes, such as feedback or oscillation, need different fixes.", "practical_application": "When a channel squeaks, a technician checks for feedback from an open mic, then for a faulty cable or an oscillating device, isolating inputs until the squeak stops.", "category": "Fault symptom", "related_terms": ["Feedback", "Oscillation", "Intermittent connection", "Squeal", "RF interference", "Signal tracing"], "common_mistakes": ["Pulling the master fader down instead of finding what causes the squeak.", "Assuming every squeak is acoustic feedback when it may be a circuit oscillating.", "Overlooking a faulty cable or connector as a source of intermittent squeaks."], "scenario_contexts": ["A monitor starting to squeak as gain approaches the feedback point.", "An amplifier squeaking from parasitic oscillation after a repair.", "An intermittent cable causing brief squeaks when it is moved."]}, "f2e625d0-3714-4613-ae47-28257c2ee6e3": {"definition": "A stage input is a signal source originating on stage, such as a microphone or direct box, that enters the sound system through a stage box, wall panel, or snake input. Each stage input is patched to a console channel and is the starting point of that channel's signal chain.", "plain_english": "A stage input is a signal that starts on stage, like a mic or a DI. It plugs into a stage box and runs to the mixing desk. It is the first step in that channel's path.", "purpose_function": "Stage inputs are where live sources enter the system, so they define what the console has to work with. Organizing and labeling them keeps large stage setups manageable and easy to troubleshoot.", "practical_application": "During setup a technician patches each mic and DI into numbered stage inputs, then line-checks them one by one to confirm each reaches the correct console channel.", "category": "Signal routing", "related_terms": ["Stage box", "Socket number", "Multicore (snake)", "Direct box (DI)", "Line check", "Input list"], "common_mistakes": ["Confusing the stage input number with the console channel number when they are remapped.", "Not line-checking every stage input before doors, missing a dead one.", "Forgetting that phantom power for a stage input is set at the console, not at the stage box."], "scenario_contexts": ["Patching mics and DIs into stage inputs during setup.", "Line-checking each stage input to confirm it reaches the desk.", "Tracing a dead channel back to its stage input and cable."]}, "44979f14-2ebc-4c20-afc3-1e5455e419b4": {"definition": "Stage output refers to the audio signal or signals sent out from the stage area to the rest of a sound system, such as the feeds leaving a stage box, signal splitter, or monitor console toward the front-of-house console, monitor amplifiers, or a recording rig. In troubleshooting it names the point where audio leaves the stage, giving a defined place to confirm signal is present before checking downstream links.", "plain_english": "Stage output is the sound signal leaving the stage on its way to the rest of the system. Think of it as the exit door for audio from the stage. Checking it shows if sound is getting out before you look further down the line.", "purpose_function": "It gives a defined test point for confirming that signal made it through the stage gear and is heading toward the mixer or amplifiers. This lets a technician split a system into stage and downstream halves during fault finding.", "practical_application": "When front-of-house hears nothing, a technician checks the stage output at the stage box or split to confirm signal is present there before blaming the long cable run or the FOH console.", "category": "Signal distribution", "related_terms": ["Stage box", "Signal splitter", "Front of house (FOH)", "Multicore (snake)", "Direct split", "Signal chain"], "common_mistakes": ["Assuming the fault is downstream when the stage output itself is dead or never patched.", "Confusing the stage output feed with the monitor send returning to the stage.", "Overlooking a splitter or isolation-transformer fault that kills the stage output."], "scenario_contexts": ["Verifying signal at the stage box before troubleshooting a long snake run.", "Confirming a splitter is feeding both FOH and monitors.", "Checking the stage output when a broadcast or recording truck reports no audio."]}, "4a2cd442-09a5-4639-827f-50ab7c9d415f": {"definition": "String slap is the percussive click or rattle produced when a vibrating string strikes the frets, fingerboard, or pickup of a stringed instrument. It can be a deliberate playing technique, as in slap bass, or an unwanted mechanical noise from low string action or heavy attack that a pickup or microphone reproduces along with the note.", "plain_english": "String slap is the clacking sound a string makes when it hits the frets or fingerboard. Sometimes players want it, like in slap bass. Other times it is unwanted noise that the pickup sends into the system.", "purpose_function": "Naming the noise as string slap tells a technician the sound starts at the instrument, not in the cable, preamp, or speakers. That points troubleshooting back toward the player and the instrument setup.", "practical_application": "When a bass channel has a clicky rattle, a technician checks the instrument's string height and playing style before assuming the fault is a bad DI box or a clipping preamp.", "category": "Instrument noise", "related_terms": ["Fret buzz", "Direct injection (DI)", "Transient", "Pickup", "Signal chain", "Source noise"], "common_mistakes": ["Blaming a clicky sound on distortion in the DI or preamp when it comes from the instrument.", "Trying to EQ or gate out string slap that is actually part of the player's intended tone.", "Confusing string slap with clipping distortion inside the signal chain."], "scenario_contexts": ["A slap-bass line coming through with heavy percussive attack at line check.", "A rattly acoustic guitar traced to low string action rather than to gear.", "Deciding whether a clicky transient is musical intent or a setup problem."]}, "ff052a57-a859-4b27-af06-3c8833a7d019": {"definition": "'Swap the line' is a substitution troubleshooting step in which a suspect cable, patch, or signal path is replaced with a known-good one to determine whether the fault lies in that line. If swapping the line restores the signal, the original cable or connection was faulty; if nothing changes, the problem lies elsewhere in the chain.", "plain_english": "Swap the line means replace a cable or connection with one you know works. If the sound comes back, the old line was the problem. If nothing changes, you look somewhere else.", "purpose_function": "It isolates the cable or patch as a single variable by testing one known-good link at a time. This turns guesswork into a clear yes-or-no answer about that part of the signal path.", "practical_application": "When a channel is dead or noisy, a technician swaps in a fresh cable or repatches the line to see whether the fault follows the cable or stays with the channel.", "category": "Troubleshooting technique", "related_terms": ["Substitution method", "Signal chain", "Swap the microphone", "Cable tester", "Patch bay", "Fault isolation"], "common_mistakes": ["Swapping in another cable that is also faulty and wrongly clearing the line.", "Changing more than one thing at once, so the real cause stays hidden.", "Failing to seat or patch the new line fully, leaving a loose connection that mimics the original fault."], "scenario_contexts": ["Tracing intermittent crackle on a mic line during a show.", "Isolating a dead channel by repatching to a spare input.", "Confirming whether hum follows one specific cable run."]}, "96c70c7d-ddb7-476e-ab2c-2d2096190fb8": {"definition": "'Swap the microphone' is a substitution troubleshooting step in which a suspect microphone is replaced with a known-good one to determine whether the fault originates in the mic itself. If the replacement works, the original mic was faulty; if the problem persists, the fault lies in the cable, input, or downstream signal path.", "plain_english": "Swap the microphone means put a mic you trust in place of the one you suspect. If the new mic works, the old one was broken. If the trouble stays, the mic was not the cause.", "purpose_function": "It tests the microphone as a single variable at the very start of the chain, separating a mic fault from cable, connector, or console problems. This gives a fast, clear check on the source end.", "practical_application": "When a vocal channel is dead or weak, a technician swaps in a known-good mic on the same cable and input to see whether the sound returns.", "category": "Troubleshooting technique", "related_terms": ["Substitution method", "Swap the line", "Microphone", "Signal chain", "Fault isolation", "Phantom power"], "common_mistakes": ["UNSAFE: Hot-swapping a condenser or ribbon microphone without muting the channel or dropping phantom power, which can cause a loud transient or damage a ribbon element.", "Swapping in a mic that needs different settings, such as phantom power, and misreading the result.", "Assuming the mic is bad without also checking the cable and the input."], "scenario_contexts": ["A wired vocal mic goes silent mid-set and is swapped for a spare.", "Line check reveals one channel far quieter than the rest.", "Confirming whether distortion comes from the mic or from the preamp."]}, "42007dc2-12ec-49de-b06c-89aa5d3ab87e": {"definition": "'Swap the pack' is a substitution troubleshooting step for wireless systems in which a suspect bodypack transmitter is exchanged for a known-good pack to determine whether the fault lies in the transmitter. It isolates transmitter problems, such as a dead battery, a bad connector, or a failed pack, from receiver, antenna, or RF-environment issues.", "plain_english": "Swap the pack means change a wireless bodypack transmitter for one you know works. If the signal returns, the old pack was the problem. If not, the trouble is in the receiver, antenna, or radio path.", "purpose_function": "It tests the bodypack transmitter as a single variable, separating a pack fault from receiver or RF problems. This speeds up fixing wireless dropouts, often during a fast changeover.", "practical_application": "When a wireless channel drops out or sounds distorted, a technician swaps in a fresh bodypack, usually with a known-good battery, before chasing antenna or interference issues.", "category": "Troubleshooting technique", "related_terms": ["Bodypack transmitter", "Dead pack", "Wireless microphone system", "RF dropout", "Substitution method", "Fault isolation"], "common_mistakes": ["Swapping the pack without also checking the battery, so a flat battery mimics a dead pack.", "Forgetting to match frequency and channel settings on the replacement pack.", "Assuming a dropout is the pack when the real cause is antenna placement or RF interference."], "scenario_contexts": ["A lavalier channel cutting out during a theatre performance.", "A fast actor changeover where a suspect pack is swapped between scenes.", "Distorted wireless audio traced to a failing transmitter."]}, "a9c707ac-013f-4ccb-b375-a5aa66ed8b7b": {"definition": "A 'system problem' is a fault that originates within the sound system itself, such as in cabling, connectors, consoles, processing, amplifiers, or loudspeakers, rather than in the source, performer, or room. Classifying a fault this way directs troubleshooting into the signal chain and equipment instead of the input source.", "plain_english": "A system problem is trouble that comes from the gear and wiring, not the singer, instrument, or room. Naming it this way tells you where to look. You start checking the equipment and cables, not the source.", "purpose_function": "The label sorts faults into system versus source, which is the first split many technicians make when troubleshooting. It focuses effort on the equipment chain so time is not wasted blaming the performer or the room.", "practical_application": "When several channels share the same hum or dropout, a technician calls it a system problem and checks shared gear such as power, grounding, or the console rather than each source.", "category": "Fault classification", "related_terms": ["Signal chain", "Source problem", "Root cause analysis", "Fault isolation", "Ground loop", "Troubleshooting"], "common_mistakes": ["Calling a source or performer issue a system problem and replacing gear that was never faulty.", "Assuming one dead channel is a whole-system problem instead of a single-channel fault.", "Skipping simple shared causes, such as power and grounding, when a true system problem appears."], "scenario_contexts": ["Hum appearing on every channel points to a shared system problem.", "A total loss of audio traced to a failed console or power fault.", "Deciding whether a bad sound is the system or the source during line check."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"ec2ea4cf-f9ce-4f17-82d0-1c879793795c": {"definition": "'Toast' is informal shop language for a component or piece of equipment that has been permanently damaged and no longer works, as in 'the amp is toast.' It signals hardware failure, usually from overvoltage, excess current, overheating, or a short circuit, rather than a setting, patch, or signal-flow error.", "plain_english": "Toast means a piece of gear is dead and beyond a quick fix. Like burnt toast, it is ruined. Too much power, heat, or a short has damaged it, so it needs repair or replacement.", "purpose_function": "The word quickly tells the crew a fault is hardware damage, not something a setting change can fix. That stops people chasing patches and moves them to repair or swap the unit.", "practical_application": "When a channel or amp stays dead after cables, settings, and patching are ruled out, a technician calls it toast and pulls it for service or replacement.", "category": "Fault condition", "related_terms": ["Fried", "Overvoltage", "Short circuit", "Thermal protection", "Fuse", "Signal chain"], "common_mistakes": ["Declaring gear toast before checking simple causes such as a blown fuse, an engaged mute, or a bad cable.", "UNSAFE: Repeatedly powering up a unit suspected to be toast, which can worsen the damage or create a shock or fire hazard.", "Confusing a tripped protection mode, which resets, with permanent damage."], "scenario_contexts": ["An amplifier that stays dead and smells burnt after a short.", "A console power supply that fails and will not boot.", "A loudspeaker driver destroyed by sustained overpowering."]}, "08545198-625f-407d-a256-3df675b8da70": {"definition": "To 'tone the line' is to inject a known test tone (typically a steady sine wave such as 1 kHz from a console oscillator or signal generator), or to apply a tone-generator-and-probe ('toner'), into an audio line in order to verify continuity end to end, identify which cable or channel is which, and check level. Hearing or metering the tone at the far end confirms the path is intact, while its absence localizes the break.", "plain_english": "To tone the line means to send a steady test tone down a cable or channel. You then listen or watch the meter at the far end. If the tone shows up, the path works. If not, the break is on that line.", "purpose_function": "It gives a technician a known, controlled signal to trace through a system, so a dead or misrouted path can be found without waiting for the band. It quickly separates a wiring fault from a settings problem.", "practical_application": "During line check a technician sends a 1 kHz tone through a suspect channel and listens for it at each point, or uses a tone generator and probe to trace one unlabeled cable inside a bundle.", "category": "Troubleshooting technique", "related_terms": ["Signal chain", "Line check", "Continuity test", "Test oscillator", "Tone generator and probe", "Signal tracing"], "common_mistakes": ["UNSAFE: Sending a full-level tone into live speakers or in-ear monitors, which can produce a painfully loud blast and risk hearing damage; lower the level and warn people first.", "Mistaking a tone heard through crosstalk or a wrong patch for true continuity on the intended line.", "Forgetting to remove the oscillator or tone from the mix before the performance."], "scenario_contexts": ["Tracing which of many identical black cables in a bundle carries a given channel.", "Confirming a dead input is a cable fault rather than a console setting.", "Verifying a stage-to-FOH multicore line before doors open."]}, "c4c6b0cc-cb88-4894-952c-1ce98012ba23": {"definition": "A transformer-isolated split is a microphone/line splitter that feeds one or more of its outputs through a 1:1 (unity-ratio) audio transformer, giving galvanic isolation between the shared consoles. The transformer passes the AC audio signal while blocking DC and interrupting the ground/DC path, which breaks ground loops between consoles and prevents phantom power crossing on that isolated leg (phantom must be supplied only through a direct output).", "plain_english": "A transformer-isolated split copies one mic signal to several mixing desks. At least one copy goes through a small transformer. The transformer passes the sound but blocks stray DC and the hum from ground loops. That leg cannot carry phantom power, so only one desk feeds power to the mic.", "purpose_function": "It lets front-of-house, monitors, and broadcast share the same stage mics without their grounds interacting, preventing hum and buzz and stopping one console's fault or phantom power from reaching another.", "practical_application": "A technician patches stage mics into the split, runs isolated feeds to each console, and chooses one console (usually via a direct output) to supply phantom power for condenser mics.", "category": "Signal distribution", "related_terms": ["Festival split", "Microphone splitter", "Transformer isolation", "Ground loop", "Phantom power", "Common-mode rejection"], "common_mistakes": ["Trying to power a condenser mic through the transformer-isolated leg, which blocks phantom power; use the direct output instead.", "Applying phantom power from more than one console on a direct (transformerless) tap, which can conflict and damage inputs.", "Assuming every output on the box is isolated when only the transformer leg is; direct taps still share ground and can hum."], "scenario_contexts": ["A festival where FOH and monitor consoles must share the same mics without ground-loop hum.", "A broadcast truck taking a galvanically isolated feed of every stage channel.", "Curing hum between two consoles by moving one feed to the isolated leg."]}, "71488041-4f97-49d5-9fae-b69d939053b7": {"definition": "'Work backward' is a troubleshooting method in which the technician starts at the output end of the signal chain (for example, the silent loudspeaker or a missing meter reading) and checks each stage moving upstream toward the source until the fault is located. It is efficient when the failure shows at the end of the chain and the source is known or likely to be good.", "plain_english": "Working backward means you start at the end where the problem shows, like a dead speaker. Then you check each part back toward the source until you find the fault. It is like following a garden hose from the dry end back to the kink.", "purpose_function": "It gives troubleshooting a clear direction, so a technician checks one stage at a time instead of guessing, quickly narrowing down where signal is being lost.", "practical_application": "When a channel is dead at the speaker, a technician checks the amplifier, then the processor, console output, and channel strip, moving upstream until signal reappears.", "category": "Troubleshooting method", "related_terms": ["Work forward", "Signal chain", "Signal flow", "Signal tracing", "Divide and conquer", "Root cause analysis"], "common_mistakes": ["Skipping stages and guessing instead of checking each point in order.", "Assuming the source is good without confirming it, so the real fault is missed.", "Confusing 'backward' (toward the source) with moving toward the speakers."], "scenario_contexts": ["A dead main speaker traced from the amplifier back to the console.", "No signal at FOH traced back through the multicore to the stage box.", "A missing output found by checking each stage from the amp inputs upstream."]}, "7ea9b49d-f699-48de-bd2a-42d2290fc1db": {"definition": "'Work forward' is a troubleshooting method in which the technician starts at the source end of the signal chain (for example, the microphone or instrument input) and checks each stage moving downstream toward the output until the fault is found. It is efficient when the input is the suspect stage or when systematically verifying a newly built signal path.", "plain_english": "Working forward means you start at the source, like the microphone, and follow the signal on toward the speakers. You check each part in order until you find where the sound stops. It is like tracing a river from its start down to the sea.", "purpose_function": "It gives troubleshooting a clear order from source to output, which is useful for checking a new patch or when the input itself is doubtful.", "practical_application": "Setting up a new channel, a technician confirms the mic, cable, preamp, and channel strip in turn, moving downstream to be sure each stage passes signal.", "category": "Troubleshooting method", "related_terms": ["Work backward", "Signal chain", "Signal flow", "Line check", "Signal tracing", "Gain staging"], "common_mistakes": ["Jumping ahead instead of verifying each stage from the source in order.", "Not confirming the output path is otherwise working, so a downstream fault hides the test.", "Confusing 'forward' (toward the speakers) with moving toward the source."], "scenario_contexts": ["Verifying a new mic channel from capsule to console step by step.", "Checking a signal path during line check from the stage input onward.", "Isolating a fault when the source or first cable is the suspect."]}, "0bd26978-e623-497a-bd39-246a7dd286e0": {"definition": "'Wrong channel' describes a common operator fault in which a source is present and working but is being sent to, monitored on, or adjusted on a different console channel than intended, so the expected result does not occur. Typical cases include a mic patched to the wrong channel, or an engineer riding the fader of a channel other than the one carrying the signal.", "plain_english": "Wrong channel means the sound is fine, but you are working on the wrong strip. The mic may be plugged into a different channel than you think. So the fader you move does nothing. Checking the patch fixes it.", "purpose_function": "Naming this fault reminds a technician that 'no sound' is often a routing or patch error, not broken gear, so they check channel assignment before chasing hardware.", "practical_application": "When a fader seems dead, a technician checks whether the source is actually on that channel, since the mic may be patched or routed to a different one.", "category": "Operator error", "related_terms": ["Patch", "Routing", "Signal chain", "Line check", "Wrong socket", "Wrong mix"], "common_mistakes": ["Assuming a dead fader means broken gear when the source is on another channel.", "Adjusting EQ or gain on the wrong strip and wondering why nothing changes.", "Not labeling channels, which makes wrong-channel mistakes more likely."], "scenario_contexts": ["A vocal mic that seems dead because it is patched to a neighboring channel.", "An engineer muting the wrong channel during a show.", "Gain set on the wrong strip during line check."]}, "0299acbb-5bd6-4a2b-bc92-f2d0b36e61e9": {"definition": "'Wrong mix' describes a fault, common in monitoring, where audio is present but the listener is fed the wrong mix bus—for example a performer's in-ear or wedge receiving another performer's monitor mix, or a feed taken from the wrong aux or output. The signal itself is fine; the routing or send selection is incorrect.", "plain_english": "Wrong mix means someone hears sound, but it is the wrong blend. A singer might get the drummer's monitor mix by mistake. Nothing is broken; the wrong feed was sent. Fixing the routing solves it.", "purpose_function": "Naming this fault points a technician to check mix and send routing when a performer complains about their monitors, rather than assuming a dead or faulty feed.", "practical_application": "When a musician says their monitor sounds wrong, a technician confirms which aux or mix bus feeds that wedge or in-ear before changing any levels.", "category": "Operator error", "related_terms": ["Monitor mix", "Aux send", "Mix bus", "In-ear monitor", "Wrong channel", "Routing"], "common_mistakes": ["Adjusting levels on a monitor feed before checking it is even the right mix.", "Sending one mix to every wedge and assuming each performer hears their own.", "Confusing a wrong-mix routing error with a faulty monitor or cable."], "scenario_contexts": ["A vocalist hearing the drummer's monitor mix in their in-ears.", "A wedge fed from the wrong aux bus during soundcheck.", "A broadcast feed carrying the wrong output mix."]}, "6ec796bc-0768-4151-b3dd-9f0c6639b75a": {"definition": "'Wrong socket' describes a fault where a cable is physically connected to the wrong jack or connector, so signal does not reach its intended destination—for example a plug in an adjacent input, a send jack used as a return, or a lead in the wrong stage-box position. The cable and signal are fine; only the connection point is incorrect.", "plain_english": "Wrong socket means the cable is plugged into the wrong hole. The lead and the signal are fine, but it is in the wrong jack. So the signal goes nowhere useful. Moving it to the right socket fixes it.", "purpose_function": "Naming this fault reminds a technician to check that every cable is in its correct connector before assuming a cable or device has failed.", "practical_application": "When an input is dead, a technician checks that the plug is in the right stage-box hole or console jack, not an adjacent or wrongly numbered one.", "category": "Operator error", "related_terms": ["Patch", "Stage box", "Connector", "Wrong channel", "Line check", "Signal chain"], "common_mistakes": ["Assuming a dead line is a bad cable when the plug is simply in the wrong socket.", "Miscounting holes on a stage box and inserting a plug one position off.", "Using a send jack as a return, or an output as an input, by mistake."], "scenario_contexts": ["A mic plugged into the wrong numbered input on the stage box.", "A lead in the adjacent jack, so the expected channel stays silent.", "A return patched into a send socket on a patchbay."]}, "4d74c1bf-b588-4a1b-87d6-d8f1c862bff4": {"definition": "A double patch is a patchbay connection that routes a single signal to two destinations at once, splitting one source into two paths as a form of manual mult. In routing diagnostics it can also describe the fault of feeding one destination from two sources at the same time, which causes level, phase, or loading conflicts.", "plain_english": "A double patch sends one signal to two places at the same time using patch cords. It can be on purpose, like a split. It can also be a mistake that makes two signals fight over one input.", "purpose_function": "It lets one source feed two destinations without extra hardware, for example sending a mic to both a recorder and the mix. Naming it also helps a technician spot when a signal has been split or duplicated by accident.", "practical_application": "A technician might double patch a source to monitor and record it at once, or find a double patch when a channel is unexpectedly loud or distorted because two feeds share it.", "category": "Patching technique", "related_terms": ["Mult", "Half-normal", "Patchbay", "Repatch", "Mispatch", "Signal splitter"], "common_mistakes": ["Assuming two feeds into one input sum cleanly, when two sources can conflict in level or phase.", "Double patching a source and forgetting one path is still live, causing unexpected sound or bleed.", "Confusing a deliberate split (mult) with an accidental double patch during troubleshooting."], "scenario_contexts": ["Splitting one mic to both a recorder and the main mix through the patchbay.", "Finding a channel is distorted because two patch cords feed the same input.", "Sending a playback source to two rooms at once for monitoring."]}, "22d17630-3225-484b-9366-7bada477f8f7": {"definition": "A mispatch is a patching error in which a signal is connected to the wrong point, so a source reaches an unintended destination or a destination is fed from the wrong source. It results in missing, wrong, or misrouted audio until the connection is corrected.", "plain_english": "A mispatch is a wrong connection on a patchbay or router. The signal goes to the wrong place, or a channel gets the wrong source. It usually means silence or the wrong sound until you fix it.", "purpose_function": "Naming this error helps technicians describe and fix routing faults quickly. It points straight to checking whether cords or assignments went to the correct points.", "practical_application": "When a channel is silent or plays the wrong instrument, a technician suspects a mispatch and checks each connection against the patch list.", "category": "Patching error", "related_terms": ["Patchbay", "Repatch", "Patch discrepancy", "Signal flow", "Patch list", "Trace the line"], "common_mistakes": ["Blaming a dead channel on faulty gear when the real problem is a simple mispatch.", "Not checking the patch against a patch list or scene sheet before the show.", "Fixing a mispatch on one point but leaving its wrong pair still connected."], "scenario_contexts": ["A wireless mic showing up on the wrong console channel.", "A monitor send feeding the wrong wedge on stage.", "A recorder input capturing the wrong source because of a swapped patch."]}, "8bfe628f-29b2-44d9-9cee-65a1dc6ec974": {"definition": "An output patch is the assignment that routes a console or device's internal signal, such as a bus, mix, or channel direct out, to a specific physical or network output connector. On digital consoles it is the configurable mapping between internal output paths and output sockets or Dante, MADI, or AES streams.", "plain_english": "An output patch decides which real socket or network channel a mix or bus comes out of. It links the signal inside the desk to a physical output. Set it wrong and the sound leaves the wrong hole.", "purpose_function": "It exists so engineers can map internal mixes and buses to whatever outputs feed amps, speakers, recorders, or other systems. This flexibility lets one console drive many destinations.", "practical_application": "A technician sets the output patch to send the main mix to the PA amps and the monitor mixes to the correct stage box sockets.", "category": "Signal routing", "related_terms": ["Input patch", "Bus", "Stage box", "Dante", "MADI", "Repatch"], "common_mistakes": ["Confusing the output patch (bus to socket) with channel routing (channel to bus).", "Forgetting to update the output patch after changing which stage box or output card is used.", "Leaving an unused output patched live, sending signal where it is not wanted."], "scenario_contexts": ["Mapping matrix outputs to delay-tower amplifiers at a large show.", "Patching monitor mixes to the correct stage box outputs.", "Routing a recording feed to a MADI or Dante output."]}, "795da746-9dbc-4c62-a1ac-275435b1d2e5": {"definition": "A patch change is any alteration to the existing patching or routing, whether repatching physical cords or recalling a different routing configuration on a console. In show operation it often refers to a planned routing change made between songs, scenes, or acts.", "plain_english": "A patch change is when you change how signals are connected or routed. It might be moving cables or recalling a new setup on the desk. Shows often plan these changes between songs or acts.", "purpose_function": "It lets a system be reconfigured for different needs, such as a new act, instrument, or output setup. Planning patch changes keeps transitions fast and avoids mistakes during a show.", "practical_application": "Between sets, a technician makes the planned patch changes so the next band's inputs and outputs land on the right channels.", "category": "Patch operation", "related_terms": ["Repatch", "Scene recall", "Patch list", "Mispatch", "Output patch", "Input patch"], "common_mistakes": ["Making a patch change on a live signal and causing a loud pop or dropout.", "Not documenting a patch change, so the next technician cannot follow the routing.", "Recalling the wrong scene and applying an unintended patch change."], "scenario_contexts": ["Switching input routing between two bands during a festival changeover.", "Recalling a new console scene that repatches monitor sends for a song.", "Moving a recording feed from one output to another mid-event."]}, "6bdd6d94-d928-4b75-9faa-441bbfc37872": {"definition": "A patch discrepancy is a mismatch between the intended or documented patch, such as a patch list, scene, or plan, and the actual connections in place. It flags that the real routing does not agree with the reference and must be reconciled.", "plain_english": "A patch discrepancy is when the real connections do not match the plan. The patch list says one thing, but the cables or desk say another. It warns you to check and fix the routing.", "purpose_function": "Spotting a discrepancy catches routing errors before they cause problems in a show or session. It drives the technician to compare the actual patch against the documented plan.", "practical_application": "During line check, a technician compares each channel to the patch list and resolves any patch discrepancy before doors open.", "category": "Patching error", "related_terms": ["Patch list", "Mispatch", "Repatch", "Line check", "Trace the line", "Scene recall"], "common_mistakes": ["Ignoring a small discrepancy and assuming it will not matter once the show starts.", "Trusting memory instead of checking the patch against a written patch list.", "Fixing the symptom on the desk without correcting the underlying wrong connection."], "scenario_contexts": ["Line check reveals a channel labeled for kick is actually carrying snare.", "A recalled scene routes a bus differently from the documented plan.", "A guest engineer's patch list does not match how the stage is wired."]}, "ffdef981-f868-491f-a105-05abf34ce678": {"definition": "To repatch is to change existing connections or routing, by moving patch cords or reassigning routing on a console or router, so signals follow a new path. It is the action taken to correct a mispatch or to reconfigure a system for a new requirement.", "plain_english": "To repatch means to change the connections so signals go a new way. You move cables or change the routing on the desk. Engineers repatch to fix a wrong connection or set up for something new.", "purpose_function": "Repatching lets a system be corrected or reconfigured without new hardware. It is how technicians fix routing faults and adapt to changing input or output needs.", "practical_application": "After finding a mispatch, a technician repatches the affected channel to the correct input and confirms signal at the console.", "category": "Patch operation", "related_terms": ["Mispatch", "Patch change", "Patchbay", "Patch discrepancy", "Output patch", "Input patch"], "common_mistakes": ["Repatching a live channel without muting it first, causing a loud pop.", "Repatching to fix a problem but forgetting to update the patch list.", "Assuming a repatch fixed the fault without checking signal actually flows correctly."], "scenario_contexts": ["Repatching a dead channel to a spare input after a connector fails.", "Repatching monitor sends when a musician moves position on stage.", "Reconfiguring outputs by repatching for a different speaker setup."]}, "0650f414-c735-4d56-9066-464e3df8e99e": {"definition": "A routing loop is a signal path accidentally connected back into itself, so an output feeds a point upstream in the same chain and the signal recirculates. In consoles and DAWs this feedback loop causes runaway level buildup, oscillation, or loud howling until the offending routing is broken.", "plain_english": "A routing loop is when a signal is sent back into itself by mistake. The output feeds the input, so it goes round and round. This builds up fast into a loud howl or squeal until you break the connection.", "purpose_function": "Naming this fault helps technicians recognise and stop a fast-building howl caused by signal feeding back on itself. It points to finding and breaking the connection that closes the loop.", "practical_application": "When a bus suddenly howls or the meters pin for no clear reason, a technician looks for a routing loop, such as an aux or bus fed back to its own input.", "category": "Routing fault", "related_terms": ["Feedback", "Aux send", "Bus", "Signal flow", "Mix-minus", "Oscillation"], "common_mistakes": ["UNSAFE: Leaving a routing loop running at high level, which can damage speakers, hearing, and equipment; mute or break it at once.", "Confusing a routing loop with acoustic feedback from a mic and speaker; a routing loop is an internal signal path, not a room effect.", "Accidentally routing an output back to an input while patching, then not tracing why the level runs away."], "scenario_contexts": ["A digital console output patched back into its own input, causing sudden oscillation.", "A DAW track's output bus routed to a track that feeds it again.", "An aux send fed back into the same aux, building into a loud howl."]}, "070131ca-059d-4868-aabe-99a5757eae19": {"definition": "To trace the line is to systematically follow a signal path from source to destination, or from destination back to source, checking each connection, device, and setting in turn to locate where the signal is lost or altered. It is a core diagnostic method for isolating faults in a signal chain.", "plain_english": "Tracing the line means following a signal step by step to find where it breaks. You check each cable, connector, and setting from start to finish. It is how you find the exact spot a signal disappears.", "purpose_function": "It exists to isolate a fault to one point instead of guessing. Following the chain in order turns a vague 'no sound' into a specific bad cable, patch, or setting.", "practical_application": "When a channel is dead, a technician traces the line from the mic through the cable, stage box, patch, and preamp until the break is found.", "category": "Troubleshooting technique", "related_terms": ["Signal flow", "Signal chain", "Mispatch", "Line check", "Cable tester", "Patchbay"], "common_mistakes": ["Jumping to the middle of the chain instead of tracing in order from one end.", "Changing several things at once, so it is unclear which change fixed the fault.", "Skipping the obvious first checks like mute, gain, and patch before deeper tracing."], "scenario_contexts": ["A dead vocal mic traced from capsule to console to find a broken cable.", "Following a hum source through the chain to find where it enters.", "Tracing a monitor feed to learn why one wedge is silent."]}, "374a6a54-7e04-4209-8b62-669da833805f": {"definition": "A bass drum carrier is a rigid, body-worn harness that supports a marching bass drum in front of the player, holding the drum at a fixed height and angle so it can be played while marching. It transfers the instrument's weight to the shoulders, chest, and back, keeping the player's hands free and the drum stable in motion.", "plain_english": "A bass drum carrier is a frame you wear like a vest to hold a marching bass drum. It keeps the drum out in front at the right height. It spreads the weight across your shoulders and back. This lets you play and march at the same time.", "purpose_function": "It exists to hold a heavy drum steady on a moving player without using the hands, spreading the load to protect the player and keep the drum in a consistent playing position.", "practical_application": "When setting up a drumline, a player or technician fits the carrier so the drum sits at the correct height and angle, and checks that mounting hardware and any mic clips are secure before the field show.", "category": "Marching hardware", "related_terms": ["Marching snare", "Drumline", "Clip-on microphone", "Instrument mounting", "Field projection"], "common_mistakes": ["Setting the carrier height or angle wrong, which strains the player's back and changes the playing position.", "Failing to lock the adjustments so the drum shifts or drops during marching.", "Mounting a microphone or clip to the carrier without keeping it clear of the player's hands and sticks."], "scenario_contexts": ["Fitting a drumline's bass drums before a field show or competition.", "Mounting clip-on microphones to carried drums for amplification or broadcast.", "Adjusting carrier fit for players of different heights across a section."]}, "2e7523b0-dc4b-48b9-b92d-bd550dda8fcb": {"definition": "Bell-front projection is the forward radiation of sound from a brass instrument whose bell faces ahead of the player, such as a marching mellophone, bell-front baritone, or convertible marching brass, directing the strongest output toward the audience or field ahead. Because a brass instrument radiates most of its higher-frequency energy from the bell, a forward-facing bell aims that directional output at listeners rather than upward or to the side.", "plain_english": "Bell-front projection means a brass horn points its bell forward, so the sound aims ahead. Marching horns use this so the crowd hears them across the field. A horn sends most of its bright sound out of the bell. Facing it forward points that sound at the audience.", "purpose_function": "It exists so marching brass can throw sound toward the audience while players move down the field, improving loudness and clarity for distant listeners compared with upright or side-facing bells.", "practical_application": "A live-sound or broadcast technician aims microphones in front of bell-front instruments to capture their strongest, most direct output, and considers bell direction when predicting how a marching line will sound to the crowd.", "category": "Instrument acoustics", "related_terms": ["Directivity", "Mellophone", "Field projection", "Clip-on microphone", "Off-axis response"], "common_mistakes": ["Miking a bell-front instrument from the side or rear, which misses its strongest, most direct sound.", "Assuming all brass radiate equally in every direction, when high frequencies are strongly directional from the bell.", "Confusing bell-front projection (instrument direction) with PA projection across the field."], "scenario_contexts": ["Aiming spot mics at the front of a marching brass line.", "Comparing how upright versus bell-front horns reach the audience.", "Predicting coverage when a drum corps front ensemble faces the stands."]}, "445eb0b4-3af0-407f-a921-7fa9b8205767": {"definition": "Compander mode is the noise-reduction operating scheme of an analog wireless microphone system, in which the audio is compressed before FM transmission and expanded by the matching law at the receiver to lift the signal above the RF noise floor. The transmitter and receiver must use the same compander scheme (for example a matched 2:1 compression and 1:2 expansion), or the recovered audio has wrong dynamics and sounds dull and flat.", "plain_english": "Compander mode is a noise-cutting trick in analog wireless mics. The transmitter squeezes the sound's loud-to-quiet range before sending it. The receiver stretches it back to normal, which pushes down the radio hiss. Both units must use the same setting, or the sound comes out wrong.", "purpose_function": "It exists to raise the signal-to-noise ratio of a noisy analog radio link; matching the compression and expansion restores the original dynamics while suppressing hiss.", "practical_application": "A technician makes sure paired transmitters and receivers use the same compander system or mode, so wireless mics on a field or stage sound clean rather than dull or pumping.", "category": "Wireless systems", "related_terms": ["Companding", "Wireless microphone", "Deviation setting", "Signal-to-noise ratio", "Squelch"], "common_mistakes": ["Pairing a transmitter and receiver that use different companding schemes, giving reduced dynamic range and dull audio.", "Assuming companding removes all noise, when it only reduces the audible RF noise floor.", "Confusing wireless companding with the simple compression used for level control at the console."], "scenario_contexts": ["Matching bodypack transmitters to receivers in a wireless system.", "Troubleshooting dull or pumping wireless audio caused by mismatched companders.", "Comparing analog companded systems with digital wireless during system selection."]}, "e96908a1-21bb-4998-a797-1832bb340861": {"definition": "Crowd bleed is the unwanted pickup of audience or spectator noise by microphones intended to capture performers, a form of bleed (spill or leakage) in which off-target sound enters a mic. In live sound and broadcast it reduces separation and clarity, raising the level of crowd cheering, talking, and ambient noise in channels meant for instruments or voices.", "plain_english": "Crowd bleed is when audience noise leaks into microphones meant for the performers. The mic picks up cheering and talking you did not want. This makes the wanted sound less clear. It is a common problem at loud, crowded events.", "purpose_function": "Naming this leakage helps a technician diagnose why performer channels sound cluttered or noisy, and points to fixes such as tighter mic placement, directional mics, and level control.", "practical_application": "At a stadium or field event, a technician uses directional mics, close placement, and careful gain to limit how much crowd noise bleeds into performer and instrument channels.", "category": "Microphone technique", "related_terms": ["Bleed", "Off-axis rejection", "Directional microphone", "Field ambience", "Gain before feedback"], "common_mistakes": ["Turning a performer channel up to overcome crowd bleed, which only raises the crowd noise too.", "Using an omnidirectional mic where a directional one would reject more crowd noise.", "Confusing deliberate crowd or ambience mics with unwanted crowd bleed into performer mics."], "scenario_contexts": ["A stadium mic for a soloist also picking up nearby spectators.", "Sideline instrument mics catching crowd cheers during a marching show.", "Broadcast performer feeds contaminated by audience noise."]}, "8981c3d8-3ca8-46b6-96ab-b553ed201533": {"definition": "The deviation setting controls the frequency deviation of an FM wireless microphone transmitter, that is, the maximum amount the carrier frequency shifts away from its center in response to the audio signal, expressed in kilohertz. It trades audio dynamic range and signal-to-noise ratio against occupied RF bandwidth, and must stay within the channel spacing to avoid interfering with adjacent systems.", "plain_english": "The deviation setting controls how far an FM wireless mic's radio signal swings from its center frequency. A bigger swing can give better sound but uses more radio space. Too much can spill into a neighbor's channel. Technicians keep it within safe limits.", "purpose_function": "It exists to balance audio quality against the radio bandwidth each transmitter uses, so more wireless channels can share the spectrum without interfering.", "practical_application": "During frequency coordination, a technician relies on the system's set deviation to space channels correctly and avoid interference between many wireless mics on a field or stage.", "category": "Wireless systems", "related_terms": ["Frequency deviation", "Companding", "Frequency coordination", "Carrier frequency", "Intermodulation"], "common_mistakes": ["Assuming the deviation figure equals the full RF bandwidth used, when sidebands make the real bandwidth wider.", "Packing channels too closely without accounting for deviation, causing interference.", "Confusing frequency deviation with the carrier (channel) frequency itself."], "scenario_contexts": ["Coordinating many wireless mics for a marching band or festival.", "Diagnosing interference traced to overly wide modulation.", "Comparing bandwidth needs of analog FM versus digital wireless systems."]}, "fd1fab13-d70b-4707-9701-e1e625934c03": {"definition": "Field ambience is the ambient environmental sound of an outdoor performance space, such as a sports or marching field, including crowd noise, wind, and the open-air acoustic character, often captured with dedicated ambience (effects) microphones. It is used to convey a sense of the live space and atmosphere in a broadcast or reinforcement mix, separate from close-miked sources.", "plain_english": "Field ambience is the background sound of an open outdoor space, like a stadium field. It includes the crowd, the wind, and the wide-open feel. Sound teams capture it with special mics. It makes a broadcast feel live and real.", "purpose_function": "It exists to add realism and a sense of place to a mix, giving listeners the atmosphere of being at the event rather than only hearing isolated close mics.", "practical_application": "A broadcast technician places ambience mics around a field to capture crowd and environment, then blends that with close-miked performers for a natural, immersive mix.", "category": "Sound capture", "related_terms": ["Ambience microphone", "Crowd bleed", "Room tone", "Field projection", "Stereo miking"], "common_mistakes": ["Mixing ambience mics too loud, which buries the performers and adds noise.", "Confusing intentional field ambience with unwanted crowd bleed in performer channels.", "Placing ambience mics where they only catch wind noise instead of useful atmosphere."], "scenario_contexts": ["Capturing stadium atmosphere for a televised marching-band or sports broadcast.", "Adding crowd and environment under a close-miked field ensemble.", "Recording the open-air sound of an outdoor competition."]}, "c80cd263-219c-4fc2-8172-88ba1d2e7c79": {"definition": "Field projection is the carrying of sound across a large open outdoor area, such as a marching field or stadium, so it reaches distant listeners with adequate level and clarity. Outdoors there are few reflecting surfaces to reinforce sound, so level falls with distance (roughly following the inverse-square law) and is further affected by wind and temperature, making projection harder than indoors.", "plain_english": "Field projection is how well sound travels across a big open field to reach far-away listeners. Outdoors there are no walls to bounce sound back, so it fades fast with distance. Wind and temperature can push it around too. This makes it hard to be heard far away.", "purpose_function": "The idea helps technicians plan how instruments and PA systems will reach a distant outdoor audience, guiding choices of level, directivity, and speaker placement.", "practical_application": "A technician chooses directional loudspeakers, enough power, and careful aiming to project sound across a field, knowing open air offers no reflections to help carry it.", "category": "Sound propagation", "related_terms": ["Inverse-square law", "Bell-front projection", "Directivity", "Sound reinforcement", "Field ambience"], "common_mistakes": ["Expecting outdoor sound to carry like it does indoors, ignoring the loss from no reflections.", "Underestimating how wind and temperature bend and weaken sound over a field.", "Relying on raw volume instead of directional speakers and proper aiming for distance."], "scenario_contexts": ["Reinforcing a marching-band show so the far stands can hear it.", "Planning PA coverage for an outdoor field or stadium event.", "Comparing how sound carries indoors versus across an open field."]}, "ce5b8f0e-bc86-4d4a-8b9f-ace3770f39fc": {"definition": "A marching headset microphone is a head-worn (headworn) microphone with a boom that positions the capsule near the mouth for hands-free voice pickup, used on the field by a band director, drum major, or clinician to address or instruct performers over a PA. Its head-worn design keeps a constant mouth-to-mic distance during movement, and field use demands a secure fit and resistance to wind and outdoor conditions.", "plain_english": "A marching headset microphone is a mic worn on the head with a small boom near the mouth. It leaves the hands free, which helps a director or drum major who is conducting. Because it moves with the head, the voice stays even. It is used to be heard over a loud band outdoors.", "purpose_function": "It exists to give a moving instructor or leader consistent, hands-free amplified voice on the field, holding the mic at a fixed distance from the mouth for steady level and better gain before feedback.", "practical_application": "A technician fits the headset snugly, sets the boom just off the corner of the mouth, and pairs it with a bodypack wireless transmitter so a director can be heard across the field.", "category": "Microphones", "related_terms": ["Headworn microphone", "Bodypack transmitter", "Wireless microphone", "Windscreen", "Gain before feedback"], "common_mistakes": ["Placing the boom directly in front of the mouth, which causes popping from breath and plosives.", "Skipping a windscreen outdoors, letting wind noise ruin the voice pickup.", "Not securing the headset, so it shifts during movement and changes the level."], "scenario_contexts": ["A band director instructing rehearsal hands-free over a portable PA.", "A drum major or announcer being amplified during a field show.", "A clinician moving among sections while staying audible outdoors."]}, "cfeee341-4c76-4b25-b06d-a663bf6313d8": {"definition": "A marching snare is a high-tension snare drum designed to be carried and played on the move in a drumline, typically with a deeper shell tuned very tightly and often fitted with a synthetic aramid (Kevlar-type) batter head, producing a loud, crisp, articulate sound that projects outdoors. It is worn on a carrier harness and struck with sticks while marching.", "plain_english": "A marching snare is a snare drum built to be carried and played while marching. It is tuned very tight and hits hard, so it sounds loud and sharp outdoors. Players wear it on a harness. It uses a tough fiber head to take the high tension.", "purpose_function": "It exists to deliver a loud, cutting, precise drum sound that carries across an outdoor field, while staying wearable and playable in motion within a drumline.", "practical_application": "A technician mounts or clips a microphone near the batter head to amplify or record a marching snare, working around its very high volume and the player's movement.", "category": "Marching percussion", "related_terms": ["Bass drum carrier", "Drumline", "Clip-on microphone", "Field projection", "Snare drum"], "common_mistakes": ["Tuning a marching snare loose like a drum-set snare, losing the crisp, projecting sound it is built for.", "Over-tightening the head far beyond recommended tension, which can damage the head or drum hardware.", "Miking the drum too closely at its high volume, overloading the mic input and causing distortion."], "scenario_contexts": ["Amplifying a drumline's snares for a stadium or indoor show.", "Miking marching snares for a broadcast or recording of a field show.", "Setting up a snare line's tuning and carriers before a competition."]}, "f1981bde-f73b-4cfb-8eb8-823a8a7eb68f": {"definition": "The practice of amplifying and distributing sound for audiences in open-air environments, where the absence of enclosing surfaces means little to no reverberant reflection and sound level falls off with distance largely according to the inverse-square law (about 6 dB per doubling of distance in the free field). Coverage, intelligibility, and level are shaped by wind, temperature gradients, humidity, and ground effects rather than by room acoustics.", "plain_english": "Outdoor reinforcement is running a sound system outside, with no walls or roof. Sound spreads out and gets quiet fast as you move away. Wind and warm or cold air can bend it and change what people hear.", "purpose_function": "It delivers even, intelligible coverage to a spread-out open-air audience where there are no walls to contain or reinforce the sound. Loudspeaker placement, directivity, and delay must do the work that room reflections do indoors.", "practical_application": "A technician selects directional, weather-resistant loudspeakers, adds delay towers for distant crowds, and plans for wind and temperature changes across a show day.", "category": "Live sound application", "related_terms": ["Delay tower", "Inverse-square law", "Line array", "Wind bleed", "Parade PA", "Sound reinforcement"], "common_mistakes": ["Expecting indoor SPL and coverage outdoors, then under-powering the system for the open-air distances involved.", "Ignoring wind and temperature gradients, which bend and shift sound so coverage changes through the day.", "UNSAFE: Powering outdoor gear from mains without GFCI/RCD protection and weatherproofing, risking electric shock in damp conditions."], "scenario_contexts": ["Amplifying a band at an outdoor festival on a large open field.", "Providing speech reinforcement for a graduation or rally in a park or stadium.", "Covering a distant crowd with delay towers at an open-air concert."]}, "7e921adf-d980-4b52-bca8-d3f5d1809ed4": {"definition": "A public-address arrangement used to provide announcements, music, or reinforcement along a parade route, typically implemented as mobile loudspeakers mounted on floats or vehicles, or as a distributed series of fixed speaker positions spaced along the route. Because the audience and often the source are moving and spread over a long linear path, it relies on multiple local coverage zones rather than a single central system.", "plain_english": "A parade PA is a sound system for a parade. Speakers ride on floats or trucks, or sit along the street. Each one covers just the people nearby, so the whole route can hear the music.", "purpose_function": "It exists to carry sound to a long, moving crowd strung out along a route that one central system cannot cover. Splitting coverage into local zones keeps everyone within earshot as the parade passes.", "practical_application": "A technician rigs battery- or generator-powered speakers on floats, or spaces powered loudspeakers along the route, managing level and any delay between zones.", "category": "Live sound application", "related_terms": ["Outdoor reinforcement", "Distributed system", "Powered loudspeaker", "Delay", "Sound reinforcement", "Sideline microphones"], "common_mistakes": ["Trying to cover a whole route from one speaker stack instead of using several local zones.", "Overlapping speaker zones without delay, causing echoes and smeared speech where coverage meets.", "UNSAFE: Running generators or mains cabling on a wet street without GFCI/RCD protection and cable ramps, risking shock and trip hazards."], "scenario_contexts": ["Playing music from speakers mounted on a parade float moving down a street.", "Spacing powered speakers along a parade route for announcements.", "Providing a reviewing-stand announcer system as a parade passes."]}, "a491f23c-bb52-44c0-9e71-0a449f1dca36": {"definition": "A squelch technique in wireless microphone systems in which the transmitter continuously sends an inaudible (supra- or sub-audible) pilot tone along with the audio, and the receiver unmutes only when it detects both adequate RF signal strength and the presence of that specific tone. This tone-key verification prevents the receiver from opening onto interference or another transmitter on the same frequency when the intended transmitter is switched off.", "plain_english": "Pilot tone detection uses a hidden signal that a wireless mic sends with the sound. You cannot hear it. The receiver only turns on when it hears that secret tone. This stops loud static when the mic is off.", "purpose_function": "It stops the receiver from passing noise, static, or a rogue signal whenever the matching transmitter is not present. It lets a receiver open only for its own paired transmitter.", "practical_application": "A technician relies on pilot-tone squelch so that switching a bodypack off produces silence, not a burst of RF noise, during a live show.", "category": "Wireless systems", "related_terms": ["Tone key selection", "Squelch", "Wireless microphone", "Diversity reception", "RF interference", "Companding"], "common_mistakes": ["Assuming a silent receiver means the transmitter battery is fine, when pilot-tone squelch simply mutes a missing signal.", "Pairing transmitters and receivers that use incompatible tone-key schemes, so the receiver never unmutes.", "Confusing pilot-tone squelch with a simple noise gate on the audio."], "scenario_contexts": ["A receiver staying muted when a performer powers down a handheld transmitter.", "Rejecting a same-frequency intermittent interferer that lacks the correct tone-key.", "Troubleshooting a channel that will not unmute because of a tone-key mismatch."]}, "76d2ff21-f144-4c60-89ec-428289c5127f": {"definition": "Microphones positioned along the sidelines of a sports field or event to capture on-field or on-course sound (impacts, calls, whistles, and ambience) for broadcast or reinforcement. They are commonly highly directional shotgun microphones or parabolic-reflector microphones aimed at the action from the perimeter.", "plain_english": "Sideline microphones sit along the edge of a sports field. They point at the players to pick up hits, whistles, and calls. They are very directional, so they hear one spot and reject the rest.", "purpose_function": "They capture the close-up action sounds that make a broadcast feel live, from the field edge where crew already stand. Their tight pickup pattern isolates on-field sound from surrounding crowd noise.", "practical_application": "A broadcast audio tech deploys stand-mounted or handheld shotguns, and parabolic dishes, along the touchline and feeds them to the truck for the game mix.", "category": "Microphone application", "related_terms": ["Shotgun microphone", "Parabolic microphone", "Wind bleed", "Ambience microphone", "Outdoor reinforcement", "Directional microphone"], "common_mistakes": ["Using shotgun mics outdoors without adequate wind protection, letting wind rumble ruin the feed.", "Assuming a shotgun mic has long 'reach' rather than simply a narrower pickup angle.", "Aiming the mic loosely, so crowd noise and PA spill dominate the on-field sound."], "scenario_contexts": ["Capturing tackles and whistles at a football or rugby broadcast.", "Using parabolic dishes to follow play across a field for television.", "Miking the touchline for on-field ambience in a live sports mix."]}, "96ffdc07-c0ac-4aa0-b4a7-36113bacd700": {"definition": "The large flared terminal opening of a sousaphone-the marching form of the bass tuba associated with John Philip Sousa's band-which on the modern sousaphone is a detachable, forward-facing bell mounted above the player so the sound projects out over a moving band. As the point where the vibrating air column radiates into the air, the bell shapes the instrument's tone and the direction of its low-frequency output.", "plain_english": "A sousaphone is a big brass bass horn that wraps around the player for marching. Its bell is the wide, flared opening at the end. The bell points forward, so the deep sound shoots out ahead of the band.", "purpose_function": "The bell is where the vibrating air column leaves the instrument and becomes sound in the air, shaping its tone and directivity. Facing it forward lets a marching player throw the bass toward the audience instead of upward.", "practical_application": "When miking a sousaphone, a technician places or clips the microphone near or just inside the forward-facing bell, where the low-frequency energy radiates.", "category": "Instrument component", "related_terms": ["Tuba", "Brass instrument", "Marching band", "Microphone placement", "Tenor drums", "Directivity"], "common_mistakes": ["Placing a mic dead-centre in the bell mouth, over-capturing wind blast and losing tone.", "Treating the sousaphone like an upward-belled concert tuba when its bell faces forward.", "Assuming the bell alone sets the pitch, when the whole tubing length and the player do."], "scenario_contexts": ["Clip-miking a sousaphone bell for a marching band on the field.", "Positioning a mic at the forward bell to reinforce the bass line outdoors.", "Balancing sousaphone bell level against the rest of a marching brass section."]}, "95e913f9-1487-45fb-99dc-5c7ca657e68d": {"definition": "A tenor drum is a cylindrical drum without snares, producing a full, indefinite pitch between that of the snare drum and the bass drum. In the modern marching context the term usually refers to marching tenors-a set of several single-headed, tuned toms (commonly four to six, called 'quads' or 'quints') mounted together and carried by one player.", "plain_english": "Tenor drums have no snares, so they sound deeper and rounder than a snare drum. In a marching band, tenors are a set of several tuned drums carried by one player. The player moves across them to hit different pitches.", "purpose_function": "Tenor drums fill the mid-range of a drumline, adding melodic and rhythmic figures between the high snares and the low bass drums. The multi-drum marching set lets one player cover several pitches on the move.", "practical_application": "A technician mics or reinforces marching tenors from above the heads, balancing their mid-range punch against snares and bass drums in the line.", "category": "Percussion instrument", "related_terms": ["Snare drum", "Bass drum", "Drumline", "Marching band", "Sousaphone bell", "Microphone placement"], "common_mistakes": ["Calling marching tenors 'toms' from a drum kit, when they are a tuned single-headed marching set.", "Assuming tenor drums have snares like a snare drum.", "Miking only one drum of the set and missing the other tuned toms."], "scenario_contexts": ["Reinforcing a marching band drumline with tenors at an outdoor show.", "Miking marching tenors for a field-show broadcast or recording.", "Balancing tenor mid-range against snares and bass drums in a drumline mix."]}, "28ba3eb5-e229-4e21-b44d-db64281c5d35": {"definition": "The setting or matching of the tone-key-the pilot-tone squelch identifier-on a wireless microphone transmitter and its receiver so that the receiver will unmute only for its intended, matching transmitter. Choosing a compatible tone-key ensures a receiver ignores signals, including other transmitters on the same frequency, that do not carry the expected tone.", "plain_english": "Tone key selection means setting the secret squelch tone on a wireless mic system. The transmitter and receiver must use the same tone. Then the receiver only opens for its own mic and ignores other signals.", "purpose_function": "It pairs a receiver to its transmitter through a shared tone scheme, so the receiver rejects interference and other transmitters. This helps keep each wireless channel clean on a crowded stage.", "practical_application": "A technician matches the tone-key (pilot-tone squelch) between transmitter and receiver during setup, so each receiver unmutes only for its own mic.", "category": "Wireless systems", "related_terms": ["Pilot tone detection", "Squelch", "Wireless microphone", "Frequency coordination", "RF interference", "Companding"], "common_mistakes": ["Mismatching the tone-key scheme between transmitter and receiver, so the channel never unmutes.", "Assuming the tone-key changes the audio, when it only controls squelch.", "Believing the tone-key alone prevents same-frequency clashes without proper frequency coordination."], "scenario_contexts": ["Setting matching tone-key squelch on transmitter and receiver during system setup.", "Diagnosing a dead channel caused by a tone-key mismatch.", "Using tone-key squelch alongside frequency coordination on a multi-channel show."]}, "373251da-347e-4e5d-bc83-0c633b521c4a": {"definition": "The intrusion of wind-generated noise into a microphone signal outdoors, produced by air turbulence and pressure fluctuations at the diaphragm rather than by any acoustic source. It appears predominantly as low-frequency rumble and gusting energy, is generally worse on directional (ported) microphones than on omnidirectional ones, and is controlled with foam windscreens, basket/blimp windshields, and furry windjammer covers.", "plain_english": "Wind bleed is the low rumble wind makes when it hits a microphone outside. It is not real sound; it is air pushing on the mic. Foam and furry covers slow the wind down, so the rumble drops.", "purpose_function": "Naming wind bleed flags a specific outdoor problem: wind energy, not sound, corrupting the low end of a mic feed. Identifying it tells the technician to add wind protection and high-pass filtering rather than chase an electrical fault.", "practical_application": "A technician fits foam or furry windshields, angles mics away from gusts, and applies a high-pass filter to keep wind bleed out of an outdoor feed.", "category": "Noise artifact", "related_terms": ["Windscreen", "Shotgun microphone", "Sideline microphones", "High-pass filter", "Outdoor reinforcement", "Handling noise"], "common_mistakes": ["Blaming wind rumble on a faulty mic or cable instead of turbulence at the diaphragm.", "Using no windshield outdoors, or only thin foam, in strong gusts.", "Boosting low end to 'fix' a thin feed, which only lifts the wind bleed further."], "scenario_contexts": ["Low-frequency rumble on a sideline shotgun mic during a windy game.", "Gusts overloading a handheld mic at an outdoor stage.", "Choosing a furry windjammer over foam for a very windy outdoor shoot."]}, "f518438c-c5f4-48df-a2a1-be4855a0056e": {"definition": "A menu setting on a digital wireless microphone system that turns on encryption of the RF audio link, so the transmitted audio can only be decoded by a paired receiver holding the matching key. On Shure digital systems this activates Advanced Encryption Standard (AES-256) and requires an IR sync between receiver and transmitter to share the key.", "plain_english": "This is the switch that turns on scrambling for a wireless mic signal. Once it is on, only the matched receiver can unscramble the audio. It stops outsiders from listening in on the radio signal.", "purpose_function": "It exists to protect sensitive audio from eavesdropping by anyone with a compatible receiver or scanner. Switching it on converts the plain radio link into a secured, key-protected audio path.", "practical_application": "A technician enables encryption in the receiver menu for confidential events, then performs an IR sync on each transmitter so the paired devices share the key.", "category": "Wireless security", "related_terms": ["Encryption key", "AES-256", "IR sync", "Digital wireless", "RF link", "Receiver"], "common_mistakes": ["Enabling encryption on the receiver but forgetting to re-sync the transmitter, which causes an encryption mismatch and no audio.", "Assuming encryption improves audio quality or range; it only secures the link and does not change fidelity or coverage.", "Believing encryption is always on by default; on most models it must be turned on and synced, unlike dedicated always-on versions."], "scenario_contexts": ["A corporate annual meeting uses wireless mics, so the technician enables AES-256 encryption to block nearby scanners.", "After turning on encryption at the receiver, the tech performs an IR sync on every transmitter before doors open.", "A government briefing requires secure audio, so encryption is enabled across all wireless channels."]}, "15c7c0d1-c568-48eb-aae1-e31f2348552d": {"definition": "The secret digital value a digital wireless system uses to encrypt and decrypt the audio carried over its RF link. On Shure systems the receiver generates a unique key and shares it with each transmitter during an IR sync; only devices holding the matching key form a protected audio path.", "plain_english": "This is the secret code that locks and unlocks a wireless mic's audio. The receiver makes the code and copies it to the transmitter during sync. Only gear with the same code can hear the sound.", "purpose_function": "The key is what makes encryption work: it lets a matched transmitter and receiver share audio while shutting out any device without it. One shared key across a pair or set creates a private audio channel.", "practical_application": "A technician does not type the key in; the receiver generates it and pushes it to transmitters by IR sync, and can regenerate it between events for extra security.", "category": "Wireless security", "related_terms": ["Encryption enable", "AES-256", "IR sync", "Receiver", "Bodypack transmitter", "RF link"], "common_mistakes": ["Believing you choose or type in the key; the receiver generates it automatically and shares it only by IR sync.", "Regenerating keys or toggling encryption without re-syncing every transmitter, which leaves channels with mismatched keys and no audio.", "Assuming all transmitters keep working after a key regenerate; each one must be re-synced individually."], "scenario_contexts": ["When encryption is switched on, the receiver generates a key and passes it to the transmitter during IR sync.", "A technician regenerates keys between separate events for security and then re-syncs each transmitter.", "An encryption-mismatch warning appears, so the tech re-syncs the pair to share a matching key."]}, "2225bd60-6f7e-4ede-ac0f-c6d13523e2ec": {"definition": "A set limit for a digital wireless link's quality metric, a combined measure of RF signal strength against noise, interference, and transmission errors, below which the system flags a warning or the link is treated as unreliable. Manufacturers express link or channel quality as a percentage or a segmented meter, and a value falling toward the threshold warns of likely dropouts.", "plain_english": "Link quality is a score for how clean a wireless signal is, not just how strong. The threshold is the low mark where the system warns you. Below it, the sound is likely to drop out.", "purpose_function": "It provides an early warning: by alerting before quality reaches a failure point, it lets a technician act before the audio actually cuts out. This makes wireless coordination proactive rather than reactive.", "practical_application": "A technician watches the channel-quality meters and, when a reading falls toward the threshold, moves that channel to a cleaner frequency or hunts down the interference.", "category": "RF monitoring", "related_terms": ["Channel quality", "RF signal strength", "Squelch", "Dropout", "Packet error threshold", "Frequency coordination"], "common_mistakes": ["Confusing link or channel quality with plain RF signal strength; quality also reflects noise, interference, and errors.", "Setting the threshold too low, so warnings arrive only after the audio has already dropped out.", "Ignoring a falling quality reading because the signal-strength bars still look high."], "scenario_contexts": ["A monitor engineer watches channel-quality meters and switches to a clear frequency as readings fall toward the threshold.", "Wireless management software raises an alert when a channel's link quality drops below the set threshold.", "During a festival, rising RF interference pushes several channels close to their link quality threshold."]}, "a8ff9d24-ac4d-40ab-a9fd-10c28d64e070": {"definition": "A set limit on the number or rate of corrupted or lost data packets on a networked or digital audio link, above which the system flags a fault or treats the link as degraded. In audio networks such as Dante, packet errors are counted per device (for example CRC errors) and a rising count signals cabling, switch, or congestion problems that can cause audio glitches.", "plain_english": "Digital audio travels as small data packets over a cable or radio. A packet error is a packet that arrives broken or is lost. The threshold is how many errors are allowed before the system sounds an alarm.", "purpose_function": "It separates harmless, occasional errors from a real fault, so the system only alerts when errors reach a level likely to affect the audio. This keeps technicians focused on problems that matter.", "practical_application": "A technician monitors packet-error counters in software such as Dante Controller and, when they cross the threshold, checks cables, switches, and network load.", "category": "Network monitoring", "related_terms": ["Dante", "Latency", "Link quality threshold", "Clock synchronization", "Network switch", "Dropout"], "common_mistakes": ["Assuming any single non-zero packet-error count means instant audio failure; the trend over time matters more than one event.", "Blaming the audio device when a faulty Ethernet cable or an overloaded switch is the real cause.", "Not monitoring the counters over time, so old accumulated errors hide a new, active problem."], "scenario_contexts": ["A system technician watches Dante packet-error counters and investigates when they climb past an acceptable threshold.", "A red packet-error indicator in Dante Controller points the tech toward a suspect cable or switch.", "On a networked audio show, packet errors rise past threshold as network utilization nears its limit."]}, "86aa7475-6a96-4eee-9251-23d972b2a6b0": {"definition": "The vertical angle at which a loudspeaker or array is oriented relative to horizontal, tilting its output up or down to direct sound onto the intended audience area. In a line array, the overall aiming (the tilt of the whole hang) is set separately from the inter-cabinet splay angles that shape coverage.", "plain_english": "Aiming means tilting a speaker up or down. You point its sound at the seats you want to cover. Tilt it too high and the sound flies over people. Tilt it too low and the front rows get too much.", "purpose_function": "It steers the loudspeaker's energy toward the listeners and away from walls, ceilings, and empty areas, improving coverage and reducing unwanted reflections.", "practical_application": "A technician sets the array's tilt using an inclinometer or the prediction software, aiming the top of the hang at the last row and the lower boxes at the near seats.", "category": "Array Deployment", "related_terms": ["Array curvature", "Splay angle", "Array hang", "Coverage", "Line array"], "common_mistakes": ["Confusing the overall array aiming (tilt of the whole hang) with the splay angles set between individual cabinets", "Aiming too high, so sound passes over the audience and reflects off the back wall", "Setting tilt by eye instead of using an inclinometer or the design prediction data"], "scenario_contexts": ["Tilting a flown array down to cover a raked seating area", "Setting front-fill aim so the near seats are covered evenly", "Adjusting array tilt after checking coverage with measurement"]}, "7769900a-661a-41b0-9f14-05e849e1ba20": {"definition": "Equalization that boosts high frequencies with increasing distance to offset the progressive loss of high-frequency energy caused by the absorption of sound by air. The effect grows with frequency and throw distance and varies with temperature and humidity, so the far zones of a system receive more high-frequency correction than the near zones.", "plain_english": "Air slowly soaks up high notes as sound travels. The farther it goes, the duller it gets. This tool adds back some treble for the far seats. It keeps distant listeners from hearing a muffled sound.", "purpose_function": "It restores tonal balance over distance so listeners far from the system hear a high-frequency response similar to those near it.", "practical_application": "An engineer applies more high-frequency boost, or enables the system's air-absorption filter, on the long-throw cabinets aimed at the back of a large venue.", "category": "System Tuning", "related_terms": ["Array curvature", "Aiming (tilt)", "Equalization", "Throw distance", "Line array"], "common_mistakes": ["Applying the same high-frequency boost to near and far zones instead of scaling it with distance", "Over-boosting the highs, which stresses the drivers and makes the near seats harsh", "Ignoring that temperature and humidity change how much high frequency the air absorbs"], "scenario_contexts": ["Tuning a long-throw array for the back of an arena", "Compensating far-zone tone as humidity drops during an outdoor show", "Enabling a DSP air-absorption filter in line-array processing"]}, "96fc6b46-d2aa-43d6-8374-8908756b5ad8": {"definition": "A single device that combines a power amplifier with an integrated loudspeaker controller: DSP that applies loudspeaker-specific setups, equalization, delay, crossover filtering, and protection to the signal before amplification. It drives passive loudspeakers while performing the signal conditioning and protection those enclosures require.", "plain_english": "An amplified controller is an amplifier and a speaker brain in one box. It makes the signal loud enough to drive the speakers. It also shapes the sound and protects the speakers. You pick the setting that matches the speaker model.", "purpose_function": "It supplies each loudspeaker with the exact processing and protection it needs and the power to drive it, all from one managed device, which simplifies setup and safeguards the drivers.", "practical_application": "A technician selects the correct speaker setup on the amplified controller for the cabinets connected, so the right EQ, crossover, and limiters are applied automatically.", "category": "System Electronics", "related_terms": ["Loudspeaker controller", "Power amplifier", "DSP", "Speaker setup", "Line array"], "common_mistakes": ["UNSAFE: Selecting the wrong loudspeaker setup, which removes proper limiting and can overpower and damage the drivers", "Assuming the controller works with any brand of speaker rather than its matched enclosures", "Confusing an amplified controller with a plain power amplifier that has no built-in processing"], "scenario_contexts": ["Driving a passive line array from rack-mounted amplified controllers", "Loading the matching speaker preset before a show", "Monitoring load and temperature status from the controller over a network"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"01005b61-e026-4c59-aed3-d25bcddb7368": {"definition": "A line-array configuration in which every adjacent enclosure is set to the same splay angle, producing a constant-radius (circular arc) curvature. This constant-curvature arrangement spreads energy evenly over a wide, uniformly distributed area, in contrast to a progressive (J) array whose splay angles increase toward the bottom of the hang.", "plain_english": "An arc array sets the same angle between every speaker in the hang. This makes the array curve like part of a circle. The sound then spreads evenly across a wide area. It suits crowds that sit at a similar distance.", "purpose_function": "It provides even coverage across a wide arc of listeners at roughly equal distance, trading long throw for broad, uniform spread.", "practical_application": "A designer chooses arc (constant-curvature) mode for a short, wide room or a balcony fill, setting a single splay value across all of the boxes.", "category": "Array Configuration", "related_terms": ["Array curvature", "Splay angle", "Line array", "Array element", "Aiming (tilt)"], "common_mistakes": ["Using a constant-curvature arc for a deep room where a progressive (J) array would throw farther", "Confusing arc mode (equal splay angles) with a straight-hung array (near-zero splay)", "Assuming more curvature always means better coverage regardless of the room shape"], "scenario_contexts": ["Covering a wide, shallow audience with even level", "Deploying a compact constant-curvature system as a fill", "Choosing arc versus progressive curvature in the design software"]}, "19c46969-db45-4621-a415-759659ddf865": {"definition": "The overall curved shape of a line array formed by the cumulative splay angles set between its enclosures. Greater total curvature widens the array's vertical coverage and directs more energy to nearer listeners, while less curvature concentrates energy for longer throw.", "plain_english": "Array curvature is how much a line array bends from top to bottom. It comes from the angles set between the speakers. More bend spreads sound over the closer rows. Less bend sends sound farther to the back.", "purpose_function": "It shapes how the array's energy is distributed vertically over the audience, letting designers match coverage to the seating from front to back.", "practical_application": "In the prediction software, a designer adjusts the splay angles to build curvature that puts even level on every row from the front to the back wall.", "category": "Array Configuration", "related_terms": ["Splay angle", "Arc array (arc mode)", "Aiming (tilt)", "Array element", "Coverage"], "common_mistakes": ["Confusing curvature (the sum of the splay angles) with the overall tilt of the hang", "Straightening the array too much, so the near rows are starved and the back is too loud", "Setting curvature by eye instead of from the design and prediction software"], "scenario_contexts": ["Shaping splay angles to cover a raked seating bowl", "Increasing lower-box splay to reach the front rows", "Comparing curvature options in ArrayCalc or Soundvision"]}, "c7dcd8cf-8602-4b0b-9fe1-0ff88eaa44e5": {"definition": "A single loudspeaker enclosure that forms one unit of a larger array. Multiple identical elements are coupled together and splayed to build a line array or other array, each contributing part of the combined wavefront and overall coverage.", "plain_english": "An array element is one speaker box in a bigger stack. Many matching boxes join to make an array. Each box adds its part to the total sound. Together they act like one large speaker.", "purpose_function": "It is the repeatable building block of an array; combining many elements lets a system reach the level and pattern control that a single enclosure cannot.", "practical_application": "A crew flies a set number of array elements per hang, adding or removing boxes to match the venue's size and coverage needs.", "category": "Array Components", "related_terms": ["Line array", "Array frame", "Splay angle", "Array curvature", "Array hang"], "common_mistakes": ["Mixing incompatible enclosure models as elements within one array", "Assuming adding elements only adds level, ignoring how it changes the coverage pattern", "UNSAFE: Flying more elements than the array frame or hoist is rated to carry"], "scenario_contexts": ["Adding boxes to a hang to cover a larger crowd", "Building an array from a fixed number of matched enclosures", "Specifying element count during system design"]}, "8233b235-6d73-4f02-8d54-d1f2f88d16ca": {"definition": "The dedicated structural fitting at the top of a suspended array, also called a flying frame, bumper, or grid, from which the enclosures hang and by which the whole array attaches to the hoist or rigging point. It carries the array's entire load, sets the top pick point(s), and provides the adjustment used to establish overall aiming; it is rated to a specified working load limit (WLL).", "plain_english": "An array frame is the strong metal bracket at the top of a hanging array. The speaker boxes hang from it. It links the whole array to the motor or rigging point. It has a set weight limit that must never be passed.", "purpose_function": "It provides a single, load-rated attachment that safely supports the array's full weight and lets the crew set and lock the overall aiming angle.", "practical_application": "A rigger attaches the hoist to the array frame's chosen pick point, builds the enclosures onto it, and confirms the total load stays within the frame's rated working load limit.", "category": "Array Rigging", "related_terms": ["Array hang", "Array element", "Working load limit", "Chain hoist", "Pick point"], "common_mistakes": ["UNSAFE: Exceeding the frame's rated working load limit by flying too many enclosures", "UNSAFE: Lifting before every locking pin and safety is fully engaged and locked", "UNSAFE: Using a frame with deformed, corroded, or damaged components instead of removing it from service", "Confusing the array frame with an individual enclosure's own rigging fittings"], "scenario_contexts": ["Rigging a line array to a chain hoist for a concert", "Setting the array's aim by selecting the frame's pick-point hole", "Inspecting the frame, pins, and safeties before a lift"]}, "f788b96b-66c5-4988-853e-c2b242303abc": {"definition": "A complete assembled array of loudspeaker enclosures suspended from a single frame and rigging point (or set of points); the term also refers to the act of flying that array. Each hang is a self-contained flown cluster whose weight, curvature, and aiming are engineered and verified before and during lifting.", "plain_english": "An array hang is one full stack of speakers flown from a rigging point. It is also the job of lifting that stack into place. A show may use a left hang and a right hang. Each one must be checked with care before it goes up.", "purpose_function": "It packages a coverage zone into one suspended cluster that can be raised, aimed, and secured as a unit, so a venue can be covered from a few overhead positions.", "practical_application": "A crew builds the left and right hangs on the ground, connects each to its hoist, then raises and secures them at the design height and angle.", "category": "Array Rigging", "related_terms": ["Array frame", "Array element", "Aiming (tilt)", "Chain hoist", "Working load limit"], "common_mistakes": ["UNSAFE: Standing or working directly under a hang while it is being raised or is left unsecured", "UNSAFE: Flying a hang without a secondary safety (safety chain or bond) where one is required", "UNSAFE: Raising a hang unevenly or letting it swing instead of lifting slowly and steadily", "Confusing a single hang with the whole system of multiple hangs"], "scenario_contexts": ["Flying left and right main hangs at a concert", "Raising a hang slowly and evenly to its trim height", "Securing and locking off a hang before it is left unattended"]}, "338c423c-8c79-4d2d-8697-f4c2eeb0002f": {"definition": "Array shading is the practice of applying progressively different drive levels (gain), and sometimes EQ, to the individual elements of a loudspeaker array so that sound-pressure level and tonal balance stay even across the full depth of the audience. Also called amplitude or gain shading/tapering, it derives from array theory, where element amplitudes are tapered to shape the radiated pattern and reduce off-axis lobing.", "plain_english": "Array shading means giving each speaker in a stack its own volume level. Boxes aimed at far seats play louder. Boxes aimed at close seats play softer. This helps everyone hear about the same loudness.", "purpose_function": "It compensates for the different distances each array element must cover, keeping level and tone uniform from the front row to the back so no zone is too loud or too quiet.", "practical_application": "During system tuning, an engineer sets per-box gain (and sometimes EQ) in the array processing or prediction software so that measured response matches across all seating areas.", "category": "System Optimization", "related_terms": ["Line array", "Gain structure", "Coverage pattern", "Arrival-time difference", "Audience plane", "Splay angle"], "common_mistakes": ["Confusing amplitude shading with mechanical splay or delay, which control aim and timing rather than level", "Driving every box at the same gain and leaving the rear of a deep hall too quiet", "Over-shading the top boxes so distant seats sound dull and lack level"], "scenario_contexts": ["Tuning a line array to cover a deep, raked auditorium evenly", "Balancing near-field and far-field seating in an arena", "Adjusting per-element gain in prediction software before a show"]}, "6e425c6d-35d9-4c15-8bff-ffecad0a8261": {"definition": "The difference in the time it takes the same sound to reach a listener from two or more sources, caused by unequal path lengths; sound travels at roughly 343 m/s (about 1,130 ft/s) in air at 20 degrees C. Small arrival-time differences underlie the precedence (Haas) effect and cause comb filtering where overlapping sources combine.", "plain_english": "Sound is not instant; it takes time to travel. If two speakers play the same thing, the closer one reaches you first. That tiny time gap can change where you think the sound comes from.", "purpose_function": "Accounting for arrival-time differences lets designers align main and delay loudspeakers so their sound reaches the listener together, preserving clarity and correct localization.", "practical_application": "A technician measures path distance or uses a dual-channel measurement system, then adds electronic delay to the nearer source so both arrive in step at the audience.", "category": "System Optimization", "related_terms": ["Precedence effect", "Delay alignment", "Comb filtering", "Speed of sound", "Time alignment", "Array shading"], "common_mistakes": ["Forgetting that air temperature changes the speed of sound and shifts required delay times", "Aligning by physical distance only and ignoring processing latency in the signal chain", "Assuming co-located mains and subs need no relative delay"], "scenario_contexts": ["Setting delay times for distributed delay loudspeakers in a long room", "Aligning subwoofers with the main array at the crossover region", "Timing front-fill speakers to the main system"]}, "453df46a-1e2f-47d5-bce7-04ab64d5e2c9": {"definition": "A dedicated audio output that supplies a clean program mix to an assistive listening system (ALS) for patrons who are deaf or hard of hearing, distributed via induction (hearing) loop, FM/radio, or infrared transmission. In the United States such systems are required in many assembly areas under the ADA, and induction-loop performance is specified by IEC 60118-4.", "plain_english": "This is a special sound feed for people who have trouble hearing. It sends clear speech and music to hearing aids or small receivers. Many public places, like theaters, must offer it by law.", "purpose_function": "It gives hard-of-hearing audience members a clear, direct signal free of room noise and reverberation, improving speech intelligibility and helping the venue meet accessibility law.", "practical_application": "The engineer routes a mono, speech-forward mix from a matrix or aux output to the loop/FM/IR driver, then verifies coverage and level with a field-strength meter or a receiver check.", "category": "Accessibility Systems", "related_terms": ["Hearing loop", "Induction loop", "Aux send", "Matrix output", "Speech intelligibility", "Infrared assistive listening"], "common_mistakes": ["Feeding the full L/R mix with heavy effects instead of a clean, speech-forward mix", "Installing the system but not providing signage or working receivers", "Skipping the field-strength or receiver test so poor coverage goes unnoticed"], "scenario_contexts": ["Providing an ALS feed in a house of worship", "Meeting ADA requirements in a theatre or lecture hall", "Supplying a clear feed for a courtroom or conference room"]}, "60f80f2c-f114-4ede-b1f8-541beca2a15e": {"definition": "In acoustic prediction and system-design software, an imaginary surface mapped across the seating area, typically set at listener ear height, onto which predicted or measured sound-pressure level and frequency response are projected to judge coverage uniformity. It may be flat or follow raked and tiered seating.", "plain_english": "The audience plane is an invisible sheet drawn where people's ears sit. Designers use it to check how loud each seat will be. It shows if some seats get too much or too little sound.", "purpose_function": "It provides a consistent reference height for evaluating how evenly a loudspeaker system covers the audience, both while planning a design and while verifying it on site.", "practical_application": "In prediction software, a technician places the audience plane at ear height, reads SPL and response across the seats, and then adjusts array aim, splay, and shading.", "category": "System Design", "related_terms": ["Coverage pattern", "SPL mapping", "Array shading", "Prediction software", "Raked seating", "Line array"], "common_mistakes": ["Setting the plane at floor level instead of listener ear height", "Ignoring the seating rake so predictions do not match the real room", "Assuming one plane height fits both a seated and a standing audience"], "scenario_contexts": ["Modeling loudspeaker coverage in prediction software before load-in", "Checking for even SPL across a raked theatre", "Comparing two array designs for the same room"]}, "8cfbc92d-2a07-4ab1-90a5-460c85d4e31c": {"definition": "On automated (digital) mixing consoles, the practice of preventing selected channels or parameters from changing when a stored scene (snapshot) is recalled, using isolate or recall-safe functions, so that chosen live audio continues uninterrupted across scene changes.", "plain_english": "Sound desks can store settings called scenes and recall them fast. Sometimes you do not want one channel to change during a recall. An 'isolate' lock keeps that channel steady so its sound plays smoothly.", "purpose_function": "It stops unwanted level jumps, mutes, or glitches on critical sources such as a live announcer mic or playback when snapshots change during a performance.", "practical_application": "Before the show, the operator flags certain channels or parameters as isolate/safe, so scene recalls update everything else while leaving those sources untouched.", "category": "Console Automation", "related_terms": ["Scene recall", "Snapshot", "Recall safe", "Isolate", "Mute group", "Console automation"], "common_mistakes": ["Forgetting to isolate a live mic so a recall mutes it mid-sentence", "Isolating too many parameters so needed cue changes never fire", "Confusing isolate/safe with a simple channel mute"], "scenario_contexts": ["Running snapshot cues during a theatrical production", "Protecting a live presenter mic across scene recalls at a corporate show", "Managing saved scenes across festival act changeovers"]}, "3eb6351e-3c52-45ea-ac4e-8c4da0c29642": {"definition": "A signal processor, either a hardware unit or an algorithm, that automatically detects the frequencies of acoustic feedback (howlround) and applies narrow notch filters to attenuate them. Fixed filters are typically set during setup ('ringing out'), while dynamic/adaptive filters track and suppress new feedback during a performance.", "plain_english": "Feedback is that loud squeal from a mic and speaker loop. This device listens for the squeal and quickly cuts just that pitch. It lets you keep mics loud without the howling.", "purpose_function": "It increases usable gain before feedback and quickly tames squeals, helping keep microphones loud enough while reducing sudden loud feedback in the system.", "practical_application": "A technician raises system level during soundcheck to let the unit set fixed notches, then leaves dynamic filters active to catch feedback as microphones move.", "category": "Signal Processing", "related_terms": ["Feedback (howlround)", "Gain before feedback", "Notch filter", "Ringing out", "Graphic EQ", "Parametric EQ"], "common_mistakes": ["Relying on the suppressor instead of fixing microphone placement, monitor position, and gain structure", "UNSAFE: trusting it to prevent all feedback and running the system so hot that a sudden squeal risks hearing damage or speaker damage", "Placing so many notches that the overall tone becomes thin"], "scenario_contexts": ["Taming a lectern or podium microphone during a speech", "Following a wireless lavalier on a presenter who walks the stage", "Adding gain-before-feedback margin on stage monitors"]}, "fe7b4f3b-df0c-415f-bd55-62ac9a411a3c": {"definition": "A routing technique in which subwoofers are driven from a dedicated auxiliary (bus) send rather than the main L/R mix, letting the engineer choose exactly which channels (for example kick, bass, floor tom) reach the subs. This keeps low-frequency energy from non-bass sources such as vocals, cymbals, and guitars out of the subwoofers, reducing low-end clutter.", "plain_english": "Normally every channel feeds the subwoofers. Aux-fed subs use a separate knob per channel instead. You send only the deep instruments, like kick and bass. This keeps the low end clean.", "purpose_function": "It gives independent control of subwoofer content and level, improving clarity and impact by preventing unwanted low frequencies and stage rumble from muddying the system.", "practical_application": "The engineer assigns a post-fader mono aux to the subs, raises only bass-heavy channels on that aux, and uses the aux master to set overall subwoofer level.", "category": "Loudspeaker Deployment", "related_terms": ["Subwoofer", "Aux send", "Bus routing", "Crossover", "High-pass filter", "Low-frequency management"], "common_mistakes": ["Leaving the aux pre-fader so sub level no longer follows the channel fader", "Sending nearly every channel to the aux, which defeats the purpose of the technique", "Forgetting to high-pass full-range channels so subs still get unwanted low end"], "scenario_contexts": ["Mixing front of house for a live band", "Keeping the low end clean on a vocals-heavy program", "Managing sub content across DJ and band changeovers"]}, "73aee1fe-0498-4267-8e67-750ec6473fb7": {"definition": "A loudspeaker installed backstage, in the wings, dressing rooms, or crew areas to relay the main program plus paging and cue announcements to performers and staff who are offstage. Often called a program/show relay or backstage monitor, it is fed a dedicated mix so people offstage can follow the show and hear calls.", "plain_english": "This is a speaker placed behind or beside the stage. It sends the show's sound and cues to performers waiting offstage. That way they know what is happening and when to go on.", "purpose_function": "It keeps offstage performers and crew aware of the performance and cues, aiding timing, entrances, and coordination during a show.", "practical_application": "The technician routes a dedicated relay mix, often program audio plus stage-manager paging, to backstage and dressing-room speakers and sets levels so calls are clear but not disruptive.", "category": "Loudspeaker Deployment", "related_terms": ["Program relay", "Paging/cue system", "Stage manager", "Dressing-room speaker", "Foldback", "Backstage speaker"], "common_mistakes": ["Setting the relay so loud that it bleeds onstage into open microphones", "Feeding a delayed or effects-heavy mix instead of a clear program relay", "Leaving paging out of the relay so cue calls are missed offstage"], "scenario_contexts": ["Relaying the show to the wings during a theatre production", "Feeding program audio to dressing rooms", "Monitoring the performance from backstage at a concert or opera"]}, "a6e896ec-d01f-49b7-825d-852a28c4d65c": {"definition": "A loudspeaker placed backstage, in the wings, dressing rooms, or crew areas to relay the main program along with paging and cue announcements to performers and staff who are offstage. Also known as a program/show relay or backstage monitor, it carries a dedicated mix so offstage personnel can follow the show and hear calls.", "plain_english": "This is a speaker placed behind or beside the stage. It sends the show's sound and cues to performers waiting offstage. That way they know what is happening and when to go on.", "purpose_function": "It keeps performers and crew who are offstage informed of the performance and cues, supporting timing, entrances, and smooth coordination during a show.", "practical_application": "A technician sends a dedicated relay mix, typically program audio plus stage-manager paging, to backstage and dressing-room speakers, setting levels for clear but unobtrusive calls.", "category": "Loudspeaker Deployment", "related_terms": ["Program relay", "Paging/cue system", "Stage manager", "Dressing-room speaker", "Foldback", "Backstage loudspeaker"], "common_mistakes": ["Running the relay loud enough to bleed onstage into live microphones", "Routing a delayed or effects-laden mix rather than a clean program relay", "Omitting paging so stage-manager calls are not heard offstage"], "scenario_contexts": ["Providing a show relay to the wings in a theatre", "Sending program audio to performers in dressing rooms", "Following the performance from backstage at a large concert"]}, "b69a3935-a68b-41b8-9d60-be7932df48b7": {"definition": "A supplementary loudspeaker, or small array, that covers balcony seating the main system cannot reach adequately — commonly the shadowed zone beneath an overhanging balcony (under-balcony fill) or an upper balcony tier itself. It is delayed (time-aligned) to the main system so both arrivals combine coherently at the listener.", "plain_english": "A balcony blocks sound from reaching some seats. A balcony fill is a small extra speaker aimed at those seats. It is delayed a little so its sound lines up with the main speakers. This keeps the audio clear, not smeared.", "purpose_function": "It restores even level and intelligibility to seats the main array cannot cover, such as the shaded area under a balcony or the rear of an upper tier, so the whole room hears a consistent mix.", "practical_application": "A systems engineer flies or mounts small fill boxes under or above a balcony, then sets a delay matching the extra distance to the mains so arrivals align and the fills blend with the main PA.", "category": "Fill System", "related_terms": ["Front-fill", "Delay speaker", "Time alignment", "Coverage angle", "Line array"], "common_mistakes": ["Forgetting to delay the fill to the mains, so listeners hear two separate arrivals and lose intelligibility.", "Setting the delay in the wrong direction instead of aligning the fill to the later-arriving mains, which worsens smearing.", "Driving balcony fills too loud, so they localize as a separate source instead of blending with the main system."], "scenario_contexts": ["Covering the shadowed seats beneath a theater's overhanging balcony where the flown mains cannot reach.", "Adding delayed fills for an upper balcony tier in a concert hall so the top rows match the main mix.", "Tuning a house of worship where the main cluster leaves the under-balcony pews dull and quiet."]}, "32231ce6-3ef2-48c2-be98-b863fb78ef70": {"definition": "The use of individually delayed (and sometimes level-adjusted) drive signals to the elements of a subwoofer array so that low-frequency energy sums in a chosen direction and cancels elsewhere, aiming the beam electronically without physically moving the boxes. Because subwoofers are near-omnidirectional across their band, delay-based steering is effective for them.", "plain_english": "Subwoofers spread bass in all directions. Beam steering sends a slightly different delay to each sub. The bass then adds up where you want it and cancels where you do not. It aims the low end like a flashlight, using timing instead of moving the speakers.", "purpose_function": "It lets an engineer point subwoofer energy toward the audience and away from the stage, walls, or spill zones, controlling low-frequency coverage that is otherwise hard to direct.", "practical_application": "An engineer lays out a row of subs and enters per-box delays, often from prediction software, to tilt or curve the bass pattern toward the seats and reduce energy on the stage.", "category": "Subwoofer Array", "related_terms": ["Cardioid subwoofer array", "End-fire array", "Broadside array", "Delay", "Directivity"], "common_mistakes": ["Assuming a physical sub layout alone steers the pattern; without correct per-element delays there is no real steering.", "Using arrival delays copied from a different array size or spacing, which points the beam in the wrong direction.", "Expecting sharp steering from too few boxes, when pattern control needs an array long enough for the wavelengths involved."], "scenario_contexts": ["Keeping subwoofer energy off a stage with open microphones to reduce low-frequency bleed.", "Tilting bass coverage upward across a raked seating area for even level front to back.", "Directing subs away from a noise-sensitive boundary at an outdoor festival."]}, "25bd6ac7-a7a9-43da-8efd-31c6f097e22e": {"definition": "A systematic verification that every loudspeaker enclosure ('box') in a deployed system is connected, powered, correctly patched, and reproducing audio at the right level and polarity before an event. It is typically performed by the systems engineer after rigging and patching, often box by box using pink noise or program material.", "plain_english": "A box check makes sure every speaker in the rig actually works. The engineer sends sound to each cabinet, one at a time. They listen and watch the meters. This catches dead boxes or wrong wiring before the crowd arrives.", "purpose_function": "It confirms the whole loudspeaker system is wired, patched, and functioning correctly, catching dead amplifier channels, swapped cables, or muted boxes before soundcheck or doors.", "practical_application": "After the PA is flown and patched, the tech solos each output or box, sends test signal, and walks the array or watches amplifier monitoring to confirm every enclosure passes audio at the right level and polarity.", "category": "System Verification", "related_terms": ["Line check", "Soundcheck", "Pink noise", "Signal flow", "Polarity"], "common_mistakes": ["Checking only that boxes make sound, without confirming correct polarity and relative level per box.", "Skipping the box check after a patch change, so a swapped or dead output goes unnoticed until the show.", "UNSAFE: Running the box check at full show level while standing right at the array; this risks hearing damage, so keep levels moderate and observe OSHA/NIOSH noise-exposure limits."], "scenario_contexts": ["Verifying a flown line array hang before doors at an arena show.", "Confirming all delay and fill boxes are patched to the right outputs after a system reconfiguration.", "Finding a dead high-frequency driver or a reversed cable during pre-show checks."]}, "67fe452a-dcb3-4962-a18b-434c0412f9b3": {"definition": "Informal industry term for loudspeaker enclosures — the cabinets that house the drivers and their internal acoustic loading — used collectively for a system's loudspeaker units (for example, 'twelve boxes a side').", "plain_english": "'Boxes' is slang for the speaker cabinets in a sound system. Each box holds the speaker drivers inside a sealed or ported case. Crews count the rig in boxes, like 'twelve boxes per side.'", "purpose_function": "The term gives crews a quick, countable way to talk about loudspeaker enclosures when planning hangs, coverage, truck space, and crew tasks.", "practical_application": "A crew chief states how many boxes fly per side and how many go on the ground, so the team deploys the right number and model of enclosures and plans cabling and coverage.", "category": "Loudspeaker Hardware", "related_terms": ["Line array", "Enclosure", "Driver", "Subwoofer", "Ground stack"], "common_mistakes": ["Assuming every 'box' in a hang is identical, when a rig often mixes full-range, downfill, and subwoofer enclosures.", "Treating box count as a coverage spec; the enclosures' models, angles, and processing determine coverage, not the number alone."], "scenario_contexts": ["A crew chief calling 'sixteen boxes a side, four subs per stack' during load-in planning.", "A rider specifying the number and model of boxes required for a tour's main hangs.", "Deciding how many boxes fit on a truck for transport between venues."]}, "b516e26e-206f-4c0f-9ba1-a796d412a3aa": {"definition": "A loudspeaker (typically subwoofer) configuration in which several enclosures are placed side by side in a row and driven together, so the primary radiation is perpendicular (broadside) to the line of boxes. The row length sets horizontal directivity: longer rows narrow the pattern and shorter rows widen it, with pattern control increasing as frequency rises.", "plain_english": "A broadside array is a straight row of subwoofers all facing forward. Together they push bass out in front of the row. A longer row makes a narrower beam of bass. A shorter row spreads it wider.", "purpose_function": "It combines several woofers to raise output and to shape horizontal coverage through row length, making it the simplest way to spread even bass across a wide audience.", "practical_application": "An engineer lines subs across the front of a stage as a broadside row for uniform low end across the width of the crowd, choosing the number of boxes to set how wide or narrow the pattern is.", "category": "Subwoofer Array", "related_terms": ["End-fire array", "Cardioid subwoofer array", "Beam steering (subs)", "Directivity", "Subwoofer array"], "common_mistakes": ["Expecting a broadside row to be directional front-to-back; it radiates strongly both forward and rearward unless made cardioid.", "Spacing the boxes too far apart, which causes lobing and uneven coverage across the audience.", "Making the row very long for output without realizing this also narrows the horizontal pattern."], "scenario_contexts": ["Spreading a line of subwoofers across the downstage edge for even bass at a festival.", "Choosing a short broadside group for a wide club audience versus a long row for a narrow room.", "Comparing a broadside layout with an end-fire or cardioid setup when rear rejection is needed."]}, "d30f92f1-0c6e-42b4-adca-f112a316a698": {"definition": "The systematic process of locating and eliminating unwanted buzzes, hums, rattles, and other spurious noises in a sound system during setup — isolating whether the source is electrical (ground loop, RF, bad connection), mechanical (loose grille, fastener, sympathetic vibration), or a faulty component.", "plain_english": "A buzz hunt is the search for annoying buzzes or hums in a system. The tech turns things on and off to find the source. It might be a loose part, a bad cable, or a ground problem. You fix it before the show.", "purpose_function": "It removes distracting noise from the signal chain and the physical rig so the system is quiet, tracking each noise to its true cause instead of masking it with more gain.", "practical_application": "A tech mutes channels one at a time, wiggles connectors, and swaps cables to trace a buzz, then fixes the cause — reseating a connector, replacing a cable, or correctly resolving a grounding issue.", "category": "Troubleshooting", "related_terms": ["Ground loop", "Hum", "Signal flow", "Line check", "Box check"], "common_mistakes": ["Turning up the gain to 'hear past' a buzz instead of finding and fixing its actual source.", "Assuming every buzz is electrical, when many are mechanical rattles from loose grilles, hardware, or nearby objects.", "UNSAFE: Disconnecting a device's mains safety ground (earth) to stop a ground-loop hum defeats protective earthing and creates a shock hazard; break the loop with proper isolation or corrected grounding per NEC/NFPA 70 and OSHA, never by lifting the ground."], "scenario_contexts": ["Tracking down a 50/60 Hz hum in a PA caused by a ground loop between stage and FOH power.", "Finding a rattle in a subwoofer traced to a loose grille screw rather than the driver.", "Chasing an intermittent buzz to a failing microphone cable during pre-show checks."]}, "dd2e9860-e1d7-4979-80cf-684b591f3ddb": {"definition": "A subwoofer arrangement that produces a cardioid (heart-shaped) directional pattern with strong forward output and reduced rearward radiation, achieved by combining boxes with controlled spacing, delay, and/or polarity inversion so rear-going energy cancels. Common realizations are the front/back (gradient) pair with a reverse-polarity, delayed rear box, and the end-fire line driven with successive delays.", "plain_english": "Normal subwoofers throw bass forward and backward equally. A cardioid sub array uses timing and a signal flip, called polarity, to cancel the bass going backward. Most of the low end then goes toward the audience. The stage behind the subs stays cleaner and quieter.", "purpose_function": "It keeps low-frequency energy off the stage and rear areas — reducing bleed into microphones, stage rumble, and spill behind the system — while keeping full output toward the audience.", "practical_application": "An engineer sets a front-facing and a rear-facing sub, or a stack with one box reversed, applies the rear box's polarity inversion and delay, then verifies rear cancellation by measurement or by listening behind the array.", "category": "Subwoofer Array", "related_terms": ["End-fire array", "Broadside array", "Beam steering (subs)", "Polarity", "Directivity"], "common_mistakes": ["Skipping the delay or polarity inversion on the rear element, so the array stays omnidirectional with no rear rejection.", "Using the wrong spacing or delay for the design frequency, which shifts or ruins the cancellation.", "Expecting broadband rejection; cardioid subs control only the low-frequency range and rejection varies with frequency."], "scenario_contexts": ["Reducing low-frequency bleed onto a stage with open vocal microphones at a live concert.", "Keeping bass off a nearby residential boundary at an outdoor event.", "Cleaning up a boomy stage for musicians by cancelling rearward subwoofer energy."]}, "8f644803-2fca-4686-93dc-e9ec84a941d3": {"definition": "A loudspeaker mounted on, or suspended from, a catwalk (an elevated access walkway or bridge above an auditorium or stage) so it can project onto the audience from a high, forward, central vantage in a permanent or semi-permanent installation.", "plain_english": "A speaker placed on a raised walkway high above the seats. Its height helps the sound reach the whole crowd more evenly.", "purpose_function": "It puts a loudspeaker at an elevated, unobstructed position for direct coverage and clean aiming, while the catwalk gives crew safe access to install, aim, and service the box.", "practical_application": "Technicians rig and aim catwalk speakers during a venue install in theaters and houses of worship, always fitting a secondary safety to each flown enclosure.", "category": "Loudspeaker Placement", "related_terms": ["Center cluster", "Flown loudspeaker", "Secondary suspension", "Coverage angle", "Central Loudspeaker System"], "common_mistakes": ["UNSAFE: Flying the speaker from a single point or with no secondary safety; overhead loudspeaker enclosures require at least two suspension points and an adequate design factor.", "Assuming the catwalk or structure can carry any speaker weight without checking the enclosure's rated load and the building's structural limits.", "Aiming the box level or upward so it sprays reflective ceiling and rear-wall surfaces instead of angling down onto the audience."], "scenario_contexts": ["A theater install where the main cluster hangs from a lighting catwalk above the proscenium.", "A house of worship using catwalk-mounted speakers to reach rear pews without blocking sightlines.", "Re-aiming or servicing a permanently installed speaker by reaching it from the catwalk."]}, "cc44d181-7b8f-4b1d-b0fa-bc4ff19ce212": {"definition": "A loudspeaker installed flush in, or suspended just below, a ceiling and firing downward, used in distributed arrays to give even coverage over a listening area; in commercial installs it is commonly driven from a 70 V or 100 V constant-voltage line.", "plain_english": "A speaker built into the ceiling that points straight down. Many are spread across a room so everyone hears about the same volume.", "purpose_function": "It provides uniform overhead coverage in rooms with low-to-medium ceilings where floor or wall speakers would be uneven or intrusive; the distributed layout keeps level differences small across the space.", "practical_application": "Integrators lay ceiling speakers on a grid spaced from ceiling height and coverage angle, wire them to a constant-voltage amplifier, and set each transformer tap for the target level.", "category": "Loudspeaker Placement", "related_terms": ["Distributed system", "Constant-voltage system", "70-volt line", "Coverage angle", "Central Loudspeaker System"], "common_mistakes": ["Spacing the speakers too far apart, leaving level dips or dead spots between them.", "Ignoring transformer tap settings so the summed taps exceed the amplifier's rated power.", "UNSAFE: Suspending ceiling speakers above people without an independent safety cable, relying on the tile grid or a single fixing alone."], "scenario_contexts": ["Background music and paging in an office, retail store, or restaurant.", "Speech reinforcement in a conference room with a suspended tile ceiling.", "A distributed voice-alarm or mass-notification system in a corridor."]}, "765d3d92-b38a-49c2-8ff3-43697971f486": {"definition": "A single group (cluster) of loudspeakers flown at the horizontal center of a venue, typically above and slightly behind the front of the stage, acting as the primary system so coverage is symmetrical and sound appears to originate from the performer.", "plain_english": "A group of speakers hung together in the middle above the stage. Placing them in one spot makes the sound seem to come from the person on stage.", "purpose_function": "It concentrates the main coverage at one central, elevated source for strong, natural localization to the stage and even left-to-right coverage, avoiding the imaging and comb-filtering problems of split left/right systems.", "practical_application": "Common in houses of worship and lecture halls, the cluster is flown on rated rigging and aimed so each box covers a defined seating zone, with a secondary safety fitted to every enclosure.", "category": "Loudspeaker Array", "related_terms": ["Central Loudspeaker System", "Catwalk speaker", "Center fill", "Point source", "Coverage angle"], "common_mistakes": ["UNSAFE: Rigging the cluster from a single point or without a secondary safety and proper design factor; overhead loudspeaker enclosures must have at least two suspension points.", "Confusing a center cluster (one central source) with a split left/right main system.", "Hanging the cluster too low or too far downstage, which hurts rear coverage or invites feedback with stage mics."], "scenario_contexts": ["A house of worship where a single flown cluster covers the whole congregation.", "A lecture hall or courtroom needing clear, localized speech from a central source.", "A theater using a central cluster for even coverage and natural stage localization."]}, "0d0be809-4cbe-4b90-9cfd-35a9b4ba644a": {"definition": "A loudspeaker or small array placed at the front-center of the stage to cover the seats directly in front of and between widely spaced main left and right hangs, filling the on-axis coverage gap and restoring centered imaging for that audience.", "plain_english": "A speaker at the middle of the stage front. It covers the seats that sit between the main left and right speakers.", "purpose_function": "It fills the coverage and imaging hole left by widely spaced left/right mains, giving center-seated listeners solid vocal imaging and a level that matches the rest of the room.", "practical_application": "At front of house the engineer feeds center fill from a matrix or aux (often vocals plus a little music), delays it to time-align with the mains, and sets its level just enough to pull the image center.", "category": "Fill System", "related_terms": ["Front fill", "Center cluster", "Main hang", "Time alignment", "Stereo imaging"], "common_mistakes": ["Running center fill too loud so it dominates instead of gently centering the image.", "Failing to delay the center fill to the mains, smearing arrival timing for center seats.", "Confusing center fill (mid-stage, for center seats) with front fill (stage lip, for the first rows)."], "scenario_contexts": ["A wide left/right concert system where center seats lack clear vocal imaging.", "A worship stage feeding vocals to a center fill for the middle sections.", "Anchoring the image to the stage in a room with a strong power alley."]}, "a23bba36-6026-45a3-8b83-60bbf56a2309": {"definition": "An arrangement of subwoofers grouped at the horizontal center of the stage rather than split left and right, often built as a cardioid, end-fire, or gradient array, to give even low-frequency coverage across the audience and avoid the interference caused by widely spaced left/right subs.", "plain_english": "All the bass speakers grouped together in the center of the stage. Keeping them in one place gives smoother, more even bass across the crowd.", "purpose_function": "Centralizing the subs removes the left/right spacing that creates a narrow loud strip down the middle and weak bass at the sides; arraying them can also steer low-end energy toward the audience and away from the stage.", "practical_application": "System techs build a center block, or split it into cardioid or end-fire arrays with rear subs delayed and polarity-adjusted to control the pattern, then align the array with the main hangs.", "category": "Subwoofer Array", "related_terms": ["Cardioid subwoofer array", "End-fire array", "Power alley", "Subwoofer", "Comb filtering"], "common_mistakes": ["Assuming any center stack is directional; a plain center array is roughly omnidirectional without cardioid or end-fire processing.", "Setting the wrong delay or polarity on the rear subs, which weakens the intended cardioid pattern.", "Ignoring the coupling gain of stacked subs and overdriving the amplifiers or overwhelming the audience."], "scenario_contexts": ["A festival main system using a large center sub array to even out bass.", "Building a cardioid center array to keep low end off a live stage and its mics.", "Replacing left/right sub stacks with a center array to remove the power alley."]}, "0849a2dd-7680-4484-b835-6a446f737ef7": {"definition": "A sound-system design approach in which reinforcement originates from a single loudspeaker or cluster placed centrally, usually high and above or behind the primary sound source, as opposed to a distributed (many-speaker) or split left/right layout; it is one of the classic system topologies in sound-system engineering.", "plain_english": "A sound system where one main speaker or cluster in the center does most of the work. It helps the sound seem to come from the stage.", "purpose_function": "It gives the most natural localization, so sound appears to come from the talker, plus simple and coherent coverage; this suits speech and works best where room geometry lets one high central source reach all seats.", "practical_application": "Designers pick a central system for churches, courtrooms, and auditoriums with enough ceiling height, siting the cluster above the stage and adding fills or delays where the single source cannot reach.", "category": "System Configuration", "related_terms": ["Center cluster", "Distributed system", "Point source", "Delay loudspeaker", "Coverage angle"], "common_mistakes": ["Specifying a central system in a low, wide room where one source cannot cover all seats; a distributed system fits better there.", "Confusing a central system (the design topology) with a center cluster (the physical loudspeaker group).", "UNSAFE: Concentrating the whole system on one overhead point without engineering the load, using rated hardware, and fitting a secondary safety to the cluster."], "scenario_contexts": ["Designing speech reinforcement for a church with a high ceiling.", "A courtroom or council chamber needing clear, localized speech.", "An auditorium where a central cluster plus delay speakers covers the whole room."]}, "7957036b-e2ad-41cb-a9a4-aa9c53d5405e": {"definition": "A loudspeaker or small system aimed at the choir area to deliver a program or monitor mix (typically the band, accompaniment, and sometimes the choir's own voices) so choir members can hear the rest of the ensemble and stay together; it is a form of choir monitoring.", "plain_english": "A speaker pointed at the choir so the singers can hear the music. It helps them stay in time and on pitch.", "purpose_function": "It gives the choir a clear reference of the accompaniment and mix they cannot otherwise hear from behind or beside the main system, improving their timing and tuning.", "practical_application": "In worship audio the engineer sends a dedicated aux or monitor mix to the choir-fill speakers, balancing enough level to be heard against the feedback risk from nearby choir microphones.", "category": "Monitoring", "related_terms": ["Choir Monitor Loudspeaker", "Stage monitor", "Foldback", "Aux mix", "Gain before feedback"], "common_mistakes": ["Confusing choir fill (feeding sound to the choir) with a fill speaker that covers audience seats.", "Pushing the choir-fill level too high near open choir mics, triggering feedback.", "Sending the full front-of-house mix instead of a tailored monitor mix the choir actually needs."], "scenario_contexts": ["A church choir standing behind the main speakers and needing to hear the band.", "Setting a dedicated monitor aux for a large choir loft.", "Lowering choir-fill level to control feedback with open choir microphones."]}, "406791d7-2097-43ac-b600-5664d961ec66": {"definition": "A monitor loudspeaker dedicated to the choir, positioned to let choir members hear a foldback mix (accompaniment, click track, and/or their own voices) so they can stay in tune and in time with the rest of the ensemble.", "plain_english": "A monitor speaker just for the choir. It lets the singers hear the music and themselves clearly.", "purpose_function": "It acts as the choir's foldback, so a group standing away from the main system can hear the reference mix and keep the whole choir together on pitch and timing.", "practical_application": "Placed at the choir loft on a stand, bracket, or flown position and fed a dedicated monitor mix; the tech sets EQ and level to maximize gain before feedback near the choir mics.", "category": "Stage Monitoring", "related_terms": ["Choir fill", "Stage monitor", "Foldback", "In-ear monitor", "Gain before feedback"], "common_mistakes": ["Using an audience or fill speaker as a choir monitor without a separate monitor mix.", "Placing the monitor so it fires into the choir mics, causing feedback.", "Overloading the mix with too many sources instead of the few the choir really needs."], "scenario_contexts": ["A worship service where the choir stands behind the PA and needs foldback.", "Feeding a click or guide track to a choir during a recorded production.", "Balancing monitor level and EQ to avoid feedback in a live choir loft."]}, "6e72afe8-e389-4e52-9ba8-a6949d67b3c8": {"definition": "A loudspeaker with several drivers mounted in a tall, narrow vertical enclosure so their combined output forms a line source, producing narrow vertical dispersion and wide horizontal dispersion that concentrates sound on the audience and reduces energy toward reflective floors and ceilings.", "plain_english": "A tall, thin speaker with several small drivers stacked in a line. It spreads sound wide side to side but keeps it narrow up and down.", "purpose_function": "The vertical stacking narrows the vertical coverage, which cuts floor and ceiling reflections and raises the direct-to-reverberant ratio for clearer speech in echoey rooms, while the wide horizontal pattern covers the seating.", "practical_application": "Installers mount column speakers vertically on walls or pillars in reverberant spaces such as churches, atriums, and transit halls; some models are electronically steerable to tilt the beam onto the audience without moving the box.", "category": "Loudspeaker Type", "related_terms": ["Line array", "Beam steering", "Directivity", "Central Loudspeaker System", "Coverage angle"], "common_mistakes": ["Mounting a column horizontally, which flips its narrow pattern control into the wrong plane.", "Expecting strong low-frequency directivity; pattern control weakens as frequency drops and the column gets short relative to the wavelength.", "Assuming a fixed column aims itself; a non-steerable column must be physically tilted toward the listeners."], "scenario_contexts": ["Speech reinforcement in a stone church or cathedral with long reverberation.", "A steerable column array covering an airport or train-station concourse.", "A wide, shallow room where a narrow vertical pattern reduces ceiling reflections."]}, "2cc04287-c9ef-4b11-94d6-b0f46d902721": {"definition": "A dynamics compressor (often a limiter) inserted in the full-range signal path before the crossover splits the signal into frequency bands, so a single gain-reduction stage acts on the entire broadband program feeding the system. Because it operates ahead of band-splitting, its gain changes affect all bands together, preserving spectral balance but providing less driver-specific protection than per-band, post-crossover limiters.", "plain_english": "A pre-crossover compressor tames volume before the sound is split into low and high bands. It works on the whole mix at once, not on one band. Its gain changes keep the same tone but catch loud peaks.", "purpose_function": "It applies overall dynamic control or peak limiting to the whole program before frequency division, so level control happens once on the combined signal rather than per band. This keeps the tonal balance intact while taming peaks that would otherwise reach every amplifier and driver.", "practical_application": "An engineer patches a compressor across the main output ahead of the loudspeaker processor or crossover to gently control overall level, while relying on separate post-crossover limiters for driver protection.", "category": "System processing", "related_terms": ["Crossover Slope", "Crossover Filter Type", "Limiter", "Loudspeaker management system", "Gain structure", "Biamplification"], "common_mistakes": ["Confusing a pre-crossover compressor with the per-band driver-protection limiters; a broadband stage cannot protect a single driver, such as a compression driver, on its own.", "Setting it too aggressively, which pumps the whole mix and dulls transients across all bands at once.", "Relying on a pre-crossover compressor alone for loudspeaker protection, then overloading high-frequency drivers because excess HF energy still passes through."], "scenario_contexts": ["Configuring a loudspeaker management processor, the engineer places a gentle compressor before the crossover to control overall program level.", "A broadband peak limiter sits pre-crossover to catch stray transients before the signal is split to the amplifiers.", "Setting up gain structure, the tech distinguishes the pre-crossover compressor from the per-band limiters that protect each driver."]}, "ff74fe3b-2c99-46ec-a937-455f5da5f75c": {"definition": "The degree to which a sound system delivers consistent sound-pressure level and frequency response across the entire listening area, so that all seats hear a similar loudness and tonal balance. It is a primary design goal, quantified by measuring level and spectral variation from front to back and side to side of the intended coverage area.", "plain_english": "Coverage uniformity means every seat hears about the same loudness and tone. A good system does not blast the front rows and starve the back. It is like even room lighting with no bright spots or dark corners.", "purpose_function": "It exists because audiences spread over a wide area, and the system must serve distant and off-axis listeners as well as those up front. Designing for uniformity prevents overly loud front rows, weak back rows, and uneven tone across the room.", "practical_application": "A technician aims and splays loudspeakers, adds delay speakers, and measures level from front to back to keep level and tonal variation within a small target range across the seats.", "category": "System design", "related_terms": ["Delay stack", "Directivity", "Splay angle", "Line array", "SPL", "Time alignment"], "common_mistakes": ["Judging coverage only from the mix position instead of listening and measuring across all the seats.", "Assuming more level fixes uneven coverage; raising output does not even out the pattern, it just makes the whole range louder.", "Checking only loudness (SPL) and ignoring frequency response, when uniformity includes consistent tonal balance too."], "scenario_contexts": ["Designing a system for a wide venue, the engineer splays boxes and adds delays to even out coverage.", "Walking the room during soundcheck, a tech listens from the front, back, and sides to check uniformity.", "Measurement software shows the back rows well down in level, so the crew adds a delay stack to restore uniform coverage."]}, "edaadb5f-fd1c-4bbc-be98-2cc2cb8c78f9": {"definition": "The mathematical order (degree) of the filters used in an audio crossover, which sets how steeply each output band rolls off outside its passband. Order maps directly to slope: a first-order filter gives 6 dB per octave, and each additional order adds another 6 dB per octave (second-order = 12, third = 18, fourth = 24 dB/octave).", "plain_english": "Filter order is a number that sets how fast a crossover cuts sound past the split point. A higher order means a steeper, faster cut. Each step up adds 6 dB per octave to the slope.", "purpose_function": "It determines how much the drivers overlap near the crossover frequency and how well each driver is shielded from frequencies it cannot handle. Higher orders give tighter band separation but introduce more phase shift and group delay near the crossover.", "practical_application": "When configuring a loudspeaker processor, a technician selects a filter order (commonly fourth-order, 24 dB/octave) to keep low-frequency energy out of a compression driver.", "category": "Crossover design", "related_terms": ["Crossover Slope", "Crossover Filter Type", "Linkwitz-Riley", "Butterworth", "Compression driver", "Biamplification"], "common_mistakes": ["Confusing order with type; order sets the slope, while type (Butterworth, Linkwitz-Riley, Bessel) sets the response shape and summing behaviour.", "Assuming higher order is always better; steeper filters add more phase shift and group delay around the crossover frequency.", "Choosing too low an order on the high-pass to a compression driver, letting damaging low-frequency energy reach it."], "scenario_contexts": ["Setting up an active crossover, the tech selects fourth-order filters for a steep 24 dB/octave split.", "Comparing DSP presets, an engineer notes one uses second-order and another fourth-order filters at the same frequency.", "Protecting a horn driver, a system tech raises the filter order to steepen the low-cut below the driver's rated limit."]}, "49b01bf4-2152-44ef-9f85-c7c1880a440f": {"definition": "The named filter alignment used for a crossover's response shape — such as Butterworth, Bessel, or Linkwitz-Riley — each defining passband flatness, the level at the crossover frequency, and how the two outputs sum through the crossover region. For example, Linkwitz-Riley outputs are 6 dB down at the crossover frequency, stay in phase, and sum flat, whereas Butterworth outputs are 3 dB down and do not sum flat.", "plain_english": "Filter type is the recipe a crossover uses to split the sound. Common types are Butterworth, Bessel, and Linkwitz-Riley. Each one blends the two bands in a different way where they overlap.", "purpose_function": "The type sets how the high and low outputs add back together through the crossover region, which affects flatness and phase. Engineers pick a type (often Linkwitz-Riley) so the drivers combine smoothly without a peak or dip at the split frequency.", "practical_application": "In a speaker processor, a technician chooses a filter type such as fourth-order Linkwitz-Riley so the woofer and driver sum flat and in phase at the crossover frequency.", "category": "Crossover design", "related_terms": ["Crossover Filter Order", "Crossover Slope", "Linkwitz-Riley", "Butterworth", "Bessel", "Phase response"], "common_mistakes": ["Confusing filter type with slope or order; the type is the alignment (summing and phase behaviour), not the steepness.", "Assuming every type sums flat; Butterworth outputs are 3 dB down at the crossover and do not sum flat, unlike Linkwitz-Riley.", "Mismatching filter types or phase between bands, causing a dip or a lobe in the response at the crossover frequency."], "scenario_contexts": ["Configuring a two-way processor, the tech selects Linkwitz-Riley to get a flat, in-phase summed response at the split.", "Comparing crossover presets, an engineer hears a response bump from a Butterworth alignment at the crossover frequency.", "A design calls for Bessel filters where preserving transient and phase behaviour matters more than steepness."]}, "bcafab3d-6246-4293-b75b-b04375915775": {"definition": "The rate at which a crossover filter attenuates signal outside its passband, expressed in decibels per octave (dB/octave). Common slopes are 6, 12, 18, and 24 dB/octave, corresponding to first-, second-, third-, and fourth-order filters respectively; steeper slopes confine each band's energy more tightly to its intended driver.", "plain_english": "Slope is how fast a crossover cuts the sound past the split point. It is measured in dB per octave. A gentle 6 dB slope fades slowly, while a steep 24 dB slope cuts fast.", "purpose_function": "The slope controls how much the two drivers overlap near the crossover and how far unwanted frequencies extend into each driver. Steeper slopes reduce overlap and better protect drivers, at the cost of more phase shift near the crossover.", "practical_application": "A technician sets a steep slope such as 24 dB/octave on the high-pass to a compression driver to keep damaging low frequencies away from it.", "category": "Crossover design", "related_terms": ["Crossover Filter Order", "Crossover Filter Type", "High-pass filter", "Octave", "Compression driver", "Passband"], "common_mistakes": ["Confusing the slope (dB/octave) with the crossover frequency (the Hz split point); they are independent settings.", "Assuming steeper is always better; steeper slopes add more phase shift and group delay around the crossover.", "Using too gentle a high-pass slope on a compression driver, letting low-frequency energy overload and damage it."], "scenario_contexts": ["Dialing in a loudspeaker preset, the tech sets a 24 dB/octave slope on the driver's high-pass.", "Comparing two designs, an engineer notes one uses 12 dB/octave and the other 24 dB/octave at the same frequency.", "Troubleshooting a failed driver, a tech checks that the high-pass slope is steep enough for the driver's rating."]}, "e682cca0-2592-475e-9774-50d9d0bad9fe": {"definition": "A dedicated auxiliary or zone audio feed routed to loudspeakers in a 'cry room' — a separate, sound-isolated space (typically in a house of worship or cinema) with a viewing window, where caregivers with restless or crying children can still follow the program without disturbing the main room. The feed is usually a matrix, aux, or zone output from the mixer or processor, with its own independent level control.", "plain_english": "A cry room is a small side room where parents with fussy babies can still watch and listen. The cry-room feed is the wire that carries sound to that room's speakers. It has its own volume so it does not disturb the main hall.", "purpose_function": "It lets people who must step out — usually with young children — keep following the service or show. It exists so the main room stays undisturbed while the side room still receives clear program audio at its own level.", "practical_application": "A technician assigns a spare aux or matrix output to the cry-room loudspeaker and sets its level so occupants hear the program clearly, checking it before the event since it is out of earshot at the mix position.", "category": "Zone feed", "related_terms": ["Aux send", "Matrix output", "Zone (distributed audio)", "Program feed", "Distributed system", "Cue speaker"], "common_mistakes": ["Feeding the cry room from the main house mix, so its level rises and falls with the room instead of using an independent send.", "Forgetting to check the feed before the service, leaving the cry room silent when it is needed.", "Setting the cry-room level too high or too low because it cannot be heard from the mix position."], "scenario_contexts": ["In a church, a matrix output feeds the cry-room loudspeaker so parents with infants can still hear the sermon.", "A cinema routes program audio to a cry room so caregivers can watch the film without disturbing the auditorium.", "During setup, a tech confirms the cry-room feed is live and at a comfortable listening level."]}, "91c7df47-4d50-4627-b211-386974077dc6": {"definition": "A small monitor loudspeaker used to audition a selected cue, solo, or program feed at an operator position, letting an engineer or operator hear a chosen source without it reaching the main system. It reproduces the console's solo/PFL bus or a selected channel so the operator can check a source or an upcoming cue in isolation.", "plain_english": "A cue speaker is a small speaker used to listen in on one chosen sound. It lets an operator check a source or the next cue on its own. The audience never hears it.", "purpose_function": "It gives an operator a private way to listen to a selected source, solo, or upcoming cue for checking and timing. This keeps monitoring separate from the main mix that the audience hears.", "practical_application": "An operator presses solo or PFL and the selected channel plays through the cue speaker, so they can check it or line up the next cue before bringing it into the main mix.", "category": "Monitoring", "related_terms": ["PFL (Pre-Fade Listen)", "Solo bus", "Cue wedge", "Control room monitor", "Talkback", "Program feed"], "common_mistakes": ["Confusing the cue/solo feed with the main output, then wondering why the audience cannot hear a soloed source.", "Leaving a channel soloed to the cue speaker and forgetting it, so monitoring stays stuck on one source.", "Running the cue speaker so loud that it bleeds into nearby microphones or distracts from the room mix."], "scenario_contexts": ["At front of house, an engineer solos a channel to the cue speaker to track down a noisy input.", "In a broadcast booth, the operator uses a cue speaker to hear the program feed for reference.", "Before a cue, an operator auditions the next playback on the cue speaker to check its start."]}, "f8ed7488-db18-465f-943a-cfabf2c43561": {"definition": "A stage monitor wedge dedicated to feeding cue, click, or reference material to a performer, rather than a full monitor mix — for example a floor wedge carrying a click track, count-ins, or timing cues. It uses the same wedge-format monitor loudspeaker but is fed from a dedicated cue or auxiliary mix.", "plain_english": "A cue wedge is a floor speaker aimed at a performer. Instead of the full band mix, it plays cues like a click track or count-ins. This helps the performer stay in time and know what comes next.", "purpose_function": "It delivers timing and cue information — such as a click or count-ins — to a performer on stage. It exists so the artist can follow the show's structure without that material reaching the audience.", "practical_application": "A monitor engineer routes a click and count-in mix to a wedge at the drummer's or music director's position to serve as their cue wedge.", "category": "Stage monitoring", "related_terms": ["Stage monitor", "Wedge", "Click track", "Cue speaker", "Monitor mix", "Aux send"], "common_mistakes": ["Feeding the cue wedge from the main monitor mix, so the cues get buried under the band.", "Aiming the cue wedge where it spills into vocal microphones, causing feedback or bleed.", "Confusing a cue wedge with an in-ear cue feed; both carry cues, but a wedge is open on the stage."], "scenario_contexts": ["A drummer without in-ears gets a click through a cue wedge to stay locked to tempo.", "A music director uses a cue wedge to hear count-ins and section cues during a live show.", "On a theatre stage, a wedge carries timing cues to a performer who is not on in-ear monitors."]}, "5216d1b5-b0a4-4ff4-b9ff-c858ef321793": {"definition": "A group (stack) of loudspeakers placed farther back in a large audience area and electronically delayed so its output arrives in step with the sound from the main system, reinforcing level for distant listeners while preserving intelligibility. The delay is set to the acoustic travel time from the mains to the stack, usually with a small added offset so the precedence (Haas) effect keeps listeners localising the sound toward the stage.", "plain_english": "A delay stack is a set of speakers placed further back in a big crowd. It plays the same sound as the main speakers, but a little late. The small delay lines the sound up so far-off listeners hear it clearly.", "purpose_function": "It exists because one main system loses level and clarity over long distances. The delay stack tops up the level for distant seats, while its timing keeps the sound anchored to the stage rather than to the nearer speakers.", "practical_application": "A technician measures the distance from the mains to the stack and sets the delay to that travel time — sound covers roughly one foot per millisecond (about 340 m/s) — then adds a few milliseconds so localisation stays on stage.", "category": "Loudspeaker deployment", "related_terms": ["Delay tower", "Haas effect (precedence effect)", "Coverage Uniformity", "Time alignment", "Line array", "Signal delay"], "common_mistakes": ["Setting the delay by ear or guesswork instead of measuring the distance, so the stack and mains arrive out of step and smear the sound.", "Forgetting the small extra offset for the precedence effect, so distant listeners localise the sound to the delay stack instead of the stage.", "Running the delay stack too loud, which pulls the perceived source off the stage and muddies clarity.", "UNSAFE: Ground-stacking or flying a delay stack without proper mechanical securing, bracing, and rigging inspection within the manufacturer's and applicable standards' limits, risking a topple or fall onto people below."], "scenario_contexts": ["In a long arena floor, the crew adds a delay stack partway back to lift level for the rear seats.", "A tech measures the distance from the mains to the delay position and sets the delay to that travel time plus a small offset.", "On a festival field, delay towers extend coverage while their delay keeps the sound localised to the stage."]}, "7a447818-4136-484d-b3aa-f7125dd1db48": {"definition": "A single, typically low-power loudspeaker that serves as one element of a distributed loudspeaker system, mounted (commonly in a ceiling or on a wall) to cover a small local area, and usually fitted with a line-matching (constant-voltage 70V/100V) transformer so that many such units can share one amplifier line.", "plain_english": "One small speaker in a group spread around a room. Each covers a little patch of the space. A built-in transformer lets many of them share a single amplifier.", "purpose_function": "It provides even, intelligible sound within its local zone; spreading many low-power units across a space yields more uniform coverage than a few high-power speakers can.", "practical_application": "A technician mounts these ceiling or wall units, sets each transformer power tap for the wanted level, and wires them across a 70V or 100V line for paging or background music.", "category": "Distributed Audio", "related_terms": ["Distributed loudspeaker system", "Constant-voltage system", "70V line", "Ceiling loudspeaker", "Line-matching transformer", "Point-source loudspeaker"], "common_mistakes": ["Assuming one distributed loudspeaker covers a large area; each unit only covers a small local zone.", "Ignoring listening-plane coverage; real coverage over the audience is narrower than the quoted polar pattern.", "UNSAFE: Connecting a low-impedance (4-8 ohm) driver directly to a 70V/100V line without its matching transformer, which overloads and can damage the amplifier."], "scenario_contexts": ["A ceiling speaker in an airport concourse delivering paging and background music.", "A wall-mounted speaker serving one conference-room zone fed from a 70V line.", "A restaurant fitted with many small ceiling speakers for even background music."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"4e065f2e-0f4a-4603-8916-709df69d08a5": {"definition": "A sound system that spreads many low-power loudspeakers across the coverage area, each serving a small zone with overlapping coverage, rather than using a few high-power point sources; such systems commonly use constant-voltage (70V/100V) distribution so that numerous speakers share amplifier lines through step-down transformers.", "plain_english": "A sound system that uses many small speakers spread across a space. Each covers a small area, and together they give even sound. It is common for paging and background music.", "purpose_function": "It delivers uniform level and clear speech across large or complex spaces; using many small sources avoids the too-loud-then-too-quiet result of relying on a few big speakers.", "practical_application": "Installers design speaker spacing for even listening-plane coverage, then wire the units on 70V/100V lines, keeping the summed transformer taps within the amplifier's rated power.", "category": "Distributed Audio", "related_terms": ["Distributed loudspeaker", "Constant-voltage system", "70V line", "100V line", "Point-source system", "Paging system"], "common_mistakes": ["Thinking louder or bigger speakers are better; a distributed design deliberately uses many low-power units for even coverage.", "Confusing constant-voltage (70V/100V) distribution with low-impedance (4-8 ohm) direct connection.", "UNSAFE: Summing speaker taps up to or beyond the amplifier's rating; keep the total load safely below rated power to avoid overload."], "scenario_contexts": ["A shopping-mall paging and music system with hundreds of ceiling speakers on 70V lines.", "A stadium concourse system for announcements and emergency voice messages.", "An office building's zoned background-music and paging installation."]}, "e064140c-02d1-4eac-8bd6-273462d7ddf4": {"definition": "In audio, a shorthand for a distributed loudspeaker system: a design that uses many spread-out, low-power loudspeakers, each covering a small zone with overlapping coverage and typically fed by constant-voltage (70V/100V) lines, to achieve even coverage over a large area.", "plain_english": "In sound work, this is short for a distributed loudspeaker system. It uses many small speakers spread out to cover a big space evenly, instead of a few large ones.", "purpose_function": "It exists to give consistent coverage and speech intelligibility across large areas, especially for paging and background music where even level matters more than stereo imaging.", "practical_application": "A technician recognises a distributed system by its many ceiling or wall speakers on shared 70V/100V lines, and services it by checking taps, transformers, and zones.", "category": "Distributed Audio", "related_terms": ["Distributed loudspeaker system", "Distributed loudspeaker", "Constant-voltage system", "70V line", "Paging system"], "common_mistakes": ["Reading 'distributed system' only in a computing sense; in audio it means a distributed loudspeaker system.", "Assuming it aims for stereo or hi-fi imaging; it targets even coverage and speech intelligibility.", "Mixing constant-voltage and low-impedance wiring on the same amplifier line."], "scenario_contexts": ["A hotel's building-wide background-music and paging installation.", "A school's classroom and corridor announcement system.", "A warehouse paging system covering aisles with many ceiling speakers."]}, "955878d2-8db0-4eac-b5a1-7ac22f72b99d": {"definition": "A supplementary loudspeaker (or the lowest cabinets of a flown array) aimed downward to cover the audience area immediately below and in front of a high-mounted main array or cluster, filling the near zone that the main system's downward-limited coverage would otherwise miss.", "plain_english": "A speaker aimed down to cover people sitting right under a high, flown main speaker. The main speakers throw sound out over that near area, so down-fill covers it.", "purpose_function": "It extends coverage to seats close to and beneath a flown array, giving those listeners adequate level and clarity instead of a dead spot directly under the hang.", "practical_application": "A system tech adds down-fill boxes at the bottom of a hang, or as separate cabinets, then aims and levels them to blend smoothly with the main array's coverage.", "category": "Loudspeaker Coverage", "related_terms": ["Line array", "Front-fill", "In-fill", "Main array", "Flown array", "Loudspeaker coverage"], "common_mistakes": ["Confusing down-fill with front-fill; down-fill covers the area just below a flown array, front-fill the front-row edge.", "Aiming the whole main array steeply downward instead of adding a dedicated down-fill.", "UNSAFE: Adding down-fill cabinets to a flown array without confirming the rigging's rated capacity, load path, and structural limits first."], "scenario_contexts": ["A flown line array in an arena needs down-fill for the seats directly beneath the hang.", "A high proscenium cluster in a theatre uses down-fill for the front stalls.", "An outdoor festival hang adds down-fill for the pit area close to the stage."]}, "5c96e4fa-b635-4747-ba25-df680a31a14e": {"definition": "A loudspeaker installed in a performer's dressing room that reproduces the show-relay (program) feed together with stage-management paging, so that performers can follow the performance and hear calls while away from the stage.", "plain_english": "A speaker in a dressing room that plays the live show and the stage manager's calls. Performers use it to follow the show and know when to head to the stage.", "purpose_function": "It keeps performers and staff aware of the show's progress and of cues or calls, so they are ready for entrances without needing to wait at the stage.", "practical_application": "A technician installs and levels these speakers during fit-up, ensuring paging takes priority over the relay feed so that calls are always heard clearly.", "category": "Backstage Audio", "related_terms": ["Show relay", "Paging system", "Program feed", "Stage manager's call", "Backstage monitor"], "common_mistakes": ["Feeding dressing rooms the front-of-house mix instead of a dedicated show-relay feed with paging priority.", "Forgetting that paging must override or duck the relay so calls are clearly heard.", "Setting the level so high that the relay disturbs performers or leaks into open microphones."], "scenario_contexts": ["A stage manager pages a performer from a dressing room to the stage before an entrance.", "Performers listen to the show relay to catch their cue while waiting backstage.", "A theatre technician checks dressing-room speaker levels during fit-up."]}, "e1f9d087-93b0-473f-aac9-391ae9e10440": {"definition": "A loudspeaker located in a dressing room that carries the show-relay (program) feed and stage-management paging so performers can follow the performance and hear calls; a synonym for a dressing-room loudspeaker.", "plain_english": "A speaker in a dressing room that plays the show and the stage manager's announcements. It lets performers follow the show and hear when they are called.", "purpose_function": "It provides show relay and paging to performers away from the stage, helping them stay ready for cues and entrances.", "practical_application": "A tech commissions these speakers during fit-up, checking that both the relay feed and paging work and that pages override the relay audio.", "category": "Backstage Audio", "related_terms": ["Dressing-room loudspeaker", "Show relay", "Paging system", "Program feed", "Backstage monitor"], "common_mistakes": ["Assuming it carries the full front-of-house mix; it carries a show-relay/program feed plus paging.", "Not giving the stage manager's page priority over the relay audio.", "Confusing it with a stage monitor; it is for listening backstage, not for performance monitoring."], "scenario_contexts": ["A quick-change actor follows the show over the dressing-room speaker.", "A stage manager's call to the dressing room is heard on this speaker.", "A tech commissions dressing-room speakers so relay and paging both work."]}, "01ec6843-2334-45c4-8367-c0927a9c9636": {"definition": "A verification step during system deployment or setup in which each loudspeaker, and each of its drivers (for example the low- and high-frequency transducers), is confirmed to be connected, powered, and reproducing signal correctly, often including a polarity check of every element.", "plain_english": "A test that makes sure every speaker, and each part inside it, is working. The tech checks each box so there are no dead or wrongly wired speakers before the show.", "purpose_function": "It catches dead, disconnected, or reverse-wired drivers before an event, ensuring the whole deployed system covers the audience as designed.", "practical_application": "During setup, a technician sends test signals to each output, then walks the rig listening to confirm every box and driver responds and is in correct polarity.", "category": "System Check", "related_terms": ["System check", "Soundcheck", "Loudspeaker driver", "Polarity check", "Line check", "Signal flow"], "common_mistakes": ["Checking only that some sound comes out, not that each individual driver (low- and high-frequency) is working.", "Skipping polarity, so a reverse-wired driver cancels output where coverage overlaps.", "UNSAFE: Sending a sudden full-level test signal, which can damage drivers and expose people to harmful sound; start low and raise gradually."], "scenario_contexts": ["A system tech walks the venue confirming every deployed loudspeaker box is producing sound.", "During deployment, each array element is checked for a working low- and high-frequency driver.", "Before doors, the crew runs a driver check to find any dead or reverse-polarity box."]}, "6fe297b0-5596-4541-9844-216eb2048c96": {"definition": "The independent gain (level) applied to a single frequency band, or its associated driver section, within a multi-way loudspeaker's active crossover or DSP loudspeaker-management processor. Setting driver/band gains fixes the relative output of the low-, mid-, and high-frequency sections so the assembled system delivers the intended overall frequency response.", "plain_english": "A big speaker often splits sound into low, mid, and high parts. Each part has its own driver. Driver or band gain sets how loud each part plays. Techs adjust these to balance the speaker's overall tone.", "purpose_function": "It lets the designer balance the output of each driver section so the crossover bands blend into one smooth, correctly weighted response instead of one band overpowering the others.", "practical_application": "A technician loads a factory loudspeaker preset or tunes by measurement, then trims each band's gain in the processor to match drivers, correct tonal balance, and align levels across a deployed system.", "category": "System Tuning", "related_terms": ["Active Crossover", "Loudspeaker Management System", "Gain Structure", "Line Array", "Excursion Limiter", "System Tuning"], "common_mistakes": ["Raising one band's gain to reshape tone when EQ is the correct tool, which unbalances the crossover blend", "Editing individual band gains inside a factory preset and losing the manufacturer's voicing and built-in driver protection", "Confusing band gain with input gain or amplifier sensitivity and corrupting the overall gain structure"], "scenario_contexts": ["Loading a manufacturer preset for a three-way box and confirming each band's gain matches the factory voicing", "Tuning a deployed line array by measurement and trimming the HF band gain to compensate for air absorption over distance", "Balancing subwoofer band gain against the main tops so the crossover region sums smoothly across the venue"]}, "33cfd4ae-5336-4556-acf5-c625e8a722b2": {"definition": "A dedicated stage-monitor system placed beside or behind the drummer, typically a subwoofer paired with a full-range top box, that reproduces the drummer's monitor mix. It supplies the low-frequency energy and level a drummer needs to feel kick, bass, and click that small floor wedges alone cannot deliver.", "plain_english": "A drum fill is a speaker set up just for the drummer. It usually has a sub for low sounds plus a top box. It plays the drummer's own mix so they can hear and feel the kick and bass. It sits right next to the drum kit.", "purpose_function": "It gives the drummer a powerful, stable personal monitor at the back of the stage, delivering the low-end punch and clarity floor wedges lack so the drummer can lock in with the band.", "practical_application": "A monitor engineer positions the drum fill on or beside the riser, feeds it a focused monitor mix heavy on kick, bass, and click, and rings it out for gain before feedback.", "category": "Stage Monitoring", "related_terms": ["Stage Monitor", "Wedge", "Side-fill", "Monitor Mix", "In-Ear Monitor", "Subwoofer"], "common_mistakes": ["Feeding the drum fill a full front-of-house mix instead of a focused monitor mix, muddying the stage sound", "Running the drum fill so loud it bleeds into vocal microphones and out to the audience", "UNSAFE: Stacking a heavy drum-fill sub and top box on a riser without securing them, so vibration can walk the stack toward the edge"], "scenario_contexts": ["Setting up a rock show where the drummer needs strong kick and bass to keep time on a loud stage", "Building a monitor world at soundcheck and assigning a dedicated aux mix to the drum fill", "Supporting a click track and backing tracks so the drummer feels the tempo reference clearly"]}, "29417147-cab9-45da-9c14-2056eda5fae0": {"definition": "A technique in which the aiming and shape of a loudspeaker array's output beam are controlled by applying independent DSP delay and amplitude shading to each driver element, rather than by physically tilting the enclosure. Because the beam is formed by controlled interference between elements, its angle and width can be set and changed without moving the array.", "plain_english": "Normally you aim a speaker by tilting it. Electronic steering aims the sound using a computer instead. It delays each speaker by a tiny amount so the sound adds up in one direction. This lets you point the sound without moving the box.", "purpose_function": "It lets a fixed, visually discreet column array direct sound onto the audience and away from reflective surfaces, improving clarity in reverberant rooms without mechanical rigging changes.", "practical_application": "In churches, transport hubs, and atriums a technician mounts a steerable column vertically, then uses the manufacturer's software to set the beam's down-tilt and opening angle onto the seating area.", "category": "Loudspeaker Arrays", "related_terms": ["Beam Steering", "Column Array", "Line Array", "Delay", "Coverage Angle", "DSP"], "common_mistakes": ["Assuming steering works at any frequency; short high-frequency wavelengths and directional drivers resist beam steering", "Ignoring rear or side lobes that electronic steering can create, unlike a physically tilted array", "Expecting steering to overcome a poor mounting height or position instead of correct physical placement"], "scenario_contexts": ["Installing a steerable column in a reverberant church and aiming the beam down onto the pews to raise intelligibility", "Covering a train-station concourse where speakers must be flush and unobtrusive yet still direct speech to travelers", "Reconfiguring coverage in a multi-use hall via software instead of re-rigging the loudspeakers"]}, "82b10cac-c1e0-4ca0-97a3-f41ecf27b7d8": {"definition": "A directional loudspeaker array, most often used with subwoofers, in which two or more identical enclosures are spaced along the front-to-back axis of radiation and fed progressively increasing delay (rear box first, front box delayed by the acoustic travel time between boxes) so their outputs sum forward and partially cancel rearward. The result is a gradient, cardioid-like pattern that projects low frequencies toward the audience while reducing them on stage and behind the array.", "plain_english": "An end-fire array lines up subwoofers one behind another. Each rear box plays a tiny bit before the one ahead of it. The delays make the bass add up in front and cancel behind. This sends low sound to the crowd and keeps it off the stage.", "purpose_function": "It provides directional bass control using only delay, reducing low-frequency spill onto the stage and back of house so vocals stay clearer and less bass escapes to neighbors.", "practical_application": "An engineer places subs in a line pointing at the audience, sets the interbox delay to match the acoustic travel time between adjacent boxes, and confirms the front-to-back rejection with measurement.", "category": "Loudspeaker Arrays", "related_terms": ["Cardioid Subwoofer Array", "Gradient Array", "Subwoofer", "Delay", "Directional Control", "Line Array"], "common_mistakes": ["Setting the interbox delay by guesswork instead of the actual box spacing, weakening both forward summation and rear cancellation", "Expecting deep rejection at all bass frequencies; end-fire cancellation is strongest over a band set by the spacing", "Spacing the boxes unevenly so the array no longer sums coherently on axis"], "scenario_contexts": ["Deploying subs at an outdoor festival to keep low-frequency spill off the stage and neighboring properties", "Setting up directional bass in a venue with a noise curfew or nearby residences", "Reducing bass buildup behind the loudspeakers so the monitor engineer and performers hear cleaner low end"]}, "9c90512e-0db0-4123-91d1-24015c66c3e0": {"definition": "A signal-processing function, usually within a loudspeaker-management DSP or amplifier, that limits low-frequency drive to keep a driver's cone and voice-coil movement within its maximum linear excursion (Xmax). It acts mainly at low frequencies, where a given voltage produces the largest cone displacement, preventing mechanical over-travel that causes distortion or physical damage.", "plain_english": "A speaker cone can only move in and out so far. Push it too hard, especially with deep bass, and it can bottom out or tear. An excursion limiter is a safety control in the processor. It quietly holds back low frequencies so the cone stays within safe travel.", "purpose_function": "It protects the driver from mechanical failure caused by over-excursion at high levels and low frequencies, letting a system run loud with less risk of physical damage than thermal limiting alone can prevent.", "practical_application": "A technician relies on the manufacturer's excursion limiter inside a factory loudspeaker preset, and avoids editing it, so woofers stay protected even during heavy bass or a dropped microphone.", "category": "Driver Protection", "related_terms": ["Xmax", "Loudspeaker Management System", "RMS Limiter", "Peak Limiter", "Driver/Band Gain", "Power Compression"], "common_mistakes": ["Confusing an excursion limiter with a thermal (RMS) limiter; one guards mechanical travel, the other guards the voice coil against heat", "Disabling or bypassing the excursion limiter in a factory preset to gain output, risking woofer damage", "Assuming the limiter can substitute for an undersized system instead of adding proper low-frequency capacity"], "scenario_contexts": ["Configuring a loudspeaker-management processor so woofers are protected during a bass-heavy EDM set", "Guarding against a dropped or thumped microphone sending a large low-frequency transient to the drivers", "Verifying that a factory preset's excursion protection is active before pushing a system to its rated output"]}, "249cf8d7-09bc-4a20-93e3-6ff776fe377a": {"definition": "The region far enough from a sound source that its wavefront behaves essentially like that of a point source: sound pressure level falls about 6 dB per doubling of distance (the inverse-square law) and the source's directivity is fully developed. It is contrasted with the near field, close to the source, where pressure and particle velocity are not in phase and level does not follow the simple 6-dB rule.", "plain_english": "The far field is the area well away from a speaker. Out there, sound gets quieter in a simple, steady way. Each time you double your distance, the level drops about 6 decibels. Measurements taken here show how the speaker really behaves for the audience.", "purpose_function": "The far-field concept tells technicians where a loudspeaker's published coverage and response are valid, so measurements and coverage predictions are made where the source acts as one predictable point.", "practical_application": "When measuring or aligning a system, a technician places the measurement microphone in the far field so the captured response reflects true on-axis behavior rather than near-field anomalies.", "category": "Acoustics", "related_terms": ["Near Field", "Inverse Square Law", "Free Field", "Directivity", "Critical Distance", "Sound Pressure Level"], "common_mistakes": ["Measuring too close, in the near field, and assuming the result represents the speaker's true far-field response", "Believing the 6-dB-per-doubling rule holds indoors; room reflections change it beyond the critical distance", "Confusing far field with simply 'far away,' ignoring that the boundary depends on source size and frequency"], "scenario_contexts": ["Placing a measurement microphone far enough from a loudspeaker to capture its true on-axis frequency response", "Predicting audience SPL over distance when designing coverage for a large venue", "Explaining why a published polar or sensitivity spec is measured at a far-field reference distance"]}, "346b3aa6-8190-4199-bbbc-2b4779497cf2": {"definition": "A descriptor for a loudspeaker or array section designed to deliver adequate sound pressure level and intelligibility to listeners far from the source, achieved with narrow vertical dispersion and high directivity that concentrate energy toward the distant coverage area. In a line array it usually refers to the tightly splayed upper cabinets aimed at the farthest seats.", "plain_english": "Far-throw, or long-throw, speakers are made to reach the back of a big crowd. They focus their sound into a narrow beam. That keeps enough volume and clarity for people far away. In a line array, the top boxes usually do the long-throw job.", "purpose_function": "It concentrates limited acoustic energy onto distant seating so those listeners hear a level and clarity close to the front rows, compensating for the level lost over distance.", "practical_application": "When designing an array, a technician assigns tightly angled top cabinets to cover the far seats and wider-angled lower cabinets to cover nearby rows, balancing level from front to back.", "category": "Coverage", "related_terms": ["Near-throw (short-throw)", "Line Array", "Directivity", "Coverage Angle", "Splay Angle", "Far field"], "common_mistakes": ["Assuming a long-throw box is simply louder rather than more directional over distance", "Using wide-dispersion boxes for far coverage, wasting energy on walls and ceilings and losing distant clarity", "Ignoring high-frequency air absorption, which reduces intelligibility at long throw even with a directional box"], "scenario_contexts": ["Assigning the top cabinets of a line array to cover the farthest seats in an arena", "Choosing a narrow-dispersion, high-directivity box to reach the rear of a deep outdoor field", "Adding delay towers when a single long-throw array can no longer maintain level and clarity at the back"]}, "3102df31-1c48-4bd3-aa82-9906d813d5e7": {"definition": "In production audio, 'flown' (or 'flying') describes loudspeakers or other equipment suspended overhead from building structure or rigging rather than ground-stacked. Flown enclosures and their suspension hardware must be purpose-built and rated for overhead suspension, carry a manufacturer-declared Working Load Limit with the required design factors, and be rigged following recognized overhead-load and rigging standards.", "plain_english": "'Flown' means a speaker hangs in the air overhead instead of sitting on the ground. Rigging attached to the building or a truss holds it up. Only speakers built and rated for hanging may be flown. This work can kill people if it fails, so trained riggers and rated gear are required.", "purpose_function": "Flying loudspeakers raises them above the audience to improve sightlines and coverage and to reach distant listeners, while clearing stacked boxes from the floor; it exists because elevated, angled coverage is often acoustically and logistically superior.", "practical_application": "A rigger uses only enclosures and hardware rated for overhead suspension, hangs each array from rated suspension points and hardware kept within the Working Load Limit and required design factors, fits independent secondary safety where the manufacturer or standard requires it, and has the assembly checked before anyone works or stands beneath it.", "category": "Rigging", "related_terms": ["Ground-stacked", "Rigging", "Working Load Limit", "Design Factor", "Fly Bar (Bumper)", "Chain Hoist"], "common_mistakes": ["UNSAFE: Flying a loudspeaker not rated by its manufacturer for overhead suspension, or hanging it from carrying handles or improvised hardware", "UNSAFE: Relying on a single load path with no independent secondary safety where redundancy is required, or exceeding the enclosure's or hardware's Working Load Limit and required design factors", "UNSAFE: Using damaged, uninspected, or unrated slings and shackles; rated-capacity markings and competent-person inspection before use are required", "Confusing the enclosure's own weight with the total working load, ignoring added array frames, cabling, and dynamic forces"], "scenario_contexts": ["Flying a main line array from a truss or building steel above the audience at a concert", "Hanging center and side hang clusters in a theater or house of worship for even coverage and clear sightlines", "Rigging a delay or fill loudspeaker overhead where a ground stack would block views or walkways"]}, "c4474e98-4468-4aa1-8057-d52749c7d45c": {"definition": "A subwoofer suspended overhead from a rigging structure such as a truss, beam, or line-array frame, rather than placed on the floor, so its low-frequency output radiates from height. Flying subs can extend low-frequency throw and, when arranged in a vertical column or gradient configuration, improve directional control; overhead-suspended enclosures must comply with ANSI E1.8 and the manufacturer's rigging data.", "plain_english": "A flown subwoofer hangs in the air from rigging instead of sitting on the floor. Hanging subs can throw bass farther and aim it better. Only rated gear and trained riggers should fly one.", "purpose_function": "It places low-frequency energy up high to even out bass coverage over distance and, in arrays, to steer bass away from the stage or rear wall, while also freeing floor space near the stage.", "practical_application": "A system tech flies a column of subs beside or behind a line array using the manufacturer's rigging frame and load-rated hardware, verifying loads against rigging software and the venue's rated points.", "category": "Loudspeaker Deployment", "related_terms": ["Ground subwoofer", "Line array", "Cardioid subwoofer array", "Flybar (bumper/grid)", "Working load limit", "Rigging point"], "common_mistakes": ["UNSAFE: exceeding the enclosure or hardware working load limit, or flying with unrated rigging hardware", "UNSAFE: omitting required secondary safety or retention where the manufacturer or standard calls for it", "Assuming a flown sub couples to the ground like a ground stack, when flying removes the boundary gain"], "scenario_contexts": ["Flying a column of subs next to a main line array at an arena", "Suspending cardioid subs to keep low end off the stage", "Verifying rigging-point loads before lifting a flown sub array"]}, "8173a5d1-5fcc-4c26-8cd1-10c5cad70899": {"definition": "A load-rated bar or beam used to suspend loudspeaker enclosures from a rigging point, hoist, or truss, forming the mechanical link between the overhead structure and the cabinets. It carries the load to one or more rated pick points and commonly provides the means to set the hang angle.", "plain_english": "A fly bar is a strong metal bar that speakers hang from. It connects the cabinets to the rigging above. It must be rated to hold the full weight safely.", "purpose_function": "It gives a single rated attachment point to lift and hold a loudspeaker or array, transferring the weight into the venue's rigging while keeping the cabinets at the correct height and angle.", "practical_application": "Riggers shackle the fly bar to a chain hoist and connect the top cabinet, then raise the array; the bar's rated pick holes let the tech set the array's tilt.", "category": "Rigging Hardware", "related_terms": ["Flybar (bumper/grid)", "Line array", "Chain hoist", "Shackle", "Working load limit", "Rigging point"], "common_mistakes": ["UNSAFE: loading a fly bar beyond its rated working load limit or using unrated shackles and hardware", "UNSAFE: rigging without the required safety pins, keepers, or secondary retention", "Confusing the fly bar with the truss or beam it hangs from"], "scenario_contexts": ["Flying a line array from a chain hoist on a fly bar", "Setting an array's tilt using the fly bar's pick holes", "Connecting subs beneath a main hang on a rated bar"]}, "21ff39a4-64a4-4139-970c-6ac9668f3fd4": {"definition": "The top frame of a flown line array — also called a bumper, grid, or top frame — that attaches to the hoist or rigging and carries the cabinets beneath it, while setting the array's overall up-tilt and providing the rated pick point(s) for lifting. It is a suspension component covered by ANSI E1.8 and matched to a specific loudspeaker system.", "plain_english": "A flybar, or bumper, is the frame at the top of a hanging speaker array. The whole array hangs from it. It sets how far the array tilts up or down.", "purpose_function": "It is the single rated lifting and aiming interface for a line array, carrying all the cabinets' weight and letting the tech set the top-box angle so coverage reaches the intended seats.", "practical_application": "A system tech picks the array on its flybar, then dials in the top-box angle at the bumper before setting the inter-cabinet splay angles down the hang.", "category": "Rigging Hardware", "related_terms": ["Fly bar", "Line array", "Splay angle", "Chain hoist", "Working load limit", "Flown subwoofer"], "common_mistakes": ["UNSAFE: loading a flybar beyond its rated capacity or mismatching it to a different cabinet model", "UNSAFE: omitting the required safety pins or keepers at the pick and cabinet connections", "Assuming the flybar sets every array angle when it sets only the top-box tilt"], "scenario_contexts": ["Rigging a line array top frame to a motor at load-in", "Setting the overall array up-angle at the bumper", "Matching the correct bumper to a specific cabinet series"]}, "814b1d5b-0421-4589-9658-acd14fa87e52": {"definition": "A stage monitor loudspeaker aimed back toward performers so they can hear themselves and other sources; \"foldback\" is chiefly British and Australian usage for stage monitoring. It is typically a floor wedge or side-fill cabinet fed from monitor mixes that are separate from the front-of-house mix.", "plain_english": "A foldback speaker points back at the performers on stage. It lets them hear their own singing or playing. Foldback is just another word for a stage monitor.", "purpose_function": "It sends a dedicated mix back to the performers so they can stay in time and in tune, because the main speakers face away from them toward the audience.", "practical_application": "A monitor engineer builds a separate mix for each foldback wedge, tunes it, and rings out feedback before the performer relies on it.", "category": "Stage Monitoring", "related_terms": ["Stage monitor", "Wedge", "Side fill", "In-ear monitor", "Monitor mix", "Feedback"], "common_mistakes": ["Thinking foldback is a different device from a stage monitor", "Running foldback too loud, which raises feedback risk and stage spill", "Feeding foldback from the front-of-house mix instead of a dedicated monitor send"], "scenario_contexts": ["A singer's wedge at the front edge of the stage", "Side-fill foldback covering a drummer", "A monitor engineer ringing out foldback before doors"]}, "9da66036-5fe0-44d3-9013-9139304abae6": {"definition": "A group of small loudspeakers placed along the front edge of the stage, arranged in a horizontal row, to cover the first audience rows that fall below or outside the main system's vertical coverage. It provides even level and clear localization for the closest listeners.", "plain_english": "A front fill array is a row of small speakers at the stage edge. They cover the people sitting right up front. The big main speakers usually shoot over those seats.", "purpose_function": "It fills the coverage gap directly in front of the stage that the mains overshoot, giving front-row listeners proper level and intelligibility.", "practical_application": "A system tech spaces several front fills across the stage lip, delays them to the mains, and sets a low level so they help the front rows without drawing attention.", "category": "Fill Loudspeakers", "related_terms": ["Front fills", "Delay", "Main array", "Coverage", "Localization", "Near fill"], "common_mistakes": ["Setting the front fill array too loud so it dominates the mix up front", "Skipping delay alignment to the main system", "Spacing the boxes so far apart that coverage gaps appear between them"], "scenario_contexts": ["Covering the first rows in a theatre", "A row of fills along an arena stage lip", "Delayed front fills at a corporate presentation"]}, "f05ee98a-aa1c-4eba-a3cc-0d8d07009903": {"definition": "Loudspeakers placed at the front of the stage to cover audience seats too close or too low for the main loudspeakers to reach; also written front fill. They restore level and central imaging for the nearest listeners.", "plain_english": "Front fills are speakers at the edge of the stage. They cover the audience sitting closest to it. The main speakers usually aim over those front seats.", "purpose_function": "They give the front rows proper coverage and clear sound placement, filling the area the mains shoot past.", "practical_application": "An engineer adds front fills, delays them to the mains, and keeps their level modest so the front rows hear well without a hotspot.", "category": "Fill Loudspeakers", "related_terms": ["Front fill array", "Delay", "Main array", "Coverage", "Near fill", "Foldback speaker"], "common_mistakes": ["Running front fills too hot for the front rows", "Not time-aligning front fills with the main system", "Assuming the mains alone cover the first rows of seats"], "scenario_contexts": ["Front-row coverage at a concert", "Fills at the lip of a conference stage", "Restoring central imaging for close seats"]}, "cb901b05-ea79-48a5-829c-027606298679": {"definition": "A loudspeaker designed to reproduce the full or near-full audible spectrum from a single enclosure, typically combining low/mid drivers with a high-frequency device; in live sound it usually denotes a main cabinet covering roughly the low-60s Hz upward, often paired with subwoofers for the lowest octaves. It is distinct from a single-driver \"full-range\" transducer.", "plain_english": "A full-range loudspeaker plays lows, mids, and highs from one box. It covers most of what we can hear. Subwoofers are often added for the deepest bass.", "purpose_function": "It provides broadband coverage from a single cabinet so a system can reproduce most program material without separate boxes for each frequency band.", "practical_application": "A tech deploys full-range cabinets as the mains and adds subs beside or beneath them to extend the low end for music.", "category": "Loudspeaker Types", "related_terms": ["Subwoofer", "Line array", "Point source", "Crossover", "Two-way loudspeaker", "Coaxial loudspeaker"], "common_mistakes": ["Assuming full-range means the box reaches deep bass near 20 Hz without a subwoofer", "Confusing a full-range PA cabinet with a single full-range driver", "Sending lows to both the full-range mains and the subs without a crossover, causing overlap"], "scenario_contexts": ["Choosing mains for a small club", "Full-range tops over subs at an outdoor show", "A coaxial full-range monitor wedge"]}, "82819a1a-0939-47a8-b0ac-eb9dea3d0f43": {"definition": "A loudspeaker array configuration that combines multiple sources with controlled amplitude and time offsets, and sometimes reversed polarity, to create directional, gradient-like radiation with increased cancellation to one side. Cardioid and end-fire subwoofer arrays are common examples of gradient low-frequency arrays.", "plain_english": "A gradient array uses several speakers timed and aimed to push sound one way. It cancels sound going the other way. Directional subwoofer setups work like this.", "purpose_function": "It shapes low-frequency directivity so bass travels toward the audience while cancelling behind the array, keeping the stage and neighbouring areas quieter.", "practical_application": "A system tech builds a cardioid or end-fire sub array, setting each cabinet's delay and polarity so the front adds and the rear cancels.", "category": "Array Configuration", "related_terms": ["Cardioid subwoofer array", "End-fire array", "Subwoofer", "Delay", "Polarity", "Directivity"], "common_mistakes": ["Setting the delay or polarity wrong so the wanted direction cancels instead of the rear", "Expecting deep rear cancellation across all frequencies from a gradient array", "Ignoring element spacing, which sets the frequency range where cancellation works"], "scenario_contexts": ["A cardioid sub array to keep bass off the stage", "End-fire subs at an outdoor festival", "Steering low end away from a nearby residence"]}, "da89bff3-8152-4b31-8a52-aaa32b424681": {"definition": "A subwoofer placed on the floor (ground-stacked) rather than flown, using the boundary to gain low-frequency efficiency through ground coupling. Ground subs are commonly arranged in horizontal arrays such as cardioid or end-fire across the stage front; the floor placement adds acoustic gain but can create horizontal \"power-alley\" interference between left/right stacks.", "plain_english": "A ground subwoofer sits on the floor instead of hanging. The floor boosts its bass output. These subs are often lined up along the front of the stage.", "purpose_function": "It delivers efficient, powerful low end by coupling to the ground, and lets techs build horizontal arrays that steer bass across the audience.", "practical_application": "A tech ground-stacks subs across the stage front, then spaces and delays them into a cardioid or end-fire array to control bass direction and coverage.", "category": "Loudspeaker Deployment", "related_terms": ["Flown subwoofer", "Cardioid subwoofer array", "End-fire array", "Ground stack", "Power alley", "Subwoofer"], "common_mistakes": ["Using only two left/right ground sub stacks and getting a power-alley comb across the audience", "Assuming ground subs need no delay or polarity alignment to the mains", "UNSAFE: stacking subs high or unbraced so the stack can topple onto people, instead of securing per the manufacturer's guidance"], "scenario_contexts": ["A row of ground subs along the stage front", "Left/right ground-stacked subs at a club", "End-fire ground subs at a festival"]}, "4473a53e-f44e-475b-9487-d50d562d17ea": {"definition": "A loudspeaker deployment method in which enclosures are stacked and supported on the ground, stage, riser, or on top of subwoofers, rather than flown overhead. The array's weight is carried in compression by the surface below, and inter-cabinet angles are set with ground-stack frames or wedge accessories.", "plain_english": "Ground-stacking means placing speakers on the floor or on top of each other. The whole stack rests on the ground instead of hanging from above. It is used when there is no safe rigging point overhead.", "purpose_function": "It lets a system be deployed where no overhead rigging points exist or flying is not allowed, sending the array's weight straight down to the ground. It also gives a stable base that can support additional loudspeakers.", "practical_application": "A crew builds a ground stack on a stacking frame beside the stage when a venue has no roof steel or the budget rules out motors and towers.", "category": "Deployment method", "related_terms": ["Flown array", "Hang", "Ground-stacked subwoofer", "Stacking frame", "Line array", "Sub array"], "common_mistakes": ["Assuming a ground stack always sounds worse than a flown array; with correct height and splay it can cover well, though front-row coverage and sightlines are harder.", "Placing the stack too low, so the array fires into the first rows and cannot reach the back of the audience.", "UNSAFE: Building a ground stack above the manufacturer's maximum stack height, or without stacking interlocks and restraint against tip-over, especially outdoors in wind."], "scenario_contexts": ["A club with no rigging steel gets a ground-stacked line array on stacking frames at each side of the stage.", "An outdoor festival flies the mains but ground-stacks extra subwoofers across the front of the stage.", "A ballroom bans flying, so the tops are ground-stacked on subwoofers behind the barricade."]}, "c470c5f6-afd6-4a47-910d-b2abf0b572c1": {"definition": "A subwoofer, or array of subwoofers, placed on the ground rather than flown, so it gains boundary (half-space) loading from the floor and provides a rigid base that can also support the main tops. Ground placement is standard for horizontal sub arrays (broadside, end-fire, cardioid, and gradient) used to steer low-frequency coverage.", "plain_english": "A ground-stacked subwoofer sits on the floor instead of hanging up high. The floor reflects its low sound, which makes the bass louder and more efficient. A row of ground subs can also aim the bass where you want it.", "purpose_function": "Ground placement adds acoustic gain from the floor and gives a solid base for the tops. Laying subs in a line lets engineers control where the low end goes and where it is reduced.", "practical_application": "A tech lays a broadside or cardioid row of subs on the ground across the stage front, then stacks the main tops on the end pairs.", "category": "Deployment method", "related_terms": ["Ground-stacked (ground stack)", "Cardioid subwoofer array", "End-fire array", "Boundary loading", "Flown subwoofer", "Sub array"], "common_mistakes": ["Ignoring boundary loading, so the ground subs end up much louder than the flown tops and the balance is wrong.", "Spacing the subs by guesswork instead of the array pattern's required spacing, which ruins the intended low-frequency steering.", "UNSAFE: Stacking tops on ground subs above the maker's rated stack height, or without interlocks and restraint, risking a topple onto people."], "scenario_contexts": ["A festival lays a cardioid ground-sub array to keep low end off the stage and reduce spill toward neighbours.", "A theatre puts two ground-stacked subs under the side hangs to reinforce the low end.", "An engineer builds an end-fire ground-sub line to push bass toward the audience and cancel it behind."]}, "d92dc24b-740e-454d-91f4-1c2b187c0bd9": {"definition": "In live sound, a hang is a flown (suspended) array or column of loudspeakers rigged overhead from a single set of points; as a verb it is the act of flying such a system. Each enclosure connects through rated rigging frames and links, with inter-cabinet splay angles set to shape the vertical coverage.", "plain_english": "A hang is a group of speakers hung in the air from rigging points above the stage. Crews also say 'hang' for the job of flying them. The angles set between the boxes aim the sound at the crowd.", "purpose_function": "Flying a hang lifts the array above the audience for even coverage and clear sightlines. Setting the splay angles focuses the sound from the front to the back of the room.", "practical_application": "A rigger connects the top frame to a motor, builds the boxes with pinned splay angles, then flies the left and right hangs and trims their height.", "category": "Deployment method", "related_terms": ["Flown array", "Ground-stacked (ground stack)", "Rigging frame", "Splay angle", "Chain hoist", "Working load limit"], "common_mistakes": ["UNSAFE: Exceeding the working load limit of the hoist, frame, or overhead points, or using unrated hardware; overhead rigging must stay within rated capacity and use only inspected, load-rated components.", "UNSAFE: Skipping pre-use inspection, or working and standing under a suspended hang; damaged rigging must be removed from service and loads must not be suspended over people without proper control.", "Relying on a single load path where a secondary/safety retention is required.", "Setting splay angles or array shading wrong, so coverage is uneven from front to back."], "scenario_contexts": ["A crew flies the left and right main hangs from motorized chain hoists on the venue's rigging steel.", "An arena show adds a rear delay hang to cover the seats behind the main arrays.", "A system tech trims a hang's height and grid angle after checking the rigging plot and load limits."]}, "e6df259d-9955-4789-a4be-2f9b5d8ad678": {"definition": "A diagnostic routine that verifies a deployed audio system is fully functional before use, confirming that each amplifier channel, loudspeaker driver, network link, and cable connection is present, correctly addressed, and within expected parameters. On networked amplifier platforms it typically measures loudspeaker impedance and reports damaged drivers, defective or missing connections, and mis-cabling.", "plain_english": "A health check is a quick test that makes sure the whole system works before the show. It looks for dead speakers, bad cables, and wrong connections. Finding faults now avoids surprises during the gig.", "purpose_function": "It catches faults during setup instead of mid-show, and it gives a known-good baseline so a technician can trust the rig once doors open.", "practical_application": "Before soundcheck a tech runs the amplifiers' health or system check in the control software, then chases any flagged driver, cable, or network fault.", "category": "System verification", "related_terms": ["System Check", "Impedance", "Array verification", "Amplifier", "Dante", "Input Router/Matrix"], "common_mistakes": ["Skipping the health check because the system 'worked yesterday', then finding a dead driver during the show.", "Running the check with amplifiers muted or loudspeakers unplugged, so faults are hidden and the pass means nothing.", "Treating a single impedance reading as absolute instead of comparing it against a stored reference baseline."], "scenario_contexts": ["A monitor tech runs a health check across all amps and finds one wedge with an open driver.", "During load-in the system check flags a mis-cabled array element before it causes a problem on stage.", "A touring rig runs a health check at every venue to confirm nothing shook loose in transit."]}, "dbc3a37b-1f56-4b1e-a19e-ab3c53776cdb": {"definition": "Equalization that boosts a loudspeaker system's high-frequency response to offset high-frequency loss, most commonly the frequency-dependent absorption of sound by air over distance, so distant listeners hear the intended tonal balance. The required boost scales with throw distance and varies with temperature, humidity, and altitude.", "plain_english": "Air soaks up high notes more than low notes over long distances. High-frequency compensation adds that treble back so far seats still sound clear. The longer the throw, the more boost is needed.", "purpose_function": "It restores tonal balance for long-throw coverage, keeping the far field from sounding dull compared with seats close to the speakers.", "practical_application": "A system engineer applies air or HF compensation to a long-throw hang or delay so the back of the room matches the tonality up front.", "category": "System tuning", "related_terms": ["Air absorption", "High-Shelf Filter", "Delay loudspeaker", "Line array", "Atmospheric correction", "Equalization"], "common_mistakes": ["Applying air compensation to near-field boxes that don't need it, which makes the close seats harsh.", "Ignoring temperature and humidity changes, so a setting made on a cool morning is wrong for a hot, full room.", "Confusing distance-based HF compensation with a fixed high-shelf 'smiley' EQ."], "scenario_contexts": ["An outdoor festival adds HF compensation to the long-throw hang for the far field on a hot, dry day.", "A stadium delay tower gets air-absorption compensation to match the mains' tone at distance.", "An engineer reduces HF compensation as evening humidity rises and high-frequency air absorption drops."]}, "2c6848ad-f2cb-44ed-bd32-e326356b2316": {"definition": "A shelving equalizer that boosts or cuts all frequencies above a set corner (shelf) frequency by a roughly constant amount, forming a plateau or 'shelf' in the frequency response above that point. It is defined by its corner frequency and its gain, and it affects the whole high band rather than a narrow region.", "plain_english": "A high-shelf filter turns everything above a chosen frequency up or down together. Think of it as a single dimmer for all the treble at once. It sets the level of the high end as a whole.", "purpose_function": "It shapes the overall brightness or dullness of a signal, letting an engineer lift or tame the whole treble region without touching the mids and lows.", "practical_application": "A tech uses a high-shelf cut to soften harsh top end, or a gentle high-shelf boost to add air to a dull-sounding room.", "category": "Signal processing", "related_terms": ["Low-Shelf Filter", "Parametric EQ", "Corner frequency", "High-Frequency Compensation (HFC)", "Equalization", "Peaking filter"], "common_mistakes": ["Confusing a high-shelf with a high-pass filter; a shelf changes level above the corner, while a high-pass removes lows below it.", "Setting the corner frequency too low, so a high-shelf boost also lifts the upper mids and sounds harsh.", "Using a large high-shelf boost to fix distance-related HF loss instead of proper air compensation."], "scenario_contexts": ["An engineer adds a high-shelf cut in the top octave to tame cymbal harshness in a bright room.", "A gentle high-shelf boost adds a sense of air to a dull playback system.", "A system tech uses a high-shelf on the house EQ to match tonality across zones."]}, "fcfde41a-d9af-48be-8908-12fffd8e34c5": {"definition": "A sound system that combines two or more different loudspeaker technologies or formats within one integrated design, such as a line array paired with point-source enclosures, or active and passive cabinets, so each part covers the zone or task it suits best. The subsystems are level- and time-aligned to work together as one coherent system.", "plain_english": "A hybrid system mixes different speaker types in one setup. Tall line-array boxes can cover the far crowd while point-source boxes cover the sides. Each type does the job it is best at.", "purpose_function": "It exists to solve coverage problems that no single loudspeaker type handles well, matching the right enclosure to each audience zone.", "practical_application": "A designer specs a hybrid rig with line-array mains, point-source fills, and separate subwoofers, then aligns them all into one system.", "category": "System type", "related_terms": ["Line array", "Point source", "In-fill", "Hang", "Sub array", "System alignment"], "common_mistakes": ["Assuming different boxes will blend on their own; a hybrid system needs careful level and time alignment between subsystems.", "Mixing enclosures with very different tonal signatures without EQ matching, so the zones sound different.", "Ignoring the overlap regions where two subsystems meet, which causes comb filtering."], "scenario_contexts": ["A theatre uses a hybrid of line-array mains and point-source front-fills for the first rows.", "A house of worship blends a compact line array with point-source under-balcony speakers.", "A festival pairs a main hang with point-source side systems as a hybrid design."]}, "8073bf10-5dd1-4a87-9c72-ff08499499c8": {"definition": "A fill loudspeaker or subsystem aimed at the central audience area between the two main hangs, covering the inner/centre seats near the stage that the outward-angled main left/right systems under-cover. It is one of a family of fill roles alongside out-fill, front-fill, and down-fill.", "plain_english": "In-fills are speakers that cover the middle seats near the stage. The main left and right speakers point outward and miss that centre strip. In-fills fill the gap in the middle.", "purpose_function": "It gives even coverage and correct imaging for the centre section that the outward-angled main arrays under-cover, especially close to the stage.", "practical_application": "A tech hangs or stacks a small in-fill box angled to the centre seats, then aligns it in level and time with the mains.", "category": "Deployment method", "related_terms": ["Out-fill", "Front-fill", "Down-fill", "Hang", "Main array", "Coverage angle"], "common_mistakes": ["Confusing in-fill, which covers the centre between the mains, with out-fill, which extends coverage to the outer seats.", "Running in-fills too loud, so the centre image pulls away from the stage and the mains.", "Forgetting to time-align in-fills to the mains, which causes comb filtering where the coverage overlaps."], "scenario_contexts": ["A wide stage leaves a centre gap between the main hangs, so in-fills cover the middle seats.", "An arena adds in-fills to keep vocal imaging centred for seats close to the stage.", "A tech aligns in-fill level and delay to the mains before doors open."]}, "1d0ac665-cec7-47b1-975b-77fa6a4f39f2": {"definition": "The section of a loudspeaker processor, amplifier, or console that assigns and mixes incoming signals to output channels, allowing any input (or combination of inputs) to be routed, summed, and gain-weighted to any output. A matrix arranges inputs against outputs as cross-points, so each output can draw from a chosen set of inputs.", "plain_english": "An input router or matrix decides which incoming signals feed which speaker outputs. Picture a grid that can connect any input to any output. It can also mix several inputs into one output.", "purpose_function": "It provides flexible signal distribution, so one device can feed different zones or array sections from chosen sources without re-patching cables.", "practical_application": "A tech uses the processor's matrix to send the main mix to the arrays and a separate feed to the delays or fills, setting each cross-point's level.", "category": "Signal routing", "related_terms": ["Loudspeaker processor", "Signal routing", "Zone", "Delay loudspeaker", "Gain", "Output channel"], "common_mistakes": ["Leaving an unused matrix cross-point open, so an output receives an unwanted extra source.", "Confusing a matrix (many-to-many with mixing) with a simple router or patch (one input to one output).", "Setting cross-point gains wrong, so one zone is too loud or too quiet relative to the others."], "scenario_contexts": ["A system processor's matrix feeds mains, front-fills, and delays from one input bus.", "A tech routes a press feed to a separate output using the console's matrix.", "An installer configures a matrix so each room zone can select its own source."]}, "bdeb9b33-8af6-4556-96a0-29f02b539a3b": {"definition": "A cardioid subwoofer configuration built as a single vertical stack in which at least one cabinet is physically reversed to fire rearward and is driven with inverted polarity plus a small time delay. The rear-facing element cancels low-frequency energy radiated behind the stack while summing to the front, producing a unidirectional (cardioid) pattern that reduces bass on stage and backstage.", "plain_english": "Subwoofers normally push bass in every direction, even back toward the stage. In this setup the boxes are stacked and one faces backward. That reversed box is flipped and delayed so its sound cancels the bass behind the stack. The result is loud bass out front and much quieter bass on stage.", "purpose_function": "It gives a subwoofer stack directional control so most low-frequency energy reaches the audience instead of the stage. This cuts bass buildup on stage, reduces microphone bleed, and limits spill toward neighbors.", "practical_application": "A system tech builds the reversed cabinet into the stack, applies the manufacturer's cardioid preset (polarity inversion plus delay), then verifies front-to-rear rejection with a measurement system before doors.", "category": "Cardioid subwoofer array", "related_terms": ["Cardioid subwoofer array", "End-fire array", "Subwoofer array", "Polarity inversion", "Gradient array", "Rear rejection"], "common_mistakes": ["Forgetting to invert polarity on the reversed cabinet, so the rear energy adds instead of cancelling", "Using the wrong delay time or preset, which collapses the cardioid pattern and its rear rejection", "Assuming that physically reversing a box alone creates cardioid output without the required DSP settings", "Ignoring the small forward level loss and gain structure changes the technique introduces"], "scenario_contexts": ["Deploying ground-stacked subs at a festival to keep low end off the stage and out of the monitor world", "Reducing bass spill toward a residential noise boundary at an outdoor show", "Cleaning up a boomy stage where vocal mics pick up too much subwoofer energy"]}, "1f7a279b-200d-4727-a441-f1418bbdf31e": {"definition": "A flown line array hung in a 'J' profile: the upper cabinets carry little or no inter-element splay and act as a tight long-throw section, while the lower cabinets use progressively increasing splay angles to spread coverage across the nearer, down-front audience. The straight-then-curved shape resembles the letter J.", "plain_english": "A J-array is a hanging line of speaker boxes shaped like the letter J. The top boxes point straight out and sit nearly flat against each other. This tight section throws sound far to the back rows. The bottom boxes angle down and fan out to cover people near the stage.", "purpose_function": "It lets one hang cover both distant and near listeners evenly. The straight top reaches the back rows with level and clarity, and the curved bottom fills the front without over-shooting it.", "practical_application": "A system designer sets the per-box splay angles in prediction software such as ArrayCalc or Soundvision, then the crew pins those exact angles when building the array so the hang matches the design.", "category": "Line array configuration", "related_terms": ["Line array", "Splay angle", "Curved array", "J-shape array", "Rigging frame", "Coverage angle"], "common_mistakes": ["Adding too much splay in the top boxes, which weakens long throw to the back of the room", "Using too little splay at the bottom, so the front rows get uneven or hot coverage", "Setting angles by eye instead of using the manufacturer's prediction software", "UNSAFE: Flying the array before confirming the rigging frame, pins, and total load are inspected and within the manufacturer's rated working load limit"], "scenario_contexts": ["Covering a deep concert floor plus a distant upper tier from a single flown hang", "Tuning a hang in prediction software before a tour load-in to match the venue's seating rake", "Adjusting bottom splay to avoid over-covering the pit or down-front area"]}, "6cb1c7f1-f05f-4a6b-bfd1-a983950ca5a9": {"definition": "A line array flown in the shape of the letter 'J', with a nearly straight, low-splay upper section for long throw and a curved lower section of progressively increasing splay angles for near-field, down-front coverage. 'J-shape array' is another name for a J-array.", "plain_english": "A J-shape array is a flown line of speaker boxes bent like the letter J. The straight top section throws sound to the far seats. The fanned-out bottom section covers the closer, down-front crowd. It is just another name for a J-array.", "purpose_function": "The shape lets a single hang serve distant and near listeners at once. The straight top carries level to the back rows, while the curved bottom evenly covers the front without over-shooting it.", "practical_application": "A designer predicts the per-box splay in array software and the crew builds the hang to those exact angles, checking that the straight and curved sections match the seating geometry.", "category": "Line array configuration", "related_terms": ["J-array", "Line array", "Splay angle", "Curved array", "Coverage angle", "Rigging frame"], "common_mistakes": ["Treating the whole array as a straight line and losing near-field coverage down front", "Over-curving the top section, which sacrifices long throw to the back", "Guessing splay angles instead of predicting them in the manufacturer's software", "UNSAFE: Raising the hang before the rigging hardware, load path, and safeties are inspected and confirmed within rated limits"], "scenario_contexts": ["A single flown hang covering both a distant balcony and the floor down front", "Building a touring array to match each venue's seating rake", "Comparing a J-shape hang with a fully curved hang during system design"]}, "a22924fa-1d6d-46d7-82fa-6f42aedbe945": {"definition": "The use of a Left-Center-Right main loudspeaker layout in live sound reinforcement, using three main systems (left, center, and right) rather than a two-system left/right pair. The center system anchors lead vocals and mono content to the stage while left and right carry stereo width and effects.", "plain_english": "LCR means left, center, and right. In live sound it uses three main speaker systems instead of two. The center one handles the lead voice and other mono sounds. This keeps them tied to the middle of the stage. Left and right add width and stereo effects.", "purpose_function": "It keeps vocals and other central content locked to the stage for every seat, not just the middle. This improves imaging and intelligibility across a wide audience compared with a plain left/right rig.", "practical_application": "A front-of-house engineer routes lead vocals and mono elements to the center system and pans stereo sources to left and right, matching level and time alignment so the three systems image as one.", "category": "Main system format", "related_terms": ["LCR system", "Left-center-right system", "Center cluster", "Left main", "Mono cluster", "Stereo imaging"], "common_mistakes": ["Sending every source to all three systems, which blurs imaging instead of improving it", "Not time-aligning the center to left and right, causing comb filtering in the overlap zones", "Under-powering or under-designing the center for the vocal load it must carry", "Panning stereo music into the center, which collapses the width it is meant to preserve"], "scenario_contexts": ["Reinforcing a musical theatre show where every seat needs the vocal centered on stage", "A wide arena where a plain left/right rig would leave center seats with poor imaging", "A worship service mixing spoken word to the center and music in stereo to left and right"]}, "7e64bd9e-3d71-414a-ba54-3e5541ae47d5": {"definition": "A three-channel main loudspeaker system arranged as Left, Center, and Right. The center channel reproduces centered content (typically lead vocals and mono material) anchored to the stage or screen, while the left and right channels provide stereo width; used in live sound, cinema, and immersive playback.", "plain_english": "An LCR system uses three main speaker spots: left, center, and right. The center speaker plays sounds meant to come from the middle, like a lead voice. Left and right add stereo width. Together they spread clear, well-placed sound to a wide crowd.", "purpose_function": "The dedicated center channel holds central content in place for listeners across the whole width of the room. Left and right then handle stereo width without also having to carry the center image.", "practical_application": "A designer specifies left, center, and right hangs or clusters, then the mix routes centered content to the center and panned content to left and right, with all three aligned in level and time.", "category": "Main system format", "related_terms": ["LCR live", "Left-center-right system", "Center cluster", "Left main", "Stereo imaging", "Phantom center"], "common_mistakes": ["Confusing LCR with plain stereo and never feeding the center any dedicated content", "Failing to align the three systems in time and level, which smears the image in overlap zones", "Assuming a center channel removes the need to design left and right coverage properly"], "scenario_contexts": ["Designing mains for a large theatre so dialogue stays centered for off-axis seats", "A cinema installation with discrete left, center, and right screen channels", "An arena concert adding a center hang to lock vocals to the stage"]}, "a7a6fab2-0a7a-4840-8ac8-d35da09f4e3e": {"definition": "The loudspeaker cluster deployed on the left side of a sound reinforcement system: a group of cabinets flown or stacked together as one coherent source serving the left portion of the coverage, such as the left element of a left/right or LCR main system.", "plain_english": "A cluster is a group of speaker boxes grouped tightly to act as one source. The left cluster is the group placed on the left side of the stage. It covers the left part of the crowd. In a stereo or LCR rig it carries the left channel.", "purpose_function": "It provides left-side coverage and, in stereo or LCR, the left channel of the main system. Grouping the boxes as one cluster keeps their combined output coherent rather than scattered.", "practical_application": "A crew flies or stacks the left cluster at stage-left, aims it at its coverage zone, and matches its level, delay, and EQ to the right (and any center) so the whole system images correctly.", "category": "Loudspeaker position", "related_terms": ["Left hang", "Left main", "Center cluster", "LCR system", "Loudspeaker cluster", "Splay angle"], "common_mistakes": ["Aiming the left cluster at the whole room instead of only its coverage zone, causing overlap and combing", "Not matching left cluster level and delay to the right, which pulls the stereo image to one side", "UNSAFE: Flying the cluster from unrated points or without a secondary safety and a load check within the manufacturer's rated working load limit"], "scenario_contexts": ["Building the left main hang for a concert PA at stage-left", "Aligning left and right clusters so the stereo image sits centered for most seats", "A house of worship with permanently flown left and right clusters"]}, "00a45f29-d3b2-4bd9-9f71-4c1858e480f5": {"definition": "The flown loudspeaker array suspended on the left side of the stage, where 'hang' denotes a rigged/flown array (usually a line array) as opposed to a ground stack. The left hang provides left-side or left-channel coverage in a left/right or LCR system.", "plain_english": "In live sound a hang is a line of speaker boxes flown in the air on rigging. The left hang is the flown array on the left side of the stage. It covers the left part of the crowd. It can also be the left channel of a stereo system.", "purpose_function": "Flying the array as the left hang lifts it above the crowd for clear sightlines and even coverage. It serves as the left side or left channel of the main system.", "practical_application": "The rigging crew flies the left hang from a hoist and rigging frame, the system tech dials in the per-box splay angles from the design, then aligns it to the right hang.", "category": "Loudspeaker position", "related_terms": ["Left cluster", "Left main", "Line array", "Rigging frame", "Chain hoist", "Splay angle"], "common_mistakes": ["Confusing a 'hang' (flown array) with a ground stack when reading a system design", "Not matching the left and right hangs in splay, level, and delay, which skews the image", "UNSAFE: Raising the hang before secondary safeties, total load, and rigging hardware are inspected and confirmed within rated limits"], "scenario_contexts": ["Flying the left main line array from an arena's rigging points before a show", "Reading a stage plot that calls for a left hang plus a center hang", "Matching the left and right hangs during system alignment"]}, "1f224f85-7aef-46c3-9986-248b7046ba3b": {"definition": "The left main loudspeaker system: the left-side element of the principal (main) house PA in a left/right or LCR configuration, carrying the left channel and covering the left portion of the audience. It may be a flown line array (left hang) or a ground stack (left stack).", "plain_english": "The mains are the main speakers that cover the whole crowd. The left main is the left half of that system. It plays the left channel and covers the left side of the crowd. It can be flown in the air or stacked on the ground.", "purpose_function": "It delivers the left channel and left-side coverage of the primary PA. Paired with the right main (and any center), it forms the full main system the audience hears.", "practical_application": "An engineer sets the left main's level, delay, and EQ to match the right main so the stereo image is centered, then adds fills for areas the mains cannot cover.", "category": "Main system", "related_terms": ["Left hang", "Left cluster", "Right main", "LCR system", "Main system", "Delay fill"], "common_mistakes": ["Running the left main louder than the right, pulling the whole mix image to the left", "Forgetting to time-align the mains, which smears the center image", "Assuming the mains alone cover everywhere and skipping needed front or delay fills"], "scenario_contexts": ["Setting up left and right mains for a stereo concert PA", "Balancing the left and right mains during soundcheck for a centered image", "Labeling amplifier and processor channels for the left main during patching"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"4d4c7ff4-d751-46a6-991f-ebe698ca64c8": {"definition": "A main loudspeaker system built from three parts: a left, a center, and a right system. The center reproduces centered content (typically lead vocals and mono material) fixed to the stage or screen, while left and right supply stereo width; it is the full-name form of an 'LCR system'.", "plain_english": "A left-center-right system uses three main speaker spots instead of two. The middle one keeps central sounds, like a lead voice, tied to the stage. The left and right speakers add stereo width. This spreads clear, well-placed sound across a wide crowd.", "purpose_function": "The center system holds central content in place for every seat across the room's width. Left and right then carry stereo width without also having to anchor the center image.", "practical_application": "A designer deploys three main systems and routes centered content to the center, panning the rest to left and right, with all three matched in level and aligned in time.", "category": "Main system format", "related_terms": ["LCR system", "LCR live", "Center cluster", "Left main", "Stereo imaging", "Phantom center"], "common_mistakes": ["Feeding the center nothing and effectively running the rig as plain left/right", "Not time-aligning the three systems, which causes combing in the overlap zones", "Sending stereo music to the center, which collapses the width it is meant to preserve"], "scenario_contexts": ["Specifying left, center, and right hangs for a large theatre or arena", "Keeping dialogue centered on stage for a musical so all seats hear it placed correctly", "A cinema or immersive install using discrete left, center, and right channels"]}, "ea58a464-85d6-4697-b631-b3ff1a1484af": {"definition": "A front-of-house loudspeaker configuration using two main systems, one on each side of the stage, that together cover the audience and reproduce a left/right stereo image. Each side is an array or point-source system aimed to cover the seating from its side, with panned content creating stereo width.", "plain_english": "A left-right PA uses two main speaker systems, one on each side of the stage. Together they cover the crowd and give a left-and-right stereo sound. It is the most common way to set up a concert PA.", "purpose_function": "It provides full-range coverage across the audience plus a stereo image, so panned instruments and effects spread naturally between the left and right sides.", "practical_application": "A system tech flies or stacks a matched system on each side, then aims, levels, and time-aligns both sides so they cover the room evenly and image correctly at center.", "category": "Loudspeaker Systems", "related_terms": ["Left-right system", "Line array", "Front fill", "Center cluster", "Main array", "Point source"], "common_mistakes": ["Assuming everyone hears true stereo, when only listeners near the center get a balanced left/right image and side seats hear mostly the nearer side.", "Panning critical elements such as the lead vocal hard left or right, so half the audience loses them; keep key content centered or mono.", "Forgetting front or lip fill, so the first rows between the two hangs get little coverage."], "scenario_contexts": ["A concert in a theatre or arena with a flown line array on each side of the stage.", "A corporate event using a stacked loudspeaker on each side of a presentation screen.", "A festival stage where left and right hangs cover a wide, deep audience."]}, "e2216c4e-6964-42cd-8e36-c111067525b4": {"definition": "A low-frequency deployment in which subwoofers are split into two groups, one flanking each side of the stage, typically under or beside the main left/right hangs. Because the two spaced sources sum differently at each listening position, this layout produces position-dependent comb filtering, including a low-frequency buildup down the center known as the power alley, and uneven bass coverage compared with a centered or gradient array.", "plain_english": "This setup puts the subwoofers in two groups, one on each side of the stage. Because the groups are far apart, their bass adds up unevenly across the crowd. A strong bass zone often forms down the middle while other spots get less.", "purpose_function": "It matches the subs to a left-right main system and is quick to deploy, but its main trade-off is uneven low-frequency coverage caused by the two spaced sources interacting.", "practical_application": "A system engineer may choose left-right subs for speed and simplicity, then measure the room and often switch to a centered, cardioid, or end-fire array when even bass coverage matters.", "category": "Loudspeaker Systems", "related_terms": ["Cardioid subwoofer array", "End-fire array", "Comb filtering", "Left-right PA (LR)", "Subwoofer alignment", "Power alley"], "common_mistakes": ["Expecting even bass everywhere, when spaced left/right subs comb so level and low-end tone change as listeners move across the room.", "Placing the left and right sub stacks far apart without realizing this strengthens the center power alley and side cancellations.", "Not measuring the low-frequency coverage, so uneven bass goes unnoticed until the show."], "scenario_contexts": ["A stereo main PA where subs are stacked under each side hang for a fast, simple setup.", "A smaller show where a centered or gradient sub array is not practical.", "Comparing sub deployments during system design to decide between left-right and directional arrays."]}, "41cb16c8-5a73-4615-99ce-b6d3072d1742": {"definition": "A main sound-reinforcement deployment that splits the full-range system into two matched sides, left and right of the stage, fed as a stereo or dual-mono pair. It is the default main-PA topology for music reinforcement, as distinct from a single center cluster or a distributed system.", "plain_english": "A left-right system splits the main sound system into two matched sides. One side sits left of the stage and one sits right. It is the standard way to set up sound for live music.", "purpose_function": "It delivers full-range audience coverage plus a left/right stereo image and frames the stage visually, which is why it is the most common main-PA layout.", "practical_application": "An engineer deploys matched left and right systems, aligns them to each other and to any subs and fills, and mixes with stereo or mono content as the room dictates.", "category": "Loudspeaker Systems", "related_terms": ["Left-right PA (LR)", "Center cluster", "Line array", "Front fill", "Distributed system", "Mono system"], "common_mistakes": ["Treating a left-right system as if every seat hears stereo, when only central listeners do.", "Mixing important content in hard stereo, so side and off-center seats miss it.", "Skipping alignment between the two sides, which smears the center image and blurs clarity."], "scenario_contexts": ["Setting up mains for a live band in a club, theatre, or arena.", "Deciding between a left-right layout and a center cluster for speech intelligibility.", "Designing a stereo playback system for a corporate or theatrical show."]}, "04366766-7fba-463b-b6ab-8c91c12ea2ef": {"definition": "The attack time of a limiter is the interval it takes to apply gain reduction after the signal exceeds the threshold. Short attack times clamp fast transients quickly but can dull them and add distortion; longer attack times sound more transparent but let more of the peak pass.", "plain_english": "Attack is how fast a limiter reacts once a sound crosses its set level. A fast attack grabs loud peaks almost instantly. A slower attack lets a bit of the peak through but sounds more natural.", "purpose_function": "It sets how tightly the limiter catches peaks, balancing peak control against transient punch and audible artifacts.", "practical_application": "An engineer sets a fast attack on a peak limiter protecting drivers, and a slower attack on a bus limiter to keep transients lively.", "category": "Dynamics Processing", "related_terms": ["Limiter Release", "Limiter Threshold", "Limiter Overshoot", "Look-ahead", "Peak limiter", "Gain reduction"], "common_mistakes": ["Setting attack too slow on a protection limiter, letting peaks through that can damage drivers or clip converters.", "Using an extremely fast attack on program material, which flattens transients and dulls the mix.", "Confusing attack time with threshold; attack is a speed, threshold is a level."], "scenario_contexts": ["Tuning a loudspeaker protection limiter to catch fast transients.", "Setting a mastering or bus limiter for transparent peak control.", "Adjusting an input limiter on a recorder to catch sudden loud sounds."]}, "25207315-e149-40d3-9c88-ca4a5509a650": {"definition": "Overshoot is the amount by which a limiter's output momentarily exceeds its intended threshold or ceiling before gain reduction fully takes effect, caused by finite attack time and detector delay. Look-ahead and peak-accurate detection reduce or eliminate overshoot so the true peak stays at or below the set ceiling.", "plain_english": "Overshoot is when a bit of a loud peak slips past a limiter before it clamps down. It happens because the limiter cannot react in zero time. A look-ahead feature helps stop this by reacting slightly early.", "purpose_function": "Understanding overshoot matters because leftover peaks can clip the next device or overdrive a driver, so engineers choose limiters and settings that minimize it.", "practical_application": "An engineer picks a look-ahead or true-peak limiter, or leaves a little headroom, so overshoot does not clip converters or overdrive amplifiers.", "category": "Dynamics Processing", "related_terms": ["Limiter Attack", "Look-ahead", "True peak", "Limiter Threshold", "Brickwall limiter", "Clipping"], "common_mistakes": ["Assuming any limiter guarantees output stays below the ceiling; without look-ahead, fast peaks overshoot.", "Setting the ceiling at 0 dBFS with a non-true-peak limiter, so overshoot and inter-sample peaks cause downstream clipping.", "Blaming overshoot on the threshold rather than on the limiter's attack and detection design."], "scenario_contexts": ["Mastering to a true-peak ceiling for streaming loudness standards.", "Protecting an amplifier or converter where any peak above the ceiling risks clipping.", "Comparing limiter algorithms for how well they hold the set output ceiling."]}, "dd68815e-238f-4bf4-bcc6-e6478916c6c5": {"definition": "The release time of a limiter is the interval over which it returns gain toward unity after the signal falls back below the threshold. Short release times recover quickly but can cause audible pumping or low-frequency distortion; long release times sound smoother but hold gain reduction longer, reducing loudness.", "plain_english": "Release is how fast a limiter lets go after a loud sound passes. A fast release brings the volume back quickly but can sound pumpy. A slow release sounds smoother but stays quiet a bit longer.", "purpose_function": "It controls how the limiter recovers, trading recovery speed against smoothness, loudness, and distortion.", "practical_application": "An engineer lengthens release to reduce pumping on a bass-heavy mix, or shortens it to push loudness on a limiter.", "category": "Dynamics Processing", "related_terms": ["Limiter Attack", "Limiter Threshold", "Limiter Overshoot", "Pumping", "Auto-release", "Gain reduction"], "common_mistakes": ["Setting release too fast on low-frequency content, which causes distortion and audible pumping.", "Setting release so slow that the limiter stays clamped and ducks later, quieter material.", "Confusing release with the threshold; release is a time, not a level."], "scenario_contexts": ["Tuning a mix-bus or mastering limiter to avoid pumping.", "Setting a loudspeaker protection limiter's recovery so levels return naturally.", "Adjusting a broadcast limiter for consistent perceived loudness."]}, "6ead41ae-27f0-47ef-8b64-b086e346ff36": {"definition": "The threshold of a limiter is the input level at or above which the limiter begins to reduce gain, holding output near a set ceiling while signal below the threshold passes unaffected. Because a limiter uses a very high (often infinite) ratio, level above threshold is prevented from rising further at the output.", "plain_english": "The threshold is the level where the limiter switches on. Sounds quieter than the threshold pass through untouched. Sounds louder than it get turned down so they cannot go over the set limit.", "purpose_function": "It sets the point where limiting starts, defining the maximum level the system allows and protecting downstream gear or drivers from overload.", "practical_application": "A system tech sets the threshold to the maximum safe level for the amplifiers and loudspeakers, so the PA cannot be driven past it.", "category": "Dynamics Processing", "related_terms": ["Limiter Attack", "Limiter Release", "Ratio", "Ceiling", "Gain reduction", "System limiter"], "common_mistakes": ["UNSAFE: Raising a loudspeaker protection limiter's threshold above the manufacturer's rating to get more level, which can overheat and destroy drivers and expose people nearby to unsafe sound levels.", "Setting the threshold so low that the limiter works constantly, squashing the dynamics.", "Confusing the threshold with output or makeup gain; the threshold is where limiting begins."], "scenario_contexts": ["Setting system limiter thresholds during PA tuning to protect amplifiers and drivers.", "Configuring a mastering limiter's threshold for a target loudness.", "Protecting an input stage by setting a limiter threshold below the clipping point."]}, "eb3bb0bf-57d3-4cdc-8298-e3edf38ad6ec": {"definition": "A line source is a sound source formed by a continuous or closely spaced line of radiating elements that behaves as a single coherent source over its length, producing a cylindrical rather than spherical wavefront in its near field. Within that cylindrical region level falls roughly 3 dB per doubling of distance, versus about 6 dB for a point source; in the far field a finite line source reverts to point-source behavior.", "plain_english": "A line source is a tall, tight column of speakers that acts like one long source. It sends sound out in a cylinder shape instead of a ball. Up close, its level drops off more slowly with distance than a single box.", "purpose_function": "Its slower level loss and controlled vertical pattern let a line source throw sound evenly from the front to the back of a large audience, which is the principle line arrays use.", "practical_application": "A system designer curves and splays a line array so its coupled elements act as a line source, delivering consistent level and tone across a deep audience.", "category": "Loudspeaker Systems", "related_terms": ["Line array", "Point source", "Cylindrical wavefront", "Coupling", "Coverage angle", "Near field"], "common_mistakes": ["Assuming line-source behavior at all frequencies and distances, when it only holds in the near field and where element spacing is small relative to wavelength.", "Believing a line source never loses level; it still attenuates, just more slowly in the near field.", "Confusing a line source with any vertical stack, when the elements must couple coherently to act as a line."], "scenario_contexts": ["Designing a flown line array for even coverage in a large venue.", "Explaining why line arrays throw farther than point-source boxes.", "Comparing near-field cylindrical and far-field spherical behavior when predicting coverage."]}, "f94580ac-840f-4049-a517-2cfb3ed27ea0": {"definition": "Lip fill is a form of front fill using small loudspeakers placed along the front edge, or lip, of the stage to cover the first audience rows that fall below and between the main left/right systems. The fills are level-matched and usually time-aligned to the mains so near-front seats receive intelligible, well-localized sound.", "plain_english": "Lip fill speakers sit along the front edge of the stage. They cover the first few rows that the big main speakers shoot over. This gives people at the front clear sound instead of a thin or muffled mix.", "purpose_function": "It fills the coverage gap directly in front of the stage where the main hangs cannot reach, giving front-row listeners full, localized sound.", "practical_application": "A system tech spaces small full-range boxes along the stage lip, levels them to the mains, and delays them so the front rows still hear the stage.", "category": "Loudspeaker Systems", "related_terms": ["Front fill", "Rear fill", "Delay speaker", "Main array", "Coverage angle", "Time alignment"], "common_mistakes": ["Running lip fills too loud, so the front rows hear the fills instead of the stage image.", "Not delaying lip fills to the mains, which smears localization for the front seats.", "Skipping lip fill entirely, leaving the first rows in a coverage hole below the main arrays."], "scenario_contexts": ["Covering the front rows at a concert where the flown mains shoot over them.", "A theatre or corporate stage with seating right up against the stage lip.", "Filling the gap between the left/right hangs for the audience directly in front of center stage."]}, "85e48569-4305-4ccd-9679-02d7ee75035b": {"definition": "Small loudspeakers placed along the front edge, or lip, of a stage to cover the closest rows of the audience, which sit below and inside the main system's aim. A form of front fill, they restore level and vocal intelligibility for listeners too near the stage for the mains or delays to reach evenly.", "plain_english": "Small speakers set at the front edge of the stage. They give clear sound to people in the first few rows. Those seats sit too close for the big speakers to cover well.", "purpose_function": "They fill the coverage gap right in front of the stage, where the main loudspeakers shoot over the nearest listeners, keeping level and clarity for the front rows.", "practical_application": "A technician sets and aims lip fills along the stage edge, then adjusts their level and delay so front-row sound matches the mains without drawing attention to the fill boxes.", "category": "Fill Loudspeakers", "related_terms": ["Front fill", "Delay loudspeaker", "Main loudspeaker", "Coverage", "Loudspeaker Directivity"], "common_mistakes": ["Setting lip fills too loud, which pulls the sound image down to the stage floor instead of the performers.", "Skipping delay alignment, so front-row listeners hear an echo between the fill and the mains.", "Aiming lip fills up into the stage microphones and causing feedback."], "scenario_contexts": ["Covering the first rows in a theatre where the flown mains shoot over the closest seats.", "A corporate stage where the front row sits right against the stage lip.", "A worship stage needing clear vocals for the nearest part of the congregation."]}, "b46c2381-30e1-4127-bdc2-9ae60665954d": {"definition": "The vertical height above the floor of the audience's ears, used as the reference plane for aiming loudspeakers and for taking design predictions and measurements. Common references approximate seated ear height or standing ear height, chosen to match how the audience will experience the event.", "plain_english": "The height of the audience's ears above the floor. Designers aim the speakers and take test readings at this height. It is not measured at the top of the head or at the ground.", "purpose_function": "It defines where sound must actually arrive, so coverage, aiming, and measurements target the ears of listeners rather than the floor or ceiling.", "practical_application": "A technician sets the measurement microphone at listening height and checks predicted coverage on the same plane, so tuning reflects what the audience really hears.", "category": "System Design", "related_terms": ["Coverage", "Listening test", "Long throw", "Loudspeaker Directivity", "Delay loudspeaker"], "common_mistakes": ["Measuring at the floor or at chest height instead of ear height, giving misleading results.", "Forgetting that a standing audience raises listening height compared with a seated one.", "Aiming speakers at the top of heads or the back wall rather than at ear level."], "scenario_contexts": ["Setting microphone height for system tuning in an empty room before doors open.", "Predicting coverage in design software for a seated theatre audience.", "Deciding speaker tilt for a standing general-admission crowd."]}, "5a5e92d3-6f14-41ce-847f-e8b1530ff096": {"definition": "A controlled subjective evaluation in which listeners judge the sound quality, differences, or preferences of audio equipment, recordings, or system tunings. Formal versions use methods such as blind or double-blind comparison and standardized rating scales to reduce bias.", "plain_english": "A test where people listen closely and rate how something sounds. It catches quality issues that meters alone can miss, and often hides which option is playing.", "purpose_function": "It captures how sound is actually perceived, complementing objective measurements that cannot fully predict human judgments of quality or preference.", "practical_application": "A technician runs a listening test to compare two system tunings, speaker models, or codec settings, ideally hiding which is which to keep the judgment fair.", "category": "System Verification", "related_terms": ["Listening height", "Loudspeaker Directivity", "Frequency response", "Reference monitor", "A/B comparison"], "common_mistakes": ["Letting listeners see which option is playing, so expectation bias skews the result.", "Comparing options at different loudness, since the louder one usually seems better.", "Judging from a single seat instead of several positions across the coverage area."], "scenario_contexts": ["A blind A/B comparison of two loudspeaker models before a purchase.", "Checking a new system tuning against the old one during commissioning.", "Evaluating audio codec quality in a broadcast or streaming chain."]}, "353bb992-cf03-4554-b6c9-b3a4ce9f5cdd": {"definition": "A loudspeaker installed in a venue's lobby, foyer, or similar public circulation area to distribute background music, a program feed of the event, and paging or announcements to patrons outside the main auditorium. Such units are usually part of a distributed, constant-voltage (70/100 V) system driving many low-level speakers from shared amplifier lines.", "plain_english": "A speaker in the lobby or entrance area of a venue. It plays background music, announcements, or a feed of the show. This is for people who are not yet in the main room.", "purpose_function": "It extends audio into public areas so patrons hear paging, announcements, and program material while in the lobby, restrooms, or corridors.", "practical_application": "A technician wires lobby speakers onto a 70- or 100-volt distributed line, sets each transformer tap for even background level, and routes paging or a show feed to them.", "category": "Distributed Systems", "related_terms": ["Distributed system", "Constant-voltage system", "Paging", "Program feed", "Ceiling loudspeaker"], "common_mistakes": ["Connecting a low-impedance speaker straight onto a 70/100 V line without its matching transformer, which overloads and can damage the amplifier.", "Setting lobby level so high it competes with the auditorium or disturbs staff.", "Forgetting to route paging or emergency announcements to lobby zones."], "scenario_contexts": ["Playing background music and paging in a theatre lobby before doors open.", "Feeding a live mix of the show to foyer speakers for latecomers.", "Announcing show-starting calls to patrons in the concourse."]}, "e4b2f6b9-875b-414c-99a7-de3fcea51aae": {"definition": "A loudspeaker installed in a venue's lobby, foyer, or similar public circulation area to distribute background music, a program feed of the event, and paging or announcements to patrons outside the main auditorium. Such units are usually part of a distributed, constant-voltage (70/100 V) system driving many low-level speakers from shared amplifier lines.", "plain_english": "A speaker in the lobby or entrance area of a venue. It plays background music, announcements, or a feed of the show. This is for people who are not yet in the main room.", "purpose_function": "It extends audio into public areas so patrons hear paging, announcements, and program material while in the lobby, restrooms, or corridors.", "practical_application": "A technician wires lobby speakers onto a 70- or 100-volt distributed line, sets each transformer tap for even background level, and routes paging or a show feed to them.", "category": "Distributed Systems", "related_terms": ["Distributed system", "Constant-voltage system", "Paging", "Program feed", "Ceiling loudspeaker"], "common_mistakes": ["Connecting a low-impedance speaker straight onto a 70/100 V line without its matching transformer, which overloads and can damage the amplifier.", "Setting lobby level so high it competes with the auditorium or disturbs staff.", "Forgetting to route paging or emergency announcements to lobby zones."], "scenario_contexts": ["Playing background music and paging in a theatre lobby before doors open.", "Feeding a live mix of the show to foyer speakers for latecomers.", "Announcing show-starting calls to patrons in the concourse."]}, "be6689fb-7a74-4b3c-b3b6-da27cf045f60": {"definition": "A loudspeaker or array configuration designed to project sound efficiently over a long distance to reach distant listeners. Long-throw systems rely on high directivity, especially narrow vertical coverage, to maintain sound-pressure level and clarity at range while limiting wasted energy onto nearer surfaces.", "plain_english": "A speaker set up to send sound far across a big space. It uses a tight, focused beam so people at the back still hear it clearly and loudly.", "purpose_function": "It delivers enough level and intelligibility to the farthest seats, which lose sound level over distance, without over-powering the closer areas.", "practical_application": "A technician assigns long-throw boxes, often the top cabinets of a line array, to cover the deep and rear seating, pairing them with short-throw fills for the near field.", "category": "Loudspeaker Deployment", "related_terms": ["Short throw", "Line array", "Loudspeaker Directivity", "Delay loudspeaker", "Coverage"], "common_mistakes": ["Confusing more power with more throw; directivity, not just wattage, controls reach.", "Using a wide-dispersion box for a long throw, wasting energy on walls and reverberation.", "Forgetting that level still falls with distance, so far seats may still need delay speakers."], "scenario_contexts": ["Covering the upper deck of an arena from a flown main array.", "Reaching the back lawn of an outdoor amphitheatre.", "Aiming the top cabinets of a line array at the farthest seating."]}, "0bc4e148-4f29-4296-b2c3-7a0c31701a7c": {"definition": "The degree to which a loudspeaker concentrates its radiated sound energy in a particular direction rather than spreading it uniformly. It is quantified by the directivity factor (Q) and the directivity index (DI, in dB, equal to 10 log Q), both of which vary with frequency.", "plain_english": "How much a speaker aims its sound one way instead of spreading it all around. A tight beam like a flashlight is focused; a bare bulb spilling light everywhere is not.", "purpose_function": "It determines where a speaker's sound goes, letting designers cover the audience while keeping energy off walls, ceilings, and stages to control reflections and feedback.", "practical_application": "A technician reads a speaker's directivity, as Q or coverage angle, from its data to choose and aim boxes so sound lands on people, not on reflective surfaces.", "category": "Loudspeaker Behavior", "related_terms": ["Directivity index", "Coverage angle", "Long throw", "Constant directivity", "Beamwidth"], "common_mistakes": ["Assuming coverage angle is the same at every frequency; directivity changes with frequency.", "Treating the rated coverage angle as a hard edge rather than a gradual level drop-off.", "Ignoring directivity when placing speakers, which causes reflections, poor clarity, or feedback."], "scenario_contexts": ["Choosing a horn coverage pattern to match an audience area.", "Comparing directivity plots when selecting loudspeakers for a room.", "Aiming speakers to avoid reflective walls in a reverberant hall."]}, "56856e45-9297-4fc5-b824-5073a3c25347": {"definition": "An equalization filter that boosts or cuts the level of all frequencies below a set corner (turnover) frequency by a fixed amount, while leaving frequencies above it largely unchanged. Its response forms a shelf: it transitions around the corner frequency and then flattens at the chosen gain across the low end.", "plain_english": "An EQ tool that turns everything below a chosen frequency up or down together. It works like a volume knob just for the low end, leaving the higher notes alone.", "purpose_function": "It shapes the low-frequency balance of a signal, adding or reducing overall bass weight without the narrow, surgical effect of a peaking (bell) filter.", "practical_application": "A technician uses a low-shelf to add warmth or tame boominess on a channel or system output, setting the corner frequency and the amount of boost or cut.", "category": "Equalization", "related_terms": ["High-shelf filter", "Peaking filter", "High-pass filter", "Parametric EQ", "Corner frequency"], "common_mistakes": ["Confusing a low-shelf with a high-pass filter; a shelf levels off, while a high-pass keeps rolling off.", "Applying a large low-shelf boost that overloads amplifiers or subwoofer drivers.", "Setting the corner frequency too high, so the shelf affects the midrange as well as the bass."], "scenario_contexts": ["Adding low-end warmth to a thin vocal or acoustic guitar.", "Reducing overall bass buildup in a boomy room during system tuning.", "Gently shaping the bottom octaves on a mix bus."]}, "01ffbb3f-3b07-4abb-a5d6-d690f26dc9d8": {"definition": "The primary loudspeaker array that provides the principal sound coverage for the main audience area of a sound reinforcement system, typically a vertical line array or point-source cluster deployed as flown or ground-stacked left/right groups. It is distinguished from supplementary fill, delay, and subwoofer subsystems.", "plain_english": "This is the main group of speakers that covers most of the crowd. It is usually a tall stack of boxes, hung or stacked at each side of the stage. Smaller fill speakers cover the spots it cannot reach.", "purpose_function": "It delivers the bulk of the sound energy evenly across the main listening area, forming the backbone of the PA that other subsystems only supplement.", "practical_application": "A system tech flies or stacks the main array left and right, then sets its splay angles and level so it covers the seating without gaps.", "category": "Loudspeaker Deployment", "related_terms": ["Main system", "Line array", "Main left and right", "Fill loudspeaker", "Delay loudspeaker", "Subwoofer array"], "common_mistakes": ["Assuming the main array alone can cover the whole venue, when front-fill and delay speakers are needed for near and far zones.", "Aiming the array too high or too low, so energy hits walls or the floor instead of the audience.", "Confusing the main array (the physical group of boxes) with the main mix that feeds it."], "scenario_contexts": ["Flying left and right line-array hangs for an outdoor festival main stage.", "Ground-stacking a main array on subwoofers in a venue with no rigging points."]}, "6483e467-3d1f-4e49-a8ea-7cc2e97786ce": {"definition": "The primary audio signal path carrying the main mix from a mixing console's main (master) output bus to the main loudspeaker system, usually the left/right (and center) program feed that drives the mains through system processing and amplification.", "plain_english": "This is the main sound signal sent from the mixing desk to the main speakers. It carries the finished mix the audience hears. Think of it as the master output going out to the PA.", "purpose_function": "It routes the completed program mix to the main system so the audience hears the intended balance, keeping the primary output separate from monitor and auxiliary feeds.", "practical_application": "An engineer patches the console's main L/R output through system processing to the amplifiers, then checks the main feed before doors open.", "category": "Signal Distribution", "related_terms": ["Main system", "Main output bus", "Matrix-fed system", "System processor", "Main left and right"], "common_mistakes": ["Confusing the main feed (the signal) with the main hangs (the physical speakers).", "Sending the main feed straight to amplifiers without system processing, tuning, or limiting.", "Forgetting to assign or unmute channels to the main bus, so the main feed carries nothing."], "scenario_contexts": ["Sending the console main L/R feed to a drive rack that distributes signal to the PA.", "Providing a main feed to a broadcast truck or recording rig as a split of the house mix."]}, "05fac0a9-2d29-421e-acb9-b97e67986a1a": {"definition": "The flown (suspended) primary loudspeaker arrays of a sound system, rigged overhead—typically the left and right line-array hangs—supported from a certified fly frame (bumper) via chain hoists or rated steel from approved overhead points. They provide the main audience coverage and must be rigged, load-verified, and inspected to entertainment-rigging safety standards.", "plain_english": "These are the main speaker stacks hung in the air above each side of the stage. Special metal frames and motorized chain hoists lift them safely. Only trained riggers should fly them, and each hang needs a separate backup safety line.", "purpose_function": "Flying the mains lifts the main coverage above the crowd for clearer sightlines and more even coverage than ground stacking, while transferring the load safely into rated overhead structure.", "practical_application": "A rigger attaches the fly frame to a chain hoist, builds the array, fits an independent secondary safety, and verifies the load with array prediction software before lifting.", "category": "Flown Array Rigging", "related_terms": ["Main array", "Fly frame (bumper)", "Chain hoist", "Secondary safety", "Working load limit", "Ground stack"], "common_mistakes": ["UNSAFE: Flying a main hang without an independent secondary safety rated to hold the full array weight.", "UNSAFE: Exceeding the working load limit of the fly frame, hoist, or rigging points, or skipping load calculation for heavy arrays.", "UNSAFE: Rigging overhead mains without a qualified rigger, or without inspecting shackles, pins, slings, and hoists before every use.", "UNSAFE: Using inter-cabinet splay angles outside the manufacturer's certified rigging limits, which can overstress the array frame."], "scenario_contexts": ["Flying left/right main hangs from motorized chain hoists on a festival roof structure.", "Suspending main arrays from certified building steel in an arena using rated slings and shackles."]}, "f18ad181-42f0-4832-a255-182e94be8d20": {"definition": "The two primary loudspeaker systems positioned to the left and right of the stage, forming the principal stereo (or matched dual-mono) main coverage of a sound reinforcement system; commonly abbreviated main L/R.", "plain_english": "These are the main speakers set up on the left and right of the stage. Together they cover the audience and create a left-right stereo image. Most concert PAs use this two-sided layout.", "purpose_function": "Splitting the mains into left and right provides stereo imaging and wide, balanced coverage of the audience from two spaced positions.", "practical_application": "A tech deploys matched left and right hangs, time-aligns them, and balances their levels so coverage and imaging are even across the seats.", "category": "Loudspeaker Deployment", "related_terms": ["Main array", "Main system", "Stereo imaging", "Center cluster", "Fill loudspeaker"], "common_mistakes": ["Expecting true stereo imaging everywhere, when only listeners near the center hear a balanced image.", "Mismatching left and right in level, delay, or EQ, which pulls the image to one side.", "Relying on main L/R alone in wide rooms without out-fill or delay speakers for the edges."], "scenario_contexts": ["Setting up left/right line-array hangs for a stereo music concert.", "Balancing main L/R levels so mono content stays centered for most of the audience."]}, "6aa57577-f0f6-4654-b3bb-3b362e4a5b84": {"definition": "A loudspeaker that provides the principal sound coverage for the main listening area, as distinct from monitor, fill, delay, or subwoofer loudspeakers; the primary program transducer of a sound reinforcement or playback system.", "plain_english": "This is a speaker that does the main job of covering the audience. It is not a monitor, a small fill, or a sub. It plays the primary mix the listeners are meant to hear.", "purpose_function": "It reproduces the main program signal for the audience, serving as the core sound source that other loudspeakers only support or extend.", "practical_application": "A technician chooses a main loudspeaker rated for the room's size and coverage needs, then places or flies it to cover the primary listening area.", "category": "Loudspeaker Deployment", "related_terms": ["Main loudspeaker system", "Main array", "Fill loudspeaker", "Stage monitor", "Subwoofer"], "common_mistakes": ["Confusing a main loudspeaker with a stage monitor, which faces the performers, not the audience.", "Choosing a main loudspeaker whose coverage pattern does not match the room shape.", "Assuming one main loudspeaker per side covers everyone, ignoring fills for near and far zones."], "scenario_contexts": ["Selecting a full-range main loudspeaker as the primary box for a small club PA.", "Distinguishing the main loudspeakers from monitors when patching and tuning a system."]}, "173da1ca-26b4-4dd4-81d7-dc43d55b65a2": {"definition": "The complete primary loudspeaker subsystem of a sound reinforcement installation—its main loudspeakers together with their amplification, processing, and rigging—that delivers principal coverage to the main audience area, exclusive of fill, delay, effects, and monitor subsystems.", "plain_english": "This is the whole main speaker setup for the audience. It includes the main speakers plus their amps, processing, and rigging. It does the main covering job, while fills and delays just help out.", "purpose_function": "It groups the main loudspeakers and their support gear into one primary coverage system, so it can be designed, tuned, and operated as the core of the PA.", "practical_application": "A system engineer designs the main loudspeaker system for the required coverage and level, then tunes it as a unit before adding fills and delays.", "category": "Loudspeaker Deployment", "related_terms": ["Main loudspeaker", "Main array", "Main system", "System processor", "Fill loudspeaker"], "common_mistakes": ["Treating the main loudspeaker system as just the boxes, forgetting the amps and processing it depends on.", "Tuning the mains after fills and subs, instead of first establishing the main system as the reference.", "Under-sizing the main system so it cannot reach the required level without distortion."], "scenario_contexts": ["Specifying the main loudspeaker system for a theatre based on coverage and headroom targets.", "Commissioning and tuning the main loudspeaker system as the reference before integrating subsystems."]}, "d1b580c8-5d13-41f7-8984-2054c98f9976": {"definition": "The primary sound reinforcement system that provides coverage to the majority of the audience, comprising the main loudspeakers (and often subwoofers) with their processing and amplification; it serves as the reference system to which fill, delay, and effect subsystems are aligned.", "plain_english": "This is the primary sound system that covers most of the crowd. It is the main speakers, and often the subs, working together. Other smaller systems are then set to match it.", "purpose_function": "It carries the main coverage load and acts as the tuning reference, so all other subsystems are timed and leveled to blend with it.", "practical_application": "An engineer tunes the main system first, then time-aligns delays and fills to it so the whole PA sounds like one source.", "category": "Loudspeaker Deployment", "related_terms": ["Main loudspeaker system", "Main array", "Subsystem", "Delay loudspeaker", "System alignment"], "common_mistakes": ["Aligning fills and delays to each other instead of to the main system.", "Confusing the main system (the whole primary rig) with a single main loudspeaker.", "Letting subwoofer timing drift out of alignment with the main system."], "scenario_contexts": ["Establishing the main system as the alignment reference during system tuning.", "Deciding whether subwoofers are counted as part of the main system for a given design."]}, "1249c52b-4045-47a8-bec0-7da355cc068b": {"definition": "A loudspeaker subsystem—commonly a delay, fill, zone, or press/broadcast feed—that is driven from a mixing console's matrix output rather than directly from the main mix bus, allowing its level, EQ, and mix content to be tailored independently of the mains.", "plain_english": "This is a set of speakers fed from a mixing desk's matrix output. A matrix lets you build a custom mix for that area. So a lobby or balcony can get its own level and sound.", "purpose_function": "Feeding a system from a matrix lets the engineer send a dedicated, independently adjustable mix to a zone or fill without disturbing the main mix.", "practical_application": "An engineer routes a delay tower or lobby feed from a console matrix, then adjusts that matrix's level and EQ for its zone alone.", "category": "Signal Distribution", "related_terms": ["Matrix (console)", "Main feed", "Delay loudspeaker", "Zone", "Auxiliary bus"], "common_mistakes": ["Confusing a matrix output with an aux send; a matrix mixes existing buses or groups, not raw input channels.", "Forgetting that a matrix-fed zone will not follow main-bus changes unless it is sourced from the mains.", "Leaving a matrix-fed delay or fill without its own delay time and EQ, so it does not align with the mains."], "scenario_contexts": ["Feeding balcony delays and under-balcony fills from separate console matrices.", "Providing a matrix-fed press or broadcast mix distinct from the house main feed."]}, "8aba2f7a-1f53-4493-917b-a493d67464ab": {"definition": "Directing a loudspeaker's coverage by physically orienting the cabinet—setting its tilt, splay (inter-cabinet) angles, height, and horizontal rotation using rigging or mounting hardware—rather than steering coverage electronically with DSP. In line arrays it sets the array's overall site angle and the splay between enclosures to shape vertical coverage.", "plain_english": "This means pointing speakers at the crowd by physically tilting and angling the boxes. You set the hang angle and the gaps between cabinets with rigging hardware. It shapes where the sound lands without any digital steering.", "purpose_function": "Mechanical aiming shapes and directs coverage to match the audience geometry, placing energy where listeners are and keeping it off walls, ceilings, and empty seats.", "practical_application": "Using array prediction software, a tech sets the fly-frame site angle and each inter-cabinet splay, then pins those angles before the array is flown.", "category": "Array Aiming", "related_terms": ["Splay angle", "Site angle", "Main array", "Fly frame (bumper)", "Beam steering", "Coverage pattern"], "common_mistakes": ["Setting splay angles by eye instead of using manufacturer prediction software, causing coverage gaps or overlap.", "Confusing mechanical aiming with electronic beam steering, which shapes coverage with DSP, not hardware.", "UNSAFE: Using inter-cabinet or frame angle combinations outside the manufacturer's certified rigging limits, which can overstress the array frame."], "scenario_contexts": ["Setting line-array splay angles and site angle in prediction software before a show.", "Tilting and rotating a point-source cabinet on a yoke to cover a balcony."]}, "39f94e7a-709b-4d91-933c-28790410419f": {"definition": "A public-address (PA) system that reproduces a single audio channel, feeding the same summed signal to all loudspeakers regardless of their position. Every listener hears identical program content with no left-right stereo image, keeping coverage and tonal balance consistent across the audience area.", "plain_english": "A mono PA sends one channel of sound to every speaker. So everyone hears the same mix, no matter where they sit. There is no left or right split like in stereo. This keeps the sound even for the whole crowd.", "purpose_function": "It delivers consistent level and content to every seat, because stereo imaging collapses for listeners who sit off to one side. Mono also simplifies system tuning, gain structure, and cabling in speech and live-sound reinforcement.", "practical_application": "A technician routes a single mix bus to all zones for conferences, houses of worship, and many concerts, so intelligibility stays even across a wide audience.", "category": "System configuration", "related_terms": ["Mono system", "Stereo PA", "Center cluster", "Point source", "Distributed system", "Coverage"], "common_mistakes": ["Assuming mono sounds worse than stereo, when mono often gives more even coverage across a wide audience", "Panning source channels hard left or right, which is pointless in a summed mono feed", "Confusing a mono PA with a single loudspeaker; a mono system can use many speakers fed one channel", "Forgetting that stereo content folded to mono can cause phase cancellation between the two sides"], "scenario_contexts": ["Reinforcing speech at a conference where every seat needs the same clarity", "Covering a wide festival field where stereo imaging would fail for most of the crowd", "A house of worship feeding one mix to left and right arrays plus front fills"]}, "fe03611c-d240-45ee-8800-6d73fc80ba3a": {"definition": "An audio system that carries and reproduces one channel of program audio, summing all sources into a single signal path fed to the loudspeakers. It contrasts with stereo or multichannel systems and presents no spatial left-right image to the listener.", "plain_english": "A mono system uses just one channel of sound. All the sources are mixed into that single channel. Every speaker then plays the same thing. There is no left and right separation.", "purpose_function": "It gives uniform sound to all listeners and avoids the off-center imaging problems stereo causes in large or wide spaces. It also reduces channel count, cabling, and tuning complexity.", "practical_application": "Technicians deploy mono systems for paging, speech, and many live events where even coverage matters more than a stereo image.", "category": "System configuration", "related_terms": ["Mono PA", "Stereo system", "Summing", "Point source", "Distributed system", "Phase"], "common_mistakes": ["Believing mono is outdated, when it remains standard for speech and wide-audience reinforcement", "Summing stereo tracks to mono without checking for phase cancellation between channels", "Confusing 'mono' (one channel) with 'one loudspeaker'", "Panning within a mix that will collapse to mono, losing the intended balance"], "scenario_contexts": ["A paging system spread across a transit terminal", "Live band reinforcement in a wide venue that prioritizes even coverage", "Folding a stereo playback source into a single house feed"]}, "2fd4ceb7-982e-4e62-94a6-5490d8ccabe7": {"definition": "A stored, recallable set of processing parameters (EQ, crossover, limiter, delay, and level) configured to optimize a sound system for music program material, as distinct from speech or emergency presets. It is loaded into loudspeaker processors, amplifier DSP, or the system controller to establish the intended voicing for music playback.", "plain_english": "This is a saved setup that tunes a sound system for playing music. It sets things like tone, volume limits, and speaker protection. A tech can recall it with one button. Other saved setups may be tuned for speech instead.", "purpose_function": "It lets an installed or touring system switch quickly to a voicing suited to music, with the correct EQ and speaker protection, without retuning by hand. This keeps results repeatable, safe for the drivers, and consistent between events.", "practical_application": "In a multipurpose venue a technician recalls the 'Music' preset for a band and a 'Speech' preset for announcements, changing the whole system's voicing instantly.", "category": "System configuration", "related_terms": ["Loudspeaker preset", "Speech preset", "System DSP", "Crossover", "Limiter", "Scene recall"], "common_mistakes": ["Loading a music preset made for a different loudspeaker model, which can remove the correct protection limits", "UNSAFE: Editing or bypassing a factory preset's limiter to chase more level, risking driver burnout or amplifier damage", "Assuming one music preset fits every room without checking room tuning and gain structure", "Forgetting to save edits, so a recalled preset reverts to old settings"], "scenario_contexts": ["A multipurpose hall switching between music and speech modes", "Recalling a manufacturer loudspeaker preset in amplifier DSP during system setup", "Storing a house music voicing for consistent playback between acts"]}, "cb82ab1c-65d0-41fc-8f21-be94cf1fc3ee": {"definition": "The region close to a sound source where the pressure and particle-velocity components are not fully in phase and the level does not yet decrease at the steady inverse-square rate of about 6 dB per doubling of distance. Its extent depends on the source size and the wavelength; beyond it lies the far field, where sound behaves as a diverging wave with predictable falloff.", "plain_english": "The near field is the zone right next to a speaker or instrument. In this zone the sound is uneven and does not drop off in a simple way. Move a little and the level can jump around. Farther away, in the far field, sound fades steadily as you back off.", "purpose_function": "Knowing where the near field ends tells a technician where measurements and listening become reliable, because level and response vary sharply close to the source. It marks where far-field rules of steady falloff and stable response begin to apply.", "practical_application": "A technician avoids taking coverage or SPL measurements in a source's near field and instead measures far enough away that response and level readings stay stable and repeatable.", "category": "Acoustics", "related_terms": ["Far field", "Inverse-square law", "Nearfield monitor", "Critical distance", "Direct sound", "Wavefront"], "common_mistakes": ["Confusing the acoustic near field with 'nearfield monitors', which are studio speakers meant for close listening", "Measuring SPL or frequency response inside the near field, where readings are unstable and misleading", "Assuming the inverse-square law (about 6 dB loss per distance doubling) holds close to the source", "Thinking the near field is a fixed distance, when it depends on source size and frequency"], "scenario_contexts": ["Choosing a measurement-microphone distance when tuning a loudspeaker", "Explaining why level changes are uneven very close to a line array", "Setting up close-listening studio monitors to reduce room reflections"]}, "c8201239-95c5-4e21-85b5-83a70ac42d2e": {"definition": "A loudspeaker, or a section of an array, designed or aimed to cover audience areas close to the system over relatively short distances. Near-throw devices typically offer wider dispersion and lower output than long-throw elements, so they cover the down-front area evenly without over-driving it.", "plain_english": "A near-throw speaker covers the people close to the stage. It spreads sound wide but not very far. This keeps the front rows even without blasting them. Long-throw speakers handle the distant seats instead.", "purpose_function": "It fills the nearby audience with even level and coverage, so the front is not too loud while far seats still get enough energy from long-throw elements. This balances level from the front of the room to the back.", "practical_application": "When building a line array, a technician gives the lower cabinets wider splay as the near-throw section, or adds separate short-throw fills for the down-front seats.", "category": "Loudspeaker coverage", "related_terms": ["Long-throw", "Out-fill", "Front fill", "Downfill", "Splay angle", "Line array"], "common_mistakes": ["Aiming a long-throw box at the front rows, which makes the down-front area too loud", "Confusing near-throw with the acoustic near field; they are different concepts", "Using too little splay in the near-throw section, leaving front seats uneven", "Forgetting near-throw elements usually need delay and level trims relative to the mains"], "scenario_contexts": ["Covering the down-front seats with the lower cabinets of a J-array", "Adding short-throw fills for a pit or the first few rows", "Balancing front-to-back level so near seats are not overpowered"]}, "b3727b15-e893-49b1-a060-2fa82f3aa108": {"definition": "A supplementary loudspeaker or array that extends a system's horizontal coverage to the outer side audience areas, beyond the reach of the main arrays. Out-fills are aimed outward from the main hangs to cover the far-left and far-right seating that the mains do not adequately reach.", "plain_english": "Out-fills are extra speakers that cover the seats out to the sides. The main speakers point at the center of the crowd. The side seats can get left out. Out-fills fill in those outer areas so everyone hears well.", "purpose_function": "They widen the system's horizontal coverage so listeners at the extreme sides get enough level and clarity. This removes weak or dead zones the main arrays cannot cover.", "practical_application": "A technician flies or stacks out-fill boxes angled toward the outer seating, then sets their level and delay to blend smoothly with the main arrays.", "category": "Loudspeaker coverage", "related_terms": ["Outfill", "In-fill", "Front fill", "Main array", "Coverage angle", "Delay alignment"], "common_mistakes": ["Setting out-fill level too high, so it pulls focus away from the main arrays", "Skipping delay alignment, which smears sound where out-fill and mains overlap", "Confusing out-fill (outer coverage) with in-fill (center-gap coverage)", "UNSAFE: Flying out-fill cabinets before confirming the rigging hardware, points, and total load are inspected and within the manufacturer's rated working load limit"], "scenario_contexts": ["Covering wide arena seating beyond the main hangs", "Reaching side balconies that the main arrays miss", "Widening coverage for a broad festival audience"]}, "c33c4c8d-1e4e-46e8-8092-cdb4043a2acd": {"definition": "A supplementary loudspeaker or array that extends a system's horizontal coverage to the outer side audience areas beyond the reach of the main arrays. 'Outfill' is the common one-word spelling of 'out-fill'; the cabinets are aimed outward to cover the far-left and far-right seating.", "plain_english": "Outfill speakers cover the seats out to the far sides. The main speakers aim at the middle of the crowd. Without help, the side seats miss out. Outfills point outward to fill those areas.", "purpose_function": "They widen horizontal coverage so listeners at the extreme sides get adequate level and clarity. This avoids weak or uncovered zones the main arrays cannot reach.", "practical_application": "A technician deploys outfill cabinets angled toward the outer seating, then trims their level and delay so they blend with the main arrays.", "category": "Loudspeaker coverage", "related_terms": ["Out-fill", "Infill", "Front fill", "Main array", "Coverage angle", "Delay alignment"], "common_mistakes": ["Confusing outfill (outer side coverage) with infill (center coverage)", "Running outfill without delay alignment, which blurs the overlap with the mains", "Setting outfill too loud, which pulls the image away from center", "UNSAFE: Flying outfill cabinets without confirming the rigging hardware and total load are within the manufacturer's rated working load limit"], "scenario_contexts": ["Extending coverage to far-side arena seating beyond the main hangs", "Covering wide sightline seats a main line array cannot reach", "Blending side coverage into a large festival system"]}, "fb034dab-0043-43f3-87ee-66fb217e1e2e": {"definition": "An output high-pass filter (HPF) is a filter applied to an individual output channel of a loudspeaker processor, system controller, amplifier, or console that passes frequencies above a set cutoff while progressively attenuating those below it. On a system output it defines the low-frequency limit of that channel, setting the low edge of a crossover band or protecting the connected driver from low-frequency energy it cannot reproduce safely.", "plain_english": "An output high-pass filter sits on one output of a sound processor. It lets high sounds pass and cuts the low ones below a set point. Techs use it to keep deep bass out of speakers that cannot handle it.", "purpose_function": "It exists to keep low-frequency energy out of drivers or zones that should not receive it, protecting loudspeakers and setting the low end of each crossover band. This keeps the system clean and prevents mechanical overload of smaller drivers.", "practical_application": "A system tech sets an output HPF on a mid-high box so the subwoofers handle the lows, or high-passes a front-fill output to keep it tight and more feedback-resistant.", "category": "Output Processing", "related_terms": ["Output Low-Pass Filter", "Output Mute", "Crossover", "Loudspeaker processor", "Driver protection", "Subsonic filter"], "common_mistakes": ["Confusing a high-pass filter, which removes lows, with a low-pass filter, which removes highs.", "Setting the cutoff too low, so subsonic energy still reaches small drivers and wastes amplifier headroom.", "Bypassing the factory output HPF in a loudspeaker preset, which lets drivers over-excurse and fail."], "scenario_contexts": ["Protecting mid-high cabinets by high-passing them above the subwoofer crossover point.", "Tightening a lectern or front-fill output by removing unneeded low end.", "Setting a subsonic filter to stop stage rumble and handling noise from reaching the amplifiers."]}, "a985fa44-551c-4105-adc0-21b6500e6a28": {"definition": "An output low-pass filter (LPF) is a filter applied to an individual output channel of a loudspeaker processor, system controller, amplifier, or console that passes frequencies below a set cutoff while progressively attenuating those above it. On a system output it defines the high-frequency limit of that channel, most commonly setting the upper edge of a subwoofer's band so it hands off cleanly to the mid-high system.", "plain_english": "An output low-pass filter sits on one output of a sound processor. It lets low sounds pass and cuts the high ones above a set point. Techs use it on a subwoofer output so it only plays deep bass.", "purpose_function": "It exists to restrict an output to its intended low-frequency band, keeping mid and high content out of subwoofers and defining the top of each crossover region. This gives a smooth handoff between the subs and the main system.", "practical_application": "A system tech sets an output LPF on a subwoofer output, often near 80 to 100 Hz, so the subs stop where the mains take over.", "category": "Output Processing", "related_terms": ["Output High-Pass Filter", "Output Mute", "Crossover", "Subwoofer", "Loudspeaker processor", "Band-pass filter"], "common_mistakes": ["Confusing a low-pass filter, which removes highs, with a high-pass filter, which removes lows.", "Setting the subwoofer LPF too high, so subs and mains overlap and cause comb filtering through the crossover region.", "Forgetting that the filter slope, not just the cutoff, controls how much overlap remains with the next band."], "scenario_contexts": ["Limiting a subwoofer output to only the low frequencies below the mains' range.", "Building a two- or three-way active crossover inside a system processor.", "Rolling off the top of a distributed low-frequency zone so it blends with full-range boxes."]}, "7dcfc9e5-5fc1-4fc9-b586-380a3fe17139": {"definition": "Output mute is a control that silences a specific output channel of a console, matrix, loudspeaker processor, or amplifier by disconnecting or fully attenuating its signal path, without changing that channel's level, processing, or routing settings. It provides an instant, recallable on/off for the output and is typically applied after processing so the muted channel produces no acoustic output.", "plain_english": "An output mute is a switch that silences one output of a sound system. It turns that speaker feed off without changing any of its settings. Flip it back and the output returns exactly as it was.", "purpose_function": "It exists to let an operator kill or restore a single output instantly, for safety checks, zone control, or troubleshooting, without losing its level and processing settings. This makes it easy to isolate one part of a system.", "practical_application": "A tech mutes an unused zone during a show, or mutes all outputs during power-up to avoid turn-on thumps through the loudspeakers.", "category": "Output Processing", "related_terms": ["Output High-Pass Filter", "Output Low-Pass Filter", "Mute group", "Matrix output", "Zone (audio)", "Signal routing"], "common_mistakes": ["UNSAFE: Treating an output mute as making a circuit safe to service; muting silences signal but amplifier outputs and mains power stay live, so de-energizing and lockout/tagout are required.", "Confusing an output mute with an input or channel mute, so the wrong point in the signal path is silenced.", "Leaving an output muted at showtime, then wasting time hunting for 'dead' speakers that are simply switched off."], "scenario_contexts": ["Silencing a zone or delay line not needed for a particular event.", "Isolating one output while troubleshooting a hum or buzz.", "Muting all outputs during system power-up to avoid turn-on transients."]}, "6467c8ba-9fb5-496f-a154-38b9a91ac24d": {"definition": "An over-balcony fill is a supplementary (fill) loudspeaker subsystem that covers audience seated on the balcony, or upper tier, as distinct from an under-balcony fill that covers seats beneath the balcony overhang. It supplies local level and intelligibility to upper-tier seats the main array under-covers, and is normally delayed to time-align with the mains.", "plain_english": "An over-balcony fill is an extra speaker system for people sitting up on the balcony. The main speakers often cannot cover those upper seats well. This fill adds clear, even sound just for that area. It is delayed so it lines up with the main sound.", "purpose_function": "It exists to give balcony seating even coverage and clear speech when the main system, aimed mainly at the floor, cannot reach the upper tier cleanly. Delaying it keeps its sound in time with the mains for a natural blend.", "practical_application": "A system tech flies or mounts small fill boxes to cover the balcony, then sets delay and level so upper-tier seats match the main system.", "category": "Fill System", "related_terms": ["Balcony fill", "Under-balcony fill", "Over-balcony loudspeaker", "Delay (fill)", "Main array", "Coverage"], "common_mistakes": ["UNSAFE: Flying or mounting fill boxes overhead without a rated secondary (safety) suspension and without staying within the rigging point's and hardware's working load limits.", "Confusing over-balcony fill, which covers seats on the balcony, with under-balcony fill, which covers seats beneath the overhang.", "Not delaying the fill to the mains, so balcony listeners hear an echo or a smeared image.", "Running the fill too loud, so it draws attention to the speakers instead of blending with the main system."], "scenario_contexts": ["Covering upper-tier seats in a theatre or concert hall that the main hangs overshoot or miss.", "Adding speech intelligibility for balcony seats in a large house of worship.", "Filling a gap where the main array's vertical coverage stops short of the top rows."]}, "d28b8488-37b3-4c27-9f35-41ac15ada782": {"definition": "An over-balcony loudspeaker is a loudspeaker deployed to cover the balcony, or upper-tier, seating area of a venue, mounted or flown so its coverage pattern serves the upper seats rather than the main floor. It is the physical loudspeaker element of an over-balcony fill subsystem and is typically time-aligned (delayed) to the main array.", "plain_english": "An over-balcony loudspeaker is a speaker set up to cover people sitting on the balcony. It is aimed at the upper seats, not the main floor. It is usually delayed so its sound matches the main speakers.", "purpose_function": "It exists to deliver even level and clear sound to upper-tier seats the main array cannot cover well. Placing and aiming it for the balcony fills a coverage gap in the room.", "practical_application": "A tech flies or wall-mounts an over-balcony loudspeaker aimed at the upper seats, then sets its delay, level, and EQ to blend with the mains.", "category": "Loudspeaker Deployment", "related_terms": ["Over-balcony fill", "Balcony fill", "Under-balcony fill", "Delay (fill)", "Coverage angle", "Flown loudspeaker"], "common_mistakes": ["UNSAFE: Flying or mounting the loudspeaker overhead without a rated secondary safety and without checking the point's working load limit and the manufacturer's approved rigging method.", "Aiming the box at the balcony rail or floor instead of at the listeners' ears, so coverage is uneven.", "Skipping delay alignment, so balcony listeners hear the loudspeaker before the main system."], "scenario_contexts": ["Covering the top tier of a theatre where the main hang cannot reach.", "Providing speech clarity to balcony seats in a large house of worship.", "Serving upper-level seating in a multi-tier hall or arena bowl."]}, "bda59b41-e0c2-4bae-ac9f-4b96ab897b3c": {"definition": "An overflow feed is a program audio (or audio-and-video) signal distributed to an overflow area, such as an additional room, lobby, tent, or seating zone used to hold audience beyond the main space's capacity. It carries the same primary program to loudspeakers in that secondary zone so listeners outside the main room still hear the event.", "plain_english": "An overflow feed sends the show's sound to extra rooms or areas. These spaces hold people when the main room is full. Speakers there play the same program so everyone can still hear.", "purpose_function": "It exists to extend program audio to spaces beyond the main room when attendance passes capacity, keeping overflow audiences connected to the event. It is usually a separate, level-independent zone feed.", "practical_application": "A tech patches an overflow feed from the main mix, often via a matrix output, to speakers in a lobby or secondary room, setting its own level and delay if needed.", "category": "Signal Distribution", "related_terms": ["Overflow-Zone Feed", "Zone (audio)", "Matrix output", "Distributed system", "Delay (fill)", "Program feed"], "common_mistakes": ["UNSAFE: Assuming an overflow feed can serve as the venue's emergency voice or paging path, which must be a separate system meeting NFPA 72 and local code.", "Feeding the overflow zone straight from the master output, so its level cannot be set independently of the main room.", "Forgetting the overflow area's own acoustics and delay, so speech there is unclear."], "scenario_contexts": ["Feeding a lobby or overflow room during a sold-out conference or service.", "Sending program to a secondary tent or hall at a large event.", "Providing the main program to a green room, nursery, or hospitality area."]}}$ape$::jsonb)) d WHERE g.id=d.id;
COMMIT;
